INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于当了上党主席。", "corrected_sentence": "他终于当上了党主席。", "error_description": "补语位置错误：“当上”是动补结构，“上”要紧跟在“当”后，应说“当上了党主席”，不能说“当了上党主席”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想当了党主席。", "corrected_sentence": "他想当党主席。", "error_description": "语义矛盾：“想当”表示尚未实现的意愿，加“了”表示已经完成，二者相冲突，应说“他想当党主席。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
