INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87729, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "相应是随着另一件事的变化而跟着变化。", "primary_collocate": null, "pronunciation": "xiāng yìng", "ipa": "ɕi̯ɑŋ˥ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "价格涨了，工资也要相应提高。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气冷了，人们也相应多穿衣服。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "收入增加，花钱也相应变多。", "target_word": "相应", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "人多了，房间也要相应变大。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生多了，学校也要相应多请老师。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司变大了，人也相应多了起来。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子长大了，书包也相应换大了。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气变热，冰淇淋的销量也相应上升。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "速度快了，危险也会相应增加。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市大了，路也相应修得更宽了。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "相应地", "label": "副词形式"}], "register": "书面", "sense_fingerprint": "相应：用在动词前，表示随着另一件事的变化而跟着变化（也相应提高）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '957488b2-d73b-4bc6-b47f-79a362d47852') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87729, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相应", "is_correct": true, "explanation": "正确。「相应」是副词，表示工资随物价上涨而跟着提高，符合语境。"}, {"text": "难道", "is_correct": false, "explanation": "语义：「难道」用于反问，这里是陈述，句子表达不通。"}, {"text": "已经", "is_correct": false, "explanation": "语法：「已经」表示动作已完成，与「要」表示将来相矛盾，句子不通。"}, {"text": "很", "is_correct": false, "explanation": "搭配：「很」修饰形容词或状态，不能修饰「提高」这类动作，「也要很提高」不成立。"}], "explanations": {"相应": "正确。「相应」是副词，表示工资随物价上涨而跟着提高，符合语境。", "难道": "语义：「难道」用于反问，这里是陈述，句子表达不通。", "已经": "语法：「已经」表示动作已完成，与「要」表示将来相矛盾，句子不通。", "很": "搭配：「很」修饰形容词或状态，不能修饰「提高」这类动作，「也要很提高」不成立。"}, "sentence_index": 0, "correct_answer": "相应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气相应很热。", "explanation": "这里应该用〈一直〉。相应要说明跟着另一件事变化，「天气很热」前面没有变化的对象，不能用相应。"}, {"text": "他相应吃过饭了。", "explanation": "这里应该用〈已经〉。相应表示跟着变化，不表示动作已经完成。"}, {"text": "我相应很喜欢这本书。", "explanation": "这里应该用〈非常〉。相应表示跟着变化，不表示程度，说很喜欢要用「非常」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87729, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相应", "is_correct": true, "explanation": "正确。「相应」是副词，表示书包随孩子长大而跟着变大，符合语境。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「非常」修饰形容词，不能直接修饰「换大了」这样的动补结构。"}, {"text": "很", "is_correct": false, "explanation": "搭配：「很」修饰形容词，「很换大了」不成立。"}, {"text": "却", "is_correct": false, "explanation": "语义：「却」表示转折，句中没有需要转折的对比，用在这里不合语境。"}], "explanations": {"相应": "正确。「相应」是副词，表示书包随孩子长大而跟着变大，符合语境。", "非常": "搭配：「非常」修饰形容词，不能直接修饰「换大了」这样的动补结构。", "很": "搭配：「很」修饰形容词，「很换大了」不成立。", "却": "语义：「却」表示转折，句中没有需要转折的对比，用在这里不合语境。"}, "sentence_index": 6, "correct_answer": "相应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他相应考上了大学。", "explanation": "这里应该用〈终于〉。相应表示跟着变化，此处没有变化的前提，不能表示考上大学这件事的结果。"}, {"text": "天相应下雨了。", "explanation": "这里应该用〈忽然〉。相应要说明跟着另一件事变化，「天下雨」前面没有变化的对象。"}, {"text": "他今天相应来晚了。", "explanation": "这里应该用〈又〉。相应表示随着另一件事的变化而跟着变化，这句话前面没有引起变化的情况，不能用相应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "收入提高，生活也相应得改善。", "corrected_sentence": "收入提高，生活也相应改善。", "error_description": "「相应」是副词，后面不能加「得」。「得」引出补语，「相应改善」直接说明动作跟着变化，应说「生活也相应改善」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "物价上涨，房租也的相应上升。", "corrected_sentence": "物价上涨，房租也相应上升。", "error_description": "「相应」是副词，前面不能加「的」。「也的相应」中的「的」多余，应说「房租也相应上升」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
