INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87730, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，相互照应或对应的。", "primary_collocate": null, "pronunciation": "xiāng yìng", "ipa": "ɕi̯ɑŋ˥ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "出了问题，就要采取相应的措施。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有权利，就有相应的责任。", "target_word": "相应", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司给了他相应的报酬。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同的年级用相应的课本。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作做得好，就会得到相应的奖励。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把表格交给相应的部门。", "target_word": "相应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请这个职位，需要具备相应的专业能力。", "target_word": "相应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每把钥匙都有相应的锁。", "target_word": "相应", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他违反了规定，受到了相应的处罚。", "target_word": "相应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们已经准备好相应的材料，明天就可以交。", "target_word": "相应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相应地", "label": "副词形式"}], "register": "书面", "sense_fingerprint": "相应：形容词，修饰名词，表示与前面情况相对应的（相应的措施）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '957488b2-d73b-4bc6-b47f-79a362d47852') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87730, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相应", "is_correct": true, "explanation": "正确。「相应的措施」指与问题相对应的措施，符合「出了问题」的语境。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：「漂亮」形容外观，不能用来形容采取的措施。"}, {"text": "安静", "is_correct": false, "explanation": "语义：「安静」描述环境或状态，「安静的措施」不成立。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：「高兴」只修饰人或情绪，不能说「高兴的措施」。"}], "explanations": {"相应": "正确。「相应的措施」指与问题相对应的措施，符合「出了问题」的语境。", "漂亮": "语义：「漂亮」形容外观，不能用来形容采取的措施。", "安静": "语义：「安静」描述环境或状态，「安静的措施」不成立。", "高兴": "搭配：「高兴」只修饰人或情绪，不能说「高兴的措施」。"}, "sentence_index": 0, "correct_answer": "相应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的看法和我相应得很。", "explanation": "这里应该用〈一致〉。相应不能带「得很」作补语，说看法与我一致要用「一致」。"}, {"text": "我们俩的身高很相应。", "explanation": "这里应该用〈相近〉。相应表示对应，不表示差别小、接近，说身高接近要用「相近」。"}, {"text": "这件事和你相应。", "explanation": "这里应该用〈相关〉。相应不表示与某人有关系，说这件事与你有关要用「相关」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相应", "is_correct": true, "explanation": "正确。「具备相应的专业能力」指与该职位对应的专业能力，符合语境。"}, {"text": "美味", "is_correct": false, "explanation": "语义：「美味」形容食物的味道，不能修饰专业能力。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：「具备」后接能力或条件，「冷」不能修饰「专业能力」。"}, {"text": "圆", "is_correct": false, "explanation": "语义：「圆」描述形状，不能用来修饰能力。"}], "explanations": {"相应": "正确。「具备相应的专业能力」指与该职位对应的专业能力，符合语境。", "美味": "语义：「美味」形容食物的味道，不能修饰专业能力。", "冷": "搭配：「具备」后接能力或条件，「冷」不能修饰「专业能力」。", "圆": "语义：「圆」描述形状，不能用来修饰能力。"}, "sentence_index": 6, "correct_answer": "相应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个很相应的人。", "explanation": "这里应该用〈踏实〉。相应表示事物之间的对应、配合，不描述人的性格，说人的性格要用「踏实」。"}, {"text": "这个房间很相应，住五个人也不挤。", "explanation": "这里应该用〈宽敞〉。相应表示与某种情况相对应的，不描述空间大小，说房间大要用「宽敞」。"}, {"text": "他对这个结果很相应。", "explanation": "这里应该用〈满意〉。相应表示对应、配合，不表示心里的满足，说对结果满意要用「满意」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "发现错误，就要改正相应得内容。", "corrected_sentence": "发现错误，就要改正相应的内容。", "error_description": "「相应」修饰名词时用「的」，不能用「得」。「得」是补语标记，这里应改为「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "考生需要准备相应地证件。", "corrected_sentence": "考生需要准备相应的证件。", "error_description": "「相应」修饰名词时用「的」，不能用「地」。「地」是修饰动词的副词标记，「相应地证件」错误，应说「相应的证件」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
