INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87731, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "版本是同一个东西在不同时候或不同做法下做出的样子。", "primary_collocate": null, "pronunciation": "bǎn běn", "ipa": "pan˨˩˦ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个游戏的旧版本和新版本，画面差别很大。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这部电影的老版本。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机游戏出了新版本。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把软件更新到最新版本。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌有三个不同的版本。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手机用的是哪个版本？", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧版本的地图已经不能用了。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的动画版本很有名。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款相机发布了新的固件版本。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的长版本比短版本好看。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "版本号", "label": "复合"}], "register": "通用", "sense_fingerprint": "同一事物在不同时期或不同做法下的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcccfa74-1e16-4e92-abd1-a3b542c01668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87731, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "版本", "is_correct": true, "explanation": "版本指同一游戏在不同时期推出的样子，“旧”“新”与之相配，画面才会有差别。"}, {"text": "版权", "is_correct": false, "explanation": "语义：版权指著作权，与画面的差别无关。"}, {"text": "文本", "is_correct": false, "explanation": "语义：文本指文字材料，游戏的画面不是文本。"}, {"text": "样本", "is_correct": false, "explanation": "搭配：样本指抽取出来检验的部分，不说游戏的旧样本和新版本。"}], "explanations": {"版本": "版本指同一游戏在不同时期推出的样子，“旧”“新”与之相配，画面才会有差别。", "版权": "语义：版权指著作权，与画面的差别无关。", "文本": "语义：文本指文字材料，游戏的画面不是文本。", "样本": "搭配：样本指抽取出来检验的部分，不说游戏的旧样本和新版本。"}, "sentence_index": 0, "correct_answer": "版本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝一杯版本。", "explanation": "版本指同一事物的不同样子，不能喝。这里应说“牛奶”。"}, {"text": "他用版本把门打开了。", "explanation": "版本不是工具，不能用来开门。这里应说“钥匙”。"}, {"text": "今天的版本很好，阳光很多。", "explanation": "版本不指天气。这里应说“天气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87731, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "版本", "is_correct": true, "explanation": "版本指同一地图在不同时期的样子，“旧”与之相配。"}, {"text": "版税", "is_correct": false, "explanation": "语义：版税指作者按销量取得的报酬，与地图的样子无关。"}, {"text": "字帖", "is_correct": false, "explanation": "语义：字帖是练字用的范本，不指地图的不同样子。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是记录音乐的符号，不指地图的不同样子。"}], "explanations": {"版本": "版本指同一地图在不同时期的样子，“旧”与之相配。", "版税": "语义：版税指作者按销量取得的报酬，与地图的样子无关。", "字帖": "语义：字帖是练字用的范本，不指地图的不同样子。", "乐谱": "语义：乐谱是记录音乐的符号，不指地图的不同样子。"}, "sentence_index": 6, "correct_answer": "版本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们公司的版本。", "explanation": "版本指同一事物的不同样子，不指人，这里应说“会计”。"}, {"text": "我等了他一个版本。", "explanation": "版本指同一事物的不同样子，不能表示时间长度，这里应说“一个小时”。"}, {"text": "他住在一个小版本里。", "explanation": "版本指同一事物的不同样子，不指住处，这里应说“房子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87731, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下载了这个软件的一只新版本。", "corrected_sentence": "我下载了这个软件的一个新版本。", "error_description": "“版本”的量词应为“个”，写成“只”是错误。“只”用于动物或成对器物中的一件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87731, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个故事有两条不同的动画版本。", "corrected_sentence": "这个故事有两个不同的动画版本。", "error_description": "“版本”的量词应为“个”，写成“条”是错误。“条”用于细长的东西，如“一条鱼”“一条路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
