INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87732, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "同一书籍因编辑、印刷或修订而产生的不同本子。", "primary_collocate": null, "pronunciation": "bǎn běn", "ipa": "pan˨˩˦ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本小说有好几个版本。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出版社准备出一个新版本。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同版本的内容不太一样。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他收藏了这本书的早期版本。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说有两个版本，结局不同。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修改以后，这本书有了新的版本。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，请用同一个版本的课本。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗的几个版本都收在书里。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的修订版本加了很多注释。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个版本的错字比旧版本少。", "target_word": "版本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "版本号", "label": "复合"}], "register": "通用", "sense_fingerprint": "同一书籍因编印修订而不同的本子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcccfa74-1e16-4e92-abd1-a3b542c01668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = 