INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "版本", "is_correct": true, "explanation": "版本指同一本书经编辑、印刷而产生的不同本子，与“好几个”相配。"}, {"text": "节拍", "is_correct": false, "explanation": "语义：节拍指音乐的节奏单位，不指书的不同本子。"}, {"text": "句号", "is_correct": false, "explanation": "语义：句号是标点符号，不指书的不同本子，不说有好几个句号。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是工具书，小说不是词典，不说有好几个词典。"}], "explanations": {"版本": "版本指同一本书经编辑、印刷而产生的不同本子，与“好几个”相配。", "节拍": "语义：节拍指音乐的节奏单位，不指书的不同本子。", "句号": "语义：句号是标点符号，不指书的不同本子，不说有好几个句号。", "词典": "语义：词典是工具书，小说不是词典，不说有好几个词典。"}, "sentence_index": 0, "correct_answer": "版本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的版本是一百块钱。", "explanation": "版本指书的不同本子，不指价钱。这里应说“价格”。"}, {"text": "我把版本放进书包里，背去学校。", "explanation": "版本是抽象的概念，不能放进书包。这里应说“书”。"}, {"text": "这本书的版本很厚，有五百页。", "explanation": "版本不指书的厚度或页数。这里应说“这本书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "版本", "is_correct": true, "explanation": "版本指同一本书的不同本子，“同一个”与之相配，指课本的同一种本子。"}, {"text": "页码", "is_correct": false, "explanation": "语义：页码指页数编号，不指课本的版本。"}, {"text": "草稿", "is_correct": false, "explanation": "语义：草稿指未定稿的文稿，不指课本的版本。"}, {"text": "印章", "is_correct": false, "explanation": "语义：印章指盖在纸上的印记，与课本的版本无关。"}], "explanations": {"版本": "版本指同一本书的不同本子，“同一个”与之相配，指课本的同一种本子。", "页码": "语义：页码指页数编号，不指课本的版本。", "草稿": "语义：草稿指未定稿的文稿，不指课本的版本。", "印章": "语义：印章指盖在纸上的印记，与课本的版本无关。"}, "sentence_index": 6, "correct_answer": "版本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的版本是鲁迅。", "explanation": "这里应该用〈作者〉。版本指同一本书的不同本子，不能指写书的人。"}, {"text": "这本小说的版本是他的朋友。", "explanation": "这里应该用〈译者〉。版本不指人，翻译作品的人要说“译者”。"}, {"text": "这套词典的版本是一位老教授。", "explanation": "这里应该用〈主编〉。版本不指人，负责编写的人要说“主编”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书修订后出了两台版本。", "corrected_sentence": "这本书修订后出了两个版本。", "error_description": "“版本”的量词应为“个”，不能用“台”。“台”用于机器、仪器等，版本不用“台”，应说“两个版本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书有不同地版本，内容不太一样。", "corrected_sentence": "这本书有不同的版本，内容不太一样。", "error_description": "“不同”修饰名词“版本”时应用“的”，不用“地”（“地”用于修饰动词、形容词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
