INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87735, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一下子是时间很短，一会儿就好了。", "primary_collocate": null, "pronunciation": "yí xià zi", "ipa": "i˧˥ ɕja˥˩ tsɿ", "syllable_count": 3, "sentences": [{"text": "这点作业一下子就写完了。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热水一下子就烧好了。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题很简单，我一下子就做对了。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪化得很快，一下子就没有了。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们一下子就把面包吃完了。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得快，一下子就到了学校。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太容易，一下子就解决了。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌很好学，我一下子就学会了。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机一下子就修好了。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨很小，一下子就停了。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "用很短的时间就完成或结束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c3fb48-7015-4f79-9d9c-8a4eda67e6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87735, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一下子", "is_correct": true, "explanation": "“一下子”表示很短时间内就完成，与“写完了”的快速结束相合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去有过某种经历，不能与“就写完了”这种表示快速完成的说法搭配。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示自始至终如此，与表示完成的“写完了”不合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时、不经常，与一次性完成的“写完了”不合。"}], "explanations": {"一下子": "“一下子”表示很短时间内就完成，与“写完了”的快速结束相合。", "曾经": "语义：“曾经”表示过去有过某种经历，不能与“就写完了”这种表示快速完成的说法搭配。", "始终": "语义：“始终”表示自始至终如此，与表示完成的“写完了”不合。", "偶尔": "语义：“偶尔”表示有时、不经常，与一次性完成的“写完了”不合。"}, "sentence_index": 0, "correct_answer": "一下子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个病一下子慢慢好起来了。", "explanation": "这里的“一下子”强调时间很短、很快完成，与逐步恢复的过程相矛盾；本词条不用于描写渐进的变化。"}, {"text": "这份报告他一下子写了三个星期。", "explanation": "“一下子”表示很短时间内完成，不能与“三个星期”这样的长时段连用，两者意思矛盾。"}, {"text": "雪一下子化了三天。", "explanation": "“一下子”表示很短时间内就结束，不能与“三天”这样的持续时段连用，两者意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87735, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一下子", "is_correct": true, "explanation": "“一下子”表示很短时间内就完成，与“解决了”的快速结果相合。"}, {"text": "勉强", "is_correct": false, "explanation": "语义：“勉强”表示费力或不情愿地做到，与“太容易”的语境不合。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒劳无益，与“解决了”的成功结果不合。"}, {"text": "总是", "is_correct": false, "explanation": "搭配：“总是”表示经常重复，不能与表示一次性完成的“就解决了”搭配。"}], "explanations": {"一下子": "“一下子”表示很短时间内就完成，与“解决了”的快速结果相合。", "勉强": "语义：“勉强”表示费力或不情愿地做到，与“太容易”的语境不合。", "白白": "语义：“白白”表示徒劳无益，与“解决了”的成功结果不合。", "总是": "搭配：“总是”表示经常重复，不能与表示一次性完成的“就解决了”搭配。"}, "sentence_index": 6, "correct_answer": "一下子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座老房子一下子很陈旧。", "explanation": "这里的“一下子”强调时间很短就完成，而“陈旧”是长期形成的状态，不能在短时间内变成这样，所以不能这样用。"}, {"text": "这棵树一下子慢慢长高了。", "explanation": "这里的“一下子”强调很短时间内就完成，与“慢慢长高”这种逐步生长的过程相矛盾；本词条不用于描写渐进的变化。"}, {"text": "这门手艺他一下子学了十年。", "explanation": "这里的“一下子”表示很短时间内就完成，而“学了十年”是很长的时段，两者意思矛盾；本词条不能与长时段连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87735, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一下子一下子就把任务做完了。", "corrected_sentence": "他一下子就把任务做完了。", "error_description": "重复错误：“一下子”不能连用两次，应只保留一个。正确形式是“他一下子就把任务做完了”，错误形式是“他一下子一下子就把任务做完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87735, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一下子的就写完了。", "corrected_sentence": "他一下子就写完了。", "error_description": "结构助词误加：“一下子”与“就”之间不能加“的”。正确形式是“他一下子就写完了”，错误形式是“他一下子的就写完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
