INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87736, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "很短的时间内；突然。", "primary_collocate": null, "pronunciation": "yí xià zi", "ipa": "i˧˥ ɕja˥˩ tsɿ", "syllable_count": 3, "sentences": [{"text": "天一下子黑了，下起了大雨。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，她一下子哭了。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一下子灭了，屋里很黑。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车一下子停了下来。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一下子站起来，走出了门。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一下子想不起他的名字。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里一下子安静了。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话一响，他一下子坐直了身子。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老朋友，他一下子笑了。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一下子大了起来。", "target_word": "一下子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "突然、一瞬间发生变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c3fb48-7015-4f79-9d9c-8a4eda67e6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一下子", "is_correct": true, "explanation": "“一下子”表示很短时间内突然发生，与“天黑了”的突然变化相合。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意去做某事，需要有意志的施事，“天”不能故意黑。"}, {"text": "亲自", "is_correct": false, "explanation": "配价：“亲自”要求由人作施事，“天”不能亲自黑了。"}, {"text": "拼命", "is_correct": false, "explanation": "语义：“拼命”形容用尽全力，与“黑了”这种自然变化不合。"}], "explanations": {"一下子": "“一下子”表示很短时间内突然发生，与“天黑了”的突然变化相合。", "故意": "语义：“故意”表示有意去做某事，需要有意志的施事，“天”不能故意黑。", "亲自": "配价：“亲自”要求由人作施事，“天”不能亲自黑了。", "拼命": "语义：“拼命”形容用尽全力，与“黑了”这种自然变化不合。"}, "sentence_index": 0, "correct_answer": "一下子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一下子学了三年外语。", "explanation": "“一下子”只表示很短的时间内发生或完成，不能与“三年”这样的长时段连用；应去掉“一下子”，或说“他整整学了三年外语”。"}, {"text": "门一下子慢慢开了。", "explanation": "这里应该用〈慢慢〉。“一下子”表示突然发生，与“慢慢”的渐进义相矛盾。"}, {"text": "他一下子住在北京十年。", "explanation": "这里应该用〈一直〉。“一下子”用于瞬间发生或很快完成的动作，不能修饰“住”这样持续的状态，也不能与“十年”连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一下子", "is_correct": true, "explanation": "“一下子”表示突然发生，与“屋里安静了”的突然变化相合。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示专为某件事而做，需要有意的施事，“屋里”不能特意安静。"}, {"text": "不断", "is_correct": false, "explanation": "语义：“不断”表示持续反复，与“安静了”这种一次性变化不合。"}, {"text": "亲口", "is_correct": false, "explanation": "配价：“亲口”要求由人说出或做出，“屋里”不能亲口安静。"}], "explanations": {"一下子": "“一下子”表示突然发生，与“屋里安静了”的突然变化相合。", "特意": "语义：“特意”表示专为某件事而做，需要有意的施事，“屋里”不能特意安静。", "不断": "语义：“不断”表示持续反复，与“安静了”这种一次性变化不合。", "亲口": "配价：“亲口”要求由人说出或做出，“屋里”不能亲口安静。"}, "sentence_index": 6, "correct_answer": "一下子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一下子慢慢长大了。", "explanation": "这里的“一下子”强调很短时间内突然完成，与“长大”这种逐步进行的过程相矛盾；本词条不用于描写渐进的变化。"}, {"text": "这座山一下子很古老。", "explanation": "这里的“一下子”表示短时间内的突然变化；“古老”是长期形成的状态，不能在短时间里突然出现，所以不能这样用。"}, {"text": "他一下子反复犹豫了很多次。", "explanation": "这里的“一下子”表示很短时间内突然完成，而“反复……很多次”描述的是长时间多次出现的过程，两者意思矛盾；本词条不指多次重复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一下子一下子忘了他的名字。", "corrected_sentence": "我一下子忘了他的名字。", "error_description": "重复错误：“一下子”不能连用两次，应只保留一个。正确形式是“我一下子忘了他的名字”，错误形式是“我一下子一下子忘了他的名字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一下子的哭了。", "corrected_sentence": "他一下子哭了。", "error_description": "结构助词误加：副词“一下子”后面不能直接加“的”修饰动词，应去掉“的”。正确形式是“他一下子哭了”，错误形式是“他一下子的哭了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
