INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87737, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "破是东西被弄坏了，有了洞或者裂开了。", "primary_collocate": null, "pronunciation": "pò", "ipa": "pʰwo˥˩", "syllable_count": 1, "sentences": [{"text": "我的裤子破了一个洞。", "target_word": "破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸太薄，一拿就破了。", "target_word": "破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的鞋子破了，雨水进来了。", "target_word": "破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球破了，孩子哭了起来。", "target_word": "破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袜子破了，妈妈给我补好了。", "target_word": "破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包破了一个口，书掉了出来。", "target_word": "破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件旧衣服的袖子破了。", "target_word": "破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔网破了，鱼都跑了。", "target_word": "破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伞破了，下雨天不能用了。", "target_word": "破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袋子破了，苹果滚了一地。", "target_word": "破", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "破了", "label": "体标"}, {"form": "破过", "label": "体标"}, {"form": "破洞", "label": "复合"}], "register": "通用", "sense_fingerprint": "东西坏了，出现洞或裂口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcccfa74-1e16-4e92-abd1-a3b542c01668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87737, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "破", "is_correct": true, "explanation": "破：pò（第四声），指东西弄坏、出现洞或裂口。"}, {"text": "坡", "is_correct": false, "explanation": "坡：pō（第一声），与 pò（第四声）声调不同，意思是斜面。"}, {"text": "婆", "is_correct": false, "explanation": "婆：pó（第二声），与 pò（第四声）声调不同，意思是老太太。"}, {"text": "末", "is_correct": false, "explanation": "末：mò（第四声），与 pò 声母不同（m 与 p），意思是结束。"}], "explanations": {"破": "破：pò（第四声），指东西弄坏、出现洞或裂口。", "坡": "坡：pō（第一声），与 pò（第四声）声调不同，意思是斜面。", "婆": "婆：pó（第二声），与 pò（第四声）声调不同，意思是老太太。", "末": "末：mò（第四声），与 pò 声母不同（m 与 p），意思是结束。"}, "sentence_index": null, "correct_answer": "破"}, "level_3": {"options": [{"text": "破", "is_correct": true, "explanation": "破指东西损坏、出现洞，与“一个洞”相配。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗不会使裤子出现洞，不说“洗了一个洞”。"}, {"text": "染", "is_correct": false, "explanation": "语义：染指给东西上色，不会造成洞。"}, {"text": "绣", "is_correct": false, "explanation": "搭配：绣是用线做花纹，不说“绣了一个洞”。"}], "explanations": {"破": "破指东西损坏、出现洞，与“一个洞”相配。", "洗": "搭配：洗不会使裤子出现洞，不说“洗了一个洞”。", "染": "语义：染指给东西上色，不会造成洞。", "绣": "搭配：绣是用线做花纹，不说“绣了一个洞”。"}, "sentence_index": 0, "correct_answer": "破"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她破了一个星期做好了蛋糕。", "explanation": "“破”指弄坏或出现裂口，不能表示耗费时间，这里应说“花”。"}, {"text": "这个运动员又破了世界冠军。", "explanation": "“破”指打破或弄坏，不用于取得冠军，这里应说“夺得”。"}, {"text": "老板破了他的请假。", "explanation": "“破”不能用于请假，这里应说“批准”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "破", "is_correct": true, "explanation": "破指衣服损坏、出现裂口，与“袖子”相配。"}, {"text": "跑", "is_correct": false, "explanation": "语义：跑指移动，袖子不会跑。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的对象是歌曲，不说袖子唱。"}, {"text": "笑", "is_correct": false, "explanation": "语义：笑是人的表情，袖子不会笑。"}], "explanations": {"破": "破指衣服损坏、出现裂口，与“袖子”相配。", "跑": "语义：跑指移动，袖子不会跑。", "唱": "搭配：唱的对象是歌曲，不说袖子唱。", "笑": "语义：笑是人的表情，袖子不会笑。"}, "sentence_index": 6, "correct_answer": "破"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那台电脑突然破了，不能开机了。", "explanation": "这里应该用〈坏〉。破指东西出现裂口或洞，电器、机器的故障只说“坏”。"}, {"text": "这盏台灯因为线路短路破了。", "explanation": "这里应该用〈坏〉。破多指东西出现裂口或洞，台灯因线路短路不亮一般说“坏”。"}, {"text": "这台冰箱因为停电破了。", "explanation": "这里应该用〈损坏〉。破用于有裂口或洞的东西，冰箱的故障要说“损坏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不小心把信封破撕了。", "corrected_sentence": "他不小心把信封撕破了。", "error_description": "“撕破”是动词加结果补语，“破”应紧跟在“撕”之后，不能放在动词前，应说“撕破了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件雨衣被破了一道口子，要补一补。", "corrected_sentence": "这件雨衣破了一道口子，要补一补。", "error_description": "“破”是不及物的结果动词，前面不能直接加“被”，应说“这件雨衣破了一道口子”。“被”字句需要动作动词，如“被划破”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b2c172-d2d3-441f-a691-e0cd4778c38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
