INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87739, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "看来是看了以后，觉得可能是这样。", "primary_collocate": null, "pronunciation": "kàn lái", "ipa": "kʰan˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他皱着眉头，看来不太高兴。", "target_word": "看来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看了看天，看来快下雨了。", "target_word": "看来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了他的脸色，看来他很累。", "target_word": "看来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间很乱，看来有人来过。", "target_word": "看来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店人很多，看来东西不错。", "target_word": "看来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看了看地图，看来这条路比较近。", "target_word": "看来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着走进来，看来考得不错。", "target_word": "看来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有水，看来刚下过雨。", "target_word": "看来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我试了试这件衣服，看来有点小。", "target_word": "看来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了一下表，看来要迟到了。", "target_word": "看来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看來", "label": "繁体"}], "register": "口语", "sense_fingerprint": "看了情况之后觉得可能是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 皱 (Zipf 3.31), 眉头 (Zipf 3.07), 太高兴 (Zipf 3.01)']::text[], '471a2867-8aea-41f5-bcb0-874b318de0af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87739, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看来", "is_correct": true, "explanation": "看来：根据他皱眉的样子推测他心情不好，与句子的语境相符。"}, {"text": "诚然", "is_correct": false, "explanation": "语域：“诚然”是书面的承认用语，与描写表情的口语语境不符。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”指过去，与“皱着眉头”正在发生的状态不符。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带做某事，不能用来修饰“不太高兴”这种情绪。"}], "explanations": {"看来": "看来：根据他皱眉的样子推测他心情不好，与句子的语境相符。", "诚然": "语域：“诚然”是书面的承认用语，与描写表情的口语语境不符。", "曾经": "体貌：“曾经”指过去，与“皱着眉头”正在发生的状态不符。", "顺便": "语义：“顺便”表示附带做某事，不能用来修饰“不太高兴”这种情绪。"}, "sentence_index": 0, "correct_answer": "看来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "看来太阳从东边升起。", "explanation": "这里不能用〈看来〉：太阳从东边升起是确定的事实，不需要根据迹象推测。"}, {"text": "看来你快去洗手！", "explanation": "这里不能用〈看来〉：它表示推测，不能用于命令别人去做事。"}, {"text": "看来我真希望他能来。", "explanation": "这里〈看来〉被当成了表示心愿的词，但它只表示根据迹象的推测，不能用来表达心里想要的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87739, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看来", "is_correct": true, "explanation": "看来：根据她笑着走进来的样子推测考得不错，与句子的语境相符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，不能用来评价考试的结果。"}, {"text": "始终", "is_correct": false, "explanation": "体貌：“始终”表示一直持续，与“走进来”这个一次性动作不符。"}, {"text": "固然", "is_correct": false, "explanation": "语域：“固然”是书面的让步用语，与口语推测的语境不符。"}], "explanations": {"看来": "看来：根据她笑着走进来的样子推测考得不错，与句子的语境相符。", "立刻": "语义：“立刻”表示马上，不能用来评价考试的结果。", "始终": "体貌：“始终”表示一直持续，与“走进来”这个一次性动作不符。", "固然": "语域：“固然”是书面的让步用语，与口语推测的语境不符。"}, "sentence_index": 6, "correct_answer": "看来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "看来一年有十二个月。", "explanation": "这里不能用〈看来〉：一年有十二个月是大家都知道的常识，不需要根据迹象推测。"}, {"text": "看来我肯定帮你搬家。", "explanation": "这里〈看来〉被当成了表示许诺的词，但它只表示根据迹象的推测，不能用来向别人许诺。"}, {"text": "看来我知道他的名字。", "explanation": "这里〈看来〉被当成了表示已经掌握的词，但它只表示根据迹象的推测，不能用于自己已经知道的事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天很阴，看来了今天会下雨。", "corrected_sentence": "天很阴，看来今天会下雨。", "error_description": "错误：「看来了」。正确：「看来」。「看来」是副词，后面不能加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨停了看来，路上会很滑。", "corrected_sentence": "雨停了，看来路上会很滑。", "error_description": "错误：「看来」位置错误，放在了「雨停了」之后、逗号之前。正确：「看来」应放在推测分句的开头，逗号在「雨停了」之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
