INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87742, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "牵引列车的动力车辆，即火车头。", "primary_collocate": null, "pronunciation": "jī chē", "ipa": "tɕi˥ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "机车在前面拉着整列火车。", "target_word": "机车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机车是用电的。", "target_word": "机车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查那台旧机车。", "target_word": "机车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机车坏了，列车只好停下来。", "target_word": "机车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新机车的力量比旧的大。", "target_word": "机车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机车后面连着二十节车厢。", "target_word": "机车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机坐在机车里开车。", "target_word": "机车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在博物馆看到一台老机车。", "target_word": "机车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路上的机车都是红色的。", "target_word": "机车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机车一鸣笛，大家都跑到站台上。", "target_word": "机车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}], "register": "中性", "sense_fingerprint": "牵引列车的动力车辆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e864c1b8-57ca-4d3b-9755-214d3c6e6153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "车厢", "is_correct": false, "explanation": "语义：车厢是被牵引的部分，自己不能拉着整列火车前进。"}, {"text": "机车", "is_correct": true, "explanation": "机车是牵引列车的动力车辆，正好拉着整列火车。"}, {"text": "铁轨", "is_correct": false, "explanation": "语义：铁轨只是供车辆行驶的轨道，不会拉车。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：“拉着整列火车”的主语应是动力车辆，人不能直接用“拉”牵引整列火车。"}], "explanations": {"车厢": "语义：车厢是被牵引的部分，自己不能拉着整列火车前进。", "机车": "机车是牵引列车的动力车辆，正好拉着整列火车。", "铁轨": "语义：铁轨只是供车辆行驶的轨道，不会拉车。", "司机": "搭配：“拉着整列火车”的主语应是动力车辆，人不能直接用“拉”牵引整列火车。"}, "sentence_index": 0, "correct_answer": "机车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机车在天上飞来飞去。", "explanation": "这里应该用〈飞机〉。飞机能在天上飞；“机车”是牵引列车在铁路上行驶的动力车辆，不能飞。"}, {"text": "机车是乘客坐的地方。", "explanation": "这里应该用〈车厢〉。乘客坐在车厢里；机车是动力车辆，驾驶员在其中，不供乘客坐。"}, {"text": "机车在江上慢慢航行。", "explanation": "这里应该用〈轮船〉。“机车”是牵引列车在铁路上行驶的动力车辆，不能在江上航行；在江上航行的是轮船。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "操场", "is_correct": false, "explanation": "语义：操场是运动场地，司机不能坐在操场里开车。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包装不下人，司机不可能坐在书包里开车。"}, {"text": "床", "is_correct": false, "explanation": "搭配：“床”不能与“开车”搭配，司机坐的是车上的驾驶位。"}, {"text": "机车", "is_correct": true, "explanation": "机车是牵引列车的动力车辆，司机坐在机车的驾驶位里开车。"}], "explanations": {"操场": "语义：操场是运动场地，司机不能坐在操场里开车。", "书包": "语义：书包装不下人，司机不可能坐在书包里开车。", "床": "搭配：“床”不能与“开车”搭配，司机坐的是车上的驾驶位。", "机车": "机车是牵引列车的动力车辆，司机坐在机车的驾驶位里开车。"}, "sentence_index": 6, "correct_answer": "机车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "渔民驾着机车出海了。", "explanation": "这里应该用〈渔船〉。渔船能在海上航行，“机车”是牵引列车的动力车辆，只能在铁路上行驶，不能出海。"}, {"text": "机车在跑道上起飞。", "explanation": "这里应该用〈飞机〉。飞机能在跑道上起飞，“机车”是牵引列车的动力车辆，不能起飞。"}, {"text": "学生在机车里上课。", "explanation": "这里应该用〈教室〉。学生上课要在教室里；“机车”是牵引列车的动力车辆，不供人上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站里停着一只机车。", "corrected_sentence": "车站里停着一台机车。", "error_description": "错误：“一只机车”；正确：“一台机车”。“只”用于动物，机车是机器，应用量词“台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "铁路旁停着一条新机车。", "corrected_sentence": "铁路旁停着一台新机车。", "error_description": "错误：“一条机车”；正确：“一台机车”。“条”用于长条形的东西，机车是机器，应用量词“台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
