INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87743, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "下任是接着现在的人来做这个工作的人。", "primary_collocate": null, "pronunciation": "xià rèn", "ipa": "ɕja˥˩ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "下任校长下个月就要来了。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在猜谁是下任经理。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是公司的下任负责人。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现任主任下个月走，下任还没定。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师希望下任能把学校办好。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下任队长是小李，他很年轻。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把工作都交给了下任。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的下任班长会是谁呢？", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，下任要从公司里选。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的人就是我们的下任老板。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "下任|接着现任做这个工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2ad337-3c61-49c3-aacc-f67cc219fb9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87743, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下任", "is_correct": true, "explanation": "正确：“下任”指接替现任的人，与“校长下个月就要来了”的语境相符。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生不能担任校长，与“校长”的身份不符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不能担任校长，与“校长”的身份不符。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：“司机校长”不是常见的职务搭配，不能这样修饰“校长”。"}], "explanations": {"下任": "正确：“下任”指接替现任的人，与“校长下个月就要来了”的语境相符。", "小学生": "语义：小学生不能担任校长，与“校长”的身份不符。", "厨师": "语义：厨师不能担任校长，与“校长”的身份不符。", "司机": "搭配：“司机校长”不是常见的职务搭配，不能这样修饰“校长”。"}, "sentence_index": 0, "correct_answer": "下任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位下任经理正在任上，每天处理公司事务。", "explanation": "这里应该用〈现任〉。下任指还没上任、等着接替别人的人，已经在职位上工作的人要用〈现任〉。"}, {"text": "这位下任市长已经当了五年市长。", "explanation": "这里应该用〈现任〉。下任指还没上任的接班人，不可能已经当了五年。"}, {"text": "我们公司新来了一件下任。", "explanation": "这里应该用〈位〉或〈个〉。下任指人，量词要用“位”或“个”，不能用“件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87743, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下任", "is_correct": true, "explanation": "正确：“下任”指接替现任的人，可以“交给”他人接替工作。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不能接受工作，与“交给了”的语境不合。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“交给”的对象必须是人，窗户不能作为接收工作的对象。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能接受工作，与“把工作都交给了”的语境矛盾。"}], "explanations": {"下任": "正确：“下任”指接替现任的人，可以“交给”他人接替工作。", "垃圾": "语义：垃圾不能接受工作，与“交给了”的语境不合。", "窗户": "配价：“交给”的对象必须是人，窗户不能作为接收工作的对象。", "钥匙": "语义：钥匙不能接受工作，与“把工作都交给了”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "下任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那部下任今天来学校了。", "explanation": "这里应该用〈位〉。下任指人，“部”用于书籍、电影等，不能用于人。"}, {"text": "我们学校来了一只下任。", "explanation": "这里应该用〈位〉。“只”用于动物，不能用于指人的下任。"}, {"text": "他是我们的下任老板，去年就离开公司了。", "explanation": "这里应该用〈前任〉。下任还没上任，已经离开的是前任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87743, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只下任下周就来公司报到。", "corrected_sentence": "那位下任下周就来公司报到。", "error_description": "错误：“那只下任”，“只”多用于动物，指人应用量词“位”或“个”。正确：“那位下任”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87743, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "谁来当下任了班长呢？", "corrected_sentence": "谁来当下任班长呢？", "error_description": "错误：“下任了班长”，“了”加在了名词“下任”后面。“下任”是名词，不能带“了”。正确：去掉“了”，说“下任班长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
