INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87744, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "接任某职务的下一个人；下一任。", "primary_collocate": null, "pronunciation": "xià rèn", "ipa": "ɕja˥˩ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "下任市长今天上午见了记者。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被大家选为下任会长。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老校长正在给下任写一封信。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁会是下任总经理，还没有人知道。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现任队长希望下任更努力。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在学习，想做下任主任。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下任老师明天就来学校了。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把钥匙留给了下任。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司已经定了下任经理。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下任部长对这件事很重视。", "target_word": "下任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "下任|接任某职务的下一个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2ad337-3c61-49c3-aacc-f67cc219fb9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下任", "is_correct": true, "explanation": "正确：“下任”指接任某职务的下一个人，与“市长今天上午见了记者”的语境相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不能担任市长，与“市长”的身份不符。"}, {"text": "护士", "is_correct": false, "explanation": "搭配：“护士市长”不是常见的职务搭配，不能这样修饰“市长”。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员不能直接担任市长，与“市长”的身份不符。"}], "explanations": {"下任": "正确：“下任”指接任某职务的下一个人，与“市长今天上午见了记者”的语境相符。", "厨师": "语义：厨师不能担任市长，与“市长”的身份不符。", "护士": "搭配：“护士市长”不是常见的职务搭配，不能这样修饰“市长”。", "演员": "语义：演员不能直接担任市长，与“市长”的身份不符。"}, "sentence_index": 0, "correct_answer": "下任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下任会长去年就已经卸任了。", "explanation": "这里应该用〈前任〉。下任还没有上任，不可能去年就卸任。"}, {"text": "我们公司来了一辆下任。", "explanation": "这里应该用〈位〉。“辆”用于车辆，下任指人，不能用“辆”。"}, {"text": "下任会长已经在这个位子上干了十年。", "explanation": "这里应该用〈现任〉。下任还没有上任，不可能已经干了十年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下任", "is_correct": true, "explanation": "正确：“下任”指接替现任的人，与“下任老师明天就来学校了”的语境相符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机不是老师，与“老师”的职务不符。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生与老师是两种不同的职业，句子表示的是接任的老师。"}, {"text": "战士", "is_correct": false, "explanation": "搭配：“战士老师”不是常见的职务搭配，不能这样修饰“老师”。"}], "explanations": {"下任": "正确：“下任”指接替现任的人，与“下任老师明天就来学校了”的语境相符。", "司机": "语义：司机不是老师，与“老师”的职务不符。", "医生": "语义：医生与老师是两种不同的职业，句子表示的是接任的老师。", "战士": "搭配：“战士老师”不是常见的职务搭配，不能这样修饰“老师”。"}, "sentence_index": 6, "correct_answer": "下任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只下任明天就来学校了。", "explanation": "这里应该用〈位〉。“只”用于动物，下任指人，不能用“只”。"}, {"text": "那张下任很有名。", "explanation": "这里应该用〈位〉。“张”用于纸张、桌子等，不能用于指人的下任。"}, {"text": "下任部长去年就退休了。", "explanation": "这里应该用〈前任〉。下任还没上任，已经退休的是前任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校选出了一位下任了校长。", "corrected_sentence": "学校选出了一位下任校长。", "error_description": "错误：“下任了校长”，“了”加在了名词“下任”后面。正确：“下任校长”，中间不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那把下任下个月就来学校。", "corrected_sentence": "那位下任下个月就来学校。", "error_description": "错误：“那把下任”，“把”多用于有柄的器物，指人应用量词“位”或“个”。正确：“那位下任”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
