INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87745, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "票是一张小纸，拿着它可以进去或者坐车。", "primary_collocate": null, "pronunciation": "piào", "ipa": "pʰjɑʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "我的票在包里，你别担心。", "target_word": "票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我看一下你的票。", "target_word": "票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张票多少钱？", "target_word": "票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了两张票，我们一起去看电影。", "target_word": "票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把票给他看。", "target_word": "票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的票丢了，进不去电影院。", "target_word": "票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天的票已经卖完了。", "target_word": "票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有票吗？没有票不能进去。", "target_word": "票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张票是去北京的。", "target_word": "票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友的票只要十块钱。", "target_word": "票", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "车票", "label": "复合"}, {"form": "门票", "label": "复合"}], "register": "中性", "sense_fingerprint": "小纸片凭证，拿着可进场或乘车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fcb4ee2-f2e1-4070-afe6-cb4d17410cdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87745, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "票", "is_correct": true, "explanation": "票（piào，第四声）：正确答案，指凭它入场或乘车的小纸片。"}, {"text": "飘", "is_correct": false, "explanation": "piāo（第一声）与 piào（第四声）声调不同，意思是飘（浮在空中）。"}, {"text": "瓢", "is_correct": false, "explanation": "piáo（第二声）与 piào（第四声）声调不同，意思是瓢（舀水的器具）。"}, {"text": "瞟", "is_correct": false, "explanation": "piǎo（第三声）与 piào（第四声）声调不同，意思是瞟（看一眼）。"}], "explanations": {"票": "票（piào，第四声）：正确答案，指凭它入场或乘车的小纸片。", "飘": "piāo（第一声）与 piào（第四声）声调不同，意思是飘（浮在空中）。", "瓢": "piáo（第二声）与 piào（第四声）声调不同，意思是瓢（舀水的器具）。", "瞟": "piǎo（第三声）与 piào（第四声）声调不同，意思是瞟（看一眼）。"}, "sentence_index": null, "correct_answer": "票"}, "level_3": {"options": [{"text": "票", "is_correct": true, "explanation": "票：指入场或乘车用的凭证，可以放进包里，符合句意。"}, {"text": "车", "is_correct": false, "explanation": "语义：车太大，不能放进包里，句子说不通。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能放进包里，句子说不通。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不能说“在包里”。"}], "explanations": {"票": "票：指入场或乘车用的凭证，可以放进包里，符合句意。", "车": "语义：车太大，不能放进包里，句子说不通。", "太阳": "语义：太阳是天体，不能放进包里，句子说不通。", "老师": "语义：老师是人，不能说“在包里”。"}, "sentence_index": 0, "correct_answer": "票"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去银行办了一张银行票，取钱很方便。", "explanation": "这里应该用〈银行卡〉。票指入场或乘车的凭证，办理银行业务要用银行卡。"}, {"text": "他忘带身份票，进不去大楼。", "explanation": "这里应该用〈身份证〉。票是入场、乘车的凭证，证明身份要用身份证。"}, {"text": "他忘了带票，没法证明自己是员工。", "explanation": "这里应该用〈证件〉。票是入场或乘车的凭证，不能用来证明身份，要用证件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "票", "is_correct": true, "explanation": "票：指可以买卖的入场凭证，“卖完”说的是票，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能买卖，也不能“卖完”。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：脸是人的外貌，不能说“卖完”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是商品，不能说“卖完”。"}], "explanations": {"票": "票：指可以买卖的入场凭证，“卖完”说的是票，符合句意。", "天气": "语义：天气不能买卖，也不能“卖完”。", "脸": "体貌：脸是人的外貌，不能说“卖完”。", "空气": "语义：空气不是商品，不能说“卖完”。"}, "sentence_index": 6, "correct_answer": "票"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他忘了带票，开不了房门。", "explanation": "这里应该用〈钥匙〉。票是入场或乘车的凭证，不能用来开门，开门要用钥匙。"}, {"text": "他买了一张电话票，就给家里打了电话。", "explanation": "这里应该用〈电话卡〉。票是入场或乘车的凭证，打电话要用电话卡。"}, {"text": "他用一张票把门锁上了。", "explanation": "这里应该用〈锁〉。票是纸片，不能用来锁门，锁门要用锁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一本电影票，就进去了。", "corrected_sentence": "他买了一张电影票，就进去了。", "error_description": "量词错误：“票”应该用“张”，“本”用于书、本子等成册的东西，不能说“一本电影票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每人都买了一把票。", "corrected_sentence": "我们每人都买了一张票。", "error_description": "量词错误：“票”应该用“张”，“把”用于有柄的东西，不能说“一把票”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
