INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87747, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "附近是离这里不远的地方。", "primary_collocate": null, "pronunciation": "fù jìn", "ipa": "fu˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "这附近有一个很大的公园。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这附近有银行吗？", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "附近有一家小店，卖早饭。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们就在附近吃午饭吧。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他就住在附近，走路五分钟就到。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这附近没有地铁站，你得坐公共汽车。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在附近找了半天，也没找到厕所。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "附近的人都认识这位老医生。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道附近哪里有好吃的饭馆吗？", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我在附近看到了一只白猫。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "离说话人所在处不远的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e08ad9-0b97-4081-94ef-5f5d51ef7e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87747, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "附近", "is_correct": true, "explanation": "正确。附近指离说话人所在处不远的地方。"}, {"text": "费尽", "is_correct": false, "explanation": "fèi（第四声）与 fù（第四声）韵母不同：ei 与 u。费尽意思是用尽力气，不指地点。"}, {"text": "复信", "is_correct": false, "explanation": "xìn 与 jìn 声母不同（x 与 j）。复信意思是回信，不指地点。"}, {"text": "附件", "is_correct": false, "explanation": "jiàn 与 jìn 韵母不同（ian 与 in）。附件意思是附带的文件，不指地点。"}, {"text": "复印", "is_correct": false, "explanation": "yìn 与 jìn 声母不同（y 与 j）。复印意思是复制文件，不指地点。"}], "explanations": {"附近": "正确。附近指离说话人所在处不远的地方。", "费尽": "fèi（第四声）与 fù（第四声）韵母不同：ei 与 u。费尽意思是用尽力气，不指地点。", "复信": "xìn 与 jìn 声母不同（x 与 j）。复信意思是回信，不指地点。", "附件": "jiàn 与 jìn 韵母不同（ian 与 in）。附件意思是附带的文件，不指地点。", "复印": "yìn 与 jìn 声母不同（y 与 j）。复印意思是复制文件，不指地点。"}, "sentence_index": null, "correct_answer": "附近"}, "level_3": {"options": [{"text": "附近", "is_correct": true, "explanation": "正确。“这附近”指离这里不远的地方，“这附近有一个很大的公园”通顺自然。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子很小，里面不可能有公园。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是文具，“这铅笔有一个很大的公园”说不通。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不能有公园。"}], "explanations": {"附近": "正确。“这附近”指离这里不远的地方，“这附近有一个很大的公园”通顺自然。", "杯子": "语义：杯子很小，里面不可能有公园。", "铅笔": "语义：铅笔是文具，“这铅笔有一个很大的公园”说不通。", "苹果": "语义：苹果是水果，不能有公园。"}, "sentence_index": 0, "correct_answer": "附近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张支票的金额是五千元附近。", "explanation": "这里不应该用〈附近〉。“附近”只指地点，不能用在数目后面，应直接说“是五千元”。"}, {"text": "我把护照放进附近，出门前却找不到了。", "explanation": "这里应该用〈里〉。“放进”后要接能容纳东西的地方，“附近”指周围一带，不是可以装东西的空间，应说“放进抽屉里”。"}, {"text": "他把钱交给附近，然后就走了。", "explanation": "这里应该用〈人〉。“交给”的对象应是人，“附近”指地点，不能直接作接受者，应说“交给旁边的人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87747, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "附近", "is_correct": true, "explanation": "正确。附近指离说话人所在处不远的地方。"}, {"text": "费劲", "is_correct": false, "explanation": "fèi（第四声）与 fù（第四声）韵母不同：ei 与 u。费劲意思是吃力、费力气，不指地点。"}, {"text": "附信", "is_correct": false, "explanation": "xìn 与 jìn 声母不同（x 与 j）。附信意思是附在文件后的信，不指地点。"}, {"text": "复健", "is_correct": false, "explanation": "jiàn 与 jìn 韵母不同（ian 与 in）。复健意思是康复训练，不指地点。"}], "explanations": {"附近": "正确。附近指离说话人所在处不远的地方。", "费劲": "fèi（第四声）与 fù（第四声）韵母不同：ei 与 u。费劲意思是吃力、费力气，不指地点。", "附信": "xìn 与 jìn 声母不同（x 与 j）。附信意思是附在文件后的信，不指地点。", "复健": "jiàn 与 jìn 韵母不同（ian 与 in）。复健意思是康复训练，不指地点。"}, "sentence_index": null, "correct_answer": "附近"}, "level_3": {"options": [{"text": "附近", "is_correct": true, "explanation": "正确。“附近”表示找的范围在厕所可能所在的周围一带，与“找了半天”相符。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌上不可能找到厕所，“在书桌找厕所”语义冲突。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是书，里面不会有厕所，“在词典找了半天”语义冲突。"}, {"text": "书包", "is_correct": false, "explanation": "语义：厕所不会在书包里，“我在书包找了半天，也没找到厕所”语义冲突。"}], "explanations": {"附近": "正确。“附近”表示找的范围在厕所可能所在的周围一带，与“找了半天”相符。", "书桌": "语义：书桌上不可能找到厕所，“在书桌找厕所”语义冲突。", "词典": "语义：词典是书，里面不会有厕所，“在词典找了半天”语义冲突。", "书包": "语义：厕所不会在书包里，“我在书包找了半天，也没找到厕所”语义冲突。"}, "sentence_index": 6, "correct_answer": "附近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的生日是十月一日附近。", "explanation": "这里不应该用〈附近〉。“附近”只指地点，不能用在日期后面，应说“是十月一日”。"}, {"text": "我的护照号码是三一六五二附近，请仔细核对。", "explanation": "这里不应该用〈附近〉。“附近”只指地点，不能用在号码后面，应直接说“是三一六五二”。"}, {"text": "我给附近写了一封信，告诉他我很好。", "explanation": "这里应该用〈人〉。“写信给”的对象应是人，“附近”指地点，不能直接作收信人，应说“写信给旁边的人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的公司离学校附近。", "corrected_sentence": "他的公司在学校附近。", "error_description": "错误形式：“他的公司离学校附近”；正确形式：“他的公司在学校附近”。“离”表示与某处相距多远，不能与“附近”组成表示位置的短语；表示位置应用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆离医院附近。", "corrected_sentence": "图书馆在医院附近。", "error_description": "错误形式：“图书馆离医院附近”；正确形式：“图书馆在医院附近”。“离”表示与某处相距多远，不能与“附近”组成表示位置的短语；表示位置应用“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
