INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87748, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87748, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "靠近某个地方的地方；周围。", "primary_collocate": null, "pronunciation": "fù jìn", "ipa": "fu˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "车站附近总是有很多人。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院附近很安静，没有什么车。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河附近的草地上，开着很多花。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车停在商店附近。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山附近有几个小村子。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司附近新开了一家书店。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车站附近的路很窄，车开不快。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校附近不能放鞭炮。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在公园附近走了一圈。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家在北京附近，坐车一小时就到。", "target_word": "附近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "靠近某个地点的周围地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e08ad9-0b97-4081-94ef-5f5d51ef7e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87748, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "附近", "is_correct": true, "explanation": "正确。附近指靠近某个地点的周围。"}, {"text": "费尽", "is_correct": false, "explanation": "fèi（第四声）与 fù（第四声）韵母不同：ei 与 u。费尽意思是用尽力气，不指地点。"}, {"text": "复信", "is_correct": false, "explanation": "xìn 与 jìn 声母不同（x 与 j）。复信意思是回信，不指地点。"}, {"text": "附件", "is_correct": false, "explanation": "jiàn 与 jìn 韵母不同（ian 与 in）。附件意思是附带的文件，不指地点。"}, {"text": "复印", "is_correct": false, "explanation": "yìn 与 jìn 声母不同（y 与 j）。复印意思是复制文件，不指地点。"}], "explanations": {"附近": "正确。附近指靠近某个地点的周围。", "费尽": "fèi（第四声）与 fù（第四声）韵母不同：ei 与 u。费尽意思是用尽力气，不指地点。", "复信": "xìn 与 jìn 声母不同（x 与 j）。复信意思是回信，不指地点。", "附件": "jiàn 与 jìn 韵母不同（ian 与 in）。附件意思是附带的文件，不指地点。", "复印": "yìn 与 jìn 声母不同（y 与 j）。复印意思是复制文件，不指地点。"}, "sentence_index": null, "correct_answer": "附近"}, "level_3": {"options": [{"text": "附近", "is_correct": true, "explanation": "正确。“附近”指车站周围的地方，符合“总是有很多人”的描述。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底没有很多人，与“车站”的人群场景冲突。"}, {"text": "月球", "is_correct": false, "explanation": "语义：月球上人很少，“月球附近总是有很多人”与事实不符。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“书包”不是能聚集很多人的场所，“书包附近”不能作为人群聚集的地点。"}], "explanations": {"附近": "正确。“附近”指车站周围的地方，符合“总是有很多人”的描述。", "海底": "语义：海底没有很多人，与“车站”的人群场景冲突。", "月球": "语义：月球上人很少，“月球附近总是有很多人”与事实不符。", "书包": "搭配：“书包”不是能聚集很多人的场所，“书包附近”不能作为人群聚集的地点。"}, "sentence_index": 0, "correct_answer": "附近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身份证号码是三二一附近，请仔细核对。", "explanation": "这里不应该用〈附近〉。“附近”只指某地周围的地方，不能用在号码后面，应直接说“是三二一”。"}, {"text": "我把钥匙放进附近，谁也找不到。", "explanation": "这里应该用〈里〉。“放进”后要接能容纳东西的地方，“附近”只指周围一带，不是可以装东西的空间，应说“放进抽屉里”。"}, {"text": "他把那封信寄给了附近，然后就走了。", "explanation": "这里应该用〈人〉。“寄给”的对象应是人，“附近”指地点，不能直接作收信人，应说“寄给旁边的人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87748, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "附近", "is_correct": true, "explanation": "正确。附近指靠近某个地点的周围。"}, {"text": "费劲", "is_correct": false, "explanation": "fèi（第四声）与 fù（第四声）韵母不同：ei 与 u。费劲意思是吃力、费力气，不指地点。"}, {"text": "附信", "is_correct": false, "explanation": "xìn 与 jìn 声母不同（x 与 j）。附信意思是附在文件后的信，不指地点。"}, {"text": "复健", "is_correct": false, "explanation": "jiàn 与 jìn 韵母不同（ian 与 in）。复健意思是康复训练，不指地点。"}], "explanations": {"附近": "正确。附近指靠近某个地点的周围。", "费劲": "fèi（第四声）与 fù（第四声）韵母不同：ei 与 u。费劲意思是吃力、费力气，不指地点。", "附信": "xìn 与 jìn 声母不同（x 与 j）。附信意思是附在文件后的信，不指地点。", "复健": "jiàn 与 jìn 韵母不同（ian 与 in）。复健意思是康复训练，不指地点。"}, "sentence_index": null, "correct_answer": "附近"}, "level_3": {"options": [{"text": "附近", "is_correct": true, "explanation": "正确。“附近”指火车站周围的路，符合“路很窄，车开不快”的描述。"}, {"text": "天空", "is_correct": false, "explanation": "语义：路不在天空上，“天空附近的路很窄”与语境冲突。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：抽屉是柜子的一部分，“抽屉附近的路很窄，车开不快”说不通。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“课本”不能作为路的参照地点，“课本附近的路”不成立。"}], "explanations": {"附近": "正确。“附近”指火车站周围的路，符合“路很窄，车开不快”的描述。", "天空": "语义：路不在天空上，“天空附近的路很窄”与语境冲突。", "抽屉": "语义：抽屉是柜子的一部分，“抽屉附近的路很窄，车开不快”说不通。", "课本": "搭配：“课本”不能作为路的参照地点，“课本附近的路”不成立。"}, "sentence_index": 6, "correct_answer": "附近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张票的座位号是十二排附近。", "explanation": "这里不应该用〈附近〉。“附近”只指某地周围的地方，不能用在座位号后面，应说“是十二排”。"}, {"text": "这箱苹果的重量是五斤附近，正好称准了。", "explanation": "这里不应该用〈附近〉。“附近”只指地点，不能用在重量后面，应说“正好五斤”。"}, {"text": "我家到车站的距离恰好是一公里附近，精确地量过了。", "explanation": "这里不应该用〈附近〉。“附近”只指地点，不能用在距离数字后面，应说“恰好是一公里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们走公园附近了。", "corrected_sentence": "我们走到公园附近了。", "error_description": "错误形式：“我们走公园附近了”；正确形式：“我们走到公园附近了”。表示移动到某处时，“走”后要用“到”引出目的地，缺少“到”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的学校离书店附近。", "corrected_sentence": "他的学校在书店附近。", "error_description": "错误形式：“他的学校离书店附近”；正确形式：“他的学校在书店附近”。“离”表示与某处相距多远，不能与“附近”组成表示位置的短语；表示位置应用“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b191c03-bb58-4047-9fd1-b5a24eda03ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87749, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "原生", "is_correct": true, "explanation": "正确：“原生”与“次生”相对，指未受破坏、原来的植被。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：“柔软”形容质地松软，与“次生”没有反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "无关：“宽阔”形容面积大，与“次生”没有反义关系。"}, {"text": "陈旧", "is_correct": false, "explanation": "无关：“陈旧”指时间久、不新鲜，与“次生”的重新形成不构成反义。"}], "correct_answer": "原生", "explanations": {"原生": "正确：“原生”与“次生”相对，指未受破坏、原来的植被。", "柔软": "无关：“柔软”形容质地松软，与“次生”没有反义关系。", "宽阔": "无关：“宽阔”形容面积大，与“次生”没有反义关系。", "陈旧": "无关：“陈旧”指时间久、不新鲜，与“次生”的重新形成不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87749, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "原生", "is_correct": true, "explanation": "正确：“原生”与“次生”相对，指未受破坏、原来的植被。"}, {"text": "轻盈", "is_correct": false, "explanation": "无关：“轻盈”形容身体或物体的轻巧，与“次生”没有反义关系。"}, {"text": "寂寞", "is_correct": false, "explanation": "无关：“寂寞”形容心情，与“次生”没有反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "无关：“狭窄”形容空间小，与“次生”没有反义关系。"}], "correct_answer": "原生", "explanations": {"原生": "正确：“原生”与“次生”相对，指未受破坏、原来的植被。", "轻盈": "无关：“轻盈”形容身体或物体的轻巧，与“次生”没有反义关系。", "寂寞": "无关：“寂寞”形容心情，与“次生”没有反义关系。", "狭窄": "无关：“狭窄”形容空间小，与“次生”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87749, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "次生是后来才出来的，不是第一次长出来的。", "primary_collocate": null, "pronunciation": "cì shēng", "ipa": "tsʰɨ˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这片树林是次生的，不是原来的。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的树大多是次生的。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原始森林被砍掉后，长出了次生的树。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的草是次生的，不是原来就有的。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾以后，山坡上长出次生的小树。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的树都是次生的。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "次生的树长得比较矮。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这片森林是次生的。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些次生的小树长得很快。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老树被砍光了，现在这里都是次生的树。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次生的", "label": "的字结构"}], "register": "书面", "sense_fingerprint": "次生：原来的被破坏后，后来重新长出来的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c338676-2383-4c9c-9a7a-bdb10f081010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87749, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "次生", "is_correct": true, "explanation": "正确：次生指原来的植被被破坏后，后来重新长出来的。"}, {"text": "此生", "is_correct": false, "explanation": "此生与次生的第一个字声调不同，此生是第三声，次生是第四声，意思是这一辈子。"}, {"text": "刺身", "is_correct": false, "explanation": "刺身与次生的第二个字韵母不同，只差一个鼻音，意思是生鱼片。"}, {"text": "四声", "is_correct": false, "explanation": "四声与次生的第一个字声母不同，s 与 c 不同，意思是汉语的四个声调。"}], "explanations": {"次生": "正确：次生指原来的植被被破坏后，后来重新长出来的。", "此生": "此生与次生的第一个字声调不同，此生是第三声，次生是第四声，意思是这一辈子。", "刺身": "刺身与次生的第二个字韵母不同，只差一个鼻音，意思是生鱼片。", "四声": "四声与次生的第一个字声母不同，s 与 c 不同，意思是汉语的四个声调。"}, "sentence_index": null, "correct_answer": "次生"}, "level_3": {"options": [{"text": "次生", "is_correct": true, "explanation": "正确：“次生”指后来重新长出来的，与“不是原来的”相合。"}, {"text": "原生", "is_correct": false, "explanation": "语义：“原生”与“原来的”同义，句子说“不是原来的”，前后矛盾。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“勇敢”形容人的品质，不能形容树林。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”说的是价格高，不能用来修饰树林的性质。"}], "explanations": {"次生": "正确：“次生”指后来重新长出来的，与“不是原来的”相合。", "原生": "语义：“原生”与“原来的”同义，句子说“不是原来的”，前后矛盾。", "勇敢": "搭配：“勇敢”形容人的品质，不能形容树林。", "昂贵": "语义：“昂贵”说的是价格高，不能用来修饰树林的性质。"}, "sentence_index": 0, "correct_answer": "次生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间房子是次生的，是今年新盖的。", "explanation": "这里应该用〈新建〉。次生指植被被破坏后重新长出，只用于树林、草地等，不用于房屋。"}, {"text": "这条路是次生的，是去年才铺好的。", "explanation": "这里应该用〈新修〉。次生指植被被破坏后重新长出，不用于道路等人造物。"}, {"text": "这片森林是次生的，从来没有人砍过。", "explanation": "这里应该用〈原生〉。次生以原有植被被破坏为前提，句中说从没被砍过，应说原生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87749, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次生", "is_correct": true, "explanation": "正确：“次生的树”指后来重新长出的树，与句子的描述相合。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”与“长得比较矮”互相矛盾。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不用来描述树的高矮。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”形容味道，不能用来修饰树。"}], "explanations": {"次生": "正确：“次生的树”指后来重新长出的树，与句子的描述相合。", "高大": "语义：“高大”与“长得比较矮”互相矛盾。", "响亮": "搭配：“响亮”形容声音，不用来描述树的高矮。", "辛辣": "语义：“辛辣”形容味道，不能用来修饰树。"}, "sentence_index": 6, "correct_answer": "次生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个杯子是次生的，是昨天才买的。", "explanation": "这里应该用〈新买〉。次生只用于植被或生态的重新形成，不用于日用品。"}, {"text": "这只熊猫是次生的，一直生活在山林里。", "explanation": "这里应该用〈野生〉。次生只用于植被或生态的重新形成，不用来说动物。"}, {"text": "他的写作水平是次生的，是靠多年练习得来的。", "explanation": "这里应该用〈后天〉。次生指生态被破坏后重新形成，不用于人的能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87749, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大火烧过以后，山上又长出了许多次生地树。", "corrected_sentence": "大火烧过以后，山上又长出了许多次生的树。", "error_description": "错误：“许多次生地树”；正确：“许多次生的树”。“次生”作定语修饰名词，应用“的”；“地”是状语标记，不能用于定语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87749, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些树很次生的，长得很快。", "corrected_sentence": "这些树是次生的，长得很快。", "error_description": "错误：“很次生的”；正确：“是次生的”。“次生”表示成因类别，不能用程度副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87750, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "原生", "is_correct": true, "explanation": "正确：“原生”与“次生”相对，指未经派生、本来就有的。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：“柔软”形容质地，与“次生”没有反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "无关：“宽阔”形容面积大，与“次生”没有反义关系。"}, {"text": "陈旧", "is_correct": false, "explanation": "无关：“陈旧”指时间久，与“次生”的派生义没有反义关系。"}], "correct_answer": "原生", "explanations": {"原生": "正确：“原生”与“次生”相对，指未经派生、本来就有的。", "柔软": "无关：“柔软”形容质地，与“次生”没有反义关系。", "宽阔": "无关：“宽阔”形容面积大，与“次生”没有反义关系。", "陈旧": "无关：“陈旧”指时间久，与“次生”的派生义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
