INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87750, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由原生的事物引起或派生出来的，第二次形成的。", "primary_collocate": null, "pronunciation": "cì shēng", "ipa": "tsʰɨ˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "地震后还可能出现次生灾害。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂倒了以后，漏油造成次生污染。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震引起的火灾是次生灾害。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨之后，山上的石头滑下来，这是次生灾害。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水以后的疾病也是次生灾害。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家提醒大家，要小心次生灾害。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种矿物是次生的，由别的石头变来。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震本身是原生的，火灾是次生的。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "次生灾害有时比地震更可怕。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路被冲坏了，这是大雨带来的次生问题。", "target_word": "次生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次生的", "label": "的字结构"}], "register": "书面", "sense_fingerprint": "次生：由原生事物引发或派生的，第二次形成的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c338676-2383-4c9c-9a7a-bdb10f081010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87750, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "次生", "is_correct": true, "explanation": "正确：次生指由原生事物引起或派生的，第二次形成的。"}, {"text": "此生", "is_correct": false, "explanation": "此生与次生的第一个字声调不同，此生是第三声，次生是第四声，意思是这一辈子。"}, {"text": "刺身", "is_correct": false, "explanation": "刺身与次生的第二个字韵母不同，只差一个鼻音，意思是生鱼片。"}, {"text": "四声", "is_correct": false, "explanation": "四声与次生的第一个字声母不同，s 与 c 不同，意思是汉语的四个声调。"}], "explanations": {"次生": "正确：次生指由原生事物引起或派生的，第二次形成的。", "此生": "此生与次生的第一个字声调不同，此生是第三声，次生是第四声，意思是这一辈子。", "刺身": "刺身与次生的第二个字韵母不同，只差一个鼻音，意思是生鱼片。", "四声": "四声与次生的第一个字声母不同，s 与 c 不同，意思是汉语的四个声调。"}, "sentence_index": null, "correct_answer": "次生"}, "level_3": {"options": [{"text": "次生", "is_correct": true, "explanation": "正确：地震引发的灾害称“次生灾害”，与句意相合。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”形容感情，与“灾害”的感情色彩冲突。"}, {"text": "生动", "is_correct": false, "explanation": "搭配：“生动”修饰语言、画面，不修饰灾害。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”形容心情或状态，不能修饰“灾害”，句意不通。"}], "explanations": {"次生": "正确：地震引发的灾害称“次生灾害”，与句意相合。", "甜蜜": "语义：“甜蜜”形容感情，与“灾害”的感情色彩冲突。", "生动": "搭配：“生动”修饰语言、画面，不修饰灾害。", "轻松": "语义：“轻松”形容心情或状态，不能修饰“灾害”，句意不通。"}, "sentence_index": 0, "correct_answer": "次生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的性格是次生的，从小就这样。", "explanation": "这里应该用〈先天〉。次生指由别的事物引起或派生，天生的性格不能说次生。"}, {"text": "这个方案是次生的，是我们最先想出来的。", "explanation": "这里应该用〈原创〉。次生指由别的事物派生出来的，最先想出的方案应说原创。"}, {"text": "地震本身是次生的，不会引起别的灾害。", "explanation": "这里应该用〈原生〉。地震本身不是由别的事物引起的，应说原生；次生指派生的，不能用于地震本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次生", "is_correct": true, "explanation": "正确：“次生”指由别的矿物变来，与“由别的石头变来”相合。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：矿物不能聪明，句意不通。"}, {"text": "柔弱", "is_correct": false, "explanation": "语义：“柔弱”形容人或植物的性质，不能说明矿物的成因。"}, {"text": "辛勤", "is_correct": false, "explanation": "搭配：“辛勤”形容人的劳动态度，不修饰矿物。"}], "explanations": {"次生": "正确：“次生”指由别的矿物变来，与“由别的石头变来”相合。", "聪明": "语义：矿物不能聪明，句意不通。", "柔弱": "语义：“柔弱”形容人或植物的性质，不能说明矿物的成因。", "辛勤": "搭配：“辛勤”形容人的劳动态度，不修饰矿物。"}, "sentence_index": 6, "correct_answer": "次生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子是次生的，是最近才盖的。", "explanation": "这里应该用〈新建〉。次生指由别的事物引起或派生，不用于新盖的房屋。"}, {"text": "这只熊猫是次生的，一直生活在山林里。", "explanation": "这里应该用〈野生〉。次生用于生态或植被的衍生与重新形成，不用来说动物。"}, {"text": "他的写作水平是次生的，是靠多年练习得来的。", "explanation": "这里应该用〈后天〉。次生指由别的事物派生，不用于人的能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暴雨引发了山体滑坡，这次生灾害。", "corrected_sentence": "暴雨引发了山体滑坡，这是次生灾害。", "error_description": "错误：“这次生灾害”；正确：“这是次生灾害”。“次生灾害”作判断句的谓语，需要“是”引出；删去后“这”与“次生”直接相连，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
