INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87751, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "下飞机是从飞机上走下来。", "primary_collocate": null, "pronunciation": "xià fēi jī", "ipa": "ɕja˥˩ fei˥ tɕi˥", "syllable_count": 3, "sentences": [{"text": "飞机到了北京，我一下飞机就给妈妈打电话。", "target_word": "下飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家慢点儿下飞机，小心台阶。", "target_word": "下飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空姐站在门口，笑着请乘客下飞机。", "target_word": "下飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人下飞机很慢，空姐一直扶着他。", "target_word": "下飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机停好了，乘客们一个一个下飞机。", "target_word": "下飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下飞机以后，你先去哪儿拿行李？", "target_word": "下飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乘客都站在过道里，等着下飞机。", "target_word": "下飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一下飞机，接机的朋友就向他招手。", "target_word": "下飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们下飞机后，在机场坐地铁去酒店。", "target_word": "下飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统下飞机时，很多记者在机场等他。", "target_word": "下飞机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下了飞机", "label": "体标（了）"}, {"form": "下过飞机", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "乘客走出机舱、从飞机上走下来的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19caa3-16e4-4fcd-a031-4c3dbc5187f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87751, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下飞机", "is_correct": true, "explanation": "正确。“下飞机”指从飞机上走下来，与前文“飞机到了北京”相符。"}, {"text": "下车", "is_correct": false, "explanation": "搭配：“下车”用于汽车、公交等地面交通工具，不能与前文的“飞机”搭配。"}, {"text": "下船", "is_correct": false, "explanation": "语义：前文说的是飞机，不是船，所以不能说“下船”。"}, {"text": "下火车", "is_correct": false, "explanation": "语义：前文说的是飞机，不是火车，所以不能说“下火车”。"}], "explanations": {"下飞机": "正确。“下飞机”指从飞机上走下来，与前文“飞机到了北京”相符。", "下车": "搭配：“下车”用于汽车、公交等地面交通工具，不能与前文的“飞机”搭配。", "下船": "语义：前文说的是飞机，不是船，所以不能说“下船”。", "下火车": "语义：前文说的是飞机，不是火车，所以不能说“下火车”。"}, "sentence_index": 0, "correct_answer": "下飞机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公交车到站了，大家一个一个下飞机。", "explanation": "这里应该用〈下车〉。“下飞机”只用于从飞机上下来，公交车上的人要说“下车”。"}, {"text": "轮船靠岸了，游客们陆续下飞机。", "explanation": "这里应该用〈下船〉。“下飞机”只用于飞机，从轮船上下来要说“下船”。"}, {"text": "火车进站了，我们在月台上下飞机。", "explanation": "这里应该用〈下火车〉。“下飞机”指从飞机上下来，从火车上下来要说“下火车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下飞机", "is_correct": true, "explanation": "正确。“等着下飞机”是乘客等待从飞机上下来，与前文“站在过道里”相符。"}, {"text": "躺下", "is_correct": false, "explanation": "语义：前文说乘客“站在过道里”，他们是站着等的，不能“等着躺下”。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：站在过道里排队等候，与“跳舞”无关，句意不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”需要浴室或淋浴设施，不能与“站在过道里”搭配。"}], "explanations": {"下飞机": "正确。“等着下飞机”是乘客等待从飞机上下来，与前文“站在过道里”相符。", "躺下": "语义：前文说乘客“站在过道里”，他们是站着等的，不能“等着躺下”。", "跳舞": "语义：站在过道里排队等候，与“跳舞”无关，句意不通。", "洗澡": "搭配：“洗澡”需要浴室或淋浴设施，不能与“站在过道里”搭配。"}, "sentence_index": 6, "correct_answer": "下飞机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们正在把货物下飞机。", "explanation": "这里应该用〈卸下〉。“下飞机”是人自己从飞机上走下来，不能带宾语表示把东西搬下来，应说“把货物从飞机上卸下来”。"}, {"text": "出租车停了，他付了钱就下飞机。", "explanation": "这里应该用〈下车〉。“下飞机”只用于从飞机上下来，从出租车上下来要说“下车”。"}, {"text": "请你帮我把行李箱下飞机。", "explanation": "这里应该用〈拿下〉。“下飞机”不能带宾语，行李要说“从飞机上拿下来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下飞机着就去拿行李。", "corrected_sentence": "我下飞机后就去拿行李。", "error_description": "错误在于体标“着”：“下飞机”是一次性完成的动作，不能用“着”表示动作持续，应说“下飞机后”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下飞机过，就病倒了。", "corrected_sentence": "他下飞机后，就病倒了。", "error_description": "错误在于体标“过”：“过”应紧跟动词，且此处表示先后，应说“下飞机后”；“下飞机过”把“过”放在了宾语后面，是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87754, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87754, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在对事情进行分析、研究之后得出的最后判断。", "primary_collocate": null, "pronunciation": "jié lùn", "ipa": "tɕjɛ˧˥ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "研究结果出来了，结论很清楚。", "target_word": "结论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看了检查报告，得出了结论。", "target_word": "结论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告的结论是，空气变好了。", "target_word": "结论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有证据，就不能下结论。", "target_word": "结论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家分析了很多数据，才得出这个结论。", "target_word": "结论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的结论和我们的研究不一样。", "target_word": "结论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验做了三次，结论都相同。", "target_word": "结论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告最后一页写着结论。", "target_word": "结论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们调查了一个月，结论是价格太高。", "target_word": "结论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个结论有数据支持，很可靠。", "target_word": "结论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "下结论", "label": "复合"}, {"form": "結論", "label": "繁体"}], "register": "中性", "sense_fingerprint": "分析研究之后得出的最后判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471a2867-8aea-41f5-bcb0-874b318de0af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结论", "is_correct": true, "explanation": "结论：对研究的判断，表达明确，与“研究结果出来了”的语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”与研究无关，不是研究得出的内容，不能说“很清楚”。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“清楚”多用于说明、道理，不说“视力很清楚”，应说“好”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”不是研究的产物，与“研究结果出来了”的语境不合。"}], "explanations": {"结论": "结论：对研究的判断，表达明确，与“研究结果出来了”的语境相符。", "天气": "语义：“天气”与研究无关，不是研究得出的内容，不能说“很清楚”。", "视力": "搭配：“清楚”多用于说明、道理，不说“视力很清楚”，应说“好”。", "脾气": "语义：“脾气”不是研究的产物，与“研究结果出来了”的语境不合。"}, "sentence_index": 0, "correct_answer": "结论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的结论出来了，我考得不错。", "explanation": "这里应该用〈结果〉。结论指对事情分析研究后得出的判断，考试的成绩应说〈结果〉。"}, {"text": "这道选择题的结论我选错了。", "explanation": "这里应该用〈答案〉。结论是分析研究后的判断，选择题的选项应说〈答案〉。"}, {"text": "这份调查有两根结论。", "explanation": "这里应该用量词〈个〉或〈项〉。〈根〉用于细长的东西，不能修饰〈结论〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结论", "is_correct": true, "explanation": "结论：实验后得出的判断，与“都相同”的说法相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：实验做了三次，“天空”不是实验的结果，不能说“都相同”。"}, {"text": "学生", "is_correct": false, "explanation": "配价：“相同”的主语应是结果、数量等，“学生”不能作这里的主语。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”与实验得出的内容无关，句子读起来不通。"}], "explanations": {"结论": "结论：实验后得出的判断，与“都相同”的说法相符。", "天空": "语义：实验做了三次，“天空”不是实验的结果，不能说“都相同”。", "学生": "配价：“相同”的主语应是结果、数量等，“学生”不能作这里的主语。", "月亮": "语义：“月亮”与实验得出的内容无关，句子读起来不通。"}, "sentence_index": 6, "correct_answer": "结论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司把这个结论装进了箱子。", "explanation": "这里不能用〈结论〉：它是抽象的判断，不能当作实物装进箱子。"}, {"text": "老师给我提了一个结论。", "explanation": "这里应该用〈建议〉。结论是分析后的判断，给人提供做法应说〈建议〉。"}, {"text": "他得出了一把结论。", "explanation": "这里应该用量词〈个〉。〈把〉用于有柄的东西，不能修饰〈结论〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "资料还不全，我们不能结论。", "corrected_sentence": "资料还不全，我们不能下结论。", "error_description": "错误：漏掉动词「下」。正确：「下结论」。「结论」作宾语，需要动词「下」搭配，「不能」后面要接「下结论」，只改动这一处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项研究做了两年，最后得出了一片结论。", "corrected_sentence": "这项研究做了两年，最后得出了一个结论。", "error_description": "错误：量词「片」。正确：「个」。「片」用于薄而平的东西，「结论」应配量词「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
