INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87757, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "历史观点是你怎样看过去发生的事的想法。", "primary_collocate": null, "pronunciation": "lì shǐ guān diǎn", "ipa": "li˥˩ ʂɻ̩˨˩˦ kwan˥˥ tjɛn˨˩˦", "syllable_count": 4, "sentences": [{"text": "每个人看以前的事，历史观点都不一样。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷和我对那件事的历史观点不同。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们说说自己的历史观点。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看了那本书以后，我的历史观点变了。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的历史观点来自小时候听的故事。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的历史观点常常受家人影响。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们为历史观点吵了起来。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的历史观点是从哪里学来的？", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不愿意改变自己的历史观点。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在不同国家的人，历史观点可能不一样。", "target_word": "历史观点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "个人怎样看待过去的事，日常的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed802cd7-e1c1-4adc-8439-d8c9d3271fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87757, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史观点", "is_correct": true, "explanation": "“历史观点”指个人怎样看过去的事，与“每个人看以前的事”相对应。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是对过去事情的看法，“看以前的事，时间都不一样”说不通。"}, {"text": "时代", "is_correct": false, "explanation": "语义：“时代”指一段历史阶段，不是人对事情的想法，与“每个人看”不相符。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能与“看以前的事”的看法语境搭配，句意不通。"}], "explanations": {"历史观点": "“历史观点”指个人怎样看过去的事，与“每个人看以前的事”相对应。", "时间": "语义：“时间”不是对过去事情的看法，“看以前的事，时间都不一样”说不通。", "时代": "语义：“时代”指一段历史阶段，不是人对事情的想法，与“每个人看”不相符。", "身高": "搭配：“身高”不能与“看以前的事”的看法语境搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "历史观点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去参观了历史观点。", "explanation": "这里应该用〈历史遗迹〉。“参观”的对象是具体的地方或展品，“历史观点”是抽象的想法，不能参观。"}, {"text": "博物馆里陈列着很多历史观点。", "explanation": "这里应该用〈历史资料〉。“陈列”的是实物或资料，“历史观点”是抽象的想法，不能陈列。"}, {"text": "他擦掉了桌上的历史观点。", "explanation": "这里应该用〈灰尘〉。“擦”的是有形的污物，“历史观点”是抽象的想法，不能擦掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87757, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史观点", "is_correct": true, "explanation": "“历史观点”是看待历史的想法，“朋友们为历史观点吵了起来”句意通顺。"}, {"text": "皮肤", "is_correct": false, "explanation": "搭配：“皮肤”是身体的部分，不能成为争论的话题，句意不通。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：“心跳”是身体的生理现象，不能成为争吵的对象。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”指行走的动作，不能作为吵架的内容，与句意不符。"}], "explanations": {"历史观点": "“历史观点”是看待历史的想法，“朋友们为历史观点吵了起来”句意通顺。", "皮肤": "搭配：“皮肤”是身体的部分，不能成为争论的话题，句意不通。", "心跳": "语义：“心跳”是身体的生理现象，不能成为争吵的对象。", "脚步": "语义：“脚步”指行走的动作，不能作为吵架的内容，与句意不符。"}, "sentence_index": 6, "correct_answer": "历史观点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位教授在花园里浇了很多历史观点。", "explanation": "这里应该用〈花〉。“浇”的对象是植物，“历史观点”是抽象的想法，不能浇。"}, {"text": "他每天早上都喝一杯历史观点。", "explanation": "这里应该用〈牛奶〉。“喝”的是饮品，“历史观点”是抽象的想法，不能喝。"}, {"text": "她骑着历史观点去上学。", "explanation": "这里应该用〈自行车〉。“骑”的是交通工具，“历史观点”是抽象的想法，不能骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对那件事有一只历史观点。", "corrected_sentence": "他对那件事有一种历史观点。", "error_description": "量词错误：“历史观点”是抽象的看法，应使用量词“种”或“个”，不能用“只”。错误形式是“一只历史观点”，正确形式是“一种历史观点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
