INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87758, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对历史事件、历史发展的看法和见解。", "primary_collocate": null, "pronunciation": "lì shǐ guān diǎn", "ipa": "li˥˩ ʂɻ̩˨˩˦ kwan˥˥ tjɛn˨˩˦", "syllable_count": 4, "sentences": [{"text": "这位教授的历史观点很有新意。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书表达了作者独特的历史观点。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学者们对这场战争的历史观点不同。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在文章里提出了新的历史观点。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同时代的人有不同的历史观点。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章的历史观点引起了很多讨论。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用历史观点分析了这次社会变化。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课堂上，同学们讨论了各种历史观点。", "target_word": "历史观点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家的历史观点受到了很多人关注。", "target_word": "历史观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直带着自己的历史观点研究古代社会。", "target_word": "历史观点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "学者对历史事件和历史发展的见解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed802cd7-e1c1-4adc-8439-d8c9d3271fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史观点", "is_correct": true, "explanation": "“历史观点”是对历史事件的见解，“这位教授的历史观点很有新意”句意通顺。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“新意”只能形容见解、作品，不能用来形容体重。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“很有新意”不能用来形容身高，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是人的岁数，与“有新意”所说的见解性质不相符。"}], "explanations": {"历史观点": "“历史观点”是对历史事件的见解，“这位教授的历史观点很有新意”句意通顺。", "体重": "搭配：“新意”只能形容见解、作品，不能用来形容体重。", "身高": "搭配：“很有新意”不能用来形容身高，句意不通。", "年龄": "语义：“年龄”是人的岁数，与“有新意”所说的见解性质不相符。"}, "sentence_index": 0, "correct_answer": "历史观点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在厨房里煮了一锅新的历史观点。", "explanation": "这里应该用〈汤〉。“煮”的是食物，“历史观点”是抽象的见解，不能煮。"}, {"text": "他把新买的历史观点挂在墙上。", "explanation": "这里应该用〈画〉。“挂在墙上”的是画作等实物，“历史观点”是抽象的见解，不能挂。"}, {"text": "他的历史观点没电了，要充电。", "explanation": "这里应该用〈手机〉。“充电”针对电子设备，“历史观点”是抽象的见解，不能充电。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史观点", "is_correct": true, "explanation": "“历史观点”是对历史发展的见解，“她用历史观点分析了这次社会变化”句意通顺。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是人的身体状况，不能用来分析社会变化。"}, {"text": "头发", "is_correct": false, "explanation": "语义：“头发”是身体的部分，不能用来分析社会变化，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能作为分析社会变化的方法，句意不通。"}], "explanations": {"历史观点": "“历史观点”是对历史发展的见解，“她用历史观点分析了这次社会变化”句意通顺。", "体温": "语义：“体温”是人的身体状况，不能用来分析社会变化。", "头发": "语义：“头发”是身体的部分，不能用来分析社会变化，句意不通。", "天气": "语义：“天气”是自然现象，不能作为分析社会变化的方法，句意不通。"}, "sentence_index": 6, "correct_answer": "历史观点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位教授在花园里浇了很多历史观点。", "explanation": "这里应该用〈花〉。“浇”的对象是植物，“历史观点”是抽象的见解，不能浇。"}, {"text": "他用剪刀剪开了历史观点。", "explanation": "这里应该用〈信封〉。“剪开”的是纸张等实物，“历史观点”是抽象的见解，不能剪。"}, {"text": "她在操场上踢历史观点。", "explanation": "这里应该用〈足球〉。“踢”的是球类等实物，“历史观点”是抽象的见解，不能踢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
