INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87759, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "正确：“正常”与“不正常”构成反义，指符合平时的状态。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容好看，与“不正常”没有反义关系。"}, {"text": "吵闹", "is_correct": false, "explanation": "“吵闹”指声音大、乱，与“不正常”没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”指不复杂，与“不正常”没有反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "正确：“正常”与“不正常”构成反义，指符合平时的状态。", "美丽": "“美丽”形容好看，与“不正常”没有反义关系。", "吵闹": "“吵闹”指声音大、乱，与“不正常”没有反义关系。", "简单": "“简单”指不复杂，与“不正常”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87759, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不正常是和平时不一样，有点不对劲。", "primary_collocate": null, "pronunciation": "bù zhèng cháng", "ipa": "pu˥˩ ʈʂɤŋ˥˩ ʈʂʰɑŋ˧˥", "syllable_count": 3, "sentences": [{"text": "今天他的样子很不正常，一句话也不说。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗今天不吃饭，真不正常。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，家里的灯还亮着，有点不正常。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他平时很爱笑，今天不笑，太不正常了。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话响了很久没人接，这很不正常。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天路上一辆车也没有，不正常。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈发现我今天特别安静，觉得不正常。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他平时很热情，今天见了我就躲，样子不正常。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一见到我就跑，样子很不正常。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气这么热还穿棉衣，不正常吧？", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "和平时不一样，让人觉得不对劲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c98c2ea0-82f7-4d76-b905-50f0974de4d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热情", "is_correct": false, "explanation": "语义：“热情”指待人亲切，与“一句话也不说”的表现矛盾。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀刃等物体，不能用来形容人的样子。"}, {"text": "不正常", "is_correct": true, "explanation": "正确：“不正常”指和平时不一样、让人觉得不对劲，与句中的反常表现相符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场所或场面，不能用来形容人的样子。"}], "explanations": {"热情": "语义：“热情”指待人亲切，与“一句话也不说”的表现矛盾。", "锋利": "搭配：“锋利”形容刀刃等物体，不能用来形容人的样子。", "不正常": "正确：“不正常”指和平时不一样、让人觉得不对劲，与句中的反常表现相符。", "热闹": "搭配：“热闹”形容场所或场面，不能用来形容人的样子。"}, "sentence_index": 0, "correct_answer": "不正常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场魔术和平时的表演一模一样，很不正常。", "explanation": "这里应该用〈正常〉。句中说与平时一样，“不正常”与之矛盾。"}, {"text": "这位邻居和其他邻居没什么两样，很不正常。", "explanation": "这里应该用〈正常〉。句中说与其他邻居没什么两样，“不正常”与之矛盾。"}, {"text": "这家小店的装修和别家差不多，很不正常。", "explanation": "这里应该用〈正常〉。句中说与别家差不多，“不正常”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”指开朗爱动，与“特别安静”的描述矛盾。"}, {"text": "灵活", "is_correct": false, "explanation": "搭配：“灵活”形容动作或办法，不能用来形容一种感觉。"}, {"text": "不正常", "is_correct": true, "explanation": "正确：“不正常”表示和平时不一样，让妈妈觉得不对劲，与句意相符。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”指风趣，与“特别安静”的描述不符。"}], "explanations": {"活泼": "语义：“活泼”指开朗爱动，与“特别安静”的描述矛盾。", "灵活": "搭配：“灵活”形容动作或办法，不能用来形容一种感觉。", "不正常": "正确：“不正常”表示和平时不一样，让妈妈觉得不对劲，与句意相符。", "幽默": "语义：“幽默”指风趣，与“特别安静”的描述不符。"}, "sentence_index": 6, "correct_answer": "不正常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天和平时一样有说有笑，很不正常。", "explanation": "这里应该用〈正常〉。句中说他和平时一样，“不正常”指和平时不一样，与之矛盾。"}, {"text": "小猫今天跟往常一样吃饭睡觉，真不正常。", "explanation": "这里应该用〈正常〉。句中说小猫跟往常一样，“不正常”与之矛盾。"}, {"text": "这家酒店的服务和其他酒店没什么两样，很不正常。", "explanation": "这里应该用〈正常〉。句中说与其他酒店没什么两样，“不正常”与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这孩子今天的表现太很不正常。", "corrected_sentence": "这孩子今天的表现很不正常。", "error_description": "程度副词叠用：“太”和“很”都表示程度，不能同时用在“不正常”前，应去掉“太”，说“很不正常”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种情况很不不正常。", "corrected_sentence": "这种情况很不正常。", "error_description": "否定词重复：“不正常”已含“不”，前面不能再加一个“不”，应去掉多余的“不”，说“很不正常”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87760, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "正确：“正常”与“不正常”构成反义，指符合常态、没有毛病。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线强或颜色鲜亮，与“不正常”没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”指不复杂，与“不正常”没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”指不紧张、不费力，与“不正常”没有反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "正确：“正常”与“不正常”构成反义，指符合常态、没有毛病。", "明亮": "“明亮”形容光线强或颜色鲜亮，与“不正常”没有反义关系。", "简单": "“简单”指不复杂，与“不正常”没有反义关系。", "轻松": "“轻松”指不紧张、不费力，与“不正常”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87760, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "正确：“正常”与“不正常”构成反义，指符合常态、没有毛病。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容好看，与“不正常”没有反义关系。"}, {"text": "吵闹", "is_correct": false, "explanation": "“吵闹”指声音大、乱，与“不正常”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、分明，与“不正常”没有反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "正确：“正常”与“不正常”构成反义，指符合常态、没有毛病。", "美丽": "“美丽”形容好看，与“不正常”没有反义关系。", "吵闹": "“吵闹”指声音大、乱，与“不正常”没有反义关系。", "清楚": "“清楚”形容明白、分明，与“不正常”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87760, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不符合常态的；有毛病的。", "primary_collocate": null, "pronunciation": "bù zhèng cháng", "ipa": "pu˥˩ ʈʂɤŋ˥˩ ʈʂʰɑŋ˧˥", "syllable_count": 3, "sentences": [{"text": "医生说他的心跳不正常。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器发出不正常的声音，快关掉它。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的体温不正常，要去医院看看。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑的运行速度不正常。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水龙头流出的水颜色不正常。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡觉时呼吸不正常，家人很担心。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批牛奶的味道不正常，别喝了。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机充电这么慢，肯定不正常。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的血压一直不正常，要按时吃药。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱最近总是响，不正常，请人来修吧。", "target_word": "不正常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不符合常态，身体或机器有毛病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c98c2ea0-82f7-4d76-b905-50f0974de4d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "快乐", "is_correct": false, "explanation": "语义：“快乐”指心情愉快，不能用来形容心跳。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容质地，不能用来形容心跳。"}, {"text": "不正常", "is_correct": true, "explanation": "正确：“不正常”指不符合常态、身体出了毛病，与医生的判断相符。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”指风趣，不能用来形容心跳。"}], "explanations": {"快乐": "语义：“快乐”指心情愉快，不能用来形容心跳。", "柔软": "搭配：“柔软”形容质地，不能用来形容心跳。", "不正常": "正确：“不正常”指不符合常态、身体出了毛病，与医生的判断相符。", "幽默": "语义：“幽默”指风趣，不能用来形容心跳。"}, "sentence_index": 0, "correct_answer": "不正常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "检查后医生说这款手机的电池没有任何问题，它很不正常。", "explanation": "这里应该用〈正常〉。句中说“没有任何问题”，“不正常”指有毛病，与之矛盾。"}, {"text": "这次搬家很不正常，路上没有遇到任何问题。", "explanation": "这里应该用〈顺利〉。句中说没有遇到问题，“不正常”指出了问题，与之矛盾。"}, {"text": "兽医检查后说这只狗的牙齿没有任何毛病，它很不正常。", "explanation": "这里应该用〈健康〉。句中说没有任何毛病，“不正常”指有毛病，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新鲜", "is_correct": false, "explanation": "语义：“新鲜”是好的状态，与“别喝了”的劝阻相矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外观，不能用来形容味道。"}, {"text": "不正常", "is_correct": true, "explanation": "正确：“不正常”指味道异常、有问题，与“别喝了”相符。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型或物体，不能用来形容味道。"}], "explanations": {"新鲜": "语义：“新鲜”是好的状态，与“别喝了”的劝阻相矛盾。", "漂亮": "搭配：“漂亮”形容外观，不能用来形容味道。", "不正常": "正确：“不正常”指味道异常、有问题，与“别喝了”相符。", "高大": "搭配：“高大”形容体型或物体，不能用来形容味道。"}, "sentence_index": 6, "correct_answer": "不正常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师检查后说这幅画的色彩完全没有问题，它很不正常。", "explanation": "这里应该用〈正常〉。句中说色彩没有问题，“不正常”指有毛病，与之矛盾。"}, {"text": "这份说明经过核对，内容没有任何错误，它写得很不正常。", "explanation": "这里应该用〈正确〉。句中说内容没有错误，“不正常”指有毛病，与之矛盾。"}, {"text": "这批水果经检查没有任何变质，它的味道很不正常。", "explanation": "这里应该用〈新鲜〉。句中说没有变质，“不正常”指变质或有问题，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器把声音不正常，快检查一下。", "corrected_sentence": "这台机器的声音不正常，快检查一下。", "error_description": "“把”字句误用：“把”后要接可被处置的宾语和动词，“把声音不正常”不成立，应去掉“把”，改用“的”，说“这台机器的声音不正常”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台设备的运转很不正常过。", "corrected_sentence": "这台设备的运转很不正常。", "error_description": "“过”字误用：形容词“不正常”后不能直接接“过”，“过”只能接在动词后表示经历，应去掉“过”，说“这台设备的运转很不正常”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
