INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87763, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出版是把书印出来，让大家都能买到。", "primary_collocate": null, "pronunciation": "chū bǎn", "ipa": "ʈʂʰu˥ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本书下个月就会出版。", "target_word": "出版", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她写的故事书出版了。", "target_word": "出版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书出版后，你可以在书店买到。", "target_word": "出版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的日记出版了。", "target_word": "出版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书去年出版，现在到处能买到。", "target_word": "出版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老师想出版一本英语书。", "target_word": "出版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我朋友的书明天出版。", "target_word": "出版", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书一出版，很多人都来买。", "target_word": "出版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本漫画书出版以后很好卖。", "target_word": "出版", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店里能买到刚出版的新书。", "target_word": "出版", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "出版了", "label": "体标"}, {"form": "出版社", "label": "复合"}, {"form": "出版物", "label": "复合"}], "register": "书面", "sense_fingerprint": "把书印出来让大家能买到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee16606a-f927-4c1a-ac0f-73f57f89b922') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87763, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出版", "is_correct": true, "explanation": "正确：听到的是“出版”（chū bǎn），指把书印出来让大家能买到。"}, {"text": "出产", "is_correct": false, "explanation": "“出产”（chūchǎn）的声母是 ch，与“出版”的 b 不同，意思是生产、产出。"}, {"text": "出榜", "is_correct": false, "explanation": "“出榜”（chūbǎng）的韵尾是 ng，与“出版”的 n 不同，意思是公布考试等结果的名单。"}, {"text": "出殡", "is_correct": false, "explanation": "“出殡”（chūbìn）的第二个音节是 bìn，韵母和声调都与“出版”的 bǎn 不同，意思是把灵柩送去安葬。"}], "explanations": {"出版": "正确：听到的是“出版”（chū bǎn），指把书印出来让大家能买到。", "出产": "“出产”（chūchǎn）的声母是 ch，与“出版”的 b 不同，意思是生产、产出。", "出榜": "“出榜”（chūbǎng）的韵尾是 ng，与“出版”的 n 不同，意思是公布考试等结果的名单。", "出殡": "“出殡”（chūbìn）的第二个音节是 bìn，韵母和声调都与“出版”的 bǎn 不同，意思是把灵柩送去安葬。"}, "sentence_index": null, "correct_answer": "出版"}, "level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "搭配：“出生”用于人或动物，不能说书“出生”。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因公到外地办事，不能用于书。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指学生完成学业，与书无关。"}, {"text": "出版", "is_correct": true, "explanation": "正确：“这本书下个月就会出版”指书将印出发行，语境通顺。"}], "explanations": {"出生": "搭配：“出生”用于人或动物，不能说书“出生”。", "出差": "语义：“出差”指因公到外地办事，不能用于书。", "毕业": "语义：“毕业”指学生完成学业，与书无关。", "出版": "正确：“这本书下个月就会出版”指书将印出发行，语境通顺。"}, "sentence_index": 0, "correct_answer": "出版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店出版了很多请柬。", "explanation": "这里应该用〈印刷〉。“出版”指书刊的印制发行，请柬只是印刷品，不能说出版。"}, {"text": "这篇论文已经在杂志上出版了。", "explanation": "这里应该用〈发表〉。单篇论文在杂志上刊登要用“发表”，“出版”针对整本书刊。"}, {"text": "这部电影下个月出版。", "explanation": "这里应该用〈上映〉。电影不能出版，电影在影院与观众见面要说“上映”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87763, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放假", "is_correct": false, "explanation": "语义：“放假”指学校或单位停止工作学习，不能用于书。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”是不及物动词，主语必须是人，不能用“书”作主语。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指人停止工作，与书的印行无关。"}, {"text": "出版", "is_correct": true, "explanation": "正确：“我朋友的书明天出版”指书明天印出发行，语境通顺。"}], "explanations": {"放假": "语义：“放假”指学校或单位停止工作学习，不能用于书。", "结婚": "配价：“结婚”是不及物动词，主语必须是人，不能用“书”作主语。", "退休": "语义：“退休”指人停止工作，与书的印行无关。", "出版": "正确：“我朋友的书明天出版”指书明天印出发行，语境通顺。"}, "sentence_index": 6, "correct_answer": "出版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个电视节目每晚出版。", "explanation": "这里应该用〈播出〉。电视节目是播放出去的，不能说“出版”。"}, {"text": "公司今天出版了新产品。", "explanation": "这里应该用〈发布〉。新产品的消息要说“发布”，“出版”只用于书刊。"}, {"text": "这家工厂出版了很多汽车。", "explanation": "这里应该用〈生产〉。汽车是生产出来的，不能说“出版”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87763, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套丛书明年出版了。", "corrected_sentence": "这套丛书明年出版。", "error_description": "错误形式是“明年出版了”，正确形式是“明年出版”。“明年”是将来的时间，“出版”还没有完成，不能用表示完成的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87763, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书店里能买到刚出版小说。", "corrected_sentence": "书店里能买到刚出版的小说。", "error_description": "错误形式是“刚出版小说”，正确形式是“刚出版的小说”。“刚出版”修饰“小说”时，中间要用“的”连接，省略“的”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abe1b8c7-5769-429e-b5fd-ee02daa76644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
