INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87765, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "归来是离开了一段时间，又回到原来的地方。", "primary_collocate": null, "pronunciation": "guī lái", "ipa": "kʷei˥ lai˧˥", "syllable_count": 2, "sentences": [{"text": "他在外面工作一年，终于归来了。", "target_word": "归来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，燕子从南方归来。", "target_word": "归来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶盼着我归来。", "target_word": "归来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离家十年，他今天归来。", "target_word": "归来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷归来时，家里很热闹。", "target_word": "归来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出国学习归来，朋友们去看她。", "target_word": "归来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在村口等着游子归来。", "target_word": "归来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长出海归来，带来很多鱼。", "target_word": "归来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人离开了村子，二十年后归来。", "target_word": "归来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喝了茶，等丈夫归来。", "target_word": "归来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "归来了", "label": "完成体"}], "register": "书面语", "sense_fingerprint": "离开一段时间后又回到原来的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d23fd0e-84cc-4b7b-8d40-c450f027c617') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”只用于植物或种子，不能用于描述人的返回。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：“诞生”指新生命或事物产生，与“工作一年”的语境不符。"}, {"text": "归来", "is_correct": true, "explanation": "“归来”指离开一段时间后回到原处，与“终于……了”搭配自然。"}, {"text": "浇灌", "is_correct": false, "explanation": "配价：“浇灌”是及物动词，需要带宾语，这里没有宾语，不成立。"}], "explanations": {"发芽": "搭配：“发芽”只用于植物或种子，不能用于描述人的返回。", "诞生": "语义：“诞生”指新生命或事物产生，与“工作一年”的语境不符。", "归来": "“归来”指离开一段时间后回到原处，与“终于……了”搭配自然。", "浇灌": "配价：“浇灌”是及物动词，需要带宾语，这里没有宾语，不成立。"}, "sentence_index": 0, "correct_answer": "归来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他第一次来这座城市，今天终于归来。", "explanation": "这里应该用〈抵达〉。“归来”指回到原处，第一次来这座城市不能说“归来”。"}, {"text": "他第一次坐飞机去美国，终于归来到了美国。", "explanation": "这里应该用〈到达〉。“归来”指离开后回到原处，第一次去美国不是回到原处。"}, {"text": "这个孩子昨天归来到了这个世界。", "explanation": "这里应该用〈来到〉。“归来”指离开后回到原处，孩子出生是第一次来到世界，不能说“归来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繁殖", "is_correct": false, "explanation": "搭配：“繁殖”指生物增加后代，不用于“等游子”的语境。"}, {"text": "归来", "is_correct": true, "explanation": "“归来”指离家在外的人回到家乡，与“等着游子”的语境相符。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或光灭了，不能用来描述游子。"}, {"text": "晒干", "is_correct": false, "explanation": "搭配：“晒干”多用于衣物、粮食等，不能用于人。"}], "explanations": {"繁殖": "搭配：“繁殖”指生物增加后代，不用于“等游子”的语境。", "归来": "“归来”指离家在外的人回到家乡，与“等着游子”的语境相符。", "熄灭": "语义：“熄灭”指火或光灭了，不能用来描述游子。", "晒干": "搭配：“晒干”多用于衣物、粮食等，不能用于人。"}, "sentence_index": 6, "correct_answer": "归来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头在山里待了百年，今天终于归来了。", "explanation": "这里应该用〈运回〉。“归来”只用于人或候鸟自己离开后再回来，石头不能自己归来，应说“被运回”。"}, {"text": "这条河每年春天都归来，两岸变得很热闹。", "explanation": "这里应该用〈解冻〉。河流不会离开后再回来，“归来”只用于人或候鸟，河面春天应说“解冻”。"}, {"text": "这朵花谢了以后又归来了。", "explanation": "这里应该用〈再开〉。“归来”指人或候鸟离开后再回到原处，花谢后再开应说“再开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她留学三年后终于归来了了。", "corrected_sentence": "她留学三年后终于归来了。", "error_description": "错误：“归来了了”，“了”重复出现。正确：“归来了”，只用一个“了”表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她终于等到丈夫归来了着。", "corrected_sentence": "她终于等到丈夫归来了。", "error_description": "错误：“归来了着”，“了”之后不能再接“着”，两者不能按这个顺序连用。正确：“归来了”，只用“了”表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
