INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87767, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87767, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中学生是在中学里读书的学生。", "primary_collocate": null, "pronunciation": "zhōng xué shēng", "ipa": "ʈʂʊŋ˥ ɕɥe˧˥ ʂəŋ˥", "syllable_count": 3, "sentences": [{"text": "我弟弟今年上初中，是中学生。", "target_word": "中学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上完小学以后，他就成了中学生。", "target_word": "中学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些中学生正在上初三的数学课。", "target_word": "中学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "初三的中学生都要参加中考。", "target_word": "中学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他十五岁，还是中学生，没有上大学。", "target_word": "中学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末，很多中学生去图书馆看书。", "target_word": "中学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我女儿是中学生，明年要考高中。", "target_word": "中学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏令营只收中学生，小学生不能参加。", "target_word": "中学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中学生一般要学英语、数学和物理。", "target_word": "中学生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她高中毕业以后，不再是中学生了。", "target_word": "中学生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个中学生", "label": "量词"}, {"form": "一名中学生", "label": "量词"}], "register": "中性", "sense_fingerprint": "中学生：在中学里读书的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7d2912c-6f4e-4394-8528-f3a78e8b990c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87767, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中学生", "is_correct": true, "explanation": "中学生：在中学就读的学生，与“上初中”相合。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生在小学读书，与句中“上初中”矛盾。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是教书的人，弟弟是学生，与句中“上初中”矛盾。"}, {"text": "大学生", "is_correct": false, "explanation": "语义：大学生已在大学读书，与句中“上初中”矛盾。"}], "explanations": {"中学生": "中学生：在中学就读的学生，与“上初中”相合。", "小学生": "语义：小学生在小学读书，与句中“上初中”矛盾。", "老师": "语义：老师是教书的人，弟弟是学生，与句中“上初中”矛盾。", "大学生": "语义：大学生已在大学读书，与句中“上初中”矛盾。"}, "sentence_index": 0, "correct_answer": "中学生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所小学有两千名中学生。", "explanation": "这里应该用〈小学生〉。中学生指在中学就读的学生，这是小学，应说小学生。"}, {"text": "他刚考上大学，已经是中学生了。", "explanation": "这里应该用〈大学生〉。中学生指在中学就读的学生，考上大学后应说大学生。"}, {"text": "我爷爷七十岁了，是一名中学生。", "explanation": "这里应该用〈老人〉。中学生一般是十几岁在中学读书的学生，七十岁的爷爷不是中学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中学生", "is_correct": true, "explanation": "中学生：在中学就读的学生，与“明年要考高中”的情况相合。"}, {"text": "大学生", "is_correct": false, "explanation": "语义：大学生已经读大学，与“明年要考高中”矛盾。"}, {"text": "幼儿", "is_correct": false, "explanation": "语义：幼儿还没上学，与“明年要考高中”的情况不合。"}, {"text": "教师", "is_correct": false, "explanation": "语义：教师是教书的人，不是在校读书的学生，与“明年要考高中”矛盾。"}], "explanations": {"中学生": "中学生：在中学就读的学生，与“明年要考高中”的情况相合。", "大学生": "语义：大学生已经读大学，与“明年要考高中”矛盾。", "幼儿": "语义：幼儿还没上学，与“明年要考高中”的情况不合。", "教师": "语义：教师是教书的人，不是在校读书的学生，与“明年要考高中”矛盾。"}, "sentence_index": 6, "correct_answer": "中学生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所幼儿园里有很多中学生。", "explanation": "这里应该用〈幼儿〉。中学生指在中学就读的学生，幼儿园里应说幼儿。"}, {"text": "我妈妈是中学生，每天在学校教书。", "explanation": "这里应该用〈中学老师〉。中学生指在中学读书的学生，而“每天在学校教书”的人是老师，身份矛盾。"}, {"text": "他毕业后工作好几年了，还是中学生。", "explanation": "这里应该用〈职工〉。中学生指在中学读书的学生，他已经工作多年，应说“职工”，不能说“中学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87767, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹读初一，已经是一只中学生了。", "corrected_sentence": "妹妹读初一，已经是一名中学生了。", "error_description": "错误在量词：指人的“中学生”应用“名”或“个”，用“只”（多指动物）不对。应说“一名中学生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87767, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个中学生们每天骑车上学。", "corrected_sentence": "这个中学生每天骑车上学。", "error_description": "错误在“们”：“这个”指单个人，不能与表示复数的“们”搭配；应去掉“们”，说“这个中学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
