INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87769, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一生是一个人从生下来到死去的整个时间。", "primary_collocate": null, "pronunciation": "yì shēng", "ipa": "i˥˩ ʂəŋ˥", "syllable_count": 2, "sentences": [{"text": "他的一生过得很简单。", "target_word": "一生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷一生都住在这个小村子里。", "target_word": "一生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一生很长，也很短。", "target_word": "一生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一生都给了学生。", "target_word": "一生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想用一生去爱我的家人。", "target_word": "一生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生一生帮助了很多人。", "target_word": "一生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的一生中会遇到很多朋友。", "target_word": "一生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的一生都在教书。", "target_word": "一生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是一位农民的一生。", "target_word": "一生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生没有离开过家乡。", "target_word": "一生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个人从出生到死去的整个时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '957488b2-d73b-4bc6-b47f-79a362d47852') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87769, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一生", "is_correct": true, "explanation": "正确。「一生」指一个人从出生到死去的整个时间，作主语，与「过得很简单」搭配。"}, {"text": "房间", "is_correct": false, "explanation": "语义：「过得很简单」的主语须是人或生活，房间不能过日子。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：「桌子」是物品，不能说它「过得很简单」。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：「过得很简单」只用于人的生活状态，「电脑」不能与之搭配。"}], "explanations": {"一生": "正确。「一生」指一个人从出生到死去的整个时间，作主语，与「过得很简单」搭配。", "房间": "语义：「过得很简单」的主语须是人或生活，房间不能过日子。", "桌子": "语义：「桌子」是物品，不能说它「过得很简单」。", "电脑": "搭配：「过得很简单」只用于人的生活状态，「电脑」不能与之搭配。"}, "sentence_index": 0, "correct_answer": "一生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试他一生都很紧张。", "explanation": "这里应该用〈一直〉。一生指整个人生，不能用来说某次考试中的状态持续的时长，这里应说「一直很紧张」。"}, {"text": "我们一生去吃饭吧。", "explanation": "这里应该用〈一起〉。一生指整个人生，不表示「共同」，说一起去吃饭要用「一起」。"}, {"text": "他今天一生都在家。", "explanation": "这里应该用〈一天〉。一生指一个人的整个人生，不能用来说「今天」这一天的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87769, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一生", "is_correct": true, "explanation": "正确。「你的一生中」指你整个人生的范围，与「中」和「遇到很多朋友」搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以遇到朋友的时间或空间范围，「你的冰箱中会遇到很多朋友」不成立。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：「中」前的名词要表示时间、范围或场所，「钢笔」不能作为遇到朋友的范围。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套不能作为遇到很多朋友的场所，句子无法理解。"}], "explanations": {"一生": "正确。「你的一生中」指你整个人生的范围，与「中」和「遇到很多朋友」搭配。", "冰箱": "语义：冰箱不是可以遇到朋友的时间或空间范围，「你的冰箱中会遇到很多朋友」不成立。", "钢笔": "搭配：「中」前的名词要表示时间、范围或场所，「钢笔」不能作为遇到朋友的范围。", "手套": "语义：手套不能作为遇到很多朋友的场所，句子无法理解。"}, "sentence_index": 6, "correct_answer": "一生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一台一生。", "explanation": "这里「一生」不能用〈台〉来计量。〈台〉用于机器、设备，一生是时间，不能当作机器来数。"}, {"text": "我家里有一辆一生。", "explanation": "这里「一生」不能用〈辆〉来计量。〈辆〉用于车，一生是时间，不能用车的量词。"}, {"text": "我们村养了一只一生。", "explanation": "这里「一生」不能用〈只〉来计量。〈只〉用于动物，一生是时间，不能用动物的量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一生了都住在城里。", "corrected_sentence": "他一生都住在城里。", "error_description": "「一生」后面不能直接加「了」。表示整个人生的时间不带完成标记，应说「他一生都住在城里」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一个一生都在这座城市生活。", "corrected_sentence": "我一生都在这座城市生活。", "error_description": "「一生」前不能加数量词「一个」。它本身不带量词，应说「我一生都在这座城市生活」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
