INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87771, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "嘛放在话的最后，是说这件事很明白。", "primary_collocate": null, "pronunciation": "ma", "ipa": "ma", "syllable_count": 1, "sentences": [{"text": "这个问题很简单嘛。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早就说过嘛，他会来的。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，他不是来了嘛。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本来就是嘛，谁都看得出来。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事实就在这儿嘛。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没错嘛，为什么要道歉？", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格这么低，当然好卖嘛。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是学生嘛，学习最重要。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都写在黑板上嘛，一看就懂。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明明是他先说的嘛。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "句末语气词，强调事情很明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471a2867-8aea-41f5-bcb0-874b318de0af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87771, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嘛", "is_correct": true, "explanation": "嘛（轻声 ma）是句末语气词，表示事情很明白，是本题要听辨的词。"}, {"text": "妈", "is_correct": false, "explanation": "mā（第一声）与 ma（轻声）声调不同，意思是妈妈，不是语气词。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 ma（轻声）声调不同，意思是马。"}, {"text": "骂", "is_correct": false, "explanation": "mà（第四声）与 ma（轻声）声调不同，意思是责骂。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 ma（轻声）声调不同，意思是麻木或芝麻。"}, {"text": "吧", "is_correct": false, "explanation": "ba（轻声）与 ma（轻声）声母不同，b 与 m 相对，吧 表示商量或推测，不是嘛。"}], "explanations": {"嘛": "嘛（轻声 ma）是句末语气词，表示事情很明白，是本题要听辨的词。", "妈": "mā（第一声）与 ma（轻声）声调不同，意思是妈妈，不是语气词。", "马": "mǎ（第三声）与 ma（轻声）声调不同，意思是马。", "骂": "mà（第四声）与 ma（轻声）声调不同，意思是责骂。", "麻": "má（第二声）与 ma（轻声）声调不同，意思是麻木或芝麻。", "吧": "ba（轻声）与 ma（轻声）声母不同，b 与 m 相对，吧 表示商量或推测，不是嘛。"}, "sentence_index": null, "correct_answer": "嘛"}, "level_3": {"options": [{"text": "着", "is_correct": false, "explanation": "语法：着 表示动作持续，不能用在形容词谓语句末表示语气。"}, {"text": "嘛", "is_correct": true, "explanation": "嘛 说明“这个问题很简单”是显而易见的，正合语境。"}, {"text": "吗", "is_correct": false, "explanation": "语义：吗 表示疑问，句子会变成询问，与“这个问题很简单”的陈述不合。"}, {"text": "罢", "is_correct": false, "explanation": "语域：罢 是文言语气词，与此句的口语表达不一致。"}], "explanations": {"着": "语法：着 表示动作持续，不能用在形容词谓语句末表示语气。", "嘛": "嘛 说明“这个问题很简单”是显而易见的，正合语境。", "吗": "语义：吗 表示疑问，句子会变成询问，与“这个问题很简单”的陈述不合。", "罢": "语域：罢 是文言语气词，与此句的口语表达不一致。"}, "sentence_index": 0, "correct_answer": "嘛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事他大概知道嘛，我们再问问。", "explanation": "这里应该用〈吧〉。嘛表示事情明显，与“大概”的不确定语气冲突；表示推测要用吧。"}, {"text": "他也许已经搬走了嘛，我们不必再去找他。", "explanation": "这里应该用〈吧〉。嘛表示事情明显，与“也许”的不确定语气冲突；表示推测要用吧。"}, {"text": "我还没查证这件事，它可能是真的嘛。", "explanation": "这里应该用〈吧〉。嘛表示事情明显，而“还没查证”“可能”都是不确定的推测；推测要用吧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87771, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嘛", "is_correct": true, "explanation": "嘛（轻声 ma）是句末语气词，表示事情很明白，是本题要听辨的词。"}, {"text": "码", "is_correct": false, "explanation": "mǎ（第三声）与 ma（轻声）声调不同，意思是号码，不是语气词。"}, {"text": "么", "is_correct": false, "explanation": "me（轻声）与 ma（轻声）韵母不同（e 与 a），么 用于“什么”“这么”，不是句末语气词。"}, {"text": "啦", "is_correct": false, "explanation": "la（轻声）与 ma（轻声）声母不同（l 与 m），啦 是“了啊”的合音，但不是嘛。"}, {"text": "哇", "is_correct": false, "explanation": "wa（轻声）与 ma（轻声）声母不同，哇 表示惊讶或赞叹。"}], "explanations": {"嘛": "嘛（轻声 ma）是句末语气词，表示事情很明白，是本题要听辨的词。", "码": "mǎ（第三声）与 ma（轻声）声调不同，意思是号码，不是语气词。", "么": "me（轻声）与 ma（轻声）韵母不同（e 与 a），么 用于“什么”“这么”，不是句末语气词。", "啦": "la（轻声）与 ma（轻声）声母不同（l 与 m），啦 是“了啊”的合音，但不是嘛。", "哇": "wa（轻声）与 ma（轻声）声母不同，哇 表示惊讶或赞叹。"}, "sentence_index": null, "correct_answer": "嘛"}, "level_3": {"options": [{"text": "哇", "is_correct": false, "explanation": "语义：哇 表示惊叹或赞叹，与此句的推理语气不符。"}, {"text": "过", "is_correct": false, "explanation": "语法：过 表示曾经的经历，不能放在“好卖”句末表示道理显而易见。"}, {"text": "嘛", "is_correct": true, "explanation": "嘛 表示“这个结果显而易见”，正与“价格低”推出“好卖”的道理相合。"}, {"text": "乎", "is_correct": false, "explanation": "语域：乎 是文言语气词，与此句的口语表达不一致。"}], "explanations": {"哇": "语义：哇 表示惊叹或赞叹，与此句的推理语气不符。", "过": "语法：过 表示曾经的经历，不能放在“好卖”句末表示道理显而易见。", "嘛": "嘛 表示“这个结果显而易见”，正与“价格低”推出“好卖”的道理相合。", "乎": "语域：乎 是文言语气词，与此句的口语表达不一致。"}, "sentence_index": 6, "correct_answer": "嘛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事我还没弄清楚，他大概已经答应了嘛。", "explanation": "这里应该用〈吧〉。嘛表示事情明显，与“大概”的不确定语气冲突；表示推测要用吧。"}, {"text": "明天的会议大概不会取消嘛，你先准备一下。", "explanation": "这里应该用〈吧〉。嘛表示事情明显，与“大概不会”的不确定推测冲突；推测要用吧。"}, {"text": "比赛的结果我还没看到，他也许拿了冠军嘛。", "explanation": "这里应该用〈吧〉。嘛表示事情明显，与“也许”的不确定语气冲突；表示推测要用吧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题很容易，嘛谁都会做。", "corrected_sentence": "这道题很容易嘛，谁都会做。", "error_description": "错误：嘛 被放在逗号后，写成“嘛谁都会做”，位置错误。正确：嘛 应紧跟在说明“很容易”的分句末尾（“容易嘛，”），表示这一点显而易见。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这么聪明嘛的，当然学得快。", "corrected_sentence": "他这么聪明嘛，当然学得快。", "error_description": "错误：嘛 后面多加了“的”，“嘛的”不能作语气词。正确：只用“嘛”，句末不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
