INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87772, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "语气词，表示事情显而易见，或带有劝说、期望的意思。", "primary_collocate": null, "pronunciation": "ma", "ipa": "ma", "syllable_count": 1, "sentences": [{"text": "你早说嘛，我就帮你了。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这有什么难的，多练练就会嘛。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别生气嘛，他不是故意的。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是朋友嘛，不用客气。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点嘛，大家都在等你。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子嘛，爱玩是正常的。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不会就问嘛，没人会笑你。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是老师嘛，当然懂得多。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再坐一会儿嘛，别急着走。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气好嘛，出去走走吧。", "target_word": "嘛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "句中或句末语气词，表显而易见或劝说期望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471a2867-8aea-41f5-bcb0-874b318de0af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87772, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嘛", "is_correct": true, "explanation": "嘛（轻声 ma）是句末语气词，表示事情显而易见或带有劝说、期望的意思，是本题要听辨的词。"}, {"text": "妈", "is_correct": false, "explanation": "mā（第一声）与 ma（轻声）声调不同，意思是妈妈，不是语气词。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 ma（轻声）声调不同，意思是马。"}, {"text": "骂", "is_correct": false, "explanation": "mà（第四声）与 ma（轻声）声调不同，意思是责骂。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 ma（轻声）声调不同，意思是麻木或芝麻，是名词或形容词。"}, {"text": "吧", "is_correct": false, "explanation": "ba（轻声）与 ma（轻声）声母不同，b 与 m 相对，吧 表示商量或推测，不是嘛。"}], "explanations": {"嘛": "嘛（轻声 ma）是句末语气词，表示事情显而易见或带有劝说、期望的意思，是本题要听辨的词。", "妈": "mā（第一声）与 ma（轻声）声调不同，意思是妈妈，不是语气词。", "马": "mǎ（第三声）与 ma（轻声）声调不同，意思是马。", "骂": "mà（第四声）与 ma（轻声）声调不同，意思是责骂。", "麻": "má（第二声）与 ma（轻声）声调不同，意思是麻木或芝麻，是名词或形容词。", "吧": "ba（轻声）与 ma（轻声）声母不同，b 与 m 相对，吧 表示商量或推测，不是嘛。"}, "sentence_index": null, "correct_answer": "嘛"}, "level_3": {"options": [{"text": "着", "is_correct": false, "explanation": "语法：着 表示动作持续，“早说着”不成话。"}, {"text": "哟", "is_correct": false, "explanation": "语义：哟 表示惊叹或夸张，与此句的埋怨语气不合。"}, {"text": "嘛", "is_correct": true, "explanation": "嘛 指出“早说就能帮忙”是显而易见的道理，带有埋怨的语气，正合语境。"}, {"text": "吗", "is_correct": false, "explanation": "语义：吗 表示疑问，句子会变成询问，与“早说就帮你”的陈述不合。"}], "explanations": {"着": "语法：着 表示动作持续，“早说着”不成话。", "哟": "语义：哟 表示惊叹或夸张，与此句的埋怨语气不合。", "嘛": "嘛 指出“早说就能帮忙”是显而易见的道理，带有埋怨的语气，正合语境。", "吗": "语义：吗 表示疑问，句子会变成询问，与“早说就帮你”的陈述不合。"}, "sentence_index": 0, "correct_answer": "嘛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大概明天来嘛，我们再等等。", "explanation": "这里应该用〈吧〉。嘛表示事情明显，与“大概”的不确定语气冲突；表示推测要用吧。"}, {"text": "他也许已经知道了这件事嘛。", "explanation": "这里应该用〈吧〉。嘛表示事情明显，与“也许”的不确定语气冲突；表示推测要用吧。"}, {"text": "我完全不知道原因，这个原因可能跟天气有关嘛。", "explanation": "这里应该用〈吧〉。嘛表示事情明显，而“可能”表示不确定的推测；推测要用吧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87772, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "嘛", "is_correct": true, "explanation": "嘛（轻声 ma）是句末语气词，表示事情显而易见或带有劝说、期望的意思，是本题要听辨的词。"}, {"text": "码", "is_correct": false, "explanation": "mǎ（第三声）与 ma（轻声）声调不同，意思是号码，不是语气词。"}, {"text": "么", "is_correct": false, "explanation": "me（轻声）与 ma（轻声）韵母不同（e 与 a），么 用于“什么”“这么”，不是句末语气词。"}, {"text": "啦", "is_correct": false, "explanation": "la（轻声）与 ma（轻声）声母不同（l 与 m），啦 是“了啊”的合音，但不是嘛。"}, {"text": "哇", "is_correct": false, "explanation": "wa（轻声）与 ma（轻声）声母不同，哇 表示惊讶或赞叹。"}], "explanations": {"嘛": "嘛（轻声 ma）是句末语气词，表示事情显而易见或带有劝说、期望的意思，是本题要听辨的词。", "码": "mǎ（第三声）与 ma（轻声）声调不同，意思是号码，不是语气词。", "么": "me（轻声）与 ma（轻声）韵母不同（e 与 a），么 用于“什么”“这么”，不是句末语气词。", "啦": "la（轻声）与 ma（轻声）声母不同（l 与 m），啦 是“了啊”的合音，但不是嘛。", "哇": "wa（轻声）与 ma（轻声）声母不同，哇 表示惊讶或赞叹。"}, "sentence_index": null, "correct_answer": "嘛"}, "level_3": {"options": [{"text": "过", "is_correct": false, "explanation": "语法：过 表示经历，“不会就问过”不成话。"}, {"text": "着", "is_correct": false, "explanation": "语法：着 表示持续，不能表达劝说语气。"}, {"text": "嘛", "is_correct": true, "explanation": "嘛 表示“这样做很自然、道理很明白”，正适合用来劝对方不要怕问。"}, {"text": "罢", "is_correct": false, "explanation": "语域：罢 是文言语气词，日常口语中不用，与此句的口语语境不合。"}], "explanations": {"过": "语法：过 表示经历，“不会就问过”不成话。", "着": "语法：着 表示持续，不能表达劝说语气。", "嘛": "嘛 表示“这样做很自然、道理很明白”，正适合用来劝对方不要怕问。", "罢": "语域：罢 是文言语气词，日常口语中不用，与此句的口语语境不合。"}, "sentence_index": 6, "correct_answer": "嘛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天可能会下雨嘛，我们就改去博物馆。", "explanation": "这里应该用〈吧〉。嘛表示事情明显，与“可能”的不确定语气冲突；表示推测要用吧。"}, {"text": "我没见过他几次，他大概是我的老朋友嘛。", "explanation": "这里应该用〈吧〉。嘛表示事情明显，与“大概”的不确定语气冲突；表示推测要用吧。"}, {"text": "这次比赛的结果还没公布，他可能已经拿了冠军嘛。", "explanation": "这里应该用〈吧〉。嘛表示事情明显，与“可能”的不确定语气冲突；表示推测要用吧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们是同学，嘛不用这么客气。", "corrected_sentence": "我们是同学嘛，不用这么客气。", "error_description": "错误：嘛 被放在逗号后、分句开头，写成“嘛不用”，句子不通。正确：嘛 应紧跟在说明道理的分句末尾（“同学嘛，”），表示“我们是同学”这件事很明显，所以不用客气。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他住在这附近嘛了，当然认得路。", "corrected_sentence": "他住在这附近嘛，当然认得路。", "error_description": "错误：嘛 后面多加了“了”。嘛 是语气词，不能再接“了”。正确：只用“嘛”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
