INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87773, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比率是两个数拿来比一比，看看一个是另一个的多少。", "primary_collocate": null, "pronunciation": "bǐ lǜ", "ipa": "pi˨˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "男生和女生的比率是二比三。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请算一下红球和白球的比率。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班男女比率差不多。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么算比率。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水和糖的比率是十比一。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先把两个数的比率写下来。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大杯和小杯的比率是二比一。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用比率比较这两条路的长度。", "target_word": "比率", "complexity_tier": "T3", "furigana": "wǒ men yòng bǐ lǜ bǐ jiào zhè liǎng tiáo lù de cháng dù。", "sentence_source": "generated"}, {"text": "比率越大，说明前一个数越多。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用比率说明苹果比梨多。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两个数相比得出的倍数关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e864c1b8-57ca-4d3b-9755-214d3c6e6153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比率", "is_correct": true, "explanation": "正确：“比率”指两个数相比的关系，正好符合“二比三”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是可以按数量比较的属性，“男生和女生的颜色是二比三”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不是可以按数量比较的属性，“男生和女生的味道是二比三”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是可以按数量比较的属性，“男生和女生的名字是二比三”说不通。"}], "explanations": {"比率": "正确：“比率”指两个数相比的关系，正好符合“二比三”。", "颜色": "语义：“颜色”不是可以按数量比较的属性，“男生和女生的颜色是二比三”说不通。", "味道": "语义：“味道”不是可以按数量比较的属性，“男生和女生的味道是二比三”说不通。", "名字": "语义：“名字”不是可以按数量比较的属性，“男生和女生的名字是二比三”说不通。"}, "sentence_index": 0, "correct_answer": "比率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的比率是三十岁。", "explanation": "这里应该用〈年龄〉。“比率”表示两个数相比的关系，不能用来说一个人有多大。"}, {"text": "这个班的比率是三十人。", "explanation": "这里应该用〈人数〉。“比率”表示两个数之间的关系，不能直接说明有多少人。"}, {"text": "这本书的比率是二十元。", "explanation": "这里应该用〈价格〉。“比率”是两个数的比，不能直接说明书值多少钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比率", "is_correct": true, "explanation": "正确：“比率”表示两个数的比，正好符合“二比一”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”是人的特点，不能用数字的比来表示，“大杯和小杯的性格是二比一”说不通。"}, {"text": "图案", "is_correct": false, "explanation": "语义：“图案”是图形的样式，不能用数字的比来表示，“大杯和小杯的图案是二比一”说不通。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：“形状”不用数字的比来表示，不能说“形状是二比一”。"}], "explanations": {"比率": "正确：“比率”表示两个数的比，正好符合“二比一”。", "性格": "语义：“性格”是人的特点，不能用数字的比来表示，“大杯和小杯的性格是二比一”说不通。", "图案": "语义：“图案”是图形的样式，不能用数字的比来表示，“大杯和小杯的图案是二比一”说不通。", "形状": "搭配：“形状”不用数字的比来表示，不能说“形状是二比一”。"}, "sentence_index": 6, "correct_answer": "比率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的比率是每小时八十公里。", "explanation": "这里应该用〈速度〉。“比率”是两个数的比，不能用来表示行驶的快慢。"}, {"text": "今天的比率是三十度。", "explanation": "这里应该用〈温度〉。“比率”不是温度的单位或数值，不能说“三十度”。"}, {"text": "这个房间的比率是二十平方米。", "explanation": "这里应该用〈面积〉。“比率”是两个数的比，不能直接说明房间有多大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次调查算出了一只比率。", "corrected_sentence": "这次调查算出了一个比率。", "error_description": "量词错误：“比率”前应用“个”，不能用“只”。“只”用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们比率说明一班的男生比女生多。", "corrected_sentence": "我们用比率说明一班的男生比女生多。", "error_description": "漏字错误：“我们比率说明”缺少“用”；正确：“我们用比率说明”。“比率”作为工具，要用“用”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
