INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87774, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个相关数值的比，常用百分数表示。", "primary_collocate": null, "pronunciation": "bǐ lǜ", "ipa": "pi˨˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "今年学生的合格比率是百分之九十。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司男女员工的比率差不多是一比一。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市老人的比率越来越高。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试通过的比率提高了。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里用百分数写出了比率。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年男生的比率比今年低。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学生戴眼镜的比率在上升。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比率超过了百分之五十。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想降低坏产品的比率。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们算出了人口的比率。", "target_word": "比率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用百分数表示的两个相关数值之比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e864c1b8-57ca-4d3b-9755-214d3c6e6153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比率", "is_correct": true, "explanation": "正确：“比率”用百分数表示两个相关数值之比，正好符合“百分之九十”。"}, {"text": "人数", "is_correct": false, "explanation": "语义：“人数”是个数，不能说“合格人数是百分之九十”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用百分数表示，“合格颜色”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是长度，不用百分数表示，“合格身高是百分之九十”说不通。"}], "explanations": {"比率": "正确：“比率”用百分数表示两个相关数值之比，正好符合“百分之九十”。", "人数": "语义：“人数”是个数，不能说“合格人数是百分之九十”。", "颜色": "语义：“颜色”不能用百分数表示，“合格颜色”说不通。", "身高": "语义：“身高”是长度，不用百分数表示，“合格身高是百分之九十”说不通。"}, "sentence_index": 0, "correct_answer": "比率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛的比率是下午三点。", "explanation": "这里应该用〈时间〉。“比率”是两个数的比，不能用来表示比赛开始的时刻。"}, {"text": "这次考试的比率是三十人。", "explanation": "这里应该用〈人数〉。“比率”表示两个数之间的关系，不能直接说明有多少人。"}, {"text": "这朵花的比率是红色。", "explanation": "这里应该用〈颜色〉。“比率”是两个数的比，不能用来说一朵花是什么颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比率", "is_correct": true, "explanation": "正确：“比率”指相关数量之间的比，“小学生戴眼镜的比率在上升”正确。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不会“在上升”，句子说不通。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“音量”指声音的大小，不能说“小学生戴眼镜的音量在上升”。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：“字迹”是写出来的字的样子，和“戴眼镜”没有关系，“在上升”也说不通。"}], "explanations": {"比率": "正确：“比率”指相关数量之间的比，“小学生戴眼镜的比率在上升”正确。", "名字": "语义：“名字”不会“在上升”，句子说不通。", "音量": "搭配：“音量”指声音的大小，不能说“小学生戴眼镜的音量在上升”。", "字迹": "语义：“字迹”是写出来的字的样子，和“戴眼镜”没有关系，“在上升”也说不通。"}, "sentence_index": 6, "correct_answer": "比率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的比率是六十公斤。", "explanation": "这里应该用〈体重〉。“比率”是两个数的比，不能用来说明重量。"}, {"text": "这条路的比率是三百米。", "explanation": "这里应该用〈长度〉。“比率”不是距离，不能说“三百米”。"}, {"text": "这本书的比率是二十元。", "explanation": "这里应该用〈价格〉。“比率”是两个数的比，不能直接说明书值多少钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "报告里写出了一只比率。", "corrected_sentence": "报告里写出了一个比率。", "error_description": "量词错误：“比率”前应用“个”，不能用“只”。“只”用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把比率说明今年合格的学生比去年多。", "corrected_sentence": "老师用比率说明今年合格的学生比去年多。", "error_description": "介词错误：表示凭借的手段要用“用”，应说“用比率说明”，不能用“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
