INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87775, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "以内是在某个范围里面，没有超出去。", "primary_collocate": null, "pronunciation": "yǐ nèi", "ipa": "i˨˩ nei˥˩", "syllable_count": 2, "sentences": [{"text": "这次旅行的钱要在五千元以内。", "target_word": "以内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的问题控制在三个以内。", "target_word": "以内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在学校一公里以内，走路就到。", "target_word": "以内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛只收十岁以内的孩子。", "target_word": "以内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月的手机费都在一百元以内。", "target_word": "以内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把作文写在三百字以内。", "target_word": "以内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校附近一公里以内有三家银行。", "target_word": "以内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的时间在两个小时以内。", "target_word": "以内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三天以内，我一定给你回信。", "target_word": "以内", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一百块以内的礼物，你都可以买。", "target_word": "以内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在数量、距离、时间词后，表示没有超出这个范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aa1c745-16a8-430c-a276-d96c4b94600f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87775, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以内", "is_correct": true, "explanation": "正确：“以内”表示在五千元的范围之内，与“要在”的限制相符。"}, {"text": "以外", "is_correct": false, "explanation": "语义：“以外”表示超出五千元，与“要在”规定的上限相反。"}, {"text": "之间", "is_correct": false, "explanation": "搭配：“之间”需要两个界限，不能只说“五千元之间”。"}, {"text": "以前", "is_correct": false, "explanation": "搭配：“以前”指时间上的先后，不能用来表示金额。"}], "explanations": {"以内": "正确：“以内”表示在五千元的范围之内，与“要在”的限制相符。", "以外": "语义：“以外”表示超出五千元，与“要在”规定的上限相反。", "之间": "搭配：“之间”需要两个界限，不能只说“五千元之间”。", "以前": "搭配：“以前”指时间上的先后，不能用来表示金额。"}, "sentence_index": 0, "correct_answer": "以内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把东西都放在书架以内。", "explanation": "这里应该用〈上〉。以内用于数量、时间或距离的范围，不表示物体的位置，应说“放在书架上”。"}, {"text": "他的家在学校和超市以内。", "explanation": "这里应该用〈之间〉。以内只限定一个界限之内，两个地点中间的位置要用“之间”。"}, {"text": "他在困难以内仍然坚持学习。", "explanation": "这里应该用〈之中〉。以内表示数量、时间或距离的范围，不能用于困难这类处境，处境里要用“之中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87775, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以内", "is_correct": true, "explanation": "正确：“以内”表示在一公里的距离之内，与“附近”相符。"}, {"text": "期间", "is_correct": false, "explanation": "搭配：“期间”指一段时间，不能用来表示距离。"}, {"text": "以上", "is_correct": false, "explanation": "语义：“以上”表示超过一公里，与“附近”的近距离相矛盾。"}, {"text": "以来", "is_correct": false, "explanation": "搭配：“以来”指从过去某时起到现在，不能用于距离。"}], "explanations": {"以内": "正确：“以内”表示在一公里的距离之内，与“附近”相符。", "期间": "搭配：“期间”指一段时间，不能用来表示距离。", "以上": "语义：“以上”表示超过一公里，与“附近”的近距离相矛盾。", "以来": "搭配：“以来”指从过去某时起到现在，不能用于距离。"}, "sentence_index": 6, "correct_answer": "以内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你三点以内到办公室。", "explanation": "这里应该用〈之前〉。以内表示一段范围，不能用于具体的时间点。"}, {"text": "我从三岁以内一直住在这里。", "explanation": "这里应该用〈以来〉。以内只表示范围，不能表示从过去某时开始一直持续到现在。"}, {"text": "我们干到三点以内。", "explanation": "这里应该用〈为止〉。以内表示范围，不能表示动作进行到某个终点就停止。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书的价格以二十元以内。", "corrected_sentence": "这本书的价格在二十元以内。", "error_description": "介词误用：“以”不能引出数量范围，应使用介词“在”，说“在二十元以内”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个包裹的重量在两公斤的以内。", "corrected_sentence": "这个包裹的重量在两公斤以内。", "error_description": "结构错误：“以内”直接放在数量词后面，中间不能加“的”，应说“在两公斤以内”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
