INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87777, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "主持是在一个活动里带着大家，安排大家一个一个来。", "primary_collocate": null, "pronunciation": "zhǔ chí", "ipa": "ʈʂu˨˩˦ ʈʂʰɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "晚会请小李来主持。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在晚会上主持节目，大家都笑了。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次主持生日会，有点儿紧张。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的活动谁主持？", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她主持得很好，每个人都能说话。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他主持唱歌比赛，一个一个叫名字。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你主持一下，让大家一个一个说。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节晚会由两个人主持。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢在朋友的聚会上主持活动。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王主持过学校的新年晚会。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主持了", "label": "体标"}, {"form": "主持过", "label": "体标"}, {"form": "主持人", "label": "复合"}], "register": "中性", "sense_fingerprint": "在活动里带着大家并安排大家依次参与", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fcb4ee2-f2e1-4070-afe6-cb4d17410cdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87777, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主持", "is_correct": true, "explanation": "主持：在晚会上带领大家、安排节目，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：请人来晚会“睡觉”，句意不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”与请人来晚会没有关系，句子不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：请小李来晚会“游泳”，与晚会无关，句意不通。"}], "explanations": {"主持": "主持：在晚会上带领大家、安排节目，符合句意。", "睡觉": "语义：请人来晚会“睡觉”，句意不通。", "洗澡": "语义：“洗澡”与请人来晚会没有关系，句子不通。", "游泳": "语义：请小李来晚会“游泳”，与晚会无关，句意不通。"}, "sentence_index": 0, "correct_answer": "主持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他主持了一封信，很认真。", "explanation": "这里应该用〈写〉。主持指在活动里带领大家依次参与，不能用来说信件。"}, {"text": "他每天主持花，很认真。", "explanation": "这里应该用〈浇〉。主持指在活动里带领大家依次参与，不能用来说浇花。"}, {"text": "他在纸上主持了一幅画。", "explanation": "这里应该用〈画〉。主持指在活动里带领大家依次参与，不能用来说画画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87777, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主持", "is_correct": true, "explanation": "主持：带领大家依次发言，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”和安排大家依次发言没有关系，句子不通。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”接桌面、物品，不能用来安排发言顺序。"}, {"text": "拆", "is_correct": false, "explanation": "配价：“拆”需要具体的物体作宾语，这里没有，句子不成立。"}], "explanations": {"主持": "主持：带领大家依次发言，符合句意。", "吃": "语义：“吃”和安排大家依次发言没有关系，句子不通。", "擦": "搭配：“擦”接桌面、物品，不能用来安排发言顺序。", "拆": "配价：“拆”需要具体的物体作宾语，这里没有，句子不成立。"}, "sentence_index": 6, "correct_answer": "主持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在晚会上主持了一首歌，大家都鼓掌。", "explanation": "这里应该用〈演唱〉。“主持”指带领、串联节目，不表示自己唱歌这个具体动作。"}, {"text": "她在台上主持了一段舞蹈。", "explanation": "这里应该用〈表演〉。“主持”是带领、安排大家依次参与，不表示自己跳舞。"}, {"text": "她在窗前主持衣服。", "explanation": "这里应该用〈晾〉。主持指在活动里带领大家依次参与，不能用来说晾衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他主持地很有趣，大家都笑了。", "corrected_sentence": "他主持得很有趣，大家都笑了。", "error_description": "结构助词错误：动词后带程度补语要用“得”，不能用“地”，应说“主持得很有趣”；“地”用于动词前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她主持很好，大家都很满意。", "corrected_sentence": "她主持得很好，大家都很满意。", "error_description": "补语连接词缺失：动词后带程度补语时中间要加“得”，应说“主持得很好”；只说“主持很好”，句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
