INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87778, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "负责掌握、处理或带领（会议、活动等）。", "primary_collocate": null, "pronunciation": "zhǔ chí", "ipa": "ʈʂu˨˩˦ ʈʂʰɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "明天的会议由王经理主持。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来主持今天的会？", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我主持这次班会。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他主持过很多次大会。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理正在主持会议。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会议我来主持，你们准备吧。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长主持了开学典礼。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她主持会议很认真。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个星期一的会，都由他主持。", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能不能帮我主持一下今天的会议？", "target_word": "主持", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主持了", "label": "体标"}, {"form": "主持过", "label": "体标"}, {"form": "主持人", "label": "复合"}], "register": "中性", "sense_fingerprint": "负责掌握并带领会议或活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fcb4ee2-f2e1-4070-afe6-cb4d17410cdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主持", "is_correct": true, "explanation": "主持：负责带领会议，与“由王经理”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能说“吃会议”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”接房间、场地，不接“会议”。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能带“会议”作宾语。"}], "explanations": {"主持": "主持：负责带领会议，与“由王经理”搭配，符合句意。", "吃": "语义：“吃”的对象是食物，不能说“吃会议”。", "打扫": "搭配：“打扫”接房间、场地，不接“会议”。", "睡": "配价：“睡”是不及物动词，后面不能带“会议”作宾语。"}, "sentence_index": 0, "correct_answer": "主持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在主持电梯，很辛苦。", "explanation": "这里应该用〈修理〉。主持指负责带领会议或活动，不能用来说电梯。"}, {"text": "她每天主持窗户，很辛苦。", "explanation": "这里应该用〈擦〉。主持指负责带领会议或活动，不能用来说擦窗户这类具体动作。"}, {"text": "他正在主持卧室的墙。", "explanation": "这里应该用〈粉刷〉。主持指负责带领会议或活动，不能用来说墙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主持", "is_correct": true, "explanation": "主持：带领、掌握典礼的进行，符合句意。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”接桌子、玻璃等，不接“典礼”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮料，不能说“喝典礼”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“开学典礼”作宾语。"}], "explanations": {"主持": "主持：带领、掌握典礼的进行，符合句意。", "擦": "搭配：“擦”接桌子、玻璃等，不接“典礼”。", "喝": "语义：“喝”的对象是饮料，不能说“喝典礼”。", "哭": "配价：“哭”是不及物动词，不能带“开学典礼”作宾语。"}, "sentence_index": 6, "correct_answer": "主持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他主持过学校的秘书。", "explanation": "这里应该用〈担任〉。“主持”指带领会议，不能用来说明职务，应说“担任秘书”。"}, {"text": "他在比赛中主持了一个球。", "explanation": "这里应该用〈踢进〉。主持指负责带领会议或活动，不能用来说球员的动作。"}, {"text": "他主持过班长，管得很好。", "explanation": "这里应该用〈当〉。“主持”不能接职务名词“班长”，应说“当班长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她主持地很认真，大家都很满意。", "corrected_sentence": "她主持得很认真，大家都很满意。", "error_description": "结构助词错误：动词后带程度补语要用“得”，不能用“地”，应说“主持得很认真”；“地”用于动词前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他主持着两次班会。", "corrected_sentence": "他主持过两次班会。", "error_description": "体标错误：表示经历过几次，要用“过”，不能用“着”。“着”表示动作或状态的持续，不能与“两次”搭配，应说“主持过两次班会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87779, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱歌", "is_correct": false, "explanation": "与“回到”无反义关系：“唱歌”与返回某地没有对立。"}, {"text": "离开", "is_correct": true, "explanation": "“离开”与“回到”意义相反，指离去某处，正与“回到院子里”相对。"}, {"text": "讨论", "is_correct": false, "explanation": "与“回到”无反义关系：“讨论”与返回某地没有对立。"}, {"text": "参加", "is_correct": false, "explanation": "与“回到”无反义关系：“参加”与返回某地没有对立。"}], "correct_answer": "离开", "explanations": {"唱歌": "与“回到”无反义关系：“唱歌”与返回某地没有对立。", "离开": "“离开”与“回到”意义相反，指离去某处，正与“回到院子里”相对。", "讨论": "与“回到”无反义关系：“讨论”与返回某地没有对立。", "参加": "与“回到”无反义关系：“参加”与返回某地没有对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87779, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "观察", "is_correct": false, "explanation": "与“回到”无反义关系：“观察”是看的动作，与返回某地没有对立。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“回到”无反义关系：“吃饭”与返回某地没有对立。"}, {"text": "散步", "is_correct": false, "explanation": "与“回到”无反义关系：“散步”与返回某地没有对立。"}, {"text": "离开", "is_correct": true, "explanation": "“离开”与“回到”意义相反，指离去某处，正与“回到出生的地方”相对。"}], "correct_answer": "离开", "explanations": {"观察": "与“回到”无反义关系：“观察”是看的动作，与返回某地没有对立。", "吃饭": "与“回到”无反义关系：“吃饭”与返回某地没有对立。", "散步": "与“回到”无反义关系：“散步”与返回某地没有对立。", "离开": "“离开”与“回到”意义相反，指离去某处，正与“回到出生的地方”相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87779, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回到是走回原来待过的地方。", "primary_collocate": null, "pronunciation": "huí dào", "ipa": "xweɪ̯˧˥ tɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "孩子玩完以后回到了妈妈身边。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开三年，终于回到了村子。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，我回到宿舍休息。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跑出去玩，又回到了院子里。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买完东西，她马上回到办公室。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天六点回到家，先洗手。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行结束了，我们回到熟悉的小城。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸回到房间，关上了门。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以前，牛羊都回到了山下。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业后他回到了出生的地方。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回到了", "label": "完成体"}, {"form": "回到过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "走回原来待过的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 小狗 (Zipf 3.89), 出去玩 (Zipf 3.4), 院子 (Zipf 3.93)','sentence 8 above tier T1: 3 words above tier T1 (max 2): 天黑 (Zipf 3.56), 牛羊 (Zipf 3.11), 山下 (Zipf 3.7)']::text[], '117b498c-ddd5-4e59-81b8-2a4e87b7131e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87779, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“妈妈身边”作宾语。"}, {"text": "回到", "is_correct": true, "explanation": "“回到”表示走回原来待过的地方，与“玩完以后回到了妈妈身边”相符。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的宾语多是问题或计划，不能接“妈妈身边”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的宾语应是食物，不能吃“妈妈身边”。"}], "explanations": {"散步": "配价：“散步”是不及物动词，不能带“妈妈身边”作宾语。", "回到": "“回到”表示走回原来待过的地方，与“玩完以后回到了妈妈身边”相符。", "讨论": "搭配：“讨论”的宾语多是问题或计划，不能接“妈妈身边”。", "吃": "语义：“吃”的宾语应是食物，不能吃“妈妈身边”。"}, "sentence_index": 0, "correct_answer": "回到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小狗跑出去玩，又回到了一个从没见过的洞里。", "explanation": "这里应该用〈钻进〉。回到表示走回原来待过的地方，“从没见过的洞”不是原来待过的地方；进入新的洞穴要用钻进。"}, {"text": "我们第一次来这个村子，就回到了这里。", "explanation": "这里应该用〈到达〉。回到需要以前待过，第一次来的地方要用到达。"}, {"text": "这趟列车终于回到了它从未停靠过的车站。", "explanation": "这里应该用〈抵达〉。回到表示走回原来待过的地方，列车从未停靠过的车站不能说回到；第一次到达要用抵达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87779, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出发", "is_correct": false, "explanation": "配价：“出发”是不及物动词，不能直接带“小城”作宾语。"}, {"text": "回到", "is_correct": true, "explanation": "“回到”表示回到原来待过的地方，与“旅行结束了，我们回到熟悉的小城”相符。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”的宾语多是活动，不能接“小城”。"}, {"text": "散发", "is_correct": false, "explanation": "搭配：“散发”多接气味、光热，不能接“小城”。"}], "explanations": {"出发": "配价：“出发”是不及物动词，不能直接带“小城”作宾语。", "回到": "“回到”表示回到原来待过的地方，与“旅行结束了，我们回到熟悉的小城”相符。", "举办": "搭配：“举办”的宾语多是活动，不能接“小城”。", "散发": "搭配：“散发”多接气味、光热，不能接“小城”。"}, "sentence_index": 6, "correct_answer": "回到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从没去过那个地方，却回到了那里。", "explanation": "这里应该用〈到达〉。回到需要以前待过，从未去过的地方不能说回到。"}, {"text": "他毕业后回到了那份礼物。", "explanation": "这里应该用〈收到〉。回到只能跟地点或状态，不能以物品作宾语。"}, {"text": "他毕业后回到了那个还没开始的学期。", "explanation": "这里应该用〈进入〉。回到表示走回原来待过的地方或状态，“还没开始的学期”不可能是原来待过的，应该用进入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他放学后回到着家里。", "corrected_sentence": "他放学后回到了家里。", "error_description": "错误：“回到”表示一次性完成的返回，不能加“着”表示进行。完成的动作要用“了”，应说“回到了家里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸昨晚没有回到了房间。", "corrected_sentence": "爸爸昨晚没有回到房间。", "error_description": "错误：“没有”否定动作后不能再加“了”。正确形式是“没有回到房间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
