INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "返回到（某处）。", "primary_collocate": null, "pronunciation": "huí dào", "ipa": "xweɪ̯˧˥ tɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他下班后很快就回到了家。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天下午回到北京。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出差三天，昨天晚上回到了上海。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从国外回到了自己的城市。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，大家回到了酒店。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，请同学们回到座位上。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想早点回到学校上课。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走过很多地方，最后回到了老家。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出差一周，今天回到了家里。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你们十分钟后回到这里。", "target_word": "回到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回到了", "label": "完成体"}, {"form": "回到过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "返回到某个地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '117b498c-ddd5-4e59-81b8-2a4e87b7131e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寄", "is_correct": false, "explanation": "语义：“寄”的宾语应是物品或信件，不能寄“家”。"}, {"text": "回到", "is_correct": true, "explanation": "“回到”表示返回某个地点，与“下班后很快就回到了家”相符。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“家”作宾语。"}, {"text": "感到", "is_correct": false, "explanation": "搭配：“感到”后接感受，如“感到温暖”，不能接“家”作宾语。"}], "explanations": {"寄": "语义：“寄”的宾语应是物品或信件，不能寄“家”。", "回到": "“回到”表示返回某个地点，与“下班后很快就回到了家”相符。", "散步": "配价：“散步”是不及物动词，不能带“家”作宾语。", "感到": "搭配：“感到”后接感受，如“感到温暖”，不能接“家”作宾语。"}, "sentence_index": 0, "correct_answer": "回到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他第一次来上海，终于回到了这座城市。", "explanation": "这里应该用〈到达〉。回到表示回到以前待过的地方，第一次去的城市要用到达。"}, {"text": "他收到一份礼物，又回到了那份礼物。", "explanation": "这里应该用〈找回〉。回到表示走回某个地点或状态，不能以物品作宾语；失而复得的东西要用找回。"}, {"text": "我们一家人回到了一个陌生的小镇。", "explanation": "这里应该用〈搬到〉。回到表示走回原来待过的地方，而“陌生的小镇”从未待过，应该用搬到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与“我想早点”的愿望相矛盾。"}, {"text": "回到", "is_correct": true, "explanation": "“回到”表示返回原来的地方，与“我想早点回到学校上课”的语境相符。"}, {"text": "思考", "is_correct": false, "explanation": "搭配：“思考”不能以“学校”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能带“学校”作宾语。"}], "explanations": {"讨厌": "语义：“讨厌”表示厌恶，与“我想早点”的愿望相矛盾。", "回到": "“回到”表示返回原来的地方，与“我想早点回到学校上课”的语境相符。", "思考": "搭配：“思考”不能以“学校”作宾语。", "唱": "配价：“唱”不能带“学校”作宾语。"}, "sentence_index": 6, "correct_answer": "回到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他还没出生的时候，就回到了这座城市。", "explanation": "这里应该用〈来到〉。回到表示走回原来待过的地方，而他还没出生，不可能待过这座城市，应该用来到。"}, {"text": "我从来没去过北京，却回到了北京。", "explanation": "这里应该用〈到达〉。回到需要以前待过，从未去过的地方不能说回到。"}, {"text": "他昨天才认识我们，今天就回到了我们中间。", "explanation": "这里应该用〈加入〉。回到表示重回原来待过的位置；刚认识的人成为团体一员应说加入，不能说回到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她周末就回到着老家。", "corrected_sentence": "她周末就回到了老家。", "error_description": "错误：“回到”表示一次性完成的返回，不能加“着”表示进行。完成的动作要用“了”，应说“回到了老家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我终于被回到了老家。", "corrected_sentence": "我终于回到了老家。", "error_description": "错误：“回到”表示主语自己返回某地，不是被别人处置的动作，不能用“被”构成被动句。正确形式是“我终于回到了老家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670b84e2-0a44-43ee-9a7c-0d30441297b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
