INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87781, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "民族主义是人们特别爱自己的民族，想让自己的民族好。", "primary_collocate": null, "pronunciation": "mín zú zhǔ yì", "ipa": "min˧˥ tsu˧˥ ʈʂu˨˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "他的民族主义很强，总是先想自己的民族。", "target_word": "民族主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人因为民族主义，特别爱自己的民族。", "target_word": "民族主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民族主义让很多人觉得自己的民族最好。", "target_word": "民族主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说，民族主义不是不喜欢别人。", "target_word": "民族主义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过分的民族主义会让人看不起别的民族。", "target_word": "民族主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小听故事，心里有很深的民族主义。", "target_word": "民族主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的民族主义很深。", "target_word": "民族主义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛时，我们能看到球迷的民族主义。", "target_word": "民族主义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "民族主义太强，人就不容易听别人的话。", "target_word": "民族主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，民族主义是爱自己的民族。", "target_word": "民族主义", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "民族主义者", "label": "派生"}], "register": "书面", "sense_fingerprint": "人们对自己民族的强烈感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e864c1b8-57ca-4d3b-9755-214d3c6e6153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87781, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民族主义", "is_correct": true, "explanation": "正确：“民族主义”是对本民族的强烈感情，“总是先想自己的民族”正好符合。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”是长度，不能说“很强”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或口感，和“先想自己的民族”不搭。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是岁数，不能说“很强”，与后半句也不搭。"}], "explanations": {"民族主义": "正确：“民族主义”是对本民族的强烈感情，“总是先想自己的民族”正好符合。", "身高": "搭配：“身高”是长度，不能说“很强”。", "味道": "语义：“味道”指气味或口感，和“先想自己的民族”不搭。", "年龄": "语义：“年龄”是岁数，不能说“很强”，与后半句也不搭。"}, "sentence_index": 0, "correct_answer": "民族主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有早起的民族主义。", "explanation": "这里应该用〈习惯〉。民族主义是一种感情和想法，不是可以养成的行为习惯。"}, {"text": "他的民族主义是下午三点。", "explanation": "这里应该用〈时间〉。民族主义是一种感情，不是时间，不能说它在几点。"}, {"text": "他的民族主义是打篮球。", "explanation": "这里应该用〈爱好〉。民族主义是对民族的感情，不是可以拿来做的活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87781, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民族主义", "is_correct": true, "explanation": "正确：“民族主义”是一种感情，“这位老人的民族主义很深”正确。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不能说“很深”，句子说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”一般说“很重”或“很轻”，不说“很深”。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“学历”不说“很深”，要说“学问很深”。"}], "explanations": {"民族主义": "正确：“民族主义”是一种感情，“这位老人的民族主义很深”正确。", "名字": "语义：“名字”不能说“很深”，句子说不通。", "脚步": "搭配：“脚步”一般说“很重”或“很轻”，不说“很深”。", "学历": "搭配：“学历”不说“很深”，要说“学问很深”。"}, "sentence_index": 6, "correct_answer": "民族主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的民族主义有一米八。", "explanation": "这里应该用〈身高〉。民族主义是抽象的感情，不能用来说身高。"}, {"text": "我们在民族主义里跑了一圈。", "explanation": "这里应该用〈操场〉。民族主义是思想，不能说在里面跑步。"}, {"text": "他买的民族主义是十块钱一斤。", "explanation": "这里应该用〈水果〉。民族主义是抽象的思想，不是可以按斤卖的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里有一只民族主义，很爱自己的国家。", "corrected_sentence": "他心里有一种民族主义，很爱自己的国家。", "error_description": "量词错误：“民族主义”前应用“种”，不能用“只”。“只”用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她民族主义很感兴趣。", "corrected_sentence": "她对民族主义很感兴趣。", "error_description": "介词遗漏：“感兴趣”的对象要用介词“对”引出，应说“对民族主义很感兴趣”，不能省去“对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87782, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "国际主义", "is_correct": true, "explanation": "正确：国际主义主张各国人民联合，与强调本民族利益与独立的民族主义相对。"}, {"text": "经济", "is_correct": false, "explanation": "无关：“经济”与民族主义的思想内容没有反义关系。"}, {"text": "科学", "is_correct": false, "explanation": "无关：“科学”指知识体系，不与民族主义构成反义。"}, {"text": "音乐", "is_correct": false, "explanation": "无关：“音乐”是艺术形式，与民族主义没有反义关系。"}], "correct_answer": "国际主义", "explanations": {"国际主义": "正确：国际主义主张各国人民联合，与强调本民族利益与独立的民族主义相对。", "经济": "无关：“经济”与民族主义的思想内容没有反义关系。", "科学": "无关：“科学”指知识体系，不与民族主义构成反义。", "音乐": "无关：“音乐”是艺术形式，与民族主义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87782, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "国际主义", "is_correct": true, "explanation": "正确：国际主义主张各国人民联合，与强调本民族利益与独立的民族主义相对。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是家具，与民族主义没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是地理事物，与民族主义没有反义关系。"}, {"text": "钢笔", "is_correct": false, "explanation": "无关：“钢笔”是书写工具，与民族主义没有反义关系。"}], "correct_answer": "国际主义", "explanations": {"国际主义": "正确：国际主义主张各国人民联合，与强调本民族利益与独立的民族主义相对。", "桌子": "无关：“桌子”是家具，与民族主义没有反义关系。", "河流": "无关：“河流”是地理事物，与民族主义没有反义关系。", "钢笔": "无关：“钢笔”是书写工具，与民族主义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "强调本民族利益、文化与独立的思想和运动。", "primary_collocate": null, "pronunciation": "mín zú zhǔ yì", "ipa": "min˧˥ tsu˧˥ ʈʂu˨˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "十九世纪，欧洲出现了民族主义运动。", "target_word": "民族主义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书讲的是民族主义的历史。", "target_word": "民族主义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "民族主义思想让这个国家得到了独立。", "target_word": "民族主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里研究民族主义。", "target_word": "民族主义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "民族主义运动要求国家独立和文化自由。", "target_word": "民族主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了亚洲的民族主义思想。", "target_word": "民族主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家的独立都和民族主义有关。", "target_word": "民族主义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家的文章常常谈民族主义。", "target_word": "民族主义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "民族主义强调本民族的文化和利益。", "target_word": "民族主义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在那个年代，民族主义影响了很多人。", "target_word": "民族主义", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "民族主义者", "label": "派生"}], "register": "书面", "sense_fingerprint": "强调本民族利益与独立的思想和运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e864c1b8-57ca-4d3b-9755-214d3c6e6153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民族主义", "is_correct": true, "explanation": "正确：十九世纪欧洲的“民族主义运动”是历史上真实存在的运动，正好符合句意。"}, {"text": "互联网", "is_correct": false, "explanation": "语义：十九世纪还没有互联网，“互联网运动”说不通。"}, {"text": "数码", "is_correct": false, "explanation": "语义：“数码”是现代技术，十九世纪不可能出现“数码运动”。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“运动”不能和“手机”搭配，“手机运动”不成词。"}], "explanations": {"民族主义": "正确：十九世纪欧洲的“民族主义运动”是历史上真实存在的运动，正好符合句意。", "互联网": "语义：十九世纪还没有互联网，“互联网运动”说不通。", "数码": "语义：“数码”是现代技术，十九世纪不可能出现“数码运动”。", "手机": "搭配：“运动”不能和“手机”搭配，“手机运动”不成词。"}, "sentence_index": 0, "correct_answer": "民族主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种民族主义是三十元一斤。", "explanation": "这里应该用〈商品〉。民族主义是思想，不是可以按斤卖的东西。"}, {"text": "他在大学里吃民族主义。", "explanation": "这里应该用〈研究〉。民族主义是抽象的思想，不是食物，不能“吃”。"}, {"text": "他的民族主义比他爸爸还高。", "explanation": "这里应该用〈身高〉。民族主义是思想，不是人的身体，不能用来比身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民族主义", "is_correct": true, "explanation": "正确：“独立”与“民族主义”有关，句子说的是这种思想与国家独立的关系。"}, {"text": "天气", "is_correct": false, "explanation": "语义：独立和天气没有关系，“和天气有关”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“有关”后接的是抽象的事情，不接“颜色”。"}, {"text": "食物", "is_correct": false, "explanation": "语义：国家独立和食物没有关系，句子说不通。"}], "explanations": {"民族主义": "正确：“独立”与“民族主义”有关，句子说的是这种思想与国家独立的关系。", "天气": "语义：独立和天气没有关系，“和天气有关”说不通。", "颜色": "搭配：“有关”后接的是抽象的事情，不接“颜色”。", "食物": "语义：国家独立和食物没有关系，句子说不通。"}, "sentence_index": 6, "correct_answer": "民族主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在民族主义里跑了一圈。", "explanation": "这里应该用〈操场〉。民族主义是思想，不能说在里面跑步。"}, {"text": "他把民族主义涂成了蓝色。", "explanation": "这里应该用〈墙〉。民族主义是抽象的思想，不是可以涂上颜色的东西。"}, {"text": "他的民族主义有三十页。", "explanation": "这里应该用〈书页〉。民族主义是思想，不是书，不能用页数来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只很重要的民族主义。", "corrected_sentence": "这是一种很重要的民族主义。", "error_description": "量词错误：“民族主义”前应用“种”，不能用“只”。“只”用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对民族主义研究的很深入。", "corrected_sentence": "他对民族主义研究得很深入。", "error_description": "补语标记错误：连接补语的结构助词应为“得”，不能用“的”。应说“研究得很深入”，不能说“研究的很深入”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d39b49-4b4f-4c30-b99d-9d336f7e775c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
