INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87783, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "伴侣是一起过日子、做伴的人。", "primary_collocate": null, "pronunciation": "bàn lǚ", "ipa": "pan˥˩ ly˨˩˦", "syllable_count": 2, "sentences": [{"text": "老人一个人住，很想有个伴侣。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的伴侣很会照顾人。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人不一定要结婚才能有伴侣。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她找到了可以过一辈子的伴侣。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是互相照顾的老年伴侣。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上回到家，伴侣已经把饭做好了。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有伴侣以后，他的生活变得热闹了。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和伴侣一起搬到了新城市。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的伴侣会互相理解，互相帮助。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对伴侣说：“今天我来洗碗。”", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "对", "label": "量词"}, {"form": "人生伴侣", "label": "复合"}, {"form": "生活伴侣", "label": "复合"}], "register": "中性", "sense_fingerprint": "一起过日子、互相做伴的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c3fb48-7015-4f79-9d9c-8a4eda67e6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87783, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伴侣", "is_correct": true, "explanation": "“伴侣”指互相做伴、一起过日子的人，与“一个人住，很想有人做伴”相合。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：“顾客”指购买东西的人，与老人想有人做伴的意思不合。"}, {"text": "房东", "is_correct": false, "explanation": "语义：“房东”指出租房屋的人，与想有人做伴的需要不合。"}, {"text": "老板", "is_correct": false, "explanation": "语义：“老板”指雇用他人的人，与“一个人住，很想有人做伴”不合。"}], "explanations": {"伴侣": "“伴侣”指互相做伴、一起过日子的人，与“一个人住，很想有人做伴”相合。", "顾客": "语义：“顾客”指购买东西的人，与老人想有人做伴的意思不合。", "房东": "语义：“房东”指出租房屋的人，与想有人做伴的需要不合。", "老板": "语义：“老板”指雇用他人的人，与“一个人住，很想有人做伴”不合。"}, "sentence_index": 0, "correct_answer": "伴侣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "司机今天接了很多伴侣。", "explanation": "这里应该用〈乘客〉。“伴侣”指互相做伴、一起过日子的人，不指临时搭车的人。"}, {"text": "老师教了很多伴侣。", "explanation": "这里应该用〈学生〉。“伴侣”指互相做伴的人，不用于课堂上的学生。"}, {"text": "我们公司今天招了很多伴侣。", "explanation": "这里应该用〈员工〉。“伴侣”指互相做伴、一起过日子的人，不指公司里的员工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87783, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伴侣", "is_correct": true, "explanation": "“伴侣”指一起过日子的人，与“他的生活变得热闹”相合。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：“墓地”指埋葬死者的地方，与“生活变得热闹”正相反。"}, {"text": "皱纹", "is_correct": false, "explanation": "体貌：“皱纹”是面部的纹路，属于外表特征，不能使生活变热闹。"}, {"text": "手术", "is_correct": false, "explanation": "语义：“手术”是医疗操作，与“生活变得热闹”的意思不合。"}], "explanations": {"伴侣": "“伴侣”指一起过日子的人，与“他的生活变得热闹”相合。", "墓地": "语义：“墓地”指埋葬死者的地方，与“生活变得热闹”正相反。", "皱纹": "体貌：“皱纹”是面部的纹路，属于外表特征，不能使生活变热闹。", "手术": "语义：“手术”是医疗操作，与“生活变得热闹”的意思不合。"}, "sentence_index": 6, "correct_answer": "伴侣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一台伴侣。", "explanation": "这里应该用〈位〉。“伴侣”指人，不能用指机器的量词“台”。"}, {"text": "他看了一部伴侣。", "explanation": "这里应该用〈位〉。“伴侣”指人，不能用指影视、书籍的量词“部”。"}, {"text": "门口站着一扇伴侣。", "explanation": "这里应该用〈位〉。“伴侣”指人，不能用指门的量词“扇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87783, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于找到了一伴侣。", "corrected_sentence": "他终于找到了一位伴侣。", "error_description": "量词缺失：“伴侣”指人，数词“一”后须加量词“位”，不能直接说“一伴侣”。正确形式是“他终于找到了一位伴侣”，错误形式是“他终于找到了一伴侣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87783, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找到了一位能一起过日子伴侣。", "corrected_sentence": "他找到了一位能一起过日子的伴侣。", "error_description": "结构助词缺失：定语“能一起过日子”与中心词“伴侣”之间须加“的”。正确形式是“他找到了一位能一起过日子的伴侣”，错误形式是“他找到了一位能一起过日子伴侣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
