INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同在一起生活、工作的人，多指夫妻。", "primary_collocate": null, "pronunciation": "bàn lǚ", "ipa": "pan˥˩ ly˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们结婚十年了，是很好的生活伴侣。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她希望找一个爱旅行的伴侣。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张和老伴是一对幸福的伴侣。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和他一起开店的伴侣就是他的妻子。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚时，他们说要做一辈子的伴侣。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的伴侣今天陪我去看医生。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的伴侣去年去世了，他很难过。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们既是夫妻，也是工作上的伴侣。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和伴侣每个周末都一起做饭。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选择伴侣时，性格比外表更重要。", "target_word": "伴侣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "对", "label": "量词"}, {"form": "人生伴侣", "label": "复合"}, {"form": "生活伴侣", "label": "复合"}], "register": "中性", "sense_fingerprint": "一起生活、工作的人，多指夫妻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c3fb48-7015-4f79-9d9c-8a4eda67e6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伴侣", "is_correct": true, "explanation": "“伴侣”指一起生活的人，多指配偶，与“结婚十年”相合。"}, {"text": "对手", "is_correct": false, "explanation": "语义：“对手”指竞争的一方，与夫妻之间的亲密生活不合。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：“顾客”指购买商品的人，与夫妻关系不合。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指搭乘交通工具的人，与夫妻共同生活的意思不合。"}], "explanations": {"伴侣": "“伴侣”指一起生活的人，多指配偶，与“结婚十年”相合。", "对手": "语义：“对手”指竞争的一方，与夫妻之间的亲密生活不合。", "顾客": "语义：“顾客”指购买商品的人，与夫妻关系不合。", "乘客": "语义：“乘客”指搭乘交通工具的人，与夫妻共同生活的意思不合。"}, "sentence_index": 0, "correct_answer": "伴侣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找到了一辆伴侣。", "explanation": "这里应该用〈位〉。“伴侣”指人，量词用“位”或“个”，不能用指车辆的“辆”。"}, {"text": "我家门前种了一棵伴侣。", "explanation": "这里应该用〈位〉。“伴侣”指人，不能用指植物的量词“棵”。"}, {"text": "书架上放着一本伴侣。", "explanation": "这里应该用〈位〉。“伴侣”指人，不能用指书籍的量词“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伴侣", "is_correct": true, "explanation": "“伴侣”指一起生活的人，与“这位老人的伴侣去世”的情境相合。"}, {"text": "房子", "is_correct": false, "explanation": "配价：“去世”的主语须是人，“房子”不能作主语去世。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”没有生命，与“去世”的语义不合。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”没有生命，不能“去世”，与句意不合。"}], "explanations": {"伴侣": "“伴侣”指一起生活的人，与“这位老人的伴侣去世”的情境相合。", "房子": "配价：“去世”的主语须是人，“房子”不能作主语去世。", "电脑": "语义：“电脑”没有生命，与“去世”的语义不合。", "手机": "语义：“手机”没有生命，不能“去世”，与句意不合。"}, "sentence_index": 6, "correct_answer": "伴侣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师今年教了三十个伴侣。", "explanation": "这里应该用〈学生〉。“伴侣”指一起生活、工作的人，多指夫妻，不指学校里的学生。"}, {"text": "这座城市里有两百万伴侣。", "explanation": "这里应该用〈居民〉。“伴侣”指一起生活、工作的人，多指夫妻，不指整座城市的人口。"}, {"text": "这盘棋他是我的伴侣，我们在棋盘上互相厮杀。", "explanation": "这里应该用〈对手〉。“伴侣”指一起生活、工作的人，不指下棋或比赛时互相竞争的一方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于找到了一只好伴侣。", "corrected_sentence": "她终于找到了一位好伴侣。", "error_description": "量词错误：“伴侣”指人，应用量词“位”；“只”多用于动物或成对之物，不能修饰人。正确形式是“一位好伴侣”，错误形式是“一只好伴侣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们是很好伴侣。", "corrected_sentence": "他们是很好的伴侣。", "error_description": "结构助词缺失：形容词“好”与名词之间应用“的”连接。正确形式是“很好的伴侣”，错误形式是“很好伴侣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
