INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87785, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事故是没有想到的坏事，有时会让人受伤。", "primary_collocate": null, "pronunciation": "shì gù", "ipa": "ʂɻ̩⁵¹ ku⁵¹", "syllable_count": 2, "sentences": [{"text": "路上下雨，前面发生了一起事故。", "target_word": "事故", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机开车太快，所以出了事故。", "target_word": "事故", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故让两个人受了伤。", "target_word": "事故", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂发生事故后，大家都很担心。", "target_word": "事故", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时看手机，很容易出事故。", "target_word": "事故", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好没有人在事故中受伤。", "target_word": "事故", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在处理路口的事故。", "target_word": "事故", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为一次事故，不能再开车了。", "target_word": "事故", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪天路滑，事故特别多。", "target_word": "事故", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要小心，别出什么事故。", "target_word": "事故", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一起事故", "label": "量词"}, {"form": "交通事故", "label": "复合"}], "register": "中性", "sense_fingerprint": "没有想到的、可能让人受伤的坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43e9cbc-284b-4337-94c6-a22041e14477') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87785, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好事", "is_correct": false, "explanation": "语义：“好事”与“没有想到的坏事”意思相反，不能用在这里。"}, {"text": "事故", "is_correct": true, "explanation": "正确。“发生了一起事故”指意外发生了坏事，与“下雨”的语境相符。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“一起”计数的是事件，不能说“一起雨”，而且句中已经有“下雨”。"}, {"text": "演出", "is_correct": false, "explanation": "语义：演出是事先安排好的活动，不会“突然发生”，不能说“发生了一起演出”。"}], "explanations": {"好事": "语义：“好事”与“没有想到的坏事”意思相反，不能用在这里。", "事故": "正确。“发生了一起事故”指意外发生了坏事，与“下雨”的语境相符。", "雨": "搭配：“一起”计数的是事件，不能说“一起雨”，而且句中已经有“下雨”。", "演出": "语义：演出是事先安排好的活动，不会“突然发生”，不能说“发生了一起演出”。"}, "sentence_index": 0, "correct_answer": "事故"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为这次事故感到骄傲。", "explanation": "〈事故〉指没有想到的坏事，不能让人为它感到骄傲。这里应该用〈成就〉，指值得自豪的事。"}, {"text": "这起事故是他很喜欢的运动。", "explanation": "〈事故〉是没有想到的坏事，不是可以喜欢的活动。这里应该用〈运动〉这类人们愿意参加的活动。"}, {"text": "这次事故很好，大家都很高兴。", "explanation": "〈很好〉用来评价好的事情，事故是坏事，不能这样评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小吃", "is_correct": false, "explanation": "语义：警察处理的是交通等需要处理的问题，“小吃”不是可以被处理的对象。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“处理”搭配的是问题、事务，不说“处理歌曲”，唱歌曲要说“唱”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能由警察“处理”，句子说的是路口发生的需要处理的事。"}, {"text": "事故", "is_correct": true, "explanation": "正确。“处理路口的事故”指警察处理路口发生的交通事故，搭配自然。"}], "explanations": {"小吃": "语义：警察处理的是交通等需要处理的问题，“小吃”不是可以被处理的对象。", "歌曲": "搭配：“处理”搭配的是问题、事务，不说“处理歌曲”，唱歌曲要说“唱”。", "天气": "语义：天气不能由警察“处理”，句子说的是路口发生的需要处理的事。", "事故": "正确。“处理路口的事故”指警察处理路口发生的交通事故，搭配自然。"}, "sentence_index": 6, "correct_answer": "事故"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你要小心，别做什么事故。", "explanation": "这里应该用〈出〉。事故通常说“出事故”或“发生事故”，不能说“做事故”。"}, {"text": "你要小心，别吃掉这次事故。", "explanation": "〈吃〉的对象应是食物，事故不能被吃，此句中的用法不成立。"}, {"text": "你要小心，别把这次事故送给朋友。", "explanation": "事故是伤害性的坏事，不能当作礼物送人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂昨天出了一只事故。", "corrected_sentence": "工厂昨天出了一起事故。", "error_description": "错误：“事故”的量词用了“只”，“只”用于动物或小件物品。正确：“一起事故”，“起”用于事件、事故。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一场很严重事故就这样发生了。", "corrected_sentence": "一场很严重的事故就这样发生了。", "error_description": "错误：“很严重”修饰名词“事故”时，中间漏了“的”。正确：“很严重的事故”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe15dbf-f1e9-4fde-88dd-68c177b9c4ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成功", "is_correct": true, "explanation": "反义：“成功”与“失败”指想做的事是否做成，意思相反。"}, {"text": "散步", "is_correct": false, "explanation": "无关：散步是日常动作，与“失败”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "无关：游泳是运动，与“失败”没有反义关系。"}, {"text": "种植", "is_correct": false, "explanation": "无关：种植是劳动动作，与“失败”没有反义关系。"}], "correct_answer": "成功", "explanations": {"成功": "反义：“成功”与“失败”指想做的事是否做成，意思相反。", "散步": "无关：散步是日常动作，与“失败”没有反义关系。", "游泳": "无关：游泳是运动，与“失败”没有反义关系。", "种植": "无关：种植是劳动动作，与“失败”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成功", "is_correct": true, "explanation": "反义：“成功”与“失败”指想做的事是否做成，意思相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：唱歌是文娱活动，与“失败”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：睡觉是生理活动，与“失败”没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "无关：跳舞是文娱活动，与“失败”没有反义关系。"}], "correct_answer": "成功", "explanations": {"成功": "反义：“成功”与“失败”指想做的事是否做成，意思相反。", "唱歌": "无关：唱歌是文娱活动，与“失败”没有反义关系。", "睡觉": "无关：睡觉是生理活动，与“失败”没有反义关系。", "跳舞": "无关：跳舞是文娱活动，与“失败”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "失败是想做成一件事，可是没有成功。", "primary_collocate": null, "pronunciation": "shī bài", "ipa": "ʂʅ˥ pai˥˩", "syllable_count": 2, "sentences": [{"text": "这个实验做了三次，都失败了。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他第一次做生意就失败了。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不怕失败，还想再试一次。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个计划为什么会失败呢？", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她失败了很多次，最后还是成功了。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为准备得太少，所以这次试验失败了。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的第一个计划失败了，但是他没有放弃。", "target_word": "失败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败并不可怕，可怕的是不再试。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，失败一次没关系，要再努力。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的第一次试飞失败了，大家都很难过。", "target_word": "失败", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失败了", "label": "完成体"}, {"form": "失败过", "label": "经历体"}, {"form": "失败者", "label": "复合词"}, {"form": "失敗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "想做的事、计划、实验没有成功", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae51d7e-db40-49f3-b67b-d653c6a88f9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失败", "is_correct": true, "explanation": "语义正确：“都失败了”指三次尝试都没有成功。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：实验不能“睡觉”，“都睡觉了”与句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：实验不会“散步”，句子不成立。"}, {"text": "发明", "is_correct": false, "explanation": "配价：“发明”要求带所发明的对象，“都发明了”缺少宾语。"}], "explanations": {"失败": "语义正确：“都失败了”指三次尝试都没有成功。", "睡觉": "语义：实验不能“睡觉”，“都睡觉了”与句意不通。", "散步": "语义：实验不会“散步”，句子不成立。", "发明": "配价：“发明”要求带所发明的对象，“都发明了”缺少宾语。"}, "sentence_index": 0, "correct_answer": "失败"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的钱包在地铁上失败了。", "explanation": "这里应该用〈丢失〉。“失败”指想做的事没有成功，东西遗失要说“丢失”。"}, {"text": "这辆车在山路上突然失败了。", "explanation": "这里应该用〈失控〉。车辆、局面不受控制要说“失控”；“失败”指想做成的事没有成功，不用于描述车辆。"}, {"text": "那只小狗昨天就失败了。", "explanation": "这里应该用〈失踪〉。动物或人下落不明要说“失踪”；“失败”不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失败", "is_correct": true, "explanation": "语义正确：“计划失败了”与“但是他没有放弃”形成转折，句意通顺。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：计划不能“游泳”，句子不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：计划不会“生病”，“计划生病了”不合常理。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：计划不会“唱歌”，“计划唱歌了”句意不通。"}], "explanations": {"失败": "语义正确：“计划失败了”与“但是他没有放弃”形成转折，句意通顺。", "游泳": "语义：计划不能“游泳”，句子不通。", "生病": "语义：计划不会“生病”，“计划生病了”不合常理。", "唱歌": "语义：计划不会“唱歌”，“计划唱歌了”句意不通。"}, "sentence_index": 6, "correct_answer": "失败"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的双眼突然失败了。", "explanation": "这里应该用〈失明〉。眼睛看不见要说“失明”；“失败”不用于人的眼睛。"}, {"text": "这棵树在大风里突然失败了。", "explanation": "这里应该用〈倒〉。树木被风吹倒要说“倒”；“失败”指想做的事没有成功，不用于树木。"}, {"text": "这把伞在风里失败了。", "explanation": "这里应该用〈坏〉。物品损坏要说“坏了”，“失败”不用于描述物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次试验我们失败着，大家都很沮丧。", "corrected_sentence": "这次试验我们失败了，大家都很沮丧。", "error_description": "体标错误：“失败”表示已经完成的结果，应用“了”；“着”表示持续的状态，与此不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他失败了过很多次，但是从来不放弃。", "corrected_sentence": "他失败过很多次，但是从来不放弃。", "error_description": "体标错误：“失败过”表示经历过，“了”与“过”不能同用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87788, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "获胜", "is_correct": true, "explanation": "反义：“获胜”与“失败”在比赛、对抗中意思相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：唱歌与比赛中的“失败”没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "无关：跳舞与比赛中的“失败”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：睡觉与比赛中的“失败”没有反义关系。"}], "correct_answer": "获胜", "explanations": {"获胜": "反义：“获胜”与“失败”在比赛、对抗中意思相反。", "唱歌": "无关：唱歌与比赛中的“失败”没有反义关系。", "跳舞": "无关：跳舞与比赛中的“失败”没有反义关系。", "睡觉": "无关：睡觉与比赛中的“失败”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
