INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87788, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在斗争、比赛或选举等对抗中输了，没有取胜。", "primary_collocate": null, "pronunciation": "shī bài", "ipa": "ʂʅ˥ pai˥˩", "syllable_count": 2, "sentences": [{"text": "我们队在比赛中失败了。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在选举中失败，没有当上市长。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场比赛我们不能失败。", "target_word": "失败", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那支军队打了三年仗，最后失败了。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "失败的一方要向对方说“恭喜”。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在决赛中失败，拿到了第二名。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛失败后，他哭了很久。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个国家打仗，一个胜利，一个失败。", "target_word": "失败", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国队在上一场比赛中失败过一次。", "target_word": "失败", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队虽然失败了，但是大家还是为他们鼓掌。", "target_word": "失败", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失败了", "label": "完成体"}, {"form": "失败过", "label": "经历体"}, {"form": "失败者", "label": "复合词"}, {"form": "失敗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在比赛、选举、战争等对抗中输了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae51d7e-db40-49f3-b67b-d653c6a88f9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失败", "is_correct": true, "explanation": "语义正确：“在比赛中失败”指比赛中输了，与句意相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：比赛中不能“睡觉”，“比赛中睡觉了”句意荒谬。"}, {"text": "种植", "is_correct": false, "explanation": "语义：比赛中不能“种植”，与“比赛”搭配不通。"}, {"text": "发明", "is_correct": false, "explanation": "配价：“发明”要求带宾语，“比赛中发明了”缺少对象。"}], "explanations": {"失败": "语义正确：“在比赛中失败”指比赛中输了，与句意相符。", "睡觉": "语义：比赛中不能“睡觉”，“比赛中睡觉了”句意荒谬。", "种植": "语义：比赛中不能“种植”，与“比赛”搭配不通。", "发明": "配价：“发明”要求带宾语，“比赛中发明了”缺少对象。"}, "sentence_index": 0, "correct_answer": "失败"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份文件在办公室里失败了。", "explanation": "这里应该用〈丢失〉。文件、物品遗失要说“丢失”；“失败”指在对抗中输掉，不用于此。"}, {"text": "这张优惠券已经失败了。", "explanation": "这里应该用〈失效〉。优惠券、票据过期作废要说“失效”；“失败”指在比赛、对抗中输了，不用于优惠券。"}, {"text": "他的眼睛突然失败了。", "explanation": "这里应该用〈失明〉。眼睛看不见要说“失明”；“失败”不用于人的眼睛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失败", "is_correct": true, "explanation": "语义正确：“比赛失败后”指比赛输了之后，与“他哭了很久”前后相连。"}, {"text": "散步", "is_correct": false, "explanation": "语义：比赛不能“散步”，“比赛散步后”句意不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：比赛不会“生病”，“比赛生病后”句意不通。"}, {"text": "丢失", "is_correct": false, "explanation": "配价：“丢失”要求带失去的对象，“比赛丢失后”缺少宾语。"}], "explanations": {"失败": "语义正确：“比赛失败后”指比赛输了之后，与“他哭了很久”前后相连。", "散步": "语义：比赛不能“散步”，“比赛散步后”句意不通。", "生病": "语义：比赛不会“生病”，“比赛生病后”句意不通。", "丢失": "配价：“丢失”要求带失去的对象，“比赛丢失后”缺少宾语。"}, "sentence_index": 6, "correct_answer": "失败"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一紧张，嗓子就突然失败了。", "explanation": "这里应该用〈失声〉。嗓子说不出话要说“失声”；“失败”不用于人的身体状况。"}, {"text": "这把椅子用久了就失败了。", "explanation": "这里应该用〈坏〉。物品损坏要说“坏了”；“失败”指做事没有成功，不用于椅子。"}, {"text": "他的手表在比赛时突然失败了。", "explanation": "这里应该用〈失灵〉。仪器、手表出故障要说“失灵”；“失败”指在对抗中输掉，不用于物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场比赛，我们队失败了过。", "corrected_sentence": "这场比赛，我们队失败了。", "error_description": "体标错误：「了」与「过」不能同用。表示已经失败用「失败了」，去掉多余的「过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
