INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87789, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "止血", "is_correct": true, "explanation": "止血：与“流血”相反，指让血停止流出，是反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：慢慢走路的活动，与流血没有反义关系。"}, {"text": "发抖", "is_correct": false, "explanation": "发抖：身体因寒冷或害怕而颤动，与流血没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳：在水中活动身体的运动，与流血没有反义关系。"}], "correct_answer": "止血", "explanations": {"止血": "止血：与“流血”相反，指让血停止流出，是反义关系。", "散步": "散步：慢慢走路的活动，与流血没有反义关系。", "发抖": "发抖：身体因寒冷或害怕而颤动，与流血没有反义关系。", "游泳": "游泳：在水中活动身体的运动，与流血没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87789, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "止血", "is_correct": true, "explanation": "止血：与“流血”相反，指让血停止流出，是反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字：用笔把字写在纸上，与流血无关。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：用嗓子发出声音的活动，与流血没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉：躺下休息进入睡眠，与流血没有反义关系。"}], "correct_answer": "止血", "explanations": {"止血": "止血：与“流血”相反，指让血停止流出，是反义关系。", "写字": "写字：用笔把字写在纸上，与流血无关。", "唱歌": "唱歌：用嗓子发出声音的活动，与流血没有反义关系。", "睡觉": "睡觉：躺下休息进入睡眠，与流血没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87789, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "流血是身体受伤，红色的血流出来。", "primary_collocate": null, "pronunciation": "liú xuè", "ipa": "ljou˧˥ ɕɥe˥˩", "syllable_count": 2, "sentences": [{"text": "弟弟骑车摔倒，膝盖流血了。", "target_word": "流血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看到我的手指流血，很着急。", "target_word": "流血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打篮球时，嘴流血了。", "target_word": "流血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要用手摸伤口，会一直流血。", "target_word": "流血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人头上流血，快叫医生！", "target_word": "流血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫的腿在流血。", "target_word": "流血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受了伤，但是不流血了。", "target_word": "流血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的脚流血，要马上洗。", "target_word": "流血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不怕疼，也不怕流血。", "target_word": "流血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有红色的血，是谁流血了？", "target_word": "流血", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流了血", "label": "完成体"}, {"form": "流着血", "label": "持续体"}, {"form": "流过血", "label": "经历体"}], "register": "通用", "sense_fingerprint": "身体受伤后红色的血流出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d23fd0e-84cc-4b7b-8d40-c450f027c617') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87789, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流血", "is_correct": true, "explanation": "流血：膝盖受伤，红色的血流出来，与“骑车摔倒”相符。"}, {"text": "长高", "is_correct": false, "explanation": "体貌：长高说的是人的身高，膝盖不能说长高。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：下棋的主语是人，膝盖不能下棋。"}, {"text": "读书", "is_correct": false, "explanation": "搭配：读书需要人和书，“膝盖读书”搭配不当。"}], "explanations": {"流血": "流血：膝盖受伤，红色的血流出来，与“骑车摔倒”相符。", "长高": "体貌：长高说的是人的身高，膝盖不能说长高。", "下棋": "语义：下棋的主语是人，膝盖不能下棋。", "读书": "搭配：读书需要人和书，“膝盖读书”搭配不当。"}, "sentence_index": 0, "correct_answer": "流血"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个消息，她难过得眼泪一直在流血。", "explanation": "这里应该用〈流泪〉。流血指血从伤口流出，因难过而落泪要说流泪。"}, {"text": "天气太热了，他没有受伤，可是脸上一直在流血，都是汗水。", "explanation": "这里应该用〈流汗〉。脸上流出的是汗水，不是受伤流出的血，要说流汗。"}, {"text": "这条山间的小河从山上一直流血到村子里。", "explanation": "这里应该用〈流淌〉。流血只指身体受伤时血从伤口流出，河水流动要说流淌，不能说流血。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流血", "is_correct": true, "explanation": "流血：受伤后血流出来，与“他受了伤”的语境相符。"}, {"text": "打哈欠", "is_correct": false, "explanation": "语义：打哈欠是嘴的动作，与受伤无关。"}, {"text": "冒烟", "is_correct": false, "explanation": "搭配：冒烟说的是火或东西冒出烟，不用来说人。"}, {"text": "打雷", "is_correct": false, "explanation": "语义：打雷是天气现象，人不能打雷。"}], "explanations": {"流血": "流血：受伤后血流出来，与“他受了伤”的语境相符。", "打哈欠": "语义：打哈欠是嘴的动作，与受伤无关。", "冒烟": "搭配：冒烟说的是火或东西冒出烟，不用来说人。", "打雷": "语义：打雷是天气现象，人不能打雷。"}, "sentence_index": 6, "correct_answer": "流血"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "切开的西瓜一直在流血，桌子上全是汁。", "explanation": "这里应该用〈流出汁水〉。流血指身体受伤时血从伤口流出，西瓜里流出的是汁水，不能说流血。"}, {"text": "看见蛋糕，小孩一直在流血。", "explanation": "这里应该用〈流口水〉。见到蛋糕流出的是口水，不能说流血。"}, {"text": "油漆桶倒了，地上一直在流血。", "explanation": "这里应该用〈流出〉。流血指血从伤口流出，油漆从桶里流出要说流出，不能说流血。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟的膝盖流血了了。", "corrected_sentence": "弟弟的膝盖流血了。", "error_description": "“了”多用了一个：“流血了”中的“了”只用一次，应说“弟弟的膝盖流血了。”，不能说“流血了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的脚了流血，很疼。", "corrected_sentence": "他的脚流了血，很疼。", "error_description": "“了”的位置错误：“了”应放在动词“流”后面，说“流了血”，不能放在“流”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64b868e1-4fa8-4876-8c24-ac089d8b2a4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87791, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "来得及", "is_correct": true, "explanation": "反义：“来得及”表示时间足够做完，与“来不及”的义项相对。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”与“来不及”的任何义项都没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”与“来不及”的任何义项都没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”与“来不及”的任何义项都没有反义关系。"}], "correct_answer": "来得及", "explanations": {"来得及": "反义：“来得及”表示时间足够做完，与“来不及”的义项相对。", "散步": "无关：“散步”与“来不及”的任何义项都没有反义关系。", "讨论": "无关：“讨论”与“来不及”的任何义项都没有反义关系。", "修理": "无关：“修理”与“来不及”的任何义项都没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
