INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87791, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "来不及是时间太短，已经做不完了。", "primary_collocate": null, "pronunciation": "lái bu jí", "ipa": "lai˧˥ pu tɕi˧˥", "syllable_count": 3, "sentences": [{"text": "太晚了，我来不及吃早饭。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快走吧，再不走就来不及了。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他起床太晚，来不及洗脸。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业太多，我今天来不及做完。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车马上开了，我们来不及买票。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议通知得太突然，大家来不及准备资料。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她来不及换衣服，就跑出去了。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在才开始准备，肯定来不及。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间太短，老师来不及看完我的作业。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我来不及告诉他，他就走了。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "来不及|时间太短，做不完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2ad337-3c61-49c3-aacc-f67cc219fb9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87791, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提前", "is_correct": false, "explanation": "语义：“提前”表示早于预定时间，与“太晚了”矛盾。"}, {"text": "来不及", "is_correct": true, "explanation": "“来不及”表示时间太短、没有时间做，与“太晚了”的语境一致。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的宾语是地方或展览，不能带“吃早饭”这样的动作，句子不通。"}, {"text": "等待", "is_correct": false, "explanation": "搭配：“等待”不能直接带“吃早饭”这类动作，句子不通。"}], "explanations": {"提前": "语义：“提前”表示早于预定时间，与“太晚了”矛盾。", "来不及": "“来不及”表示时间太短、没有时间做，与“太晚了”的语境一致。", "参观": "搭配：“参观”的宾语是地方或展览，不能带“吃早饭”这样的动作，句子不通。", "等待": "搭配：“等待”不能直接带“吃早饭”这类动作，句子不通。"}, "sentence_index": 0, "correct_answer": "来不及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我还有整整一年，来不及准备考试。", "explanation": "这里应该用〈来得及〉。“来不及”表示时间太短、做不完，句中说还有整整一年，时间充裕，应说“来得及”。"}, {"text": "我不想去，所以来不及去。", "explanation": "这里应该用〈不愿意〉。“来不及”只表示时间不够，句中的原因是不愿意，不能用“来不及”。"}, {"text": "他很有钱，所以来不及买车。", "explanation": "这里应该用〈买得起〉。“来不及”只说时间不够，句中说的是经济条件，应说“买得起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坚持", "is_correct": false, "explanation": "语义：“坚持”表示持续做下去，与“就跑出去了”的急促语境矛盾。"}, {"text": "来不及", "is_correct": true, "explanation": "“来不及”表示没有时间换衣服，与“就跑出去了”的语境一致。"}, {"text": "等", "is_correct": false, "explanation": "配价：“等”不能直接带“换衣服”这样的动词短语作宾语，句子不通。"}, {"text": "犹豫", "is_correct": false, "explanation": "语义：“犹豫”表示拿不定主意，与“就跑出去了”的急促语境不符。"}], "explanations": {"坚持": "语义：“坚持”表示持续做下去，与“就跑出去了”的急促语境矛盾。", "来不及": "“来不及”表示没有时间换衣服，与“就跑出去了”的语境一致。", "等": "配价：“等”不能直接带“换衣服”这样的动词短语作宾语，句子不通。", "犹豫": "语义：“犹豫”表示拿不定主意，与“就跑出去了”的急促语境不符。"}, "sentence_index": 6, "correct_answer": "来不及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的腿受伤了，所以来不及跑步。", "explanation": "这里应该用〈跑不了〉。“来不及”只说时间不够，句中的原因是腿伤，应说“跑不了”。"}, {"text": "我很喜欢这个城市，所以来不及离开。", "explanation": "这里应该用〈舍不得〉。“来不及”只表示时间不够，句中的原因是喜欢，应说“舍不得离开”。"}, {"text": "我的手机坏了，所以来不及看消息。", "explanation": "这里应该用〈看不了〉。“来不及”强调时间不够，句中的原因是手机坏了，应说“看不了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "时间太紧，我来不及了给你回电话。", "corrected_sentence": "时间太紧，我来不及给你回电话。", "error_description": "“了”不能插在“来不及”和后面的动词短语之间。应去掉“了”，说“我来不及给你回电话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他醒得晚，不来不及洗澡。", "corrected_sentence": "他醒得晚，来不及洗澡。", "error_description": "“不来不及”是双重否定，意为“来得及”，句意变成有时间洗澡，与“醒得晚”的语境矛盾。应说“来不及洗澡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
