INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87792, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "时间短促，无法顾及或完成。", "primary_collocate": null, "pronunciation": "lái bu jí", "ipa": "lai˧˥ pu tɕi˧˥", "syllable_count": 3, "sentences": [{"text": "他来不及想，就跳进了水里。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车来了，我来不及说再见。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人突然到了，妈妈来不及做饭。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车速太快，我来不及看清路牌。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我来不及把话说完，电话就断了。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课太快，同学们来不及问问题。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情太多，他来不及休息。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭了，她来不及关门就跑过去。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门铃突然响了，我来不及穿上鞋。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震来得很快，大家来不及跑。", "target_word": "来不及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "来不及|时间短促，无法顾及", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2ad337-3c61-49c3-aacc-f67cc219fb9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的宾语是地方或展览，不能带“想”这样的动词，句子不通。"}, {"text": "来不及", "is_correct": true, "explanation": "“来不及”表示没有时间考虑，与“就跳进了水里”的急促语境一致。"}, {"text": "等", "is_correct": false, "explanation": "配价：“等”不能直接带“想”这样的动词作宾语，句子不通。"}, {"text": "坚持", "is_correct": false, "explanation": "语义：“坚持”表示持续做下去，与“就跳进了水里”的急促语境矛盾。"}], "explanations": {"参观": "搭配：“参观”的宾语是地方或展览，不能带“想”这样的动词，句子不通。", "来不及": "“来不及”表示没有时间考虑，与“就跳进了水里”的急促语境一致。", "等": "配价：“等”不能直接带“想”这样的动词作宾语，句子不通。", "坚持": "语义：“坚持”表示持续做下去，与“就跳进了水里”的急促语境矛盾。"}, "sentence_index": 0, "correct_answer": "来不及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的房间太干净了，所以来不及打扫。", "explanation": "这里应该用〈没必要〉。“来不及”表示时间不够，句中的原因是房间已经干净，应说“没必要打扫”。"}, {"text": "我今天的作业都做完了，所以来不及复习。", "explanation": "这里应该用〈来得及〉。“来不及”表示时间不够，句中作业已经做完，时间充裕，应说“来得及复习”。"}, {"text": "我的眼睛很好，所以来不及看清字。", "explanation": "这里应该用〈看得清〉。“来不及”表示时间不够，句中的原因是视力好，应说“看得清”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舍得", "is_correct": false, "explanation": "语义：“舍得”表示愿意割舍，与“事情太多”的语境不符。"}, {"text": "来不及", "is_correct": true, "explanation": "“来不及”表示没有时间休息，与“事情太多”的语境一致。"}, {"text": "忙于", "is_correct": false, "explanation": "语义：“忙于”表示忙碌于某事，与“休息”的语义冲突。"}, {"text": "等待", "is_correct": false, "explanation": "配价：“等待”不能直接带“休息”作宾语，句子不通。"}], "explanations": {"舍得": "语义：“舍得”表示愿意割舍，与“事情太多”的语境不符。", "来不及": "“来不及”表示没有时间休息，与“事情太多”的语境一致。", "忙于": "语义：“忙于”表示忙碌于某事，与“休息”的语义冲突。", "等待": "配价：“等待”不能直接带“休息”作宾语，句子不通。"}, "sentence_index": 6, "correct_answer": "来不及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很安静，所以来不及说话。", "explanation": "这里应该用〈不爱说话〉。“来不及”表示时间不够，句中的原因是性格安静，应说“不爱说话”。"}, {"text": "这首歌很短，所以来不及唱完。", "explanation": "这里应该用〈唱得完〉。“来不及”表示时间不够，句中歌曲很短，应说“唱得完”。"}, {"text": "今天的作业很少，所以来不及写完。", "explanation": "这里应该用〈写得完〉。“来不及”表示时间不够，句中作业很少，时间充裕，应说“写得完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站到了，我来不及了买票就上了车。", "corrected_sentence": "车站到了，我来不及买票就上了车。", "error_description": "“了”不能放在“来不及”和后面的动作之间。应去掉“了”，说“来不及买票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子饿了，她不来不及做饭，就去买面包。", "corrected_sentence": "孩子饿了，她来不及做饭，就去买面包。", "error_description": "“不来不及”是双重否定，意为“来得及”，句意变成有时间做饭，与“就去买面包”的因果不符。应说“她来不及做饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471e8873-97e7-49ed-bd8d-dda09d905a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
