INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87793, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物是世界上的各种东西和事情。", "primary_collocate": null, "pronunciation": "shì wù", "ipa": "ʂʅ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "孩子对新事物很好奇。", "target_word": "事物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要用发展的眼光看事物。", "target_word": "事物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界上的事物都在变化。", "target_word": "事物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷一辈子见过很多事物。", "target_word": "事物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看事物不能只看表面。", "target_word": "事物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们观察身边的事物。", "target_word": "事物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个社会里，每天都有新的事物出现。", "target_word": "事物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把各种事物都记在本子里。", "target_word": "事物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子好奇地看着周围的事物。", "target_word": "事物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了解更多不同的事物。", "target_word": "事物", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物：名词，泛指世界上各种具体的东西和发生的事情（新事物、周围的事物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '957488b2-d73b-4bc6-b47f-79a362d47852') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87793, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事物", "is_correct": true, "explanation": "事物读 shì wù，指世界上的各种东西和事情，是本题正确答案。"}, {"text": "食物", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，食物指吃的东西。"}, {"text": "事故", "is_correct": false, "explanation": "第二个音节 gù 与 wù 声母不同，事故指意外造成的灾祸。"}, {"text": "十五", "is_correct": false, "explanation": "shí wǔ 两个音节的声调都与 shì wù 不同，十五是数字。"}], "explanations": {"事物": "事物读 shì wù，指世界上的各种东西和事情，是本题正确答案。", "食物": "shí（第二声）与 shì（第四声）声调不同，食物指吃的东西。", "事故": "第二个音节 gù 与 wù 声母不同，事故指意外造成的灾祸。", "十五": "shí wǔ 两个音节的声调都与 shì wù 不同，十五是数字。"}, "sentence_index": null, "correct_answer": "事物"}, "level_3": {"options": [{"text": "事物", "is_correct": true, "explanation": "正确：“新事物”指新出现的东西或事情，符合句意。"}, {"text": "黄昏", "is_correct": false, "explanation": "语义：黄昏是一天中的时段，不是可以“新”出现而引人好奇的对象，句意不通。"}, {"text": "古董", "is_correct": false, "explanation": "语义：古董本身是旧物，与“新”的修饰相冲突。"}, {"text": "祖先", "is_correct": false, "explanation": "搭配：“新祖先”自相矛盾，祖先指早已存在的先人。"}], "explanations": {"事物": "正确：“新事物”指新出现的东西或事情，符合句意。", "黄昏": "语义：黄昏是一天中的时段，不是可以“新”出现而引人好奇的对象，句意不通。", "古董": "语义：古董本身是旧物，与“新”的修饰相冲突。", "祖先": "搭配：“新祖先”自相矛盾，祖先指早已存在的先人。"}, "sentence_index": 0, "correct_answer": "事物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一辈子做过很多事物。", "explanation": "这里应该用〈事情〉。“做”后面接行为或工作，要用〈事情〉，〈事物〉不说“做事物”。"}, {"text": "他手里拿着一只事物。", "explanation": "这里应该用〈种〉或〈个〉。〈只〉用于动物或成对的物件，不用来数“事物”。"}, {"text": "他是我们班最聪明的事物。", "explanation": "这里应该用〈同学〉。“事物”指东西和事情，不用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87793, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "事物", "is_correct": true, "explanation": "事物读 shì wù，指世界上的各种东西和事情，是本题正确答案。"}, {"text": "实物", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，实物指实际存在的东西。"}, {"text": "世故", "is_correct": false, "explanation": "第二个音节 gù 与 wù 声母不同，世故指处理人情的经验。"}, {"text": "石屋", "is_correct": false, "explanation": "shí wū 两个音节的声调都与 shì wù 不同，石屋指石头建造的房屋。"}], "explanations": {"事物": "事物读 shì wù，指世界上的各种东西和事情，是本题正确答案。", "实物": "shí（第二声）与 shì（第四声）声调不同，实物指实际存在的东西。", "世故": "第二个音节 gù 与 wù 声母不同，世故指处理人情的经验。", "石屋": "shí wū 两个音节的声调都与 shì wù 不同，石屋指石头建造的房屋。"}, "sentence_index": null, "correct_answer": "事物"}, "level_3": {"options": [{"text": "事物", "is_correct": true, "explanation": "正确：“新的事物出现”指新出现的东西或情况，符合现代社会的语境。"}, {"text": "长城", "is_correct": false, "explanation": "语义：长城是古代建成的建筑，不会每天出现新的。"}, {"text": "皇帝", "is_correct": false, "explanation": "语义：皇帝是古代的称号，现代社会不会每天出现新的皇帝。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“出现”不能说海洋每天出现新的，海洋不是新出现的事物。"}], "explanations": {"事物": "正确：“新的事物出现”指新出现的东西或情况，符合现代社会的语境。", "长城": "语义：长城是古代建成的建筑，不会每天出现新的。", "皇帝": "语义：皇帝是古代的称号，现代社会不会每天出现新的皇帝。", "海洋": "搭配：“出现”不能说海洋每天出现新的，海洋不是新出现的事物。"}, "sentence_index": 6, "correct_answer": "事物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭馆的事物很新鲜，大家都爱吃。", "explanation": "这里应该用〈食物〉。〈食物〉指吃的东西，“事物”不指食品。"}, {"text": "我家的小狗是一个可爱的事物。", "explanation": "这里应该用〈动物〉。〈事物〉指东西和事情，不用来称呼活的动物。"}, {"text": "这场晚会的事物很精彩。", "explanation": "这里应该用〈节目〉。〈节目〉指演出的内容，“事物”不用于说晚会的表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在展览馆看到了三只有趣的事物。", "corrected_sentence": "我昨天在展览馆看到了三种有趣的事物。", "error_description": "量词错误：“事物”应搭配量词“种”，说“三种有趣的事物”。“只”用于动物或成对的物件，不能数“事物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们常常好奇地观察身边的事物们。", "corrected_sentence": "孩子们常常好奇地观察身边的事物。", "error_description": "词形错误：“事物”是泛指的名词，后面不加“们”。应说“观察身边的事物”，不说“事物们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
