INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "客观存在的一切事情和东西。", "primary_collocate": null, "pronunciation": "shì wù", "ipa": "ʂʅ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "事物之间都有联系。", "target_word": "事物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科学研究客观事物的规律。", "target_word": "事物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事物都有两面性。", "target_word": "事物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个事物都有自己的特点。", "target_word": "事物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要透过现象看事物的本质。", "target_word": "事物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "任何事物都不是一成不变的。", "target_word": "事物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事物发展到一定阶段，就会发生变化。", "target_word": "事物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哲学研究的是事物最一般的规律。", "target_word": "事物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用科学的方法分析各种事物。", "target_word": "事物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们是通过感觉来认识事物的。", "target_word": "事物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "客观事物", "label": "复合词"}], "register": "书面", "sense_fingerprint": "事物：名词，哲学或科学语境中指客观存在的一切对象（事物的本质、客观事物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '957488b2-d73b-4bc6-b47f-79a362d47852') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87794, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事物", "is_correct": true, "explanation": "事物读 shì wù，指客观存在的一切对象，是本题正确答案。"}, {"text": "食物", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，食物指吃的东西。"}, {"text": "事故", "is_correct": false, "explanation": "第二个音节 gù 与 wù 声母不同，事故指意外造成的灾祸。"}, {"text": "十五", "is_correct": false, "explanation": "shí wǔ 两个音节的声调都与 shì wù 不同，十五是数字。"}], "explanations": {"事物": "事物读 shì wù，指客观存在的一切对象，是本题正确答案。", "食物": "shí（第二声）与 shì（第四声）声调不同，食物指吃的东西。", "事故": "第二个音节 gù 与 wù 声母不同，事故指意外造成的灾祸。", "十五": "shí wǔ 两个音节的声调都与 shì wù 不同，十五是数字。"}, "sentence_index": null, "correct_answer": "事物"}, "level_3": {"options": [{"text": "事物", "is_correct": true, "explanation": "正确：“事物之间”指客观对象之间，可以有联系，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“椅子之间都有联系”不自然，椅子是独立的家具，与“事物之间的联系”不符。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪是人体分泌的液体，不构成可以彼此联系的对象。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“早饭之间都有联系”不成立，早饭是一顿饭，不能说彼此联系。"}], "explanations": {"事物": "正确：“事物之间”指客观对象之间，可以有联系，符合句意。", "椅子": "搭配：“椅子之间都有联系”不自然，椅子是独立的家具，与“事物之间的联系”不符。", "眼泪": "语义：眼泪是人体分泌的液体，不构成可以彼此联系的对象。", "早饭": "搭配：“早饭之间都有联系”不成立，早饭是一顿饭，不能说彼此联系。"}, "sentence_index": 0, "correct_answer": "事物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每只事物都有自己的特点。", "explanation": "这里应该用〈个〉。〈只〉用于动物或成对的物件，不用来数“事物”。"}, {"text": "他想把这些事物办好。", "explanation": "这里应该用〈事情〉。“办”后面接事情，〈事物〉不能和“办”搭配。"}, {"text": "我们班的每个事物都很努力。", "explanation": "这里应该用〈同学〉。“事物”不指人，也不能做“努力”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87794, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "事物", "is_correct": true, "explanation": "事物读 shì wù，指客观存在的一切对象，是本题正确答案。"}, {"text": "实物", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，实物指实际存在的东西。"}, {"text": "世故", "is_correct": false, "explanation": "第二个音节 gù 与 wù 声母不同，世故指处理人情的经验。"}, {"text": "石屋", "is_correct": false, "explanation": "shí wū 两个音节的声调都与 shì wù 不同，石屋指石头建造的房屋。"}], "explanations": {"事物": "事物读 shì wù，指客观存在的一切对象，是本题正确答案。", "实物": "shí（第二声）与 shì（第四声）声调不同，实物指实际存在的东西。", "世故": "第二个音节 gù 与 wù 声母不同，世故指处理人情的经验。", "石屋": "shí wū 两个音节的声调都与 shì wù 不同，石屋指石头建造的房屋。"}, "sentence_index": null, "correct_answer": "事物"}, "level_3": {"options": [{"text": "事物", "is_correct": true, "explanation": "正确：“事物发展到一定阶段”指客观对象的发展，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是静止的家具，不会“发展到一定阶段”。"}, {"text": "昨天", "is_correct": false, "explanation": "搭配：“昨天”是时间词，不能作“发展”的主语。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是固定的物件，不会经历“发展”和“变化”的过程。"}], "explanations": {"事物": "正确：“事物发展到一定阶段”指客观对象的发展，符合句意。", "桌子": "语义：桌子是静止的家具，不会“发展到一定阶段”。", "昨天": "搭配：“昨天”是时间词，不能作“发展”的主语。", "椅子": "语义：椅子是固定的物件，不会经历“发展”和“变化”的过程。"}, "sentence_index": 6, "correct_answer": "事物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市的事物很新鲜。", "explanation": "这里应该用〈食物〉。〈食物〉指吃的东西，“事物”不指食品。"}, {"text": "我家养的小猫是一个可爱的事物。", "explanation": "这里应该用〈动物〉。〈事物〉指东西和事情，不用来称呼活的动物。"}, {"text": "这部电影的事物很精彩。", "explanation": "这里应该用〈情节〉。〈情节〉指故事的发展过程，“事物”不用于指电影的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家要认识各只事物的规律。", "corrected_sentence": "科学家要认识各种事物的规律。", "error_description": "量词错误：“事物”应搭配量词“种”，说“各种事物”。“只”用于动物或成对的物件，不说“各只事物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哲学家认为事物们都在不断变化。", "corrected_sentence": "哲学家认为事物都在不断变化。", "error_description": "词形错误：“事物”是泛指的名词，后面不加“们”。应说“事物都在不断变化”，不说“事物们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
