INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高等学校中职位最高的教师。", "primary_collocate": null, "pronunciation": "jiào shòu", "ipa": "tɕjɑʊ˥˩ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他工作了十年，终于当上了教授。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大学里，教授比讲师的职位高。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她三十八岁就评上了教授，非常年轻。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要当教授，先要做很多年研究。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们学校最年轻的教授。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学的教授都有博士学位。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教授的工资比讲师高一些。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李老师工作很努力，明年可以申请当教授了。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了教授以后，还是每天去实验室。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给这位新教授一间大办公室。", "target_word": "教授", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位教授", "label": "量词"}, {"form": "副教授", "label": "复合"}, {"form": "名誉教授", "label": "复合"}], "register": "中性", "sense_fingerprint": "教授：高等学校中职位最高的教师（职称）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70440bbe-270b-40e4-ad01-5390c3128607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87796, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "教授", "is_correct": true, "explanation": "教授 jiàoshòu：高等学校中职位最高的教师（职称），正确答案。"}, {"text": "教室", "is_correct": false, "explanation": "教室 jiàoshì 与 教授 jiàoshòu 第二音节的韵母不同（i 与 ou），声调相同（都是第四声），意思是上课的房间。"}, {"text": "教书", "is_correct": false, "explanation": "教书 jiàoshū 与 教授 jiàoshòu 第二音节的韵母和声调不同，意思是从事教学工作。"}, {"text": "交售", "is_correct": false, "explanation": "交售 jiāoshòu 与 教授 jiàoshòu 第一音节声调不同（阴平与去声），意思是把东西交给国家。"}], "explanations": {"教授": "教授 jiàoshòu：高等学校中职位最高的教师（职称），正确答案。", "教室": "教室 jiàoshì 与 教授 jiàoshòu 第二音节的韵母不同（i 与 ou），声调相同（都是第四声），意思是上课的房间。", "教书": "教书 jiàoshū 与 教授 jiàoshòu 第二音节的韵母和声调不同，意思是从事教学工作。", "交售": "交售 jiāoshòu 与 教授 jiàoshòu 第一音节声调不同（阴平与去声），意思是把东西交给国家。"}, "sentence_index": null, "correct_answer": "教授"}, "level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生是学书的人，没有通过工作当上教授，与“工作了十年，终于当上了”矛盾。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩不能通过工作当上职位，与“工作了十年，终于当上了”矛盾。"}, {"text": "教授", "is_correct": true, "explanation": "教授：职称名，与“工作了十年，终于当上了”相符。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“当上了”后接的应是职称或职位，“病人”不是职位。"}], "explanations": {"学生": "语义：学生是学书的人，没有通过工作当上教授，与“工作了十年，终于当上了”矛盾。", "小孩": "语义：小孩不能通过工作当上职位，与“工作了十年，终于当上了”矛盾。", "教授": "教授：职称名，与“工作了十年，终于当上了”相符。", "病人": "搭配：“当上了”后接的应是职称或职位，“病人”不是职位。"}, "sentence_index": 0, "correct_answer": "教授"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这家公司的教授，每天负责给客人倒茶。", "explanation": "这里应该用〈服务员〉。教授是高校的教师职称，给客人倒茶的人不能称教授。"}, {"text": "他是我们学校的教授，每天负责给全校的学生理发。", "explanation": "这里应该用〈理发师〉。教授是高校的教师职称，给学生理发的人不能称教授。"}, {"text": "这位教授今年才二十岁，还在上中学。", "explanation": "这里应该用〈中学生〉。教授是高等学校的职称，需要多年工作才能获得，中学生不能称教授。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87796, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "教授", "is_correct": true, "explanation": "教授 jiàoshòu：高等学校中职位最高的教师（职称），正确答案。"}, {"text": "胶水", "is_correct": false, "explanation": "胶水 jiāoshuǐ 与 教授 jiàoshòu 两个音节的声调和第二音节韵母都不同，意思是粘东西用的液体。"}, {"text": "交手", "is_correct": false, "explanation": "交手 jiāoshǒu 与 教授 jiàoshòu 两个音节的声调都不同，意思是交战、动手。"}, {"text": "较少", "is_correct": false, "explanation": "较少 jiàoshǎo 与 教授 jiàoshòu 第一音节相同，第二音节韵母和声调不同，意思是比较少。"}], "explanations": {"教授": "教授 jiàoshòu：高等学校中职位最高的教师（职称），正确答案。", "胶水": "胶水 jiāoshuǐ 与 教授 jiàoshòu 两个音节的声调和第二音节韵母都不同，意思是粘东西用的液体。", "交手": "交手 jiāoshǒu 与 教授 jiàoshòu 两个音节的声调都不同，意思是交战、动手。", "较少": "较少 jiàoshǎo 与 教授 jiàoshòu 第一音节相同，第二音节韵母和声调不同，意思是比较少。"}, "sentence_index": null, "correct_answer": "教授"}, "level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "搭配：“工资”的主体要是人，“桌子”不能领工资，与“比讲师高一些”不搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有工资，句子比较的是人的工资，与语境矛盾。"}, {"text": "教授", "is_correct": true, "explanation": "教授：职称名，与“的工资比讲师高一些”相符。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不领工资，与“比讲师高一些”的语境矛盾。"}], "explanations": {"桌子": "搭配：“工资”的主体要是人，“桌子”不能领工资，与“比讲师高一些”不搭配。", "石头": "语义：石头没有工资，句子比较的是人的工资，与语境矛盾。", "教授": "教授：职称名，与“的工资比讲师高一些”相符。", "小狗": "语义：小狗不领工资，与“比讲师高一些”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "教授"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们宿舍楼的教授，每天负责检查大家的门锁。", "explanation": "这里应该用〈宿管〉。教授是高等学校的职称，宿舍楼的管理人员不能称教授。"}, {"text": "这位送包裹的人是我们学校的教授，每天骑车送货。", "explanation": "这里应该用〈快递员〉。教授是高校的教师职称，骑车送货的人不能称教授。"}, {"text": "学校给这位新教授安排了一份端盘子的工作。", "explanation": "这里应该用〈服务员〉。教授是高校的职称，端盘子的人不能称教授。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时当了过教授。", "corrected_sentence": "他年轻时当过教授。", "error_description": "体标错误：“当”后的“了”和“过”不能同时使用，应说“当过教授”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
