INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87797, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "混凝土是沙子、石头和水泥加水拌成的东西。变硬以后像石头一样结实。", "primary_collocate": null, "pronunciation": "hùn níng tǔ", "ipa": "xwən˥˩ niŋ˧˥ tʰu˨˩˦", "syllable_count": 3, "sentences": [{"text": "孩子在院子里踩过还没干的混凝土。", "target_word": "混凝土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家门前的路是混凝土的。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "混凝土变硬以后，像石头一样。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在花园里用混凝土做了一张桌子。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有一块旧混凝土。", "target_word": "混凝土", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨天不要在外面倒混凝土。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这面墙不是砖的，是混凝土的。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "混凝土比木头重，也比木头结实。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用混凝土把小路修平了。", "target_word": "混凝土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新鲜的混凝土很湿，别用手摸。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "吨", "label": "量词"}, {"form": "钢筋混凝土", "label": "复合"}, {"form": "混凝土块", "label": "复合"}], "register": "中性", "sense_fingerprint": "沙石水泥拌成、变硬后像石头的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed802cd7-e1c1-4adc-8439-d8c9d3271fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "混凝土", "is_correct": true, "explanation": "正确。句子说的是还没干、还未变硬的混凝土。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不会“还没干”，也不会被踩在地上变硬，句子说不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会被孩子踩在院子里，句子的情境说不通。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不会“还没干”，也不能被孩子踩在院子里，句子说不通。"}], "explanations": {"混凝土": "正确。句子说的是还没干、还未变硬的混凝土。", "面包": "语义：面包不会“还没干”，也不会被踩在地上变硬，句子说不通。", "作业": "语义：作业不会被孩子踩在院子里，句子的情境说不通。", "电视": "语义：电视不会“还没干”，也不能被孩子踩在院子里，句子说不通。"}, "sentence_index": 0, "correct_answer": "混凝土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "混凝土可以用来消毒，猪圈撒一点就行。", "explanation": "这里应该用〈石灰〉。混凝土不能用来消毒，猪圈消毒要用石灰。"}, {"text": "爸爸买了一张混凝土。", "explanation": "这里应该用〈吨〉。“张”用于纸、桌子等平面的东西，混凝土不说“一张”。"}, {"text": "爸爸买了一支混凝土。", "explanation": "这里应该用〈吨〉。“支”用于杆状的东西，混凝土不说“一支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "混凝土", "is_correct": true, "explanation": "正确。“这面墙不是砖的，是混凝土的”指墙是混凝土做的。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：墙不会是饼干做的，与“不是砖的”的对比说不通。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉不能砌成墙，句子的建造情境说不通。"}, {"text": "糖块", "is_correct": false, "explanation": "语义：糖块不能砌成墙，句子的建造情境说不通。"}], "explanations": {"混凝土": "正确。“这面墙不是砖的，是混凝土的”指墙是混凝土做的。", "饼干": "语义：墙不会是饼干做的，与“不是砖的”的对比说不通。", "面粉": "语义：面粉不能砌成墙，句子的建造情境说不通。", "糖块": "语义：糖块不能砌成墙，句子的建造情境说不通。"}, "sentence_index": 6, "correct_answer": "混凝土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一颗新鲜的混凝土很湿，别用手摸。", "explanation": "这里应该用〈车〉。“颗”用于颗粒状或圆形的小东西，混凝土不说“一颗”。"}, {"text": "一台新鲜的混凝土很湿，别用手摸。", "explanation": "这里应该用〈车〉。“台”用于机器，混凝土不说“一台”。"}, {"text": "一条新鲜的混凝土很湿，别用手摸。", "explanation": "这里应该用〈车〉。“条”用于细长的东西，混凝土不说“一条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸把一根混凝土倒进了模具里，做成了一个花坛。", "corrected_sentence": "爸爸把一车混凝土倒进了模具里，做成了一个花坛。", "error_description": "量词错误。混凝土一次成批运来时应用“车”（一车混凝土），不能用“根”；“根”用于细长的东西。应写作“把一车混凝土倒进”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块混凝土昨天就干透过，可以踩了。", "corrected_sentence": "这块混凝土昨天就干透了，可以踩了。", "error_description": "“干透”表示完成，句末应用“了”，不能用“过”。“干透过”应改为“干透了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
