INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87798, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由水泥、砂、石子和水按一定比例拌合而成，凝固后坚硬的建筑材料。", "primary_collocate": null, "pronunciation": "hùn níng tǔ", "ipa": "xwən˥˩ niŋ˧˥ tʰu˨˩˦", "syllable_count": 3, "sentences": [{"text": "这座桥是用混凝土建成的。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们把混凝土倒进了坑里。", "target_word": "混凝土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "混凝土干了以后非常坚硬。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋楼的墙是混凝土做的。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "建大坝需要很多混凝土。", "target_word": "混凝土", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一辆车每次能运五吨混凝土。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水泥、沙子和水可以拌成混凝土。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "混凝土要等几天才能完全变硬。", "target_word": "混凝土", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路边停着一辆运送混凝土的大卡车。", "target_word": "混凝土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在混凝土里放了钢筋，让地面更结实。", "target_word": "混凝土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吨", "label": "量词"}, {"form": "钢筋混凝土", "label": "复合"}, {"form": "混凝土块", "label": "复合"}], "register": "书面", "sense_fingerprint": "水泥砂石加水拌成的建筑材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed802cd7-e1c1-4adc-8439-d8c9d3271fb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "混凝土", "is_correct": true, "explanation": "正确。混凝土是水泥、沙石加水拌成的建筑材料，可以用来建桥。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉不是建筑材料，不能用来建成一座桥。"}, {"text": "糖果", "is_correct": false, "explanation": "语义：糖果不能建成桥，句子的建造情境说不通。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：颜料用于“涂”“画”，不说“建成”。"}], "explanations": {"混凝土": "正确。混凝土是水泥、沙石加水拌成的建筑材料，可以用来建桥。", "面粉": "语义：面粉不是建筑材料，不能用来建成一座桥。", "糖果": "语义：糖果不能建成桥，句子的建造情境说不通。", "颜料": "搭配：颜料用于“涂”“画”，不说“建成”。"}, "sentence_index": 0, "correct_answer": "混凝土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "混凝土可以用来刷墙，既便宜又能杀菌。", "explanation": "这里应该用〈石灰〉。混凝土是浇筑或砌筑用的材料，不能刷在墙上，刷墙杀菌要用石灰。"}, {"text": "我们买了一张混凝土。", "explanation": "这里应该用〈吨〉。“张”用于纸、桌子等平面的东西，混凝土不说“一张”。"}, {"text": "我们买了一根混凝土。", "explanation": "这里应该用〈吨〉。“根”用于细长的东西，混凝土不说“一根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "混凝土", "is_correct": true, "explanation": "正确。水泥、沙子和水拌在一起，可以拌成混凝土。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：水泥、沙子和水拌不成蛋糕，句子的材料说不通。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：拌合后的东西是湿的泥状，不会是冰块。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“拌”多用于拌菜、拌饭，不说“拌成饮料”。"}], "explanations": {"混凝土": "正确。水泥、沙子和水拌在一起，可以拌成混凝土。", "蛋糕": "语义：水泥、沙子和水拌不成蛋糕，句子的材料说不通。", "冰块": "语义：拌合后的东西是湿的泥状，不会是冰块。", "饮料": "搭配：“拌”多用于拌菜、拌饭，不说“拌成饮料”。"}, "sentence_index": 6, "correct_answer": "混凝土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "卡车运来了五台混凝土。", "explanation": "这里应该用〈吨〉。“台”用于机器，混凝土不说“一台”，按重量说“五吨混凝土”。"}, {"text": "卡车运来了五颗混凝土。", "explanation": "这里应该用〈吨〉。“颗”用于颗粒状或圆形的小东西，混凝土不说“颗”，按重量说“五吨混凝土”。"}, {"text": "卡车运来了五只混凝土。", "explanation": "这里应该用〈吨〉。“只”多用于动物或成对的东西，混凝土不说“只”，按重量说“五吨混凝土”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们把一支混凝土浇进了模板里。", "corrected_sentence": "工人们把一车混凝土浇进了模板里。", "error_description": "量词错误。混凝土一次成批运来时应用“车”（一车混凝土），不能用“支”；“支”用于杆状的东西。应写作“把一车混凝土浇进”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批混凝土已经透干了，可以开始盖楼。", "corrected_sentence": "这批混凝土已经干透了，可以开始盖楼。", "error_description": "补语语序错误。“干透”是动补结构，表示干到透彻，应写作“干透”，“透干”不成词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd886a38-5bf1-4944-a671-17fe4416db10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
