INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87799, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "便条是随手写的小纸条，上面写几句话。", "primary_collocate": null, "pronunciation": "biàn tiáo", "ipa": "pjɛn˥˩ tʰjɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "妈妈在桌上留了一张便条。", "target_word": "便条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给同事写了一张便条。", "target_word": "便条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱上贴着一张便条，写着“买牛奶”。", "target_word": "便条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把电话号码写在便条上了。", "target_word": "便条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上有一张便条，说老师不在。", "target_word": "便条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你看一下我放在桌上的便条。", "target_word": "便条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，我给室友留了便条。", "target_word": "便条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张便条上的字太小，我看不清。", "target_word": "便条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他撕下一页纸，写了一张便条。", "target_word": "便条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到那张写着地址的便条了。", "target_word": "便条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}], "register": "口语", "sense_fingerprint": "随手写几句话的小纸条", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c3fb48-7015-4f79-9d9c-8a4eda67e6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87799, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "便条", "is_correct": true, "explanation": "正确答案：便条 biàntiáo，随手写的小纸条。"}, {"text": "面条", "is_correct": false, "explanation": "miàn（第四声）与 biàn（第四声）声母不同，意思是面条。"}, {"text": "变调", "is_correct": false, "explanation": "diào（第四声）与 tiáo（第二声）声母不同、声调也不同，意思是变调。"}, {"text": "线条", "is_correct": false, "explanation": "xiàn 与 biàn 声母不同（x 与 b），意思是线条。"}], "explanations": {"便条": "正确答案：便条 biàntiáo，随手写的小纸条。", "面条": "miàn（第四声）与 biàn（第四声）声母不同，意思是面条。", "变调": "diào（第四声）与 tiáo（第二声）声母不同、声调也不同，意思是变调。", "线条": "xiàn 与 biàn 声母不同（x 与 b），意思是线条。"}, "sentence_index": null, "correct_answer": "便条"}, "level_3": {"options": [{"text": "床单", "is_correct": false, "explanation": "语义：床单是铺在床上的布，不会被留在桌上。"}, {"text": "便条", "is_correct": true, "explanation": "正确：便条是随手写的小纸条，适合放在桌上留给家人。"}, {"text": "作业本", "is_correct": false, "explanation": "量词：作业本应该用〈本〉，不能用〈张〉，也不是留给家人的留言。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯铺在地面，不能放在桌上当作留言。"}], "explanations": {"床单": "语义：床单是铺在床上的布，不会被留在桌上。", "便条": "正确：便条是随手写的小纸条，适合放在桌上留给家人。", "作业本": "量词：作业本应该用〈本〉，不能用〈张〉，也不是留给家人的留言。", "地毯": "语义：地毯铺在地面，不能放在桌上当作留言。"}, "sentence_index": 0, "correct_answer": "便条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌上放着一只便条，上面写着明天开会。", "explanation": "量词错误：便条是纸片，应该用〈张〉。〈只〉多用于动物或成对器物中的一个，不能用来数便条。"}, {"text": "天冷了，我穿上了一张便条。", "explanation": "语义错误：便条是写字的小纸条，不能穿在身上，这里应该用〈外套〉。"}, {"text": "他的书包里有一把便条。", "explanation": "量词错误：〈把〉用于有柄的器具，便条应该用〈张〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙发", "is_correct": false, "explanation": "语义：沙发是大件家具，不能当作留言留给室友。"}, {"text": "便条", "is_correct": true, "explanation": "正确：便条是随手写的小纸条，出门前留给室友很自然。"}, {"text": "合同", "is_correct": false, "explanation": "语域：合同是正式的法律文件，不用于日常留言。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，不会被当作留言留给室友。"}], "explanations": {"沙发": "语义：沙发是大件家具，不能当作留言留给室友。", "便条": "正确：便条是随手写的小纸条，出门前留给室友很自然。", "合同": "语域：合同是正式的法律文件，不用于日常留言。", "书桌": "语义：书桌是家具，不会被当作留言留给室友。"}, "sentence_index": 6, "correct_answer": "便条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "抽屉里有一部便条，我一直没看见。", "explanation": "量词错误：〈部〉多用于电话、电影、小说等作品，便条应该用〈张〉。"}, {"text": "这份便条有三百多页，我读了一个星期。", "explanation": "语义：便条只是随手写的几句话，不可能有三百多页，这里应该用〈书〉。"}, {"text": "他用便条给朋友打了一通电话。", "explanation": "用法错误：〈便条〉是纸片，不能当作通话工具，打电话应该用〈手机〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在门上贴了一只便条，提醒我带钥匙。", "corrected_sentence": "他在门上贴了一张便条，提醒我带钥匙。", "error_description": "量词错误：便条是纸片，应该说“一张便条”。“只”多用于动物或成对器物中的一个，不能用来数便条。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张便条写很清楚，大家都能看懂。", "corrected_sentence": "这张便条写得很清楚，大家都能看懂。", "error_description": "补语错误：“写”后面表示程度的补语要用“得”连接，应说“写得很清楚”，不能说“写很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
