INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87802, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问时间。", "primary_collocate": null, "pronunciation": "shén me shí hou", "ipa": "ʂən˧˥ mə ʂɻ̩˧˥ xoʊ̯", "syllable_count": 4, "sentences": [{"text": "你什么时候回家？", "target_word": "什么时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们什么时候吃饭？", "target_word": "什么时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候有时间？", "target_word": "什么时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他什么时候来的？", "target_word": "什么时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影什么时候开始？", "target_word": "什么时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候学的汉语？", "target_word": "什么时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师什么时候给我们考试？", "target_word": "什么时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，商店什么时候关门？", "target_word": "什么时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道他什么时候走。", "target_word": "什么时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候去过中国？", "target_word": "什么时候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "疑问代词，用来询问时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fcb4ee2-f2e1-4070-afe6-cb4d17410cdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87802, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "什么时候", "is_correct": true, "explanation": "正确：「什么时候」询问时间，与“回家”的时间语境相符。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：「哪儿」问地点，这里问的是时间，句子意思不通。"}, {"text": "谁", "is_correct": false, "explanation": "语义：「谁」问人，不能放在动词前问时间，「你谁回家」不成立。"}, {"text": "多少", "is_correct": false, "explanation": "语义：「多少」问数量，不能用来问回家的时间。"}], "explanations": {"什么时候": "正确：「什么时候」询问时间，与“回家”的时间语境相符。", "哪儿": "语义：「哪儿」问地点，这里问的是时间，句子意思不通。", "谁": "语义：「谁」问人，不能放在动词前问时间，「你谁回家」不成立。", "多少": "语义：「多少」问数量，不能用来问回家的时间。"}, "sentence_index": 0, "correct_answer": "什么时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的价格是什么时候？", "explanation": "这里应该用〈多少〉。价格问的是数目，「什么时候」只问时间点，不能用来问价格。"}, {"text": "他的老板是什么时候？", "explanation": "这里应该用〈谁〉。问人要用「谁」，「什么时候」只能问时间。"}, {"text": "你的老家是什么时候？", "explanation": "这里应该用〈哪儿〉。问地方要用「哪儿」，「什么时候」只问时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么时候", "is_correct": true, "explanation": "正确：「什么时候」问时间，符合“给我们考试”的时间语境。"}, {"text": "哪里", "is_correct": false, "explanation": "配价：「哪里」作状语要配“在”，「老师哪里给我们考试」不成立。"}, {"text": "哪个", "is_correct": false, "explanation": "搭配：「哪个」只修饰名词，不能直接修饰“给我们考试”。"}, {"text": "什么地方", "is_correct": false, "explanation": "语义：「什么地方」问地点，这里要问的是考试的时间。"}], "explanations": {"什么时候": "正确：「什么时候」问时间，符合“给我们考试”的时间语境。", "哪里": "配价：「哪里」作状语要配“在”，「老师哪里给我们考试」不成立。", "哪个": "搭配：「哪个」只修饰名词，不能直接修饰“给我们考试”。", "什么地方": "语义：「什么地方」问地点，这里要问的是考试的时间。"}, "sentence_index": 6, "correct_answer": "什么时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的年龄是什么时候？", "explanation": "这里应该用〈多大〉。年龄问的是岁数，「什么时候」只问时间点。"}, {"text": "他的座位是什么时候？", "explanation": "这里应该用〈哪个〉。选座位要用「哪个」，「什么时候」只问时间。"}, {"text": "他的身高是什么时候？", "explanation": "这里应该用〈多高〉。身高问的是长度，「什么时候」只问时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们什么时候搬家吗？", "corrected_sentence": "他们什么时候搬家？", "error_description": "错误：句末多加“吗”。“什么时候”已使疑问句成立，句末不能再加疑问语气词“吗”，应说“他们什么时候搬家？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你是什么时候学会了游泳的？", "corrected_sentence": "你是什么时候学会游泳的？", "error_description": "错误：「是……的」句式中多加了“了”。强调动作发生的时间时，句中不用“了”，应说“你是什么时候学会游泳的？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87803, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
