INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87804, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "君主的称号；古代最高统治者。", "primary_collocate": null, "pronunciation": "wáng", "ipa": "wɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "古代的王住在很大的房子里。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王有权力，国家里的人都要听他的。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久以前，这个国家的王叫人修了一座城。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王坐在高高的椅子上，看着下面的人。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，只有王可以穿金色的衣服。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王生病了，国家里的医生都来了。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的王死了，他的儿子当上了新国君。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里说，王统治了国家四十年。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王下了命令，大家都不能出城。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王把国家分给了三个儿子。", "target_word": "王", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位王", "label": "量词"}, {"form": "国王", "label": "复合"}, {"form": "女王", "label": "复合"}], "register": "中性", "sense_fingerprint": "王：君主的称号，古代最高统治者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70440bbe-270b-40e4-ad01-5390c3128607') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87804, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "王", "is_correct": true, "explanation": "王 wáng：君主的称号，古代最高统治者，正确答案。"}, {"text": "网", "is_correct": false, "explanation": "网 wǎng（第三声）与 wáng（第二声）声调不同，意思是网。"}, {"text": "房", "is_correct": false, "explanation": "房 fáng 与 wáng 声母不同（f 与 w），意思是房子。"}, {"text": "忙", "is_correct": false, "explanation": "忙 máng 与 wáng 声母不同（m 与 w），意思是忙碌。"}], "explanations": {"王": "王 wáng：君主的称号，古代最高统治者，正确答案。", "网": "网 wǎng（第三声）与 wáng（第二声）声调不同，意思是网。", "房": "房 fáng 与 wáng 声母不同（f 与 w），意思是房子。", "忙": "忙 máng 与 wáng 声母不同（m 与 w），意思是忙碌。"}, "sentence_index": null, "correct_answer": "王"}, "level_3": {"options": [{"text": "农民", "is_correct": false, "explanation": "语义：农民通常住不起很大的房子，与“古代的……住在很大的房子里”矛盾。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐没有很大的房子，与句子的语境矛盾。"}, {"text": "王", "is_correct": true, "explanation": "王：古代的最高统治者，住在很大的房子里，与句子相符。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“住”要求有生命的主语，“电脑”不能住在房子里。"}], "explanations": {"农民": "语义：农民通常住不起很大的房子，与“古代的……住在很大的房子里”矛盾。", "乞丐": "语义：乞丐没有很大的房子，与句子的语境矛盾。", "王": "王：古代的最高统治者，住在很大的房子里，与句子相符。", "电脑": "搭配：“住”要求有生命的主语，“电脑”不能住在房子里。"}, "sentence_index": 0, "correct_answer": "王"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在医院里当了一个王，每天负责给病人量体温。", "explanation": "这里应该用〈护士〉。王指君主，给病人量体温的人不能称王。"}, {"text": "学校里来了一个王，每天给学生上数学课。", "explanation": "这里应该用〈老师〉。王指君主，给学生上课的人要说“老师”。"}, {"text": "他每天在地里种庄稼，是一位王。", "explanation": "这里应该用〈农民〉。王指君主，种庄稼的人不能称王。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87804, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "王", "is_correct": true, "explanation": "王 wáng：君主的称号，古代最高统治者，正确答案。"}, {"text": "望", "is_correct": false, "explanation": "望 wàng（第四声）与 wáng（第二声）声调不同，意思是看、盼望。"}, {"text": "黄", "is_correct": false, "explanation": "黄 huáng 与 wáng 声母不同（h 与 w），意思是颜色黄。"}, {"text": "完", "is_correct": false, "explanation": "完 wán 与 wáng 韵母不同（an 与 ang），意思是完成、结束。"}], "explanations": {"王": "王 wáng：君主的称号，古代最高统治者，正确答案。", "望": "望 wàng（第四声）与 wáng（第二声）声调不同，意思是看、盼望。", "黄": "黄 huáng 与 wáng 声母不同（h 与 w），意思是颜色黄。", "完": "完 wán 与 wáng 韵母不同（an 与 ang），意思是完成、结束。"}, "sentence_index": null, "correct_answer": "王"}, "level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生不是国家的君主，不能当上新国君，与句子的语境矛盾。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手不是国家的君主，与“当上新国君”的语境矛盾。"}, {"text": "王", "is_correct": true, "explanation": "王：君主，这个国家的君主死后儿子当上了新国君，与句子相符。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“这个国家的……死了，他的儿子当上了新国君”要求前面是君主，“厨师”不能与之搭配。"}], "explanations": {"学生": "语义：学生不是国家的君主，不能当上新国君，与句子的语境矛盾。", "歌手": "语义：歌手不是国家的君主，与“当上新国君”的语境矛盾。", "王": "王：君主，这个国家的君主死后儿子当上了新国君，与句子相符。", "厨师": "搭配：“这个国家的……死了，他的儿子当上了新国君”要求前面是君主，“厨师”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "王"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家的王在医院里给病人看病。", "explanation": "这里应该用〈医生〉。王指国家的最高统治者，给病人看病的人要说“医生”。"}, {"text": "这位师傅是我们国家的王，每天在饭店里做饭。", "explanation": "这里应该用〈厨师〉。王指君主，在饭店里做饭的人要说“厨师”。"}, {"text": "那个国家的王每天骑自行车送外卖。", "explanation": "这里应该用〈外卖员〉。王指君主，骑车送外卖的人要说“外卖员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很久以前，那只王住在一座大宫殿里。", "corrected_sentence": "很久以前，那位王住在一座大宫殿里。", "error_description": "量词错误：“王”指君主，是人，应用量词“位”，不能用“只”（“只”多用于动物）。正确说法：那位王。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位年轻地王很受人民爱戴。", "corrected_sentence": "那位年轻的王很受人民爱戴。", "error_description": "结构助词错误：“年轻”修饰名词“王”时应用“的”，不能用“地”（“地”用于修饰动词）。正确说法：那位年轻的王。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3199bd-a471-4b69-b9e0-818375d1cc64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
