INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87805, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "凑是把东西放到一块儿，或者走近一点。", "primary_collocate": null, "pronunciation": "còu", "ipa": "tsʰoʊ˥˩", "syllable_count": 1, "sentences": [{"text": "我们把钱凑在一起，给老师买了一份礼物。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都凑到桌子旁边看小鸟。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把几张桌子凑在一起，大家一起吃饭。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你凑过来一点，我小声告诉你。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他凑到我耳边，轻轻说了一句话。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把两块木板凑在一起，就是一张小桌子。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "零钱不够，大家再凑一点吧。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们几个人凑了五百块钱，买了一台新电视。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗凑过来，闻了闻我的手。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈凑着灯光看信。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "凑了", "label": "体标"}, {"form": "凑过", "label": "体标"}, {"form": "凑着", "label": "体标"}, {"form": "凑凑", "label": "重叠"}, {"form": "凑钱", "label": "复合"}], "register": "口语", "sense_fingerprint": "把东西放到一起；人或物走近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd548b280-89df-4fe8-9d81-fedf7fde6e45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87805, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "凑", "is_correct": true, "explanation": "còu 表示把东西聚到一起或靠近，是本词的意思。"}, {"text": "奏", "is_correct": false, "explanation": "zòu（第四声）与 còu（第四声）声母不同（z 与 c），意思是演奏。"}, {"text": "促", "is_correct": false, "explanation": "cù（第四声）与 còu 韵母不同（无 o），意思是促使、催促。"}, {"text": "错", "is_correct": false, "explanation": "cuò（第四声）与 còu 韵母不同（uo 与 ou），意思是错误。"}, {"text": "扣", "is_correct": false, "explanation": "kòu（第四声）与 còu 声母不同（k 与 c），意思是扣子、扣住。"}], "explanations": {"凑": "còu 表示把东西聚到一起或靠近，是本词的意思。", "奏": "zòu（第四声）与 còu（第四声）声母不同（z 与 c），意思是演奏。", "促": "cù（第四声）与 còu 韵母不同（无 o），意思是促使、催促。", "错": "cuò（第四声）与 còu 韵母不同（uo 与 ou），意思是错误。", "扣": "kòu（第四声）与 còu 声母不同（k 与 c），意思是扣子、扣住。"}, "sentence_index": null, "correct_answer": "凑"}, "level_3": {"options": [{"text": "数", "is_correct": false, "explanation": "语义：“数”是点数，不是聚拢，“数在一起”不成立。"}, {"text": "凑", "is_correct": true, "explanation": "“凑在一起”表示聚拢，符合“把钱聚在一起买礼物”的语境。"}, {"text": "换", "is_correct": false, "explanation": "搭配：“换”说交换，不能说“换在一起”给老师买礼物。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与为了买礼物而集中钱的意图相反。"}], "explanations": {"数": "语义：“数”是点数，不是聚拢，“数在一起”不成立。", "凑": "“凑在一起”表示聚拢，符合“把钱聚在一起买礼物”的语境。", "换": "搭配：“换”说交换，不能说“换在一起”给老师买礼物。", "扔": "语义：“扔”表示丢弃，与为了买礼物而集中钱的意图相反。"}, "sentence_index": 0, "correct_answer": "凑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛他只是来凑热闹的，别当真。", "explanation": "这里的“凑热闹”是参与、凑趣的意思，是另一个意思，不表示聚拢或靠近。"}, {"text": "公交车上人太多，我被大家凑到了门边。", "explanation": "这里应该用〈挤〉。凑指聚拢或靠近，被人群推到某处要用挤。"}, {"text": "我们在街上凑巧碰见了老同学。", "explanation": "这里的“凑巧”是碰巧、恰好的意思，是另一个意思，不表示聚拢或靠近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87805, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "凑", "is_correct": true, "explanation": "còu 表示把东西聚到一起或靠近，是本词的意思。"}, {"text": "措", "is_correct": false, "explanation": "cuò（第四声）与 còu 韵母不同（uo 与 ou），意思是措施、安排。"}, {"text": "醋", "is_correct": false, "explanation": "cù（第四声）与 còu 韵母不同（无 o），意思是醋。"}, {"text": "叩", "is_correct": false, "explanation": "kòu（第四声）与 còu 声母不同（k 与 c），意思是敲、叩击。"}], "explanations": {"凑": "còu 表示把东西聚到一起或靠近，是本词的意思。", "措": "cuò（第四声）与 còu 韵母不同（uo 与 ou），意思是措施、安排。", "醋": "cù（第四声）与 còu 韵母不同（无 o），意思是醋。", "叩": "kòu（第四声）与 còu 声母不同（k 与 c），意思是敲、叩击。"}, "sentence_index": null, "correct_answer": "凑"}, "level_3": {"options": [{"text": "减", "is_correct": false, "explanation": "语义：“减”表示减少，与“零钱不够”的语境相反。"}, {"text": "凑", "is_correct": true, "explanation": "“凑一点”表示再聚集一些钱，符合“零钱不够”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：零钱不能“吃”，“吃一点”不能指钱。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“零钱不够”需要更多钱的语境矛盾。"}], "explanations": {"减": "语义：“减”表示减少，与“零钱不够”的语境相反。", "凑": "“凑一点”表示再聚集一些钱，符合“零钱不够”的语境。", "吃": "搭配：零钱不能“吃”，“吃一点”不能指钱。", "扔": "语义：“扔”表示丢弃，与“零钱不够”需要更多钱的语境矛盾。"}, "sentence_index": 6, "correct_answer": "凑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人太多了，我被凑得动弹不了。", "explanation": "这里应该用〈挤〉。凑指聚拢或靠近，被人群压得动弹不了要用挤。"}, {"text": "他就是来凑数的，不用管他。", "explanation": "这里的“凑数”是充数、凑足人数的意思，是本词的另一个意思，不表示聚拢或靠近。"}, {"text": "这里太亮了，我凑远一点看书。", "explanation": "凑表示靠近，不能与“远”搭配表示远离，这里的意思正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们都凑门口看热闹。", "corrected_sentence": "他们都凑到门口看热闹。", "error_description": "错误：“凑”表示走近某处，后面接处所时要用“到”，此处漏了“到”。正确说法是“凑到门口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们昨天凑着两百块钱，给老人买了礼物。", "corrected_sentence": "他们昨天凑了两百块钱，给老人买了礼物。", "error_description": "错误：“昨天”指向已完成的动作，此处应用“了”；“着”表示动作进行或状态持续，不能用于已完成的事件。正确说法是“他们昨天凑了两百块钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
