INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87806, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "聚集；拼合；靠近。", "primary_collocate": null, "pronunciation": "còu", "ipa": "tsʰoʊ˥˩", "syllable_count": 1, "sentences": [{"text": "周末同学们凑在一起，准备做一个小游戏。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想凑够路费，坐火车回家。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们几个人凑成一队，参加了比赛。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小图片凑起来是一张大地图。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们凑齐了十个人，开始比赛。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友凑在窗口，看外面的雪。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把两个旧盒子凑成了一个书架。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我凑过去一看，原来是一只小猫。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家凑了凑，每人拿出十块钱。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，他凑到老师身边问问题。", "target_word": "凑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "凑了", "label": "体标"}, {"form": "凑过", "label": "体标"}, {"form": "凑着", "label": "体标"}, {"form": "凑凑", "label": "重叠"}, {"form": "凑齐", "label": "复合"}], "register": "口语", "sense_fingerprint": "聚集在一起；拼合成整体；向前靠近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd548b280-89df-4fe8-9d81-fedf7fde6e45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87806, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "凑", "is_correct": true, "explanation": "còu 表示聚集、拼合或靠近，是本词的意思。"}, {"text": "奏", "is_correct": false, "explanation": "zòu（第四声）与 còu（第四声）声母不同（z 与 c），意思是演奏。"}, {"text": "措", "is_correct": false, "explanation": "cuò（第四声）与 còu 韵母不同（uo 与 ou），意思是措施。"}, {"text": "叩", "is_correct": false, "explanation": "kòu（第四声）与 còu 声母不同（k 与 c），意思是敲、叩击。"}, {"text": "醋", "is_correct": false, "explanation": "cù（第四声）与 còu 韵母不同（无 o），意思是醋。"}], "explanations": {"凑": "còu 表示聚集、拼合或靠近，是本词的意思。", "奏": "zòu（第四声）与 còu（第四声）声母不同（z 与 c），意思是演奏。", "措": "cuò（第四声）与 còu 韵母不同（uo 与 ou），意思是措施。", "叩": "kòu（第四声）与 còu 声母不同（k 与 c），意思是敲、叩击。", "醋": "cù（第四声）与 còu 韵母不同（无 o），意思是醋。"}, "sentence_index": null, "correct_answer": "凑"}, "level_3": {"options": [{"text": "散", "is_correct": false, "explanation": "语义：“散”表示分散，与“凑在一起”的意思相反。"}, {"text": "凑", "is_correct": true, "explanation": "“凑在一起”表示聚集，符合“同学们一起准备游戏”的语境。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”指移动，不指聚集，不能说“跑在一起”。"}, {"text": "换", "is_correct": false, "explanation": "语义：“换”说交换，不表示聚集，与“在一起”搭配不通。"}], "explanations": {"散": "语义：“散”表示分散，与“凑在一起”的意思相反。", "凑": "“凑在一起”表示聚集，符合“同学们一起准备游戏”的语境。", "跑": "搭配：“跑”指移动，不指聚集，不能说“跑在一起”。", "换": "语义：“换”说交换，不表示聚集，与“在一起”搭配不通。"}, "sentence_index": 0, "correct_answer": "凑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章写得很空，只是凑字数。", "explanation": "这里的“凑字数”是充数、凑足的意思，是另一个意思，不表示聚集、拼合或靠近。"}, {"text": "我也想去凑个热闹。", "explanation": "这里的“凑热闹”是参加的意思，是另一个意思，不表示聚集、拼合或靠近。"}, {"text": "下课了，同学们都凑回了自己家。", "explanation": "凑表示聚集或靠近，不表示分散、各自离开，这里应该用〈散〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87806, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "凑", "is_correct": true, "explanation": "còu 表示聚集、拼合或靠近，是本词的意思。"}, {"text": "错", "is_correct": false, "explanation": "cuò（第四声）与 còu 韵母不同（uo 与 ou），意思是错误。"}, {"text": "促", "is_correct": false, "explanation": "cù（第四声）与 còu 韵母不同（无 o），意思是促使、催促。"}, {"text": "扣", "is_correct": false, "explanation": "kòu（第四声）与 còu 声母不同（k 与 c），意思是扣子、扣住。"}], "explanations": {"凑": "còu 表示聚集、拼合或靠近，是本词的意思。", "错": "cuò（第四声）与 còu 韵母不同（uo 与 ou），意思是错误。", "促": "cù（第四声）与 còu 韵母不同（无 o），意思是促使、催促。", "扣": "kòu（第四声）与 còu 声母不同（k 与 c），意思是扣子、扣住。"}, "sentence_index": null, "correct_answer": "凑"}, "level_3": {"options": [{"text": "烧", "is_correct": false, "explanation": "语义：“烧”会毁坏物件，不能把两个盒子烧成书架。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”是丢弃，不能与“成了一个书架”搭配。"}, {"text": "凑", "is_correct": true, "explanation": "“凑成”表示拼合，符合“两个旧盒子做成书架”的语境。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”指清洗，不表示拼合，“洗成书架”不通。"}], "explanations": {"烧": "语义：“烧”会毁坏物件，不能把两个盒子烧成书架。", "扔": "搭配：“扔”是丢弃，不能与“成了一个书架”搭配。", "凑": "“凑成”表示拼合，符合“两个旧盒子做成书架”的语境。", "洗": "搭配：“洗”指清洗，不表示拼合，“洗成书架”不通。"}, "sentence_index": 6, "correct_answer": "凑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他凑在门后，不敢出来。", "explanation": "这里应该用〈躲〉。凑表示聚拢或靠近，躲藏、隐蔽要用躲。"}, {"text": "我被人群凑得喘不过气来。", "explanation": "这里应该用〈挤〉。凑表示聚拢或靠近，被人群推搡、压迫要用挤。"}, {"text": "我们在车站凑巧碰到了老朋友。", "explanation": "这里的“凑巧”是碰巧、恰好的意思，是另一个意思，不表示聚拢或靠近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validati