INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他悄悄凑门边听消息。", "corrected_sentence": "他悄悄凑到门边听消息。", "error_description": "错误：“凑”表示走近某处，接处所时漏了介词“到”。正确说法是“凑到门边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家昨天凑着一百块钱，买了一箱水果。", "corrected_sentence": "大家昨天凑了一百块钱，买了一箱水果。", "error_description": "错误：“昨天”指向已完成的动作，此处应用“了”；“着”表示动作进行或状态持续，不能用于已完成的事件。正确说法是“大家昨天凑了一百块钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
