INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87809, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "联盟是几个国家或几群人约好一起做事。", "primary_collocate": null, "pronunciation": "lián méng", "ipa": "li̯ɛn˧˥ mɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "三个国家结成联盟，约好一起做生意。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个村子为了保护河水，组成了一个联盟。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们组成联盟，要一起保护小狗。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两家的联盟很牢固。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个部落有个联盟，遇到大事就一起商量。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居退出了联盟，不再和我们一起做事。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了联盟，几个小国家不再害怕大国。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老国王想和邻国建立联盟。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的联盟只维持了一年。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联盟里的人说好了，有事大家帮忙。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个联盟", "label": "量词"}, {"form": "军事联盟", "label": "复合"}], "register": "中性", "sense_fingerprint": "几个国家或几群人约好一起做事的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126c10af-4fb6-480f-99ce-28dd5cb5b8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87809, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "联盟", "is_correct": true, "explanation": "正确答案：联盟 lián méng，指几个国家或几群人约好一起做事的关系。"}, {"text": "连忙", "is_correct": false, "explanation": "lián máng 与 lián méng 的第二音节韵母不同（ang／eng），连忙意思是急忙。"}, {"text": "联名", "is_correct": false, "explanation": "míng 与 méng 的韵母不同（ing／eng），联名意思是共同署名。"}, {"text": "莲蓬", "is_correct": false, "explanation": "péng 与 méng 的声母不同（p／m），莲蓬是莲花的果实，与联盟无关。"}], "explanations": {"联盟": "正确答案：联盟 lián méng，指几个国家或几群人约好一起做事的关系。", "连忙": "lián máng 与 lián méng 的第二音节韵母不同（ang／eng），连忙意思是急忙。", "联名": "míng 与 méng 的韵母不同（ing／eng），联名意思是共同署名。", "莲蓬": "péng 与 méng 的声母不同（p／m），莲蓬是莲花的果实，与联盟无关。"}, "sentence_index": null, "correct_answer": "联盟"}, "level_3": {"options": [{"text": "联盟", "is_correct": true, "explanation": "正确：“结成联盟，约好一起做生意”符合语境，联盟指约定合作的关系。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是电器，国家不能结成电视，与约好一起做生意的语境不符。"}, {"text": "团伙", "is_correct": false, "explanation": "语域：团伙带有贬义，不用于国家之间的正式约定。"}, {"text": "学校", "is_correct": false, "explanation": "语义：国家不能结成学校，学校是教育机构，与做生意无关。"}], "explanations": {"联盟": "正确：“结成联盟，约好一起做生意”符合语境，联盟指约定合作的关系。", "电视": "语义：电视是电器，国家不能结成电视，与约好一起做生意的语境不符。", "团伙": "语域：团伙带有贬义，不用于国家之间的正式约定。", "学校": "语义：国家不能结成学校，学校是教育机构，与做生意无关。"}, "sentence_index": 0, "correct_answer": "联盟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他讲了一个联盟。", "explanation": "这里应该用〈故事〉。故事可以讲，联盟是几方约好一起做事的关系，不能用“讲”来说。"}, {"text": "他是他们两家的联盟。", "explanation": "这里应该用〈盟友〉。联盟指约定合作的关系，不指个人，指结盟的一方要说盟友。"}, {"text": "他们两家的联盟搬走了。", "explanation": "这里应该用〈邻居〉。联盟是约定好的关系，不能搬走；住得近的人家应说邻居。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "联盟", "is_correct": true, "explanation": "正确：“有了联盟，几个小国家不再害怕大国”中，联盟指国家之间的约定合作。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不能让国家不再害怕大国，与句中的合作语境冲突。"}, {"text": "球场", "is_correct": false, "explanation": "语义：球场是场地，与国家之间的力量对比无关。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能让国家不再害怕大国，与句中的力量对比语境不符。"}], "explanations": {"联盟": "正确：“有了联盟，几个小国家不再害怕大国”中，联盟指国家之间的约定合作。", "课本": "语义：课本不能让国家不再害怕大国，与句中的合作语境冲突。", "球场": "语义：球场是场地，与国家之间的力量对比无关。", "钢琴": "语义：钢琴是乐器，不能让国家不再害怕大国，与句中的力量对比语境不符。"}, "sentence_index": 6, "correct_answer": "联盟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把联盟放进了冰箱。", "explanation": "这里应该用〈牛奶〉。牛奶是东西，可以放进冰箱；联盟是几方约好一起做事的关系，不是东西，不能放进冰箱。"}, {"text": "我每天早上喝一杯联盟。", "explanation": "这里应该用〈牛奶〉。牛奶是饮料，可以喝；联盟是几方约好一起做事的关系，不能喝。"}, {"text": "这个联盟很好吃。", "explanation": "这里应该用〈面包〉。面包是食物，可以说好吃；联盟是几方约好一起做事的关系，不能用“好吃”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们两家结成了一只牢固的联盟。", "corrected_sentence": "他们两家结成了一个牢固的联盟。", "error_description": "量词错误：“联盟”是抽象关系，应用量词“个”，“只”多用于动物。错误形式是“一只联盟”，正确形式是“一个联盟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个村子组成了一个新联盟们。", "corrected_sentence": "几个村子组成了一个新联盟。", "error_description": "词缀错误：“们”只用于指人的名词或代词之后，“联盟”指约定合作的关系，不能加“们”。错误形式是“新联盟们”，正确形式是“新联盟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
