INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家、团体之间为共同目的而结成的组织。", "primary_collocate": null, "pronunciation": "lián méng", "ipa": "li̯ɛn˧˥ mɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "几个国家结成了联盟，共同保护海洋。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个联盟成立已经快五十年了。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司组成联盟，一起做新产品。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的国家加入了这个联盟。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联盟里的每个国家都要遵守规定。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了应对大雪灾，几个城市建立了联盟。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球联盟决定下个月开始新的比赛。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小国家联合成一个联盟，力量就大了。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联盟的代表今天在北京开会。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个联盟的目的是帮助穷国发展经济。", "target_word": "联盟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个联盟", "label": "量词"}, {"form": "军事联盟", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家或团体为共同目的结成的组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126c10af-4fb6-480f-99ce-28dd5cb5b8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_v