INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分为", "is_correct": true, "explanation": "正确。分为：把整体划分成若干部分。"}, {"text": "身为", "is_correct": false, "explanation": "shēn（第一声）与 fēn 只差声母（sh/f），意思是作为（身为）。"}, {"text": "分位", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）只差声调，意思是分位（位置、分位数）。"}, {"text": "封为", "is_correct": false, "explanation": "fēng（第一声）与 fēn 只差韵尾（-ng/-n），意思是封（授予称号）为。"}], "explanations": {"分为": "正确。分为：把整体划分成若干部分。", "身为": "shēn（第一声）与 fēn 只差声母（sh/f），意思是作为（身为）。", "分位": "wèi（第四声）与 wéi（第二声）只差声调，意思是分位（位置、分位数）。", "封为": "fēng（第一声）与 fēn 只差韵尾（-ng/-n），意思是封（授予称号）为。"}, "sentence_index": null, "correct_answer": "分为"}, "level_3": {"options": [{"text": "分为", "is_correct": true, "explanation": "正确。“分为”表示把整体分成几个部分，符合句意。"}, {"text": "合为", "is_correct": false, "explanation": "语义：“合为”表示合成一个整体，与“分”的意思相反，句意矛盾。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”要带结果补语“成”，不能直接说“撕三个部分”。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象多为食物，不能说“煮三个部分”。"}], "explanations": {"分为": "正确。“分为”表示把整体分成几个部分，符合句意。", "合为": "语义：“合为”表示合成一个整体，与“分”的意思相反，句意矛盾。", "撕": "搭配：“撕”要带结果补语“成”，不能直接说“撕三个部分”。", "煮": "搭配：“煮”的对象多为食物，不能说“煮三个部分”。"}, "sentence_index": 0, "correct_answer": "分为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这笔钱分为三个朋友。", "explanation": "这里应该用〈分给〉。分为指把整体划分成若干部分，分给才是把东西交给人。"}, {"text": "他分为了一名老师。", "explanation": "这里应该用〈成为〉。分为表示把整体划分开，不能表示人变成某种身份。"}, {"text": "我们分为了这个问题的原因。", "explanation": "这里应该用〈分析〉。分为指把整体分成部分，不能表示对问题进行研究。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71f0b21b-d39b-4529-888d-46b30ac3bc8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.va