INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87816, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究信息的获取、处理、存储与传递的学科。", "primary_collocate": null, "pronunciation": "xìn xī xué", "ipa": "ɕin˥˩ ɕi˥ ɕɥœ˧˥", "syllable_count": 3, "sentences": [{"text": "信息学是一门研究信息处理的学科。", "target_word": "信息学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息学研究信息怎样传递。", "target_word": "信息学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在信息学领域工作了十年。", "target_word": "信息学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息学的发展离不开计算机。", "target_word": "信息学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授是信息学方面的专家。", "target_word": "信息学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息学和数学的关系很近。", "target_word": "信息学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息学课程包括数据存储和网络传递。", "target_word": "信息学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校新开了一个信息学研究中心。", "target_word": "信息学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息学的论文要用很多数据。", "target_word": "信息学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的硕士论文是关于信息学的。", "target_word": "信息学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生物信息学", "label": "复合"}, {"form": "医学信息学", "label": "复合"}, {"form": "门", "label": "量词"}], "register": "书面", "sense_fingerprint": "研究信息获取、处理、存储和传递的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af6f987a-8e01-425b-8e85-d1719427681f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信息学", "is_correct": true, "explanation": "信息学：研究信息处理的学科，与“是一门……学科”搭配，符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是学科，不能“研究信息处理”。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不能研究信息处理，句意不通。"}, {"text": "信息化", "is_correct": false, "explanation": "搭配：“信息化”指一种过程，不是学科，不能用“是一门……学科”来说明。"}], "explanations": {"信息学": "信息学：研究信息处理的学科，与“是一门……学科”搭配，符合句意。", "窗户": "语义：窗户不是学科，不能“研究信息处理”。", "面包": "语义：面包不能研究信息处理，句意不通。", "信息化": "搭配：“信息化”指一种过程，不是学科，不能用“是一门……学科”来说明。"}, "sentence_index": 0, "correct_answer": "信息学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "信息学的价格下降了。", "explanation": "这里应该用〈电脑〉。价格属于具体的商品，信息学是学科，不能说价格下降。"}, {"text": "这份信息学的数量非常多。", "explanation": "这里应该用〈数据〉。“数量很多”说的是数据，信息学是学科，没有数量。"}, {"text": "这个信息学很重要，请尽快升级。", "explanation": "这里应该用〈程序〉。信息学是学科，不能升级；需要升级的是程序或系统。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信息学", "is_correct": true, "explanation": "信息学：学科名，可以修饰“课程”，表示信息学的课程，符合句意。"}, {"text": "体育", "is_correct": false, "explanation": "语义：体育课程不包括数据存储和网络传递，句意不通。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪课程不包括数据存储和网络传递，句意不通。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语俗语，与书面的课程说明不搭，语义也不合。"}], "explanations": {"信息学": "信息学：学科名，可以修饰“课程”，表示信息学的课程，符合句意。", "体育": "语义：体育课程不包括数据存储和网络传递，句意不通。", "烹饪": "语义：烹饪课程不包括数据存储和网络传递，句意不通。", "八卦": "语域：“八卦”是口语俗语，与书面的课程说明不搭，语义也不合。"}, "sentence_index": 6, "correct_answer": "信息学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个信息学的价格很低。", "explanation": "这里应该用〈软件〉。价格属于具体的商品，信息学是学科，不能说价格很低。"}, {"text": "信息学的存储容量很大。", "explanation": "这里应该用〈计算机〉。存储容量是计算机的属性，信息学是学科，不能说存储容量。"}, {"text": "我的信息学屏幕坏了，要拿去修。", "explanation": "这里应该用〈电脑〉。屏幕是电脑的部件，信息学是学科，没有屏幕，也不能拿去修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想学了信息学，所以报了名。", "corrected_sentence": "他想学信息学，所以报了名。", "error_description": "“想”表示打算，指将来，不能与“了”连用表示完成。错误形式是“想学了信息学”，正确形式是“想学信息学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把这门信息学学了好。", "corrected_sentence": "她把这门信息学学好了。", "error_description": "“学好”是动补结构，“了”应放在“学好”之后，不能插在“学”和“好”之间。错误形式是“学了好”，正确形式是“学好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻", "is_correct": true, "explanation": "正确：“轻”与“重”在分量上相对，是反义词。"}, {"text": "快", "is_correct": false, "explanation": "无关：“快”说速度，与“重”（分量大）不构成反义关系。"}, {"text": "圆", "is_correct": false, "explanation": "无关：“圆”说形状，与“重”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”说清洁，与“重”没有反义关系。"}], "correct_answer": "轻", "explanations": {"轻": "正确：“轻”与“重”在分量上相对，是反义词。", "快": "无关：“快”说速度，与“重”（分量大）不构成反义关系。", "圆": "无关：“圆”说形状，与“重”没有反义关系。", "干净": "无关：“干净”说清洁，与“重”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻", "is_correct": true, "explanation": "正确：“轻”与“重”（分量大）在分量上相对，是反义词。"}, {"text": "硬", "is_correct": false, "explanation": "无关：“硬”说质地，与“重”的分量义没有反义关系。"}, {"text": "长", "is_correct": false, "explanation": "无关：“长”说长度，与“重”没有反义关系。"}, {"text": "窄", "is_correct": false, "explanation": "无关：“窄”说宽度，与“重”没有反义关系。"}], "correct_answer": "轻", "explanations": {"轻": "正确：“轻”与“重”（分量大）在分量上相对，是反义词。", "硬": "无关：“硬”说质地，与“重”的分量义没有反义关系。", "长": "无关：“长”说长度，与“重”没有反义关系。", "窄": "无关：“窄”说宽度，与“重”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "重是东西拿起来很沉，很费力。", "primary_collocate": null, "pronunciation": "zhòng", "ipa": "ʈʂʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这个箱子很重，我一个人拿不动。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书包太重了，背着很累。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这袋米不重，我可以自己拿回家。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他搬不动这张桌子，因为桌子太重。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你帮我拿一下，这个包有点儿重。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "行李这么重，我们打车去车站吧。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个行李箱比那个重得多，我拿起来很费力。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人手里的东西很重，我去帮他拿。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水桶装满水以后会很重，你一个人提不动。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子不太重，小孩子也能搬动。", "target_word": "重", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "更重", "label": "比较"}, {"form": "最重", "label": "最高级"}], "register": "中性", "sense_fingerprint": "重：东西拿起来沉，费力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: 3 words above tier T1 (max 2): 书包 (Zipf 3.62), 背着 (Zipf 3.75), 很累 (Zipf 3.45)']::text[], 'e7d2912c-6f4e-4394-8528-f3a78e8b990c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重", "is_correct": true, "explanation": "正确：zhòng（第四声）是“重”，指东西拿起来沉、分量大。"}, {"text": "中", "is_correct": false, "explanation": "声调不同：zhōng（第一声）与 zhòng（第四声）只差声调，“中”意思是中间。"}, {"text": "种", "is_correct": false, "explanation": "声调不同：zhǒng（第三声）与 zhòng（第四声）声调不同，“种”意思是种类。"}, {"text": "正", "is_correct": false, "explanation": "韵母不同：zhèng（eng）与 zhòng（ong）韵母不同，“正”意思是正确。"}, {"text": "账", "is_correct": false, "explanation": "韵母不同：zhàng（ang）与 zhòng（ong）韵母不同，“账”意思是账目。"}], "explanations": {"重": "正确：zhòng（第四声）是“重”，指东西拿起来沉、分量大。", "中": "声调不同：zhōng（第一声）与 zhòng（第四声）只差声调，“中”意思是中间。", "种": "声调不同：zhǒng（第三声）与 zhòng（第四声）声调不同，“种”意思是种类。", "正": "韵母不同：zhèng（eng）与 zhòng（ong）韵母不同，“正”意思是正确。", "账": "韵母不同：zhàng（ang）与 zhòng（ong）韵母不同，“账”意思是账目。"}, "sentence_index": null, "correct_answer": "重"}, "level_3": {"options": [{"text": "重", "is_correct": true, "explanation": "正确：“重”说东西分量大，与后半句“拿不动”呼应。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”说清洁，与“拿不动”没有关系，句子读下来不通。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“快”说速度，不能用来形容箱子。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不能用来形容箱子。"}], "explanations": {"重": "正确：“重”说东西分量大，与后半句“拿不动”呼应。", "干净": "语义：“干净”说清洁，与“拿不动”没有关系，句子读下来不通。", "快": "搭配：“快”说速度，不能用来形容箱子。", "甜": "搭配：“甜”说味道，不能用来形容箱子。"}, "sentence_index": 0, "correct_answer": "重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间很重，我一个人住很舒服。", "explanation": "这里应该用〈大〉。“重”说东西的分量，形容房间的空间要用“大”；“房间很重”不成立。"}, {"text": "这件大衣的价格很重，我买不起。", "explanation": "这里应该用〈贵〉。“重”说东西的分量，不能用来形容价钱；价钱高要用“贵”。"}, {"text": "他的汉语水平很重，我们都很佩服他。", "explanation": "这里应该用〈高〉。“重”说东西的分量，不能用来形容水平；水平的高低要用“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "重", "is_correct": true, "explanation": "正确：zhòng（第四声）是“重”，指东西拿起来沉、分量大。"}, {"text": "钟", "is_correct": false, "explanation": "声调不同：zhōng（第一声）与 zhòng（第四声）只差声调，“钟”意思是钟表。"}, {"text": "肿", "is_correct": false, "explanation": "声调不同：zhǒng（第三声）与 zhòng（第四声）声调不同，“肿”意思是肿胀。"}, {"text": "证", "is_correct": false, "explanation": "韵母不同：zhèng（eng）与 zhòng（ong）韵母不同，“证”意思是证件或证明。"}, {"text": "仗", "is_correct": false, "explanation": "韵母不同：zhàng（ang）与 zhòng（ong）韵母不同，“仗”意思是战斗。"}], "explanations": {"重": "正确：zhòng（第四声）是“重”，指东西拿起来沉、分量大。", "钟": "声调不同：zhōng（第一声）与 zhòng（第四声）只差声调，“钟”意思是钟表。", "肿": "声调不同：zhǒng（第三声）与 zhòng（第四声）声调不同，“肿”意思是肿胀。", "证": "韵母不同：zhèng（eng）与 zhòng（ong）韵母不同，“证”意思是证件或证明。", "仗": "韵母不同：zhàng（ang）与 zhòng（ong）韵母不同，“仗”意思是战斗。"}, "sentence_index": null, "correct_answer": "重"}, "level_3": {"options": [{"text": "重", "is_correct": true, "explanation": "正确：“重”与“得多”搭配，说行李箱的分量更大，与后半句“很费力”呼应。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线，与后半句“拿起来很费力”无关，句子不通。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价钱，与“拿起来很费力”没有联系，句子不通。"}, {"text": "热", "is_correct": false, "explanation": "搭配：“热”说温度，不能用来比较行李箱的分量。"}], "explanations": {"重": "正确：“重”与“得多”搭配，说行李箱的分量更大，与后半句“很费力”呼应。", "亮": "语义：“亮”说光线，与后半句“拿起来很费力”无关，句子不通。", "贵": "语义：“贵”说价钱，与“拿起来很费力”没有联系，句子不通。", "热": "搭配：“热”说温度，不能用来比较行李箱的分量。"}, "sentence_index": 6, "correct_answer": "重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很重，我们走了一个小时。", "explanation": "这里应该用〈长〉。“重”说东西的分量，不能形容路的长短；路的长度要用“长”。"}, {"text": "这个电梯的速度很重，一分钟就到了。", "explanation": "这里应该用〈快〉。“重”说东西的分量，不能用来形容速度；速度的快慢要用“快”。"}, {"text": "这里离市中心很重，坐车要半个小时。", "explanation": "这里应该用〈远〉。“重”说东西的分量，不能用来形容距离；距离的远近要用“远”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个包重背不动了。", "corrected_sentence": "这个包重得背不动了。", "error_description": "错误：“重”后漏掉了补语标记“得”。正确是“重得背不动了”，“得”引出程度补语；“重背不动”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个书包比那个重多得。", "corrected_sentence": "这个书包比那个重得多。", "error_description": "错误：程度补语的语序颠倒。“重”后应先接“得”，再接“多”，正确是“重得多”；“重多得”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87818, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻", "is_correct": true, "explanation": "正确：“轻”与“重”在分量上相对，是反义词。"}, {"text": "长", "is_correct": false, "explanation": "无关：“长”说长度，与“重”没有反义关系。"}, {"text": "圆", "is_correct": false, "explanation": "无关：“圆”说形状，与“重”没有反义关系。"}, {"text": "冷", "is_correct": false, "explanation": "无关：“冷”说温度，与“重”没有反义关系。"}], "correct_answer": "轻", "explanations": {"轻": "正确：“轻”与“重”在分量上相对，是反义词。", "长": "无关：“长”说长度，与“重”没有反义关系。", "圆": "无关：“圆”说形状，与“重”没有反义关系。", "冷": "无关：“冷”说温度，与“重”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f555f137-7cbf-4422-bf20-421a498cfe9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
