INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87823, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修理是把坏了的东西弄好。", "primary_collocate": null, "pronunciation": "xiū lǐ", "ipa": "ɕjoʊ˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "爸爸正在修理家里的洗衣机。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的自行车坏了，要去修理。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把坏了的椅子修理好了。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电视修理一下还能用。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅修理了一个小时。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会修理手机吗？", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟喜欢修理旧玩具。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户坏了，明天请人来修理。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个周末都修理家里的东西。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门锁坏了，我自己修理了一下。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修理了", "label": "体标"}, {"form": "修理过", "label": "体标"}, {"form": "修理修理", "label": "重叠"}, {"form": "修理工", "label": "复合"}, {"form": "修理店", "label": "复合"}], "register": "口语", "sense_fingerprint": "把坏了的东西弄好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8e11571-276b-4f80-a3d3-598e69fefa2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修理", "is_correct": true, "explanation": "正确。“修理”指把坏了的洗衣机弄好，与“正在”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：洗衣机不能被吃。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”指整个咽下去，洗衣机不能被吞下。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象应是食物，不能煮洗衣机。"}], "explanations": {"修理": "正确。“修理”指把坏了的洗衣机弄好，与“正在”搭配。", "吃": "语义：洗衣机不能被吃。", "吞": "语义：“吞”指整个咽下去，洗衣机不能被吞下。", "煮": "搭配：“煮”的对象应是食物，不能煮洗衣机。"}, "sentence_index": 0, "correct_answer": "修理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他修理了这份文件的错字。", "explanation": "这里应该用“修改”。修理用于损坏的器物，文件和文字的错误要用修改。"}, {"text": "工人们修理了一条新路。", "explanation": "这里应该用“修建”。修理用于把坏了的东西弄好，新建的路要用修建。"}, {"text": "老师修理了我的错误。", "explanation": "这里应该用“修正”。修理用于器物，错误要用修正。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修理", "is_correct": true, "explanation": "正确。“修理”指把旧玩具弄好，与“喜欢”搭配。"}, {"text": "咽", "is_correct": false, "explanation": "语义：“咽”指吞下去，玩具不能被咽下。"}, {"text": "吐", "is_correct": false, "explanation": "语义：“吐”指从嘴里吐出，喜欢吐玩具说不通。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”的对象是食物，不能煎玩具。"}], "explanations": {"修理": "正确。“修理”指把旧玩具弄好，与“喜欢”搭配。", "咽": "语义：“咽”指吞下去，玩具不能被咽下。", "吐": "语义：“吐”指从嘴里吐出，喜欢吐玩具说不通。", "煎": "搭配：“煎”的对象是食物，不能煎玩具。"}, "sentence_index": 6, "correct_answer": "修理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他修理了自己的思路。", "explanation": "这里应该用“梳理”。修理用于损坏的器物，思路要用梳理。"}, {"text": "他把资料修理得很清楚。", "explanation": "这里应该用“整理”。修理用于损坏的器物，资料要用整理。"}, {"text": "医生修理了病人的感冒。", "explanation": "这里应该用“治疗”。修理用于器物，病痛要用治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把自行车修理了好。", "corrected_sentence": "他把自行车修理好了。", "error_description": "补语位置错误：结果补语“好”要紧跟动词，应说“修理好了”，不能在动词和“好”之间加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
