INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87824, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修补、整治损坏的东西，使其恢复使用。", "primary_collocate": null, "pronunciation": "xiū lǐ", "ipa": "ɕjoʊ˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "工人们在修理路上的大坑。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶漏水了，要快点修理。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆旧车修理以后，又能开了。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的小桥坏了，大家一起修理。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他修理好电脑，又能上网了。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴雨过后，工人修理了断掉的电线。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路修理了半个月才通车。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把坏掉的水管修理好了。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请人修理教室里的灯。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子旧了，需要修理才能住。", "target_word": "修理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修理了", "label": "体标"}, {"form": "修理过", "label": "体标"}, {"form": "修理修理", "label": "重叠"}, {"form": "修理工", "label": "复合"}, {"form": "修理店", "label": "复合"}], "register": "口语", "sense_fingerprint": "修补损坏的设施或物品，使恢复使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8e11571-276b-4f80-a3d3-598e69fefa2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修理", "is_correct": true, "explanation": "正确。“修理”指修补损坏的路面，与“大坑”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：大坑不能被吃。"}, {"text": "洗", "is_correct": false, "explanation": "语义：工人不会去洗路上的大坑，这一动作与修补意义无关。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“大坑”作宾语。"}], "explanations": {"修理": "正确。“修理”指修补损坏的路面，与“大坑”搭配。", "吃": "语义：大坑不能被吃。", "洗": "语义：工人不会去洗路上的大坑，这一动作与修补意义无关。", "唱": "搭配：“唱”不能带“大坑”作宾语。"}, "sentence_index": 0, "correct_answer": "修理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们修理了一座新桥。", "explanation": "这里应该用“修建”。修理用于损坏的东西，新建的桥要用修建。"}, {"text": "他修理了作文里的错误。", "explanation": "这里应该用“修改”。错误和文字要用修改，不能用修理。"}, {"text": "他每天修理武功。", "explanation": "这里应该用“修炼”。修理用于损坏的东西，武功的练习要用修炼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修理", "is_correct": true, "explanation": "正确。“修理”指修补损坏的路，“半个月”表示修补所需的时长。"}, {"text": "跳", "is_correct": false, "explanation": "语义：路不能跳，“跳了半个月”与修路无关。"}, {"text": "笑", "is_correct": false, "explanation": "语义：路不会笑，“笑了半个月才通车”说不通。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”的对象是食物，不能用于修路。"}], "explanations": {"修理": "正确。“修理”指修补损坏的路，“半个月”表示修补所需的时长。", "跳": "语义：路不能跳，“跳了半个月”与修路无关。", "笑": "语义：路不会笑，“笑了半个月才通车”说不通。", "煎": "搭配：“煎”的对象是食物，不能用于修路。"}, "sentence_index": 6, "correct_answer": "修理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师修理了我的错字。", "explanation": "这里应该用“修正”。修理用于损坏的东西，错字要用修正。"}, {"text": "我把这份报告修理得很清楚。", "explanation": "这里应该用“整理”。修理用于损坏的东西，报告要用整理。"}, {"text": "医生修理了他的头痛。", "explanation": "这里应该用“治疗”。修理用于损坏的东西，病痛要用治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把路上的大坑修理了好。", "corrected_sentence": "工人把路上的大坑修理好了。", "error_description": "补语位置错误：结果补语“好”应紧跟动词，说“修理好了”，不能说“修理了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座老桥修理了好，大家很高兴。", "corrected_sentence": "这座老桥修理好了，大家很高兴。", "error_description": "补语位置错误：结果补语“好”应紧跟动词，说“修理好了”，不能在动词和“好”之间加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5d38431-8fe9-4adc-a7ae-41894017f9b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
