INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87825, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "今日是现在的这一天。", "primary_collocate": null, "pronunciation": "jīn rì", "ipa": "tɕin˥ ʐʅ˥˩", "syllable_count": 2, "sentences": [{"text": "今日是我的生日，朋友们都来了。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日是星期五，明天不用上班。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日是春节，街上到处都是人。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日是个好日子，他们结婚了。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问今日有什么新闻？", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日下午，学校开了一个大会。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日的晚饭是妈妈做的。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日是他第一天上班，有点紧张。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日早上，我六点就起床了。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日的会议改到下午三点了。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "今日：说话时所在的这一天，书面语的“今天”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471a2867-8aea-41f5-bcb0-874b318de0af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87825, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "今日", "is_correct": true, "explanation": "正确。今日（jīnrì）指说话时所在的这一天。"}, {"text": "近日", "is_correct": false, "explanation": "声调不同：jīn（第一声）与 jìn（第四声）不同。近日意思是最近，不是今天。"}, {"text": "金币", "is_correct": false, "explanation": "第二音节声母不同：rì 与 bì（r 与 b）不同。金币指金子做的货币，意思不同。"}, {"text": "今世", "is_correct": false, "explanation": "第二音节声母不同：rì 与 shì（r 与 sh）不同。今世指今生，不是今天。"}, {"text": "今次", "is_correct": false, "explanation": "第二音节声母不同：rì 与 cì（r 与 c）不同。今次指这一次，不是今天。"}], "explanations": {"今日": "正确。今日（jīnrì）指说话时所在的这一天。", "近日": "声调不同：jīn（第一声）与 jìn（第四声）不同。近日意思是最近，不是今天。", "金币": "第二音节声母不同：rì 与 bì（r 与 b）不同。金币指金子做的货币，意思不同。", "今世": "第二音节声母不同：rì 与 shì（r 与 sh）不同。今世指今生，不是今天。", "今次": "第二音节声母不同：rì 与 cì（r 与 c）不同。今次指这一次，不是今天。"}, "sentence_index": null, "correct_answer": "今日"}, "level_3": {"options": [{"text": "今日", "is_correct": true, "explanation": "正确。今日指说话时的这一天，与「朋友们都来了」这件已经发生的聚会相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：明天还没到，与「朋友们都来了」这件已经发生的事矛盾。"}, {"text": "下个月", "is_correct": false, "explanation": "语义：下个月还没到，与「朋友们都来了」这件已经发生的事矛盾。"}, {"text": "今生", "is_correct": false, "explanation": "语域：今生是文学用语，说某天是生日时不这样说。语义：一生不能指某一天的生日。"}], "explanations": {"今日": "正确。今日指说话时的这一天，与「朋友们都来了」这件已经发生的聚会相符。", "明天": "语义：明天还没到，与「朋友们都来了」这件已经发生的事矛盾。", "下个月": "语义：下个月还没到，与「朋友们都来了」这件已经发生的事矛盾。", "今生": "语域：今生是文学用语，说某天是生日时不这样说。语义：一生不能指某一天的生日。"}, "sentence_index": 0, "correct_answer": "今日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日他每天都早起，很辛苦。", "explanation": "这里应该用〈平时〉。今日只指一天，不能和「每天都」搭配；说习惯要用平时。"}, {"text": "以前今日是个好日子，他们结婚了。", "explanation": "这里应该用〈那天〉。今日只指现在的这一天，不能用于说以前的事；说过去的某一天要用那天。"}, {"text": "今日一年都是好日子，他们结婚了。", "explanation": "今日只指说话时的这一天，不能指「一年」这样的时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今日", "is_correct": true, "explanation": "正确。今日指说话时的这一天，与「妈妈做的晚饭」这件已做好的事相符。"}, {"text": "今昔", "is_correct": false, "explanation": "语义：今昔指现在和过去，不能用来说某一天的晚饭。"}, {"text": "当今", "is_correct": false, "explanation": "语义：当今指现在这个时代，不能用来说一顿具体的晚饭。"}, {"text": "今生", "is_correct": false, "explanation": "语域：今生是文学用语，不用于说一顿晚饭。语义：一生与一顿晚饭不相称。"}], "explanations": {"今日": "正确。今日指说话时的这一天，与「妈妈做的晚饭」这件已做好的事相符。", "今昔": "语义：今昔指现在和过去，不能用来说某一天的晚饭。", "当今": "语义：当今指现在这个时代，不能用来说一顿具体的晚饭。", "今生": "语域：今生是文学用语，不用于说一顿晚饭。语义：一生与一顿晚饭不相称。"}, "sentence_index": 6, "correct_answer": "今日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日的会议每年都改到下午三点了。", "explanation": "这里应该用〈每次〉。今日只指现在的这一天，不能和「每年」这样反复出现的时间搭配；这种情况要说「每次」。"}, {"text": "今日的会议是去年改到下午三点的。", "explanation": "这里应该用〈当时〉。今日只指现在的这一天，不能和「去年」这样的过去时间搭配；说去年改期的会议要用当时。"}, {"text": "今日的会议昨天已经开完了。", "explanation": "这里应该用〈那天〉。今日只指现在的这一天，昨天已经开完的会议不能叫今日的会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今日的要去看病。", "corrected_sentence": "我今日要去看病。", "error_description": "错误：「今日」作状语修饰动词时，后面不能加「的」。正确：去掉「的」，写作「我今日要去看病」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今日在我第一次去海边。", "corrected_sentence": "今日是我第一次去海边。", "error_description": "「今日」后面表示判断要用「是」，不能用「在」。说「今日在我第一次去海边」用错了判断动词，应说「今日是我第一次去海边」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
