INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "今天；现在。", "primary_collocate": null, "pronunciation": "jīn rì", "ipa": "tɕin˥ ʐʅ˥˩", "syllable_count": 2, "sentences": [{"text": "今日天气很好，我们去公园吧。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日的中国和过去很不一样。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今日要去看一位老朋友。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日的世界越来越小了。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从今日起，这家店每天早上八点开门。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今日没来上班，听说病了。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日我们学习新的课文。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从昨日到今日，雨一直在下。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今日的小城，比十年前漂亮多了。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，今日的作业不多。", "target_word": "今日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "今日：书面语里的“今天”，也指“现在、当今”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471a2867-8aea-41f5-bcb0-874b318de0af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87826, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "今日", "is_correct": true, "explanation": "正确。今日（jīnrì）指今天，是书面语。"}, {"text": "近日", "is_correct": false, "explanation": "声调不同：jīn（第一声）与 jìn（第四声）不同。近日意思是最近，不是今天。"}, {"text": "金币", "is_correct": false, "explanation": "第二音节声母不同：rì 与 bì（r 与 b）不同。金币指金子做的货币，意思不同。"}, {"text": "今世", "is_correct": false, "explanation": "第二音节声母不同：rì 与 shì（r 与 sh）不同。今世指今生，不是今天。"}, {"text": "今次", "is_correct": false, "explanation": "第二音节声母不同：rì 与 cì（r 与 c）不同。今次指这一次，不是今天。"}], "explanations": {"今日": "正确。今日（jīnrì）指今天，是书面语。", "近日": "声调不同：jīn（第一声）与 jìn（第四声）不同。近日意思是最近，不是今天。", "金币": "第二音节声母不同：rì 与 bì（r 与 b）不同。金币指金子做的货币，意思不同。", "今世": "第二音节声母不同：rì 与 shì（r 与 sh）不同。今世指今生，不是今天。", "今次": "第二音节声母不同：rì 与 cì（r 与 c）不同。今次指这一次，不是今天。"}, "sentence_index": null, "correct_answer": "今日"}, "level_3": {"options": [{"text": "今日", "is_correct": true, "explanation": "正确。今日指说话时的这一天，与「天气很好，我们去公园吧」的当下语境相符。"}, {"text": "昨日", "is_correct": false, "explanation": "语义：昨日已经过去，与「我们去公园吧」这一当下的提议矛盾。"}, {"text": "去年", "is_correct": false, "explanation": "语义：去年指一年以前，与当下的天气和「去公园吧」的提议不合。"}, {"text": "明年", "is_correct": false, "explanation": "语义：明年还没到，与「我们去公园吧」这一当下的提议不合。"}], "explanations": {"今日": "正确。今日指说话时的这一天，与「天气很好，我们去公园吧」的当下语境相符。", "昨日": "语义：昨日已经过去，与「我们去公园吧」这一当下的提议矛盾。", "去年": "语义：去年指一年以前，与当下的天气和「去公园吧」的提议不合。", "明年": "语义：明年还没到，与「我们去公园吧」这一当下的提议不合。"}, "sentence_index": 0, "correct_answer": "今日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今日出生在北京。", "explanation": "这里应该用〈当年〉。今日指今天或现在，不能用来说过去发生的事，比如出生；说过去要用当年。"}, {"text": "我今日读小学的时候很喜欢画画。", "explanation": "这里应该用〈那时〉。今日指今天或现在，不能用来指过去的时候，比如读小学；说过去要用那时。"}, {"text": "今日一周都在下雨。", "explanation": "今日只指说话时的这一天，不能指「一周」这样的时段；表示一周要说「这一周」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今日", "is_correct": true, "explanation": "正确。今日指说话时的这一天，与「我们学习新的课文」的课堂活动相符。"}, {"text": "今昔", "is_correct": false, "explanation": "语义：今昔指现在和过去，不能作「我们学习新的课文」的时间。"}, {"text": "当今", "is_correct": false, "explanation": "语义：当今指现在这个时代，不用来说某一天上的一节课。"}, {"text": "今生", "is_correct": false, "explanation": "语域：今生是文学用语，不用于课堂语境。语义：一生与一次课堂学习不相称。"}], "explanations": {"今日": "正确。今日指说话时的这一天，与「我们学习新的课文」的课堂活动相符。", "今昔": "语义：今昔指现在和过去，不能作「我们学习新的课文」的时间。", "当今": "语义：当今指现在这个时代，不用来说某一天上的一节课。", "今生": "语域：今生是文学用语，不用于课堂语境。语义：一生与一次课堂学习不相称。"}, "sentence_index": 6, "correct_answer": "今日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师说，今日的作业下个月才布置。", "explanation": "这里应该用〈将来〉。今日指今天或现在，不能和「下个月」这样的将来时间搭配；谈将来布置的作业要用将来。"}, {"text": "老师说，今日的作业是我们去年写完的。", "explanation": "这里应该用〈当时〉。今日指今天或现在，去年已经写完的作业不能叫今日的作业。"}, {"text": "老师说，今日的作业，前年就布置过了。", "explanation": "这里应该用〈当时〉。今日指今天或现在，不能和「前年」这样的过去时间搭配；说过去布置的作业要用当时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们今日的去爬山吧。", "corrected_sentence": "我们今日去爬山吧。", "error_description": "错误：「今日」作状语修饰动词时，后面不能加「的」。正确：去掉「的」，写作「我们今日去爬山吧」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今日在我的休息日。", "corrected_sentence": "今日是我的休息日。", "error_description": "「今日」后面表示身份或判断要用「是」，不能用「在」。说「今日在我的休息日」用错了判断动词，应说「今日是我的休息日」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
