INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87827, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大规模是说做一件事，范围很大，人很多。", "primary_collocate": null, "pronunciation": "dà guī mó", "ipa": "ta˥˩ kweɪ˥ mwo˧˥", "syllable_count": 3, "sentences": [{"text": "市政府开始大规模地修路。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天城里有一次大规模的检查。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司大规模招人，一次要二百个。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次大规模活动有一万多人来参加。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校大规模地检查了所有教室。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了过节，商店大规模地打折。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里正在进行大规模的种树活动。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的人大规模地搬走了。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院对全城人进行了大规模检查。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节前，大规模的人口流动开始了。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大规模地", "label": "状语形式"}, {"form": "大規模", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事范围很大、参加的人很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eb1202a-debe-449b-9a5c-f738d8413e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大规模", "is_correct": true, "explanation": "正确。“大规模地”修饰“修路”，说明修路的范围很大。"}, {"text": "私人", "is_correct": false, "explanation": "语义：“私人”指个人所有，与“市政府”这一公共机构修路的语境相冲突。"}, {"text": "红色", "is_correct": false, "explanation": "语义：“红色”是颜色，不能修饰“修路”这类行为。"}, {"text": "香甜", "is_correct": false, "explanation": "语义：“香甜”形容味道或睡眠，不能修饰“修路”。"}], "explanations": {"大规模": "正确。“大规模地”修饰“修路”，说明修路的范围很大。", "私人": "语义：“私人”指个人所有，与“市政府”这一公共机构修路的语境相冲突。", "红色": "语义：“红色”是颜色，不能修饰“修路”这类行为。", "香甜": "语义：“香甜”形容味道或睡眠，不能修饰“修路”。"}, "sentence_index": 0, "correct_answer": "大规模"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台大规模的机器很重。", "explanation": "这里应该用〈大型〉。“大规模”形容活动的范围广、人数多，说实物的体积要用“大型”。"}, {"text": "这是我大规模的看法。", "explanation": "这里应该用〈个人〉。“大规模”说范围大、人多，不能修饰个人的看法。"}, {"text": "他大规模地去了北京。", "explanation": "这里应该用〈一个人〉。“大规模”说范围广、人数多，不能修饰一个人的行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大规模", "is_correct": true, "explanation": "正确。“大规模的”修饰“种树活动”，与“正在进行”相符。"}, {"text": "黑色", "is_correct": false, "explanation": "语义：“黑色”是颜色，不能修饰“种树活动”。"}, {"text": "香甜", "is_correct": false, "explanation": "语义：“香甜”形容味道或睡眠，不能修饰“种树活动”。"}, {"text": "地下", "is_correct": false, "explanation": "搭配：“地下”指地面之下，与“山里正在进行……活动”的空间不协调。"}], "explanations": {"大规模": "正确。“大规模的”修饰“种树活动”，与“正在进行”相符。", "黑色": "语义：“黑色”是颜色，不能修饰“种树活动”。", "香甜": "语义：“香甜”形容味道或睡眠，不能修饰“种树活动”。", "地下": "搭配：“地下”指地面之下，与“山里正在进行……活动”的空间不协调。"}, "sentence_index": 6, "correct_answer": "大规模"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一位大规模的老师走进了教室。", "explanation": "这里应该用〈普通〉。“大规模”指范围广、人数多，不能修饰单个老师。"}, {"text": "这辆大规模的汽车很省油。", "explanation": "这里应该用〈小型〉。“大规模”形容范围广、人数多，不能用来说一辆车的体积。"}, {"text": "这是他的大规模秘密。", "explanation": "这里应该用〈私人〉。“大规模”说范围广，不能修饰只属于个人的秘密。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次大规模地活动吸引了一万人。", "corrected_sentence": "这次大规模的活动吸引了一万人。", "error_description": "错误在于“大规模”后面用了“地”。“地”用于修饰动词，修饰名词“活动”时应用“的”，应为“大规模的活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府大规模的检查了全城。", "corrected_sentence": "政府大规模地检查了全城。", "error_description": "错误在于“大规模”后面用了“的”。“的”用于修饰名词，修饰动词“检查”时应用“地”，应为“大规模地检查”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
