INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87828, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "范围广、规模大。", "primary_collocate": null, "pronunciation": "dà guī mó", "ipa": "ta˥˩ kweɪ˥ mwo˧˥", "syllable_count": 3, "sentences": [{"text": "这是一个大规模的工程。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂现在是大规模生产。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们建了一个大规模的苹果园。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次大规模的调查花了一年时间。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大规模的工厂需要很多工人。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店从小店变成了大规模的连锁店。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大规模的比赛，有一百个国家参加。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市正在做大规模的建设。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大规模生产让手机变便宜了。", "target_word": "大规模", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校计划对旧教学楼进行大规模改造。", "target_word": "大规模", "complexity_tier": "T3", "furigana": "xué xiào jì huà duì jiù jiào xué lóu jìn xíng dà guī mó gǎi zào", "sentence_source": "generated"}], "morphological_forms": [{"form": "大规模地", "label": "状语形式"}, {"form": "大規模", "label": "繁体"}], "register": "中性", "sense_fingerprint": "范围广、规模大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eb1202a-debe-449b-9a5c-f738d8413e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大规模", "is_correct": true, "explanation": "正确。“大规模的”修饰“工程”，说明工程的范围很大。"}, {"text": "胖乎乎", "is_correct": false, "explanation": "语义：“胖乎乎”形容外形，不能用来修饰“工程”。"}, {"text": "轻柔", "is_correct": false, "explanation": "搭配：“轻柔”形容声音或动作，不能用来修饰“工程”。"}, {"text": "慵懒", "is_correct": false, "explanation": "语义：“慵懒”形容人的状态，不能修饰“工程”。"}], "explanations": {"大规模": "正确。“大规模的”修饰“工程”，说明工程的范围很大。", "胖乎乎": "语义：“胖乎乎”形容外形，不能用来修饰“工程”。", "轻柔": "搭配：“轻柔”形容声音或动作，不能用来修饰“工程”。", "慵懒": "语义：“慵懒”形容人的状态，不能修饰“工程”。"}, "sentence_index": 0, "correct_answer": "大规模"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大规模地喝了一口水。", "explanation": "这里应该用〈慢慢〉。“大规模”指范围广、规模大，不能修饰“喝一口水”这样的小动作。"}, {"text": "这是我大规模的爱好。", "explanation": "这里应该用〈个人〉。“大规模”说范围大、人多，不能修饰个人的爱好。"}, {"text": "他大规模只能吃一个包子。", "explanation": "这里应该用〈一次〉。“大规模”说范围广、人数多，不能用来说吃东西的数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大规模", "is_correct": true, "explanation": "正确。“大规模的比赛”的范围与“一百个国家参加”相符。"}, {"text": "小型", "is_correct": false, "explanation": "语义：“小型”指规模小，与“一百个国家参加”相矛盾。"}, {"text": "单人", "is_correct": false, "explanation": "语义：“单人”指只有一个人，与“一百个国家参加”相矛盾。"}, {"text": "胖乎乎", "is_correct": false, "explanation": "语义：“胖乎乎”形容外形，不能用来修饰“比赛”。"}], "explanations": {"大规模": "正确。“大规模的比赛”的范围与“一百个国家参加”相符。", "小型": "语义：“小型”指规模小，与“一百个国家参加”相矛盾。", "单人": "语义：“单人”指只有一个人，与“一百个国家参加”相矛盾。", "胖乎乎": "语义：“胖乎乎”形容外形，不能用来修饰“比赛”。"}, "sentence_index": 6, "correct_answer": "大规模"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大规模地擦了擦桌子。", "explanation": "这里应该用〈随手〉。“大规模”指范围广、人数多，不能修饰“擦桌子”这种随手的小动作。"}, {"text": "她大规模地发了一条短信。", "explanation": "这里应该用〈简单〉。“大规模”指范围广、人数多，不能修饰发一条短信这种小事。"}, {"text": "一位大规模的医生走进了病房。", "explanation": "这里应该用〈普通〉。“大规模”指范围广、人数多，不能修饰单个医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次大规模地检查花了三天。", "corrected_sentence": "这次大规模的检查花了三天。", "error_description": "错误在于“大规模”后面用了“地”。“地”用于修饰动词，修饰名词“检查”时应用“的”，应为“大规模的检查”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂大规模了生产手机。", "corrected_sentence": "工厂大规模生产手机。", "error_description": "错误在于“大规模”和“生产”之间多用了“了”。“了”是动词后的体标记，不能放在状语和动词之间。应去掉“了”，为“工厂大规模生产手机。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
