INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87829, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "热闹是有很多人，又吵又开心。", "primary_collocate": null, "pronunciation": "rè nao", "ipa": "ʐɤ˥˩ nau", "syllable_count": 2, "sentences": [{"text": "过生日那天，家里来了很多朋友，特别热闹。", "target_word": "热闹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起唱歌跳舞，真热闹！", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在院子里玩，热闹得很。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年夜饭桌上，一家人说说笑笑，很热闹。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里同学们又说又笑，真热闹。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "婚礼上大家喝着酒、笑着，场面热闹。", "target_word": "热闹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都来了，家里热闹起来了。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天家里人多，吃饭的时候很热闹。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班的聚会又吵又笑，热闹极了。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过节时，邻居们坐在一起，热闹又开心。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "热热闹闹", "label": "重叠"}], "register": "中性", "sense_fingerprint": "聚会、家里人多，说笑声不断，气氛欢乐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17cd111-484e-48a1-bddc-52f40a3ae15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87829, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”指态度郑重，与朋友聚会的欢闹气氛不符"}, {"text": "伟大", "is_correct": false, "explanation": "搭配：“伟大”形容人或事业的卓越，不能用来形容聚会的场面"}, {"text": "热闹", "is_correct": true, "explanation": "热闹：家里来了很多朋友，说笑欢闹，符合这里的气氛"}, {"text": "文静", "is_correct": false, "explanation": "语义：“文静”形容人安静斯文，与众人说笑的场面相矛盾"}], "explanations": {"严肃": "语义：“严肃”指态度郑重，与朋友聚会的欢闹气氛不符", "伟大": "搭配：“伟大”形容人或事业的卓越，不能用来形容聚会的场面", "热闹": "热闹：家里来了很多朋友，说笑欢闹，符合这里的气氛", "文静": "语义：“文静”形容人安静斯文，与众人说笑的场面相矛盾"}, "sentence_index": 0, "correct_answer": "热闹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对每位客人都很热闹。", "explanation": "这里应该用〈热情〉。热闹形容场面，待人的态度要用热情"}, {"text": "他对公益活动很热闹。", "explanation": "这里应该用〈热心〉。热闹形容一群人聚在一起又吵又开心的场面，对事情的积极态度要用热心"}, {"text": "妈妈对邻居很热闹。", "explanation": "这里应该用〈亲切〉。热闹形容场面，对人的态度要用亲切"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87829, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腼腆", "is_correct": false, "explanation": "语义：“腼腆”形容人害羞，不能用来说家里的气氛"}, {"text": "严谨", "is_correct": false, "explanation": "搭配：“严谨”多用于做事或治学，不能用来修饰家里的气氛"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指不熟悉，与朋友都来了、家里变热闹的意思相反"}, {"text": "热闹", "is_correct": true, "explanation": "热闹：朋友来齐，家里的气氛欢闹起来，符合语境"}], "explanations": {"腼腆": "语义：“腼腆”形容人害羞，不能用来说家里的气氛", "严谨": "搭配：“严谨”多用于做事或治学，不能用来修饰家里的气氛", "陌生": "语义：“陌生”指不熟悉，与朋友都来了、家里变热闹的意思相反", "热闹": "热闹：朋友来齐，家里的气氛欢闹起来，符合语境"}, "sentence_index": 6, "correct_answer": "热闹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地区的经济很热闹。", "explanation": "这里应该用〈繁荣〉。热闹形容一群人又吵又开心的场面，说地区经济的兴盛要用繁荣"}, {"text": "大家的斗志很热闹。", "explanation": "这里应该用〈高昂〉。热闹形容一群人又吵又开心的场面，说斗志、士气的旺盛要用高昂"}, {"text": "大家对这次活动的反应很热闹。", "explanation": "这里应该用〈热烈〉。热闹形容一群人又吵又开心的场面，对活动的反应、态度要用热烈"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "过节的时候，院子里热闹下来了。", "corrected_sentence": "过节的时候，院子里热闹起来了。", "error_description": "“热闹”表示状态由静到动的变化，后接趋向补语应说“起来”，应说“热闹起来”，不能说“热闹下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放假的时候，村里热闹地广场上，大家又唱又跳。", "corrected_sentence": "放假的时候，村里热闹的广场上，大家又唱又跳。", "error_description": "修饰名词“广场”时，形容词后面要用“的”，应说“热闹的广场”，不能用“地”；“地”用于修饰动词或作状语，不能用来修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
