INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87830, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（场面）人多而活跃，景象繁盛。", "primary_collocate": null, "pronunciation": "rè nao", "ipa": "ʐɤ˥˩ nau", "syllable_count": 2, "sentences": [{"text": "春节的街上很热闹。", "target_word": "热闹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末的夜市非常热闹。", "target_word": "热闹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新年的时候，广场上热闹极了。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条商业街一直很热闹。", "target_word": "热闹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "庙会上人山人海，特别热闹。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "节日的城市比平时热闹多了。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家附近的市场早上最热闹。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的操场上正热闹着。", "target_word": "热闹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，球场里已经很热闹了。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇以前很安静，现在变得热闹了。", "target_word": "热闹", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "热热闹闹", "label": "重叠"}], "register": "中性", "sense_fingerprint": "街市、场所人多而繁华兴旺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17cd111-484e-48a1-bddc-52f40a3ae15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”指人遇事头脑清醒、不慌乱，不能用来形容街道的景象"}, {"text": "热闹", "is_correct": true, "explanation": "热闹：春节的街上人多、气氛活跃，符合这里的景象"}, {"text": "健康", "is_correct": false, "explanation": "搭配：“健康”多用于人或身体，不能用来形容街上的景象"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”指态度郑重、氛围庄重，与春节街上的喜庆景象不符"}], "explanations": {"冷静": "语义：“冷静”指人遇事头脑清醒、不慌乱，不能用来形容街道的景象", "热闹": "热闹：春节的街上人多、气氛活跃，符合这里的景象", "健康": "搭配：“健康”多用于人或身体，不能用来形容街上的景象", "严肃": "语义：“严肃”指态度郑重、氛围庄重，与春节街上的喜庆景象不符"}, "sentence_index": 0, "correct_answer": "热闹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的数学成绩很热闹。", "explanation": "这里应该用〈优秀〉。热闹形容场面人多活跃，说成绩的好坏要用优秀"}, {"text": "这家店的服务员很热闹。", "explanation": "这里应该用〈热情〉。热闹形容场面，待人的态度要用热情"}, {"text": "他们之间的友情很热闹。", "explanation": "这里应该用〈深厚〉。热闹形容场面人多活跃，说感情、关系的程度要用深厚"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文静", "is_correct": false, "explanation": "语义：“文静”形容人的性情安静温和，不能用来形容早上市场的景象"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容人风趣，不能用来修饰市场"}, {"text": "热闹", "is_correct": true, "explanation": "热闹：早上人多、买卖活跃，符合市场的景象"}, {"text": "肥胖", "is_correct": false, "explanation": "体貌：“肥胖”形容人或动物的体形，不能用于形容市场"}], "explanations": {"文静": "语义：“文静”形容人的性情安静温和，不能用来形容早上市场的景象", "幽默": "搭配：“幽默”形容人风趣，不能用来修饰市场", "热闹": "热闹：早上人多、买卖活跃，符合市场的景象", "肥胖": "体貌：“肥胖”形容人或动物的体形，不能用于形容市场"}, "sentence_index": 6, "correct_answer": "热闹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家的经济很热闹。", "explanation": "这里应该用〈繁荣〉。热闹形容场面人多活跃，说国家经济的兴盛要用繁荣"}, {"text": "大家的情绪很热闹。", "explanation": "这里应该用〈高涨〉。热闹形容场面，说情绪、热情的升温要用高涨"}, {"text": "这位老奶奶对孩子很热闹。", "explanation": "这里应该用〈亲切〉。热闹形容场面，对人的态度要用亲切"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春节一到，街上就热闹下来了。", "corrected_sentence": "春节一到，街上就热闹起来了。", "error_description": "“热闹”表示状态由静到动的变化，后接趋向补语应说“起来”，应说“热闹起来”，不能说“热闹下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "早上热闹地市场，人来人往。", "corrected_sentence": "早上热闹的市场，人来人往。", "error_description": "修饰名词“市场”时，形容词后面要用“的”，应说“热闹的市场”，不能用“地”；“地”用于修饰动词或作状语，不能用来修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
