INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87831, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "元首是一个国家最高的领头人。", "primary_collocate": null, "pronunciation": "yuán shǒu", "ipa": "ɥɛn˧˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "总统是这个国家的元首。", "target_word": "元首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道那个国家的元首是谁。", "target_word": "元首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在君主制国家，国王就是元首。", "target_word": "元首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "元首代表国家参加会议。", "target_word": "元首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新元首今天正式上任了。", "target_word": "元首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻的元首很受人民喜欢。", "target_word": "元首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "元首的工作很忙，每天都要开会。", "target_word": "元首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们介绍了几位国家元首。", "target_word": "元首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在电视上看到了元首。", "target_word": "元首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有一位新元首。", "target_word": "元首", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "国家元首", "label": "复合"}], "register": "正式", "sense_fingerprint": "一个国家最高的领头人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8c3fb48-7015-4f79-9d9c-8a4eda67e6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87831, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首都", "is_correct": false, "explanation": "语义：首都是城市，不是人，“总统是这个国家的首都”说不通。"}, {"text": "元首", "is_correct": true, "explanation": "正确：元首是一个国家最高的领头人，总统可以是这个国家的元首。"}, {"text": "国旗", "is_correct": false, "explanation": "语义：国旗是标志，不能用来指称担任职务的人。"}, {"text": "大个子", "is_correct": false, "explanation": "体貌：大个子描述的是身材，不是国家的职务，与“总统是……”不符。"}], "explanations": {"首都": "语义：首都是城市，不是人，“总统是这个国家的首都”说不通。", "元首": "正确：元首是一个国家最高的领头人，总统可以是这个国家的元首。", "国旗": "语义：国旗是标志，不能用来指称担任职务的人。", "大个子": "体貌：大个子描述的是身材，不是国家的职务，与“总统是……”不符。"}, "sentence_index": 0, "correct_answer": "元首"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村的元首由村民选出。", "explanation": "这里应该用〈村长〉。元首是国家最高的领头人，村里不设元首。"}, {"text": "爸爸是我们家的元首。", "explanation": "这里应该用〈家长〉。元首只指一个国家最高的领头人，不能用来称呼家里的人。"}, {"text": "这家餐厅的元首每天亲自做饭。", "explanation": "这里应该用〈老板〉或〈厨师〉。元首指国家最高的领头人，不用来称呼餐厅的人员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不能担任需要开会的职务。"}, {"text": "元首", "is_correct": true, "explanation": "正确：元首是一个国家最高的领头人，工作忙、每天开会很合理。"}, {"text": "王位", "is_correct": false, "explanation": "搭配：王位是君主的宝座，不能作为“工作很忙”的主体。"}, {"text": "国歌", "is_correct": false, "explanation": "语义：国歌是一首歌，不是人，不能有工作，也不能开会。"}], "explanations": {"石头": "语义：石头是无生命的物体，不能担任需要开会的职务。", "元首": "正确：元首是一个国家最高的领头人，工作忙、每天开会很合理。", "王位": "搭配：王位是君主的宝座，不能作为“工作很忙”的主体。", "国歌": "语义：国歌是一首歌，不是人，不能有工作，也不能开会。"}, "sentence_index": 6, "correct_answer": "元首"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支球队的元首很有经验。", "explanation": "这里应该用〈队长〉。元首指国家最高的领头人，球队里没有元首。"}, {"text": "王明是我们班的元首。", "explanation": "这里应该用〈班长〉。元首只指一个国家最高的领头人，班里没有元首。"}, {"text": "我们学校的元首是一位很有名的老师。", "explanation": "这里应该用〈校长〉。元首指国家最高的领头人，不用来称呼学校的领导。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的元首今天来开会了。", "corrected_sentence": "这家公司的老板今天来开会了。", "error_description": "用词错误：元首只指国家最高的领头人，公司的领导应该叫〈老板〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候见过我们学校的元首。", "corrected_sentence": "我小时候见过我们学校的校长。", "error_description": "用词错误：元首只指国家最高的领头人，学校的领导应该叫〈校长〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5e4362-c5fb-45e9-aafc-472479894262') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
