INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87833, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "倒是人或东西站不住，躺下去了。", "primary_collocate": null, "pronunciation": "dǎo", "ipa": "tau˨˩˦", "syllable_count": 1, "sentences": [{"text": "大风一吹，那棵老树就倒了。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩没站稳，一下子倒在地上。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地很滑，他差点儿倒了。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚风太大，路边的树倒了好几棵。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的瓶子倒了，水流了一地。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝醉了，走了几步就倒了。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老人突然倒在路上，大家快去帮忙。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点儿，别让椅子倒了。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架没放稳，上面的书全倒了。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，一个运动员在我前面倒了。", "target_word": "倒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倒了", "label": "完成体"}, {"form": "倒下", "label": "复合词"}], "register": "通用", "sense_fingerprint": "人或竖立的东西站不住而摔倒、倒塌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 瓶子 (Zipf 3.76), 水流 (Zipf 3.89), 一地 (Zipf 3.43)']::text[], '126c10af-4fb6-480f-99ce-28dd5cb5b8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87833, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "倒", "is_correct": true, "explanation": "正确答案：倒 dǎo，指人或竖立的东西站不住而倒下。"}, {"text": "到", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，到表示抵达。"}, {"text": "刀", "is_correct": false, "explanation": "dāo（第一声）与 dǎo（第三声）声调不同，刀是切割的工具。"}, {"text": "讨", "is_correct": false, "explanation": "tǎo 与 dǎo 的声母不同（送气 t／不送气 d），讨指索取或讨论。"}], "explanations": {"倒": "正确答案：倒 dǎo，指人或竖立的东西站不住而倒下。", "到": "dào（第四声）与 dǎo（第三声）声调不同，到表示抵达。", "刀": "dāo（第一声）与 dǎo（第三声）声调不同，刀是切割的工具。", "讨": "tǎo 与 dǎo 的声母不同（送气 t／不送气 d），讨指索取或讨论。"}, "sentence_index": null, "correct_answer": "倒"}, "level_3": {"options": [{"text": "倒", "is_correct": true, "explanation": "正确：“大风一吹，那棵老树就倒了”中，倒指竖立的树倒下。"}, {"text": "站", "is_correct": false, "explanation": "语义：站表示直立，与大风吹倒树的语境相反。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”一般说人或器物跌落，不说树“摔了”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，与大风吹倒老树的语境不符。"}], "explanations": {"倒": "正确：“大风一吹，那棵老树就倒了”中，倒指竖立的树倒下。", "站": "语义：站表示直立，与大风吹倒树的语境相反。", "摔": "搭配：“摔”一般说人或器物跌落，不说树“摔了”。", "唱": "语义：唱是唱歌，与大风吹倒老树的语境不符。"}, "sentence_index": 0, "correct_answer": "倒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他倒完了作业。", "explanation": "这里应该用〈写〉。作业是写的，写是用笔写字；倒指人或东西站不住而倒下，不能用于作业。"}, {"text": "他倒了一眼窗外。", "explanation": "这里应该用〈看〉。“看一眼”是固定说法；倒指人或东西站不住而倒下，不能表示看。"}, {"text": "他倒了一首歌。", "explanation": "这里应该用〈唱〉。歌是唱出来的；倒指人或东西站不住而倒下，不能表示唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87833, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "倒", "is_correct": true, "explanation": "正确答案：倒 dǎo，指人或竖立的东西站不住而倒下。"}, {"text": "道", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，道是道路。"}, {"text": "稻", "is_correct": false, "explanation": "dào 与 dǎo 的声调不同，稻是水稻。"}, {"text": "老", "is_correct": false, "explanation": "lǎo 与 dǎo 的声母不同（l／d），老指年纪大。"}], "explanations": {"倒": "正确答案：倒 dǎo，指人或竖立的东西站不住而倒下。", "道": "dào（第四声）与 dǎo（第三声）声调不同，道是道路。", "稻": "dào 与 dǎo 的声调不同，稻是水稻。", "老": "lǎo 与 dǎo 的声母不同（l／d），老指年纪大。"}, "sentence_index": null, "correct_answer": "倒"}, "level_3": {"options": [{"text": "倒", "is_correct": true, "explanation": "正确：“那个老人突然倒在路上”中，倒指人突然摔倒。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，不能表示突发的摔倒。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是书写，与路上的突发状况无关。"}, {"text": "抱", "is_correct": false, "explanation": "配价：“抱”要带宾语，不能说“抱在路上”。"}], "explanations": {"倒": "正确：“那个老人突然倒在路上”中，倒指人突然摔倒。", "唱": "语义：唱是唱歌，不能表示突发的摔倒。", "写": "语义：写是书写，与路上的突发状况无关。", "抱": "配价：“抱”要带宾语，不能说“抱在路上”。"}, "sentence_index": 6, "correct_answer": "倒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把窗户倒开了。", "explanation": "这里应该用〈推〉。“推开窗户”是固定说法；倒指人或东西站不住而倒下，不能表示推开。"}, {"text": "他倒好了门。", "explanation": "这里应该用〈关〉。关门是把门合上；倒指人或东西站不住而倒下，不能表示关门。"}, {"text": "他把老人倒起来坐好。", "explanation": "这里应该用〈扶〉。扶是用手使人站起或坐正，倒不能表示用手帮人站起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车子撞上了电线杆，电线杆倒起来了。", "corrected_sentence": "车子撞上了电线杆，电线杆倒下了。", "error_description": "补语错误：表示倒向地面要说“倒下”，“倒起来”不成立。错误形式是“倒起来”，正确形式是“倒下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他脚下一滑，就倒了在地上。", "corrected_sentence": "他脚下一滑，就倒在地上。", "error_description": "“了”位置错误：“了”不能插在“倒”和“在”之间，应删去。错误形式是“倒了在地上”，正确形式是“倒在地上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9946c228-4e98-4a02-9217-b900dc6ca611') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
