INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87836, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把机器、器材等按一定的方法固定在某处。", "primary_collocate": null, "pronunciation": "ān zhuāng", "ipa": "an˥ ʈʂwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "工人在楼顶安装太阳能板。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在每层楼都安装了灭火器。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在安装新的机器。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按图纸安装这台设备很重要。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅安装窗户时要很小心。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里安装着十台大机器。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按说明书的方法安装电池。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安装电梯需要专业的工人。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在路边安装了新路灯。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个摄像头安装在门口的墙上。", "target_word": "安装", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安装了", "label": "体标"}, {"form": "安装过", "label": "体标"}, {"form": "安装工", "label": "复合"}, {"form": "安裝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把机器、器材按一定方法固定在某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd449a6-9c7f-4543-8b31-149e4d1ca677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安装", "is_correct": true, "explanation": "“安装”指把太阳能板固定在某处使用，工人在楼顶装太阳能板符合语境。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”的对象是文字，太阳能板不能写。"}, {"text": "弹", "is_correct": false, "explanation": "搭配：“弹”接乐器，不接太阳能板。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”接歌曲，不接设备。"}], "explanations": {"安装": "“安装”指把太阳能板固定在某处使用，工人在楼顶装太阳能板符合语境。", "写": "语义：“写”的对象是文字，太阳能板不能写。", "弹": "搭配：“弹”接乐器，不接太阳能板。", "唱": "搭配：“唱”接歌曲，不接设备。"}, "sentence_index": 0, "correct_answer": "安装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府把灾民安装在临时帐篷里。", "explanation": "这里应该用〈安置〉。“安装”指固定机器器材，安排灾民的住处要用“安置”。"}, {"text": "他们用彩纸安装房间，让晚会很热闹。", "explanation": "这里应该用〈装饰〉。“安装”指固定机器器材，布置房间要用“装饰”。"}, {"text": "他把花安装在桌子上。", "explanation": "这里应该用〈摆〉。“安装”指固定机器器材，花放在桌上只需“摆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安装", "is_correct": true, "explanation": "“安装”指按方法把电池装好使其能用，“请按说明书的方法安装电池”符合语境。"}, {"text": "点", "is_correct": false, "explanation": "语义：“点”指点燃，电池不能这样处理，与按说明书安装不符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：电池不能煮，与按说明书安装不符。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”接植物或液体，不接电池。"}], "explanations": {"安装": "“安装”指按方法把电池装好使其能用，“请按说明书的方法安装电池”符合语境。", "点": "语义：“点”指点燃，电池不能这样处理，与按说明书安装不符。", "煮": "语义：电池不能煮，与按说明书安装不符。", "浇": "搭配：“浇”接植物或液体，不接电池。"}, "sentence_index": 6, "correct_answer": "安装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在田里安装了很多玉米。", "explanation": "这里应该用〈种〉。“安装”指固定机器器材，玉米要用“种”。"}, {"text": "他在黑板上安装了三行字。", "explanation": "这里应该用〈写〉。“安装”指固定机器器材，字要用“写”。"}, {"text": "我把毛巾安装在浴室的门上。", "explanation": "这里应该用〈挂〉。“安装”针对机器器材，毛巾挂在门上要用“挂”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把灯安装天花板上。", "corrected_sentence": "工人把灯安装在天花板上。", "error_description": "错误：“安装”后缺介词“在”，应说“安装在天花板上”，用“在”引出安装的处所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂安装过很多只机器。", "corrected_sentence": "这家工厂安装过很多台机器。", "error_description": "量词错误：“机器”的量词应用“台”，不用“只”（“只”多用于动物或小东西）。错误形式“很多只机器”，正确形式“很多台机器”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87837, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷淡", "is_correct": true, "explanation": "正确：“冷淡”指对事物没有热情、不感兴趣，与“狂热”的喜爱程度相反。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”指态度郑重，不表示喜爱与否，与“狂热”不构成反义。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：“懒散”说做事不认真，与“狂热”的情感强度无关，不构成反义。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说的是智力高，与“狂热”的喜爱之义不构成反义。"}], "correct_answer": "冷淡", "explanations": {"冷淡": "正确：“冷淡”指对事物没有热情、不感兴趣，与“狂热”的喜爱程度相反。", "严肃": "语义：“严肃”指态度郑重，不表示喜爱与否，与“狂热”不构成反义。", "懒散": "语义：“懒散”说做事不认真，与“狂热”的情感强度无关，不构成反义。", "聪明": "语义：“聪明”说的是智力高，与“狂热”的喜爱之义不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87837, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷淡", "is_correct": true, "explanation": "正确：“冷淡”指对事物没有热情、不感兴趣，与“狂热”的喜爱程度相反。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”说性情或态度柔和，与“狂热”的喜爱程度无关，不构成反义。"}, {"text": "朴素", "is_correct": false, "explanation": "语义：“朴素”说外表或生活简单，与“狂热”不构成反义。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：“勇敢”说不怕困难，与“狂热”的喜爱之义不构成反义。"}], "correct_answer": "冷淡", "explanations": {"冷淡": "正确：“冷淡”指对事物没有热情、不感兴趣，与“狂热”的喜爱程度相反。", "温柔": "语义：“温柔”说性情或态度柔和，与“狂热”的喜爱程度无关，不构成反义。", "朴素": "语义：“朴素”说外表或生活简单，与“狂热”不构成反义。", "勇敢": "语义：“勇敢”说不怕困难，与“狂热”的喜爱之义不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87837, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "狂热是特别特别喜欢一件事，喜欢得停不下来。", "primary_collocate": null, "pronunciation": "kuáng rè", "ipa": "kʰuɑŋ˧˥ ʐɤ˥˩", "syllable_count": 2, "sentences": [{"text": "他对足球非常狂热。", "target_word": "狂热", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我弟弟对游戏很狂热。", "target_word": "狂热", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她对音乐狂热得每天听八小时。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王是个狂热的摄影爱好者。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸对钓鱼十分狂热。", "target_word": "狂热", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他狂热地喜欢画画，天天都画。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐对跑步狂热极了。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对这个游戏曾经很狂热。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是狂热的球迷，每场比赛都看。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对旅行越来越狂热了。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "狂热的", "label": "的字结构"}, {"form": "狂热地", "label": "状语形式"}, {"form": "狂熱", "label": "繁体"}], "register": "通用", "sense_fingerprint": "狂热：对某事物极度喜爱、着迷得停不下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c338676-2383-4c9c-9a7a-bdb10f081010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "狂热", "is_correct": true, "explanation": "正确：“狂热”表示特别喜欢某事，与“对足球非常”搭配。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说的是智力，不能用来形容对足球的态度。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写外形，不能用来形容对某事的喜爱。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”指整洁，与“对足球非常”所表达的喜爱之义不合。"}], "explanations": {"狂热": "正确：“狂热”表示特别喜欢某事，与“对足球非常”搭配。", "聪明": "语义：“聪明”说的是智力，不能用来形容对足球的态度。", "高大": "体貌：“高大”描写外形，不能用来形容对某事的喜爱。", "干净": "语义：“干净”指整洁，与“对足球非常”所表达的喜爱之义不合。"}, "sentence_index": 0, "correct_answer": "狂热"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他狂热地做了三个小时题，看起来非常痛苦。", "explanation": "这里应该用〈坚持〉。狂热表示特别喜爱，做题痛苦时不能用狂热，要说坚持。"}, {"text": "店员狂热地问我需要什么帮助。", "explanation": "这里应该用〈礼貌〉。狂热表示对某事特别喜爱、着迷，店员客气地询问不是喜爱某事，不能用狂热。"}, {"text": "小明狂热地帮老人提东西。", "explanation": "这里应该用〈热心〉。狂热表示对某事特别喜爱、着迷，乐于帮助别人要说热心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "狂热", "is_correct": true, "explanation": "正确：“狂热”表示特别喜爱，与“对跑步”和“极了”搭配。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”说外貌或事物好看，不能用来说对跑步的态度。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”描写身材，与“对跑步”的态度无关。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”说光线或眼神，不能用来修饰对跑步的喜爱。"}], "explanations": {"狂热": "正确：“狂热”表示特别喜爱，与“对跑步”和“极了”搭配。", "漂亮": "语义：“漂亮”说外貌或事物好看，不能用来说对跑步的态度。", "矮小": "体貌：“矮小”描写身材，与“对跑步”的态度无关。", "明亮": "语义：“明亮”说光线或眼神，不能用来修饰对跑步的喜爱。"}, "sentence_index": 6, "correct_answer": "狂热"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位医生狂热地为病人检查身体。", "explanation": "这里应该用〈认真〉。狂热表示对某事特别喜爱、着迷，描述医生仔细工作的态度要说认真。"}, {"text": "他对客人很狂热，还端茶倒水。", "explanation": "这里应该用〈客气〉。狂热表示对某事特别喜爱、着迷，对客人有礼貌要说客气。"}, {"text": "他对这件衣服的大小很狂热。", "explanation": "这里应该用〈满意〉。狂热表示对某事特别喜爱、着迷停不下来，觉得衣服大小合适要说满意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹是个狂热地动漫迷。", "corrected_sentence": "妹妹是个狂热的动漫迷。", "error_description": "错误：“狂热地动漫迷”；正确：“狂热的动漫迷”。“狂热”修饰名词“动漫迷”时要用“的”，“地”只用来修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是个狂热地旅行迷。", "corrected_sentence": "她是个狂热的旅行迷。", "error_description": "错误：“狂热地旅行迷”；正确：“狂热的旅行迷”。“狂热”修饰名词“旅行迷”时要用“的”，“地”只用来修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87838, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷静", "is_correct": true, "explanation": "正确：“冷静”指遇事理智、不激动，与“情绪高涨、近乎失去理智”的狂热相反。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”指态度郑重，与情绪高低无关，不构成反义。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：“懒散”说做事不认真，与“狂热”的情绪强度无关，不构成反义。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说的是智力，与“狂热”的情绪状态不构成反义。"}], "correct_answer": "冷静", "explanations": {"冷静": "正确：“冷静”指遇事理智、不激动，与“情绪高涨、近乎失去理智”的狂热相反。", "严肃": "语义：“严肃”指态度郑重，与情绪高低无关，不构成反义。", "懒散": "语义：“懒散”说做事不认真，与“狂热”的情绪强度无关，不构成反义。", "聪明": "语义：“聪明”说的是智力，与“狂热”的情绪状态不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87838, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷静", "is_correct": true, "explanation": "正确：“冷静”指遇事理智、不激动，与“情绪高涨、近乎失去理智”的狂热相反。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”说性情柔和，与情绪高低无关，不构成反义。"}, {"text": "朴素", "is_correct": false, "explanation": "语义：“朴素”说外表或生活简单，与“狂热”不构成反义。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：“勇敢”说不怕困难，与情绪状态不构成反义。"}], "correct_answer": "冷静", "explanations": {"冷静": "正确：“冷静”指遇事理智、不激动，与“情绪高涨、近乎失去理智”的狂热相反。", "温柔": "语义：“温柔”说性情柔和，与情绪高低无关，不构成反义。", "朴素": "语义：“朴素”说外表或生活简单，与“狂热”不构成反义。", "勇敢": "语义：“勇敢”说不怕困难，与情绪状态不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87838, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "情绪高涨、激动，近乎失去理智的热烈。", "primary_collocate": null, "pronunciation": "kuáng rè", "ipa": "kʰuɑŋ˧˥ ʐɤ˥˩", "syllable_count": 2, "sentences": [{"text": "球迷们在球场上狂热地喊叫。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人群狂热起来，大家都在喊。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演唱会上，歌迷们非常狂热。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的演讲让大家变得狂热。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狂热的人群冲向了舞台。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛赢了，大家狂热地欢呼起来。", "target_word": "狂热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家狂热地欢呼，声音很大。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那些狂热的人听不进别人的话。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在人群里狂热地挥着手。", "target_word": "狂热", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太狂热了，什么都不想听。", "target_word": "狂热", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "狂热的", "label": "的字结构"}, {"form": "狂热地", "label": "状语形式"}, {"form": "狂熱", "label": "繁体"}], "register": "通用", "sense_fingerprint": "狂热：情绪高涨激动、近乎失去理智的热烈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c338676-2383-4c9c-9a7a-bdb10f081010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "狂热", "is_correct": true, "explanation": "正确：“狂热”修饰“喊叫”，表示情绪高涨、近乎失去理智。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”与“喊叫”意思相反，球场上不会安静地喊叫。"}, {"text": "无精打采", "is_correct": false, "explanation": "语义：“无精打采”指没有精神，与球场上狂热地喊叫的样子矛盾。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不出声，与“喊叫”矛盾。"}], "explanations": {"狂热": "正确：“狂热”修饰“喊叫”，表示情绪高涨、近乎失去理智。", "安静": "语义：“安静”与“喊叫”意思相反，球场上不会安静地喊叫。", "无精打采": "语义：“无精打采”指没有精神，与球场上狂热地喊叫的样子矛盾。", "沉默": "语义：“沉默”指不出声，与“喊叫”矛盾。"}, "sentence_index": 0, "correct_answer": "狂热"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他狂热地处理了这次投诉，语气一直很平稳。", "explanation": "这里应该用〈冷静〉。狂热指失去理智的激动，平稳地处理投诉要说冷静。"}, {"text": "他狂热地帮邻居修理自行车。", "explanation": "这里应该用〈热心〉。狂热强调情绪失控般的激动，用来说帮人做事的态度不合适。"}, {"text": "客人刚到，主人狂热地迎了上去。", "explanation": "这里应该用〈热情〉。狂热指失去理智的激动，迎接客人只是热情，不能说狂热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "狂热", "is_correct": true, "explanation": "正确：“狂热”修饰“欢呼”，表示情绪高涨、近乎失去理智。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”与“声音很大”的欢呼场面矛盾。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不出声，与“声音很大”矛盾。"}, {"text": "小声", "is_correct": false, "explanation": "语义：“小声”指声音小，与“声音很大”矛盾。"}], "explanations": {"狂热": "正确：“狂热”修饰“欢呼”，表示情绪高涨、近乎失去理智。", "冷静": "语义：“冷静”与“声音很大”的欢呼场面矛盾。", "沉默": "语义：“沉默”指不出声，与“声音很大”矛盾。", "小声": "语义：“小声”指声音小，与“声音很大”矛盾。"}, "sentence_index": 6, "correct_answer": "狂热"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位医生狂热地为病人检查身体。", "explanation": "这里应该用〈认真〉。狂热指近乎失去理智的热烈，描述医生的工作态度不合适。"}, {"text": "两国代表狂热地交谈。", "explanation": "这里应该用〈友好〉。狂热指失去理智的激动，外交场合的平和交谈不能用狂热。"}, {"text": "服务员狂热地问我要不要加饭。", "explanation": "这里应该用〈客气〉。狂热指近乎失去理智的激动，服务员的礼貌询问不能用狂热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "观众狂热的站起来欢呼。", "corrected_sentence": "观众狂热地站起来欢呼。", "error_description": "错误：“狂热的站起来”；正确：“狂热地站起来”。“狂热”修饰动词“站起来”时要用“地”，“的”只用于修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人群狂热乱成了一团。", "corrected_sentence": "人群狂热得乱成了一团。", "error_description": "错误：“狂热乱成了一团”，漏了“得”；正确：“狂热得乱成了一团”。表示程度结果时，“得”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884e763c-1b73-41d7-80ec-2627525c803e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
