INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87839, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容很了不起、让人敬佩的（多指成就、历史、一生等）。", "primary_collocate": null, "pronunciation": "guāng huī", "ipa": "kuaŋ⁵⁵ xweɪ⁵⁵", "syllable_count": 2, "sentences": [{"text": "他们取得了光辉的成就。", "target_word": "光辉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他光辉的形象留在大家心里。", "target_word": "光辉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是光辉的时刻，大家都鼓掌了。", "target_word": "光辉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有一段光辉的经历。", "target_word": "光辉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英雄的光辉事迹感动了大家。", "target_word": "光辉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了爷爷光辉的故事。", "target_word": "光辉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那是他最光辉的时候。", "target_word": "光辉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最佩服他光辉的一生。", "target_word": "光辉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都记得他光辉的名字。", "target_word": "光辉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了光辉的历史。", "target_word": "光辉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "光辉的成就 / 历史 / 一生；了不起、让人敬佩的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52f58a29-0843-4b18-9594-88ac0b975df0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光辉", "is_correct": true, "explanation": "正确：“光辉”形容了不起、让人敬佩，“光辉的成就”是常见搭配。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”形容空气或土地缺少水分，不能形容成就。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”形容声音大，成就不会吵闹，说不通。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，“咸的成就”说不通。"}], "explanations": {"光辉": "正确：“光辉”形容了不起、让人敬佩，“光辉的成就”是常见搭配。", "干燥": "语义：“干燥”形容空气或土地缺少水分，不能形容成就。", "吵闹": "语义：“吵闹”形容声音大，成就不会吵闹，说不通。", "咸": "语义：“咸”形容味道，“咸的成就”说不通。"}, "sentence_index": 0, "correct_answer": "光辉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他光辉退休后，每天在公园里下棋。", "explanation": "这里应该用〈光荣〉。“光荣退休”是固定说法，“光辉”不这样修饰退休。"}, {"text": "他光辉地洗了一个澡。", "explanation": "“光辉”形容很亮或很了不起，不能修饰洗澡这样的日常小事，这样说搭配不通。"}, {"text": "这次比赛他光辉地失败了。", "explanation": "“光辉”表示很亮或很了不起，不能用来形容“失败”，这样说搭配不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光辉", "is_correct": true, "explanation": "正确：“光辉”形容了不起、让人敬佩，“最光辉的时候”指一个人最了不起的时期。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：“时候”不能冰凉，“最冰凉的时候”说不通。"}, {"text": "干瘪", "is_correct": false, "explanation": "语义：“干瘪”指东西失去水分后变皱，不能用来形容时候。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”形容温度，不用来形容时间。"}], "explanations": {"光辉": "正确：“光辉”形容了不起、让人敬佩，“最光辉的时候”指一个人最了不起的时期。", "冰凉": "语义：“时候”不能冰凉，“最冰凉的时候”说不通。", "干瘪": "语义：“干瘪”指东西失去水分后变皱，不能用来形容时候。", "滚烫": "搭配：“滚烫”形容温度，不用来形容时间。"}, "sentence_index": 6, "correct_answer": "光辉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他犯下了光辉的错误，大家都很失望。", "explanation": "“光辉”是褒义词，只用于值得称赞的事，不能修饰“错误”。"}, {"text": "这场事故的原因很光辉。", "explanation": "“光辉”是褒义词，不能用来形容事故，这样说搭配不通。"}, {"text": "这个小偷的一生很光辉。", "explanation": "“光辉”是褒义词，用于赞美人的功绩，不能用来形容小偷这类坏人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支队伍取得了光辉地成绩。", "corrected_sentence": "这支队伍取得了光辉的成绩。", "error_description": "的/地混用：“光辉”修饰名词“成绩”时应用“的”，不能用“地”。应说“光辉的成绩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她为这个梦想付出了光辉地努力。", "corrected_sentence": "她为这个梦想付出了光辉的努力。", "error_description": "的/地混用：“光辉”修饰名词“努力”时应用“的”，不能用“地”。应说“光辉的努力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca9ddb30-e43a-4c63-956b-9f576adce309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
