INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87841, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "协会是有相同爱好的人聚起来的一个组织。", "primary_collocate": null, "pronunciation": "xié huì", "ipa": "ɕi̯ɛ˧˥ xu̯eɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我参加了学校的摄影协会。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个协会每周六都有活动。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是书法协会的会员。", "target_word": "协会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们协会有五十多个人。", "target_word": "协会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸加入了老年人跑步协会。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的围棋协会里，大家都爱下棋。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想和朋友成立一个读书协会。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个协会的人常常一起爬山。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是学校音乐协会的会长。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "协会给每个新会员发了一本小册子。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "摄影协会", "label": "复合词"}, {"form": "協會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "协会：名词，爱好相同的人自愿组成的组织（摄影协会、围棋协会）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '957488b2-d73b-4bc6-b47f-79a362d47852') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87841, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "协会", "is_correct": true, "explanation": "正确：“摄影协会”指由爱好摄影的人组成的团体，符合“参加”的语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是可以参加的团体，与“摄影”也无关。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“摄影食堂”不成立，食堂不与“摄影”构成词组。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房是医院里的房间，不是可以参加的组织。"}], "explanations": {"协会": "正确：“摄影协会”指由爱好摄影的人组成的团体，符合“参加”的语境。", "厨房": "语义：厨房不是可以参加的团体，与“摄影”也无关。", "食堂": "搭配：“摄影食堂”不成立，食堂不与“摄影”构成词组。", "病房": "语义：病房是医院里的房间，不是可以参加的组织。"}, "sentence_index": 0, "correct_answer": "协会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我参加了一条摄影协会。", "explanation": "这里应该用〈个〉。〈条〉多用于河流、裤子等，不用于协会。"}, {"text": "他每天去协会上学。", "explanation": "这里应该用〈学校〉。〈协会〉是同好者组成的团体，不能用于“上学”。"}, {"text": "他每天去协会看病。", "explanation": "这里应该用〈医院〉。〈协会〉不是医疗机构，不能用于“看病”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87841, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协会", "is_correct": true, "explanation": "正确：“成立一个读书协会”指组织一个读书团体，符合句意。"}, {"text": "气候", "is_correct": false, "explanation": "语义：气候是自然状况，不能被“成立”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景象，不能被“成立”。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：“成立一个读书饺子”不成立，饺子与“读书”和“成立”都不搭配。"}], "explanations": {"协会": "正确：“成立一个读书协会”指组织一个读书团体，符合句意。", "气候": "语义：气候是自然状况，不能被“成立”。", "天空": "语义：天空是自然景象，不能被“成立”。", "饺子": "搭配：“成立一个读书饺子”不成立，饺子与“读书”和“成立”都不搭配。"}, "sentence_index": 6, "correct_answer": "协会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家协会每天生产一千台机器。", "explanation": "这里应该用〈工厂〉。〈协会〉是团体，不生产产品。"}, {"text": "协会抓了一个小偷。", "explanation": "这里应该用〈警察〉。〈协会〉没有执法权，不能“抓”人。"}, {"text": "协会给病人做了手术。", "explanation": "这里应该用〈医生〉。〈协会〉不做手术，手术要由医生完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每周末都参加一座摄影协会。", "corrected_sentence": "我每周末都参加一个摄影协会。", "error_description": "量词错误：“协会”应搭配量词“个”，说“一个摄影协会”。“座”用于山、楼等大型建筑，不用于协会。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些协会们每年都举办一次展览。", "corrected_sentence": "这些协会每年都举办一次展览。", "error_description": "词形错误：“这些”已表示复数，“协会”后面不加“们”。应说“这些协会”，不说“这些协会们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
