INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87842, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由同行业或同爱好的人为共同目的组成的团体。", "primary_collocate": null, "pronunciation": "xié huì", "ipa": "ɕi̯ɛ˧˥ xu̯eɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他是中国作家协会的会员。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "律师协会要求律师遵守规定。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生参加过医学协会的会议。", "target_word": "协会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球协会决定改变比赛时间。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "行业协会帮助公司解决问题。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民成立了协会，一起卖水果。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个协会是为保护动物而成立的。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在商业协会工作了十年。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "协会把大家的意见交给了政府。", "target_word": "协会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为协会的会员，你要交会费。", "target_word": "协会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "行业协会", "label": "复合词"}, {"form": "協會", "label": "繁体"}], "register": "书面", "sense_fingerprint": "协会：名词，同行业或同类人为共同目的组成的正式团体（行业协会、律师协会）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '957488b2-d73b-4bc6-b47f-79a362d47852') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87842, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "协会", "is_correct": true, "explanation": "正确：“中国作家协会”是作家的会员组织，他是其中的会员，符合句意。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“中国作家食堂”不成立，“中国作家”不能修饰“食堂”。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是医疗机构，与“中国作家”这一作家团体的身份不符，“中国作家医院的会员”说不通。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站是交通场所，与“中国作家”这一作家团体的身份毫不相关，“中国作家车站的会员”说不通。"}], "explanations": {"协会": "正确：“中国作家协会”是作家的会员组织，他是其中的会员，符合句意。", "食堂": "搭配：“中国作家食堂”不成立，“中国作家”不能修饰“食堂”。", "医院": "语义：医院是医疗机构，与“中国作家”这一作家团体的身份不符，“中国作家医院的会员”说不通。", "车站": "语义：车站是交通场所，与“中国作家”这一作家团体的身份毫不相关，“中国作家车站的会员”说不通。"}, "sentence_index": 0, "correct_answer": "协会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我参加了一台足球协会。", "explanation": "这里应该用〈个〉。〈台〉多用于机器等，不用于协会。"}, {"text": "协会负责给居民办理身份证。", "explanation": "这里应该用〈派出所〉。〈协会〉是同行业或同爱好者组成的团体，不负责办理身份证件。"}, {"text": "协会判了他三年徒刑。", "explanation": "这里应该用〈法院〉。〈协会〉没有判刑的权力，判刑只能由法院做出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协会", "is_correct": true, "explanation": "正确：“为保护动物而成立的协会”指为保护动物而组成的团体，符合句意。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是为某个目的而成立的组织，句子说不通。"}, {"text": "橡皮", "is_correct": false, "explanation": "语义：橡皮是文具，不能“为保护动物而成立”。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是一种材料，不能“为保护动物而成立”。"}], "explanations": {"协会": "正确：“为保护动物而成立的协会”指为保护动物而组成的团体，符合句意。", "垃圾": "语义：垃圾不是为某个目的而成立的组织，句子说不通。", "橡皮": "语义：橡皮是文具，不能“为保护动物而成立”。", "玻璃": "语义：玻璃是一种材料，不能“为保护动物而成立”。"}, "sentence_index": 6, "correct_answer": "协会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作为协会的学生，你要认真听讲。", "explanation": "这里应该用〈学校〉。〈协会〉是会员组成的团体，没有“学生”。"}, {"text": "协会准时到站了。", "explanation": "这里应该用〈火车〉。“到站”只用于交通工具，〈协会〉不能到站。"}, {"text": "协会给我们上了一节数学课。", "explanation": "这里应该用〈老师〉。〈协会〉是会员组成的团体，不能给学生上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我父亲是一座医学协会的会员。", "corrected_sentence": "我父亲是一个医学协会的会员。", "error_description": "量词错误：“协会”应搭配量词“个”，说“一个医学协会”。“座”用于山、楼等大型建筑，不用于协会。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多行业协会们都帮助公司解决问题。", "corrected_sentence": "很多行业协会都帮助公司解决问题。", "error_description": "词形错误：“很多”已表示数量，“协会”后面不加“们”。应说“很多行业协会”，不说“行业协会们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9982f1a8-be8b-408a-a9b7-ee46a5192fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
