INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87843, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "将会是说事情现在没有发生，以后会发生。", "primary_collocate": null, "pronunciation": "jiāng huì", "ipa": "tɕjɑŋ˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "明天下午，天气将会变冷。", "target_word": "将会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明年这里将会有一座新学校。", "target_word": "将会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月，我们的公司将会搬家。", "target_word": "将会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说下周将会下大雨。", "target_word": "将会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年以后，城市将会更漂亮。", "target_word": "将会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议将会在三点开始。", "target_word": "将会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新地铁将会在明年开通。", "target_word": "将会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个星期，爷爷将会来我们家住。", "target_word": "将会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了夏天，这里将会很热闹。", "target_word": "将会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们长大以后，将会去别的城市工作。", "target_word": "将会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示事情以后会发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5429df9e-59d2-4ea4-a29b-edbfe11afe3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87843, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将会", "is_correct": true, "explanation": "正确。“将会”表示以后会发生，与“明天下午”的将来时间相合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已经发生，与“明天下午”的将来时间矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示正在进行，不与“明天下午”这种将来时间词搭配。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去的经历，与“明天下午”的将来时间矛盾。"}], "explanations": {"将会": "正确。“将会”表示以后会发生，与“明天下午”的将来时间相合。", "已经": "语义：“已经”表示已经发生，与“明天下午”的将来时间矛盾。", "正在": "搭配：“正在”表示正在进行，不与“明天下午”这种将来时间词搭配。", "曾经": "语义：“曾经”表示过去的经历，与“明天下午”的将来时间矛盾。"}, "sentence_index": 0, "correct_answer": "将会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天，天气将会很热。", "explanation": "这里应该用〈已经〉。将会表示以后会发生，“昨天”指已经过去的时间，不能用将会。"}, {"text": "我小时候将会住在北京。", "explanation": "这里应该用〈曾经〉。将会表示以后的事，说小时候的经历要用“曾经”。"}, {"text": "我现在将会看书。", "explanation": "这里应该用〈正在〉。将会表示以后，现在正在做的事要用“正在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将会", "is_correct": true, "explanation": "正确。“将会”表示以后会发生，与“明年”搭配。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示刚发生，与“明年”的将来时间矛盾。"}, {"text": "早就", "is_correct": false, "explanation": "语义：“早就”表示很久以前已经发生，与“明年开通”矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续的动作，不能与“明年”这个未来时点搭配。"}], "explanations": {"将会": "正确。“将会”表示以后会发生，与“明年”搭配。", "刚刚": "语义：“刚刚”表示刚发生，与“明年”的将来时间矛盾。", "早就": "语义：“早就”表示很久以前已经发生，与“明年开通”矛盾。", "一直": "搭配：“一直”表示持续的动作，不能与“明年”这个未来时点搭配。"}, "sentence_index": 6, "correct_answer": "将会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "去年冬天，我们将会在北方过春节。", "explanation": "这里应该用〈曾经〉。将会只表示以后的事，去年冬天发生的事要用“曾经”或过去时。"}, {"text": "我现在将会很饿，想吃点东西。", "explanation": "这里应该用〈仍然〉。将会表示以后的情况，说现在依然保持的状态要用“仍然”。"}, {"text": "他昨天将会到家。", "explanation": "这里应该用〈已经〉。将会表示以后的事，“昨天”是过去的时间，应说“他昨天已经到家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上个星期，我们将会去上海开会。", "corrected_sentence": "下个星期，我们将会去上海开会。", "error_description": "时间错误：“将会”表示以后会发生，不能和“上个星期”这样的过去时间一起用。应改为将来时间“下个星期”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下周末，他们会将会来看我。", "corrected_sentence": "下周末，他们将会来看我。", "error_description": "重复：“将会”已表示将来，前面不能再加“会”，应说“他们将会来看我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
