INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87846, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家一致认为。", "primary_collocate": null, "pronunciation": "gōng rèn", "ipa": "kʊŋ˥ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "大家都公认他是最好的老师。", "target_word": "公认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们公认小王是班里最聪明的人。", "target_word": "公认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人人都公认这个办法最好。", "target_word": "公认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱得好，大家都公认。", "target_word": "公认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公认他的汉语说得最好。", "target_word": "公认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家公认这家医院的医生很好。", "target_word": "公认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷们公认他是最好的球员。", "target_word": "公认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都公认多喝水对身体好。", "target_word": "公认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一直公认她是我们的队长。", "target_word": "公认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家们公认，多运动对身体好。", "target_word": "公认", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公认为", "label": "固定搭配"}, {"form": "公認", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大家一致承认或认为；作谓语，后接宾语或小句", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5429df9e-59d2-4ea4-a29b-edbfe11afe3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87846, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公认", "is_correct": true, "explanation": "正确：大家一致认为他是最好的老师，用“公认”。"}, {"text": "宣布", "is_correct": false, "explanation": "搭配：“宣布”需要有权威的主体，“大家都宣布”不通，不说“大家都宣布他是最好的老师”。"}, {"text": "咒骂", "is_correct": false, "explanation": "语义：“咒骂”与“最好的老师”的评价相反，前后冲突。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与“大家都认可他”的说法相反。"}], "explanations": {"公认": "正确：大家一致认为他是最好的老师，用“公认”。", "宣布": "搭配：“宣布”需要有权威的主体，“大家都宣布”不通，不说“大家都宣布他是最好的老师”。", "咒骂": "语义：“咒骂”与“最好的老师”的评价相反，前后冲突。", "讨厌": "语义：“讨厌”表示反感，与“大家都认可他”的说法相反。"}, "sentence_index": 0, "correct_answer": "公认"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做错了事，很快就公认了自己的错误。", "explanation": "这里应该用〈承认〉。“公认”指大家一致认为，主语是群体；自己认下错误要用“承认”。"}, {"text": "政府昨天公认了新的交通规定。", "explanation": "这里应该用〈宣布〉。“宣布”是正式公告，“公认”指大家认可，不指官方发布。"}, {"text": "我公认这个方案很好，你们别反对。", "explanation": "这里应该用〈赞同〉。“公认”的主语应是大家或众人，个人表示同意不说“公认”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公认", "is_correct": true, "explanation": "正确：球迷们一致认为他是最好的球员，用“公认”。"}, {"text": "驱逐", "is_correct": false, "explanation": "配价：“驱逐”后接人或事物作宾语，不能接“他是……”这样的小句。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：“躲避”表示回避，与“球迷们认可他”的意思不合。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”表示不重视，不能表示认定某人是最好的球员。"}], "explanations": {"公认": "正确：球迷们一致认为他是最好的球员，用“公认”。", "驱逐": "配价：“驱逐”后接人或事物作宾语，不能接“他是……”这样的小句。", "躲避": "语义：“躲避”表示回避，与“球迷们认可他”的意思不合。", "冷落": "语义：“冷落”表示不重视，不能表示认定某人是最好的球员。"}, "sentence_index": 6, "correct_answer": "公认"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她终于公认了我的道歉。", "explanation": "这里应该用〈接受〉。“公认”指大家一致认为，个人接受别人的道歉不能用“公认”。"}, {"text": "老师公认了三个例子。", "explanation": "这里应该用〈列举〉。“公认”指大家认可，不表示列出或举例。"}, {"text": "他公认自己没有偷东西。", "explanation": "这里应该用〈宣称〉。“公认”需要群体认可，个人为自己辩白时用“宣称”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都公认的他是好老师。", "corrected_sentence": "大家都公认他是好老师。", "error_description": "错误：“大家都公认的他”把“他”既作“的”字结构的中心语，又作“公认”的宾语，结构重复、不通；“公认”应直接带宾语。正确说法：“大家都公认他是好老师。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "专家们公认都多运动对身体有好处。", "corrected_sentence": "专家们公认多运动对身体有好处。", "error_description": "错误：副词“都”只能放在动词“公认”前面（如“专家们都公认……”），放在“公认”后面不通。此处去掉“都”即可，正确说法：“专家们公认多运动对身体有好处。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d813a9-f326-4da9-8aaf-42679c863da2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
