INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87847, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改造是把旧的东西改一改，让它变得更好。", "primary_collocate": null, "pronunciation": "gǎi zào", "ipa": "kai˨˩˦ tsɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我们把旧房子改造成了小书店。", "target_word": "改造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸想改造一下这张旧桌子。", "target_word": "改造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把旧自行车改造得很漂亮。", "target_word": "改造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间小厨房改造以后方便多了。", "target_word": "改造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把旧衣服改造成了一个包。", "target_word": "改造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们改造过这个旧仓库。", "target_word": "改造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条旧街改造后很干净。", "target_word": "改造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把阳台改造成小花园。", "target_word": "改造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧工厂改造以后变成了美术馆。", "target_word": "改造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆旧车是爸爸亲手改造的。", "target_word": "改造", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "改造了", "label": "完成体"}, {"form": "改造过", "label": "经历体"}, {"form": "改造改造", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把旧东西改一改，变成更好或另一种用途", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fcb4ee2-f2e1-4070-afe6-cb4d17410cdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87847, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拆除", "is_correct": false, "explanation": "语义：拆除是把建筑拆掉，与保留旧房子并改成书店的意思相反。"}, {"text": "改造", "is_correct": true, "explanation": "改造：把旧房子改变成另一种用途，与“改造成了小书店”相合。"}, {"text": "维修", "is_correct": false, "explanation": "搭配：“维修”指修理损坏的东西，不能说修成书店。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”要把东西从一处运到另一处，不能接“成了小书店”这种结果。"}], "explanations": {"拆除": "语义：拆除是把建筑拆掉，与保留旧房子并改成书店的意思相反。", "改造": "改造：把旧房子改变成另一种用途，与“改造成了小书店”相合。", "维修": "搭配：“维修”指修理损坏的东西，不能说修成书店。", "搬运": "配价：“搬运”要把东西从一处运到另一处，不能接“成了小书店”这种结果。"}, "sentence_index": 0, "correct_answer": "改造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他改造了下午的安排。", "explanation": "这里应该用〈调整〉。改造多指把具体事物或思想做根本改变，临时的安排要用调整。"}, {"text": "市政府改造了一座新桥。", "explanation": "这里应该用〈修建〉。改造针对已有的事物，新桥是新建的，要用修建。"}, {"text": "他改造了作业上的错误。", "explanation": "这里应该用〈改正〉。改造是把事物改成另一种样子，错误要用改正。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”指剪去枝叶，多用于草木，不能说修剪街道。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”是印刷发行书刊，与街道无关。"}, {"text": "改造", "is_correct": true, "explanation": "改造：对旧街加以整治，使之变得干净，与“改造后很干净”相合。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”是卖掉，与街道变干净的结果无关。"}], "explanations": {"修剪": "搭配：“修剪”指剪去枝叶，多用于草木，不能说修剪街道。", "出版": "语义：“出版”是印刷发行书刊，与街道无关。", "改造": "改造：对旧街加以整治，使之变得干净，与“改造后很干净”相合。", "出售": "语义：“出售”是卖掉，与街道变干净的结果无关。"}, "sentence_index": 6, "correct_answer": "改造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们改造了门口的垃圾。", "explanation": "这里应该用〈清理〉。改造是把已有事物改成新样子，垃圾要用清理。"}, {"text": "我们改造了这块地的面积。", "explanation": "这里应该用〈扩大〉。改造指改变事物的形式和用途，面积的增加要用扩大。"}, {"text": "我们改造了会议的时间。", "explanation": "这里应该用〈调整〉。改造是对实物做较大改动，会议时间这类安排要用调整。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把旧教室改造了图书室。", "corrected_sentence": "我们把旧教室改造成了图书室。", "error_description": "错误在“改造”后面缺少结果补语“成”。应说“把……改造成……”，不能只说“改造了……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们改造了过这间老屋。", "corrected_sentence": "我们改造过这间老屋。", "error_description": "错误：「改造了过」。「了」表示完成，「过」表示经历，二者不能同时用在动词后，应为「改造过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
