INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87848, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对原有的事物加以修改或变动，使之适合新的需要。", "primary_collocate": null, "pronunciation": "gǎi zào", "ipa": "kai˨˩˦ tsɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "政府正在改造老城区。", "target_word": "改造", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人们改造了旧设备，生产快多了。", "target_word": "改造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校改造了教室，增加了新电脑。", "target_word": "改造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座旧桥需要改造才能通大车。", "target_word": "改造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司改造了生产线，成本低了。", "target_word": "改造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的路已经改造完了。", "target_word": "改造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市里计划改造二十个老小区。", "target_word": "改造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们改造过旧车间，效果很好。", "target_word": "改造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了方便老人，小区改造了出入口。", "target_word": "改造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个旧体育馆明年要改造。", "target_word": "改造", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "改造了", "label": "完成体"}, {"form": "改造过", "label": "经历体"}, {"form": "改造改造", "label": "重叠"}], "register": "书面", "sense_fingerprint": "修改变动原有事物，使适应新需要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fcb4ee2-f2e1-4070-afe6-cb4d17410cdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”的对象是人或活动，不能说欢迎老城区。"}, {"text": "改造", "is_correct": true, "explanation": "改造：对老城区加以修改，使之适合新的需要，符合句意。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”是印刷发行书刊，与老城区无关。"}, {"text": "发行", "is_correct": false, "explanation": "语义：“发行”指发售书刊或股票等，不能用于地区。"}], "explanations": {"欢迎": "配价：“欢迎”的对象是人或活动，不能说欢迎老城区。", "改造": "改造：对老城区加以修改，使之适合新的需要，符合句意。", "出版": "语义：“出版”是印刷发行书刊，与老城区无关。", "发行": "语义：“发行”指发售书刊或股票等，不能用于地区。"}, "sentence_index": 0, "correct_answer": "改造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂改造了产量。", "explanation": "这里应该用〈提高〉。改造针对具体事物，产量这类数量要用提高。"}, {"text": "村民们改造了田里的蚊子。", "explanation": "这里应该用〈消灭〉。改造是对事物加以改动，蚊子要用消灭。"}, {"text": "这家工厂改造了成本。", "explanation": "这里应该用〈降低〉。改造针对具体事物，成本这类数值要用降低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预约", "is_correct": false, "explanation": "搭配：“预约”多用于座位、服务等，不能预约小区。"}, {"text": "颁发", "is_correct": false, "explanation": "配价：“颁发”的对象是奖状、证书等，不能颁发小区。"}, {"text": "溶解", "is_correct": false, "explanation": "语义：“溶解”指物质在液体中化开，与老小区无关。"}, {"text": "改造", "is_correct": true, "explanation": "改造：对老小区加以整治，使之适合新的需要，符合句意。"}], "explanations": {"预约": "搭配：“预约”多用于座位、服务等，不能预约小区。", "颁发": "配价：“颁发”的对象是奖状、证书等，不能颁发小区。", "溶解": "语义：“溶解”指物质在液体中化开，与老小区无关。", "改造": "改造：对老小区加以整治，使之适合新的需要，符合句意。"}, "sentence_index": 6, "correct_answer": "改造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市里改造了一座新体育馆。", "explanation": "这里应该用〈修建〉。改造针对已有的事物，新体育馆是新建的，要用修建。"}, {"text": "老师改造了作文里的错别字。", "explanation": "这里应该用〈改正〉。改造是把事物改成另一种样子，错别字要用改正。"}, {"text": "这场比赛改造了十分钟。", "explanation": "这里应该用〈延长〉。改造是对具体事物做改动，比赛的时间要用延长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我建议改造了这座老楼，住起来会方便些。", "corrected_sentence": "我建议改造这座老楼，住起来会方便些。", "error_description": "错误在“改造”后面多加了“了”。“建议”表示对将来的想法，后面应说“建议改造”，不能说“建议改造了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市里计划把旧车站改造文化中心。", "corrected_sentence": "市里计划把旧车站改造成文化中心。", "error_description": "错误在缺少结果补语。用“把”字句表示改造为某物时，要说“把……改造成……”或书面的“把……改造为……”，不能省掉“成”或“为”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb96e7d7-04f2-4b08-ae44-29864638de7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
