INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87849, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87849, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "兵团是很多兵组成的一大队人。", "primary_collocate": null, "pronunciation": "bīng tuán", "ipa": "piŋ˥ tʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "山下来了一个兵团，士兵们都拿着枪。", "target_word": "兵团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的兵团越来越近了。", "target_word": "兵团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的将军带着兵团去打仗。", "target_word": "兵团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个兵团有几万名士兵。", "target_word": "兵团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兵团在河边休息了一夜。", "target_word": "兵团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见一个兵团从路上走过。", "target_word": "兵团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兵团走过的地方，路上都是脚印。", "target_word": "兵团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大兵团来到城外，城里的人都很害怕。", "target_word": "兵团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军让兵团在山后等着。", "target_word": "兵团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的兵团一到，我们就撤走了。", "target_word": "兵团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个兵团", "label": "量词（个）"}, {"form": "兵团司令", "label": "复合词"}], "register": "中性", "sense_fingerprint": "由许多士兵组成的一大群军队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19caa3-16e4-4fcd-a031-4c3dbc5187f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87849, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兵团", "is_correct": true, "explanation": "正确。“一个兵团”指一大群军队，与“士兵们都拿着枪”相符。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不是队伍，“山下来了一个学校”不合常理，与“拿着枪”也矛盾。"}, {"text": "商店", "is_correct": false, "explanation": "语义：商店不能像队伍一样“来”，与后文“士兵们都拿着枪”不合。"}, {"text": "幼儿园", "is_correct": false, "explanation": "搭配：“来了一个”多用于队伍或人群，“幼儿园”不能这样“来”。"}], "explanations": {"兵团": "正确。“一个兵团”指一大群军队，与“士兵们都拿着枪”相符。", "学校": "语义：学校不是队伍，“山下来了一个学校”不合常理，与“拿着枪”也矛盾。", "商店": "语义：商店不能像队伍一样“来”，与后文“士兵们都拿着枪”不合。", "幼儿园": "搭配：“来了一个”多用于队伍或人群，“幼儿园”不能这样“来”。"}, "sentence_index": 0, "correct_answer": "兵团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座兵团有几万名士兵。", "explanation": "这里不能用〈座〉。量词“座”用于山、房屋等，“兵团”应用“个”。"}, {"text": "这个兵团有几万名顾客。", "explanation": "这里误把“兵团”当成了〈人群〉的意思：兵团专指军队中的一大队人，不能用来指顾客。"}, {"text": "他是一个兵团，每天都很认真。", "explanation": "这里误把“兵团”当成了〈士兵〉的意思：兵团指大群军队，不能用来指一个人，这里不能说“是一个兵团”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87849, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兵团", "is_correct": true, "explanation": "正确。“兵团”是大群军队，走过会留下大量脚印，与句意相符。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：飞机在空中飞行，不会在路上留下脚印，与句意矛盾。"}, {"text": "风", "is_correct": false, "explanation": "语义：风没有脚，不会在路上留下脚印，与后半句矛盾。"}, {"text": "河水", "is_correct": false, "explanation": "搭配：“河水”不能“走”，与“走过的地方”不搭配。"}], "explanations": {"兵团": "正确。“兵团”是大群军队，走过会留下大量脚印，与句意相符。", "飞机": "语义：飞机在空中飞行，不会在路上留下脚印，与句意矛盾。", "风": "语义：风没有脚，不会在路上留下脚印，与后半句矛盾。", "河水": "搭配：“河水”不能“走”，与“走过的地方”不搭配。"}, "sentence_index": 6, "correct_answer": "兵团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一个兵团只有三个人。", "explanation": "这里误把“兵团”当成了〈小队〉的意思：兵团指很多兵组成的大队，人数不可能只有三个。"}, {"text": "我早上吃了一个兵团。", "explanation": "这里误把「兵团」当成了〈食物〉的意思：兵团指很多兵组成的一大队人，不能用来吃。"}, {"text": "我把兵团扔进了垃圾桶。", "explanation": "这里误把“兵团”当成了〈纸团〉一类的小物件，兵团是很多兵组成的大队，不能扔进垃圾桶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87849, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个兵团们在山下扎营了。", "corrected_sentence": "一个兵团在山下扎营了。", "error_description": "错误在于名词后加了“们”：“兵团”指一整支队伍，不表示复数的人，不能说“兵团们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87849, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只兵团在山后等着。", "corrected_sentence": "那个兵团在山后等着。", "error_description": "错误在于量词：“兵团”指一大群军队，应用量词“个”，说“那个兵团”；“只”一般用于动物，不能用来数“兵团”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87851, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87851, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87851, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "会不会是问一件事有没有可能发生。", "primary_collocate": null, "pronunciation": "huì bu huì", "ipa": "xweɪ˥˩ pu xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "他还没来，会不会是路上堵车了？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，他还没回信，会不会是忘了？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门开着，会不会是小王回来了？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机找不到了，会不会是丢在车上了？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天不说话，会不会是生病了？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一直亮着，会不会是有人在家？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会不会是我听错了？他好像没这么说。", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么黑，会不会是要下雨了？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没回信，会不会是没看到？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜这么咸，会不会是盐放多了？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "會不會", "label": "繁体"}], "register": "口语", "sense_fingerprint": "会不会：用来猜测某事是否可能，常说“会不会是……”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471a2867-8aea-41f5-bcb0-874b318de0af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87851, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能不能", "is_correct": false, "explanation": "语义：能不能 问能力或许可，不表示推测，这里是在猜原因，用能不能说不通。"}, {"text": "该不该", "is_correct": false, "explanation": "语义：该不该 问应当与否，并不是在猜测，用该不该意思不通。"}, {"text": "会不会", "is_correct": true, "explanation": "会不会 表示对某事可能性的猜测，此处推测“没来”的原因可能是堵车，正合语境。"}, {"text": "敢不敢", "is_correct": false, "explanation": "搭配：敢不敢 要求后接动作，不能接“是路上堵车了”这样的判断结果。"}], "explanations": {"能不能": "语义：能不能 问能力或许可，不表示推测，这里是在猜原因，用能不能说不通。", "该不该": "语义：该不该 问应当与否，并不是在猜测，用该不该意思不通。", "会不会": "会不会 表示对某事可能性的猜测，此处推测“没来”的原因可能是堵车，正合语境。", "敢不敢": "搭配：敢不敢 要求后接动作，不能接“是路上堵车了”这样的判断结果。"}, "sentence_index": 0, "correct_answer": "会不会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你会不会游泳？", "explanation": "这里询问的是能力，属于会不会的另一义项，与猜测原因无关，不能用于推测“手机丢在哪儿”。"}, {"text": "他明明在家，会不会是他不在家？", "explanation": "这里应该用〈是不是〉确认。会不会表示猜测原因，而“他明明在家”已经确定，不能再猜测他不在家。"}, {"text": "这件事会不会已经发生了，我亲眼看见了。", "explanation": "这里应该用〈一定〉。说话人已亲眼所见，事情已经确定，用会不会猜测与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87851, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肯不肯", "is_correct": false, "explanation": "搭配：肯不肯 问是否愿意，要求后接动作，不能接“是我听错了”这样的判断。"}, {"text": "要不要", "is_correct": false, "explanation": "语义：要不要 问要求或意愿，不用来猜测原因，这里说不通。"}, {"text": "会不会", "is_correct": true, "explanation": "会不会 表示猜测，此处是说话人怀疑自己听错了，正合语境。"}, {"text": "想不想", "is_correct": false, "explanation": "语义：想不想 问想法或意愿，与“听错了”的怀疑无关。"}], "explanations": {"肯不肯": "搭配：肯不肯 问是否愿意，要求后接动作，不能接“是我听错了”这样的判断。", "要不要": "语义：要不要 问要求或意愿，不用来猜测原因，这里说不通。", "会不会": "会不会 表示猜测，此处是说话人怀疑自己听错了，正合语境。", "想不想": "语义：想不想 问想法或意愿，与“听错了”的怀疑无关。"}, "sentence_index": 6, "correct_answer": "会不会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天的会议，经理会不会来？", "explanation": "这里问的是将来会不会发生，属于会不会的另一义项，与对咸味原因的猜测不同。"}, {"text": "我亲眼看见他放了三勺盐，会不会是盐放多了，我很确定。", "explanation": "这里应该用〈一定是〉。说话人已经确定原因，再用会不会表示猜测就矛盾了。"}, {"text": "这个菜这么咸，会不会是盐放多了，这是事实。", "explanation": "这里应该用〈一定〉。“这是事实”已表明确定，会不会表示不确定，两者不能同时使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87851, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天没来，会不会的是病了？", "corrected_sentence": "他今天没来，会不会是病了？", "error_description": "错误：会不会 后面多加了“的”，“会不会”应直接接“是”。正确：去掉“的”，写作“会不会是病了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87851, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这屋子这么暗，是会不会停电了？", "corrected_sentence": "这屋子这么暗，会不会停电了？", "error_description": "错误：「会不会」前面多加了「是」，「是」不能放在「会不会」前面。正确：去掉「是」，写作「会不会停电了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
