INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87852, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "用于询问某事将来是否会发生，或某人是否具备某种能力。", "primary_collocate": null, "pronunciation": "huì bu huì", "ipa": "xweɪ˥˩ pu xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "你会不会游泳？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天会不会下雨？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会不会来参加我们的晚会？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会不会做中国菜？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会不会骑自行车？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师会不会同意我们的想法？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道他会不会说英语吗？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会不会唱京剧？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会不会开车？我想请你帮忙。", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天的会议，经理会不会来？", "target_word": "会不会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "會不會", "label": "繁体"}], "register": "口语", "sense_fingerprint": "会不会：询问某事是否将会发生，或某人是否会做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '471a2867-8aea-41f5-bcb0-874b318de0af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对不对", "is_correct": false, "explanation": "语法：对不对 用来确认判断，不能直接接动词「游泳」。"}, {"text": "会不会", "is_correct": true, "explanation": "会不会 询问某人是否会做某事，正合此处问能力的语义。"}, {"text": "可否", "is_correct": false, "explanation": "语域：可否 多见于公文或书面请求，不符合口语语境。"}, {"text": "行不行", "is_correct": false, "explanation": "语法：行不行 一般单用或放在句末，不能直接接动词「游泳」。"}], "explanations": {"对不对": "语法：对不对 用来确认判断，不能直接接动词「游泳」。", "会不会": "会不会 询问某人是否会做某事，正合此处问能力的语义。", "可否": "语域：可否 多见于公文或书面请求，不符合口语语境。", "行不行": "语法：行不行 一般单用或放在句末，不能直接接动词「游泳」。"}, "sentence_index": 0, "correct_answer": "会不会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭还没做好，会不会是火太小了？", "explanation": "这里表示猜测原因，属于会不会的另一义项，与询问将来或能力不同。"}, {"text": "门开着，会不会是小王回来了？", "explanation": "这里表示猜测原因，属于会不会的另一义项，与询问将来或能力不同。"}, {"text": "她今天不说话，会不会是生病了？", "explanation": "这里表示猜测原因，不是询问某事是否将会发生，属于会不会的另一义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好不好", "is_correct": false, "explanation": "语法：好不好 多用于征求意见，不能直接接「说英语」问能力。"}, {"text": "多不多", "is_correct": false, "explanation": "语法：多不多 问数量，不能直接接动词短语「说英语」。"}, {"text": "会不会", "is_correct": true, "explanation": "会不会 问某人是否会做某事，正符合此处的语境。"}, {"text": "大不大", "is_correct": false, "explanation": "语法：大不大 是形容词的正反问，不能直接接动词「说英语」。"}], "explanations": {"好不好": "语法：好不好 多用于征求意见，不能直接接「说英语」问能力。", "多不多": "语法：多不多 问数量，不能直接接动词短语「说英语」。", "会不会": "会不会 问某人是否会做某事，正符合此处的语境。", "大不大": "语法：大不大 是形容词的正反问，不能直接接动词「说英语」。"}, "sentence_index": 6, "correct_answer": "会不会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么晚了，他还没回信，会不会是忘了？", "explanation": "这里表示猜测原因，属于会不会的另一义项，与询问将来或能力不同。"}, {"text": "他没回信，会不会是没看到？", "explanation": "这里表示猜测原因，不是询问将来会不会发生，属于会不会的另一义项。"}, {"text": "灯一直亮着，会不会是有人在家？", "explanation": "这里表示猜测原因，属于会不会的另一义项，与询问将来或能力不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
