INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理是会不会批准这个计划？", "corrected_sentence": "经理会不会批准这个计划？", "error_description": "错误：「会不会」前面多加了「是」，「是」不能放在「会不会」前面。正确：去掉「是」，写作「经理会不会批准这个计划？」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ead9dac-b063-4dc1-a417-e7ddb8d801bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
