INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87853, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "本地是说话的人现在所在的这个地方。", "primary_collocate": null, "pronunciation": "běn dì", "ipa": "pən˨˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "本地的菜又好吃又便宜。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，本地有没有好玩的地方？", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在本地找一份工作。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本地的夏天天气很热。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在本地住了十年。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看过本地新闻吗？", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本地的朋友带我去吃饭。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果只有本地才有。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在本地买了一辆车。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的本地菜很有名。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本地人", "label": "复合"}, {"form": "本地话", "label": "复合"}], "register": "中性", "sense_fingerprint": "说话人现在所在的这个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9987eb-5886-4587-85c6-5e6350eb4adf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本地", "is_correct": true, "explanation": "“本地”指说话人所在的地方，“本地的菜”即这里出产的菜，与“又好吃又便宜”相合。"}, {"text": "身体", "is_correct": false, "explanation": "语义：“身体”不是地方，也不能提供可以吃的菜，“身体的菜”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“又好吃又便宜”只能用来形容可以吃的东西，“石头”不能与之搭配。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮上没有可供人食用的菜，“月亮的菜”不成立。"}], "explanations": {"本地": "“本地”指说话人所在的地方，“本地的菜”即这里出产的菜，与“又好吃又便宜”相合。", "身体": "语义：“身体”不是地方，也不能提供可以吃的菜，“身体的菜”说不通。", "石头": "搭配：“又好吃又便宜”只能用来形容可以吃的东西，“石头”不能与之搭配。", "月亮": "语义：月亮上没有可供人食用的菜，“月亮的菜”不成立。"}, "sentence_index": 0, "correct_answer": "本地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每年寒假都去本地旅游，那里的风景很美。", "explanation": "这里应该用〈外地〉。“本地”指说话人现在所在的地方，去“本地”旅游等于去自己所在的地方，说不通；去别处旅游要说“外地”。"}, {"text": "我在北京工作，本地是上海。", "explanation": "这里应该用〈家乡〉。“本地”指说话人现在所在的地方，说话人在北京，却把上海说成“本地”，自相矛盾。"}, {"text": "我昨天刚从本地搬到北京。", "explanation": "这里应该用〈原来住的地方〉。“本地”指说话人现在所在的地方，此人已经搬到北京，把以前住的地方说成“本地”不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本地", "is_correct": true, "explanation": "“本地”指这个地方，“本地的朋友”即这里的朋友，可以带我去吃饭。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不是人，没有朋友，也不能带人去吃饭。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：“雨水”是自然现象，不能交朋友，“雨水的朋友”说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：“带我去吃饭”要求能行动的人作主语，“汽车”不能充当带人吃饭的朋友。"}], "explanations": {"本地": "“本地”指这个地方，“本地的朋友”即这里的朋友，可以带我去吃饭。", "窗户": "语义：“窗户”不是人，没有朋友，也不能带人去吃饭。", "雨水": "语义：“雨水”是自然现象，不能交朋友，“雨水的朋友”说不通。", "汽车": "配价：“带我去吃饭”要求能行动的人作主语，“汽车”不能充当带人吃饭的朋友。"}, "sentence_index": 6, "correct_answer": "本地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来访的外宾大多来自本地。", "explanation": "这里应该用〈国外〉。外宾是从国外来的，“本地”指说话人所在的地方，不能说外宾来自本地。"}, {"text": "这里的本地都很热情。", "explanation": "这里应该用〈本地人〉。“本地”单独作名词只表示地点，指人要说“本地人”。"}, {"text": "我的本地是南京，现在住在北京。", "explanation": "这里应该用〈出生地〉。“本地”指说话人现在所在的地方，此人住在北京，把南京说成“本地”不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的同事本地工作。", "corrected_sentence": "我的同事在本地工作。", "error_description": "错误：“本地工作”；正确：“在本地工作”。“本地”表示地点，作状语时要用介词“在”引出，漏掉“在”会使“本地”被误解为修饰“工作”的定语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些水果是到本地运来的。", "corrected_sentence": "这些水果是从本地运来的。", "error_description": "错误在于起点介词“到”误用：表示起点应用“从”，“到”引出终点，与“运来”的起点含义相矛盾，正确应为“从本地运来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
