INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指说话人所在的地方或所说的这个地方。", "primary_collocate": null, "pronunciation": "běn dì", "ipa": "pən˨˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "本地的学校不太多。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本地的孩子都喜欢这个公园。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司在本地很有名。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本地电视台每天都报天气。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把本地的特产带给了朋友。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本地的冬天不太冷。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你介绍一下本地的历史。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外地的游客很喜欢本地小吃。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本地的路我不太熟。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻是本地报纸写的。", "target_word": "本地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本地人", "label": "复合"}, {"form": "本地话", "label": "复合"}], "register": "中性", "sense_fingerprint": "说话人所在或所说的这个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9987eb-5886-4587-85c6-5e6350eb4adf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本地", "is_correct": true, "explanation": "“本地”指说话人所说的这个地方，“本地的学校”即这里的学校，与“不太多”的描述相合。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不能办学校，“树木的学校不太多”于理不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”不能作“学校”的修饰语，“冰箱的学校”不成词组。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不能办学校，“空气的学校”不成立。"}], "explanations": {"本地": "“本地”指说话人所说的这个地方，“本地的学校”即这里的学校，与“不太多”的描述相合。", "树木": "语义：树木不能办学校，“树木的学校不太多”于理不通。", "冰箱": "搭配：“冰箱”不能作“学校”的修饰语，“冰箱的学校”不成词组。", "空气": "语义：“空气”不能办学校，“空气的学校”不成立。"}, "sentence_index": 0, "correct_answer": "本地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来访的外宾大多来自本地。", "explanation": "这里应该用〈海外〉。外宾是从国外来的，“本地”指当地，二者矛盾。"}, {"text": "这里的本地都很热情。", "explanation": "这里应该用〈本地人〉。“本地”单独作名词只表示地点，指人要说“本地人”。"}, {"text": "本地亲自去了医院，看望了老师。", "explanation": "这里应该用〈本人〉。“本地”指地方，不能指人，“本地亲自去了医院”应说“本人亲自去了医院”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本地", "is_correct": true, "explanation": "“本地”指说话人所说的这个地方，“本地的历史”即这个地方的历史，可以请人介绍。"}, {"text": "中午", "is_correct": false, "explanation": "语义：“中午”是时间，不是可以讲述历史的地方或事物，“中午的历史”说不通。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：“清晨”是一天中的时段，不能作“历史”的所属对象。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”是尚未到来的时间，没有已经发生的历史，“明天的历史”说不通。"}], "explanations": {"本地": "“本地”指说话人所说的这个地方，“本地的历史”即这个地方的历史，可以请人介绍。", "中午": "语义：“中午”是时间，不是可以讲述历史的地方或事物，“中午的历史”说不通。", "清晨": "语义：“清晨”是一天中的时段，不能作“历史”的所属对象。", "明天": "语义：“明天”是尚未到来的时间，没有已经发生的历史，“明天的历史”说不通。"}, "sentence_index": 6, "correct_answer": "本地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没有本地，所以做不成生意。", "explanation": "这里应该用〈本钱〉。“本地”指地方，不能表示资金，“没有本地，做不成生意”说不通，应说“没有本钱”。"}, {"text": "他有很强的本地，能很快学会新技能。", "explanation": "这里应该用〈本领〉。“本地”指地方，不能表示能力，“很强的本地”应说“很强的本领”。"}, {"text": "他的本地是李明，大家都叫他小李。", "explanation": "这里应该用〈本名〉。“本地”指地方，不能指人的姓名，“他的本地是李明”应说“他的本名是李明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们本地长大。", "corrected_sentence": "孩子们在本地长大。", "error_description": "错误：“本地长大”；正确：“在本地长大”。“本地”表示地点，要用介词“在”引出，漏掉“在”句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的表妹本地上学。", "corrected_sentence": "我的表妹在本地上学。", "error_description": "错误：“本地上学”；正确：“在本地上学”。“本地”表示地点，作状语时要用介词“在”引出，漏掉“在”句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87855, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87855, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87855, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出动是一队人离开原来的地方，去做事。", "primary_collocate": null, "pronunciation": "chū dòng", "ipa": "ʈʂʰu˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "天刚亮，救援队就出动了。", "target_word": "出动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说：“大家准备好，我们明天一早出动。”", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到消息，村里的年轻人都出动了。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农忙的时候，全家人都出动，去地里收麦子。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，同学们成群出动，去公园打扫。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那里有人需要帮助，志愿者马上出动。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一队人从山下出动，往山上走。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了抓小偷，警察昨晚出动了。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一听见哨声，大家一起出动。", "target_word": "出动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蚂蚁们成队出动，去找吃的。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出动了", "label": "体标（了）"}, {"form": "出动过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "一群人离开原地，集体去做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aa1c745-16a8-430c-a276-d96c4b94600f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87855, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出动", "is_correct": true, "explanation": "正确：出动（chū dòng），指一群人离开原地集体去做某件事。"}, {"text": "触动", "is_correct": false, "explanation": "chù（第四声）与 chū（第一声）声调不同，意思是触碰或感动。"}, {"text": "初冬", "is_correct": false, "explanation": "dōng（第一声）与 dòng（第四声）声调不同，意思是初冬，即冬天刚开始。"}, {"text": "促动", "is_correct": false, "explanation": "cù（c 声母，第四声）与 chū（ch 声母，第一声）读音不同，意思是推动、促使。"}], "explanations": {"出动": "正确：出动（chū dòng），指一群人离开原地集体去做某件事。", "触动": "chù（第四声）与 chū（第一声）声调不同，意思是触碰或感动。", "初冬": "dōng（第一声）与 dòng（第四声）声调不同，意思是初冬，即冬天刚开始。", "促动": "cù（c 声母，第四声）与 chū（ch 声母，第一声）读音不同，意思是推动、促使。"}, "sentence_index": null, "correct_answer": "出动"}, "level_3": {"options": [{"text": "出动", "is_correct": true, "explanation": "正确：“出动”表示救援队集体离开去救援，与“天刚亮”的行动相符。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“出生”只用于人或动物，不能用于救援队这样的团队。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”只用于人，不能用于救援队。"}, {"text": "去世", "is_correct": false, "explanation": "语义：“去世”与救援队的行动完全无关，句子意思不通。"}], "explanations": {"出动": "正确：“出动”表示救援队集体离开去救援，与“天刚亮”的行动相符。", "出生": "搭配：“出生”只用于人或动物，不能用于救援队这样的团队。", "结婚": "搭配：“结婚”只用于人，不能用于救援队。", "去世": "语义：“去世”与救援队的行动完全无关，句子意思不通。"}, "sentence_index": 0, "correct_answer": "出动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他出动去山里找药。", "explanation": "这里应该用〈独自〉。出动指一群人或一支队伍集体离开去做事，一个人去做事不用“出动”。"}, {"text": "同学们出动在教室里看书。", "explanation": "这里应该用〈都〉。出动表示一群人离开原地去做事，留在教室里看书不能说“出动”。"}, {"text": "大家在操场出动。", "explanation": "这里应该用〈聚集〉。出动表示离开原地去做事，待在原地不能说“出动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出动", "is_correct": true, "explanation": "正确：“出动”表示一队人从山下集体出发，与“往山上走”的动作相符。"}, {"text": "躺下", "is_correct": false, "explanation": "搭配：“躺下”指身体的姿势，不能用于一队人从山下移动。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”与“一队人往山上走”的行动完全不符。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”与“一队人往山上走”的行动毫无关系。"}], "explanations": {"出动": "正确：“出动”表示一队人从山下集体出发，与“往山上走”的动作相符。", "躺下": "搭配：“躺下”指身体的姿势，不能用于一队人从山下移动。", "下雨": "语义：“下雨”与“一队人往山上走”的行动完全不符。", "失业": "语义：“失业”与“一队人往山上走”的行动毫无关系。"}, "sentence_index": 6, "correct_answer": "出动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小猫出动去捉老鼠。", "explanation": "这里应该用〈去〉。出动指一群人或一队人集体行动，单独一只小猫去捉老鼠不用“出动”。"}, {"text": "工人们每天出动上班。", "explanation": "这里应该用〈上班〉。出动指一群人离开原地去执行某项任务，日常上班不用“出动”。"}, {"text": "小草出动在阳光下生长。", "explanation": "这里应该用〈生长〉。出动的主语必须是能主动行动的人或队伍，植物不能说“出动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到号声，大家都出动了了，去救人。", "corrected_sentence": "听到号声，大家都出动了，去救人。", "error_description": "体标重复：“了”只用一次，放在动词“出动”之后，应说“大家都出动了”，不能连用两个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们昨天没出动了，因为下雨了。", "corrected_sentence": "他们昨天没出动，因为下雨了。", "error_description": "体标错误：否定过去的动作用“没”，“没”后不能再加“了”，应说“他们昨天没出动，因为下雨了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
