INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87856, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出发行动；派出（人员、车辆等）。", "primary_collocate": null, "pronunciation": "chū dòng", "ipa": "ʈʂʰu˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "火灾发生后，消防队马上出动了。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察出动了二十辆警车。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨了，学校出动了五辆大巴送学生回家。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司出动了所有的车去接客人。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "接到电话，医院立刻出动了两辆救护车。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上有人落水，警方出动了三条船。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了找小孩，警方出动了很多人。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天一亮，渔船就出动了。", "target_word": "出动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雪以后，市里出动了很多车来扫雪。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察出动过很多次，都没有找到他。", "target_word": "出动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出动了", "label": "体标（了）"}, {"form": "出动过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "派出人员、车辆、船只等去执行任务，或自己出发行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aa1c745-16a8-430c-a276-d96c4b94600f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87856, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出动", "is_correct": true, "explanation": "正确：出动（chū dòng），指派出人员、车辆等去执行任务。"}, {"text": "触动", "is_correct": false, "explanation": "chù（第四声）与 chū（第一声）声调不同，意思是触碰或感动。"}, {"text": "初冬", "is_correct": false, "explanation": "dōng（第一声）与 dòng（第四声）声调不同，意思是初冬，即冬天刚开始。"}, {"text": "促动", "is_correct": false, "explanation": "cù（c 声母，第四声）与 chū（ch 声母，第一声）读音不同，意思是推动、促使。"}], "explanations": {"出动": "正确：出动（chū dòng），指派出人员、车辆等去执行任务。", "触动": "chù（第四声）与 chū（第一声）声调不同，意思是触碰或感动。", "初冬": "dōng（第一声）与 dòng（第四声）声调不同，意思是初冬，即冬天刚开始。", "促动": "cù（c 声母，第四声）与 chū（ch 声母，第一声）读音不同，意思是推动、促使。"}, "sentence_index": null, "correct_answer": "出动"}, "level_3": {"options": [{"text": "出动", "is_correct": true, "explanation": "正确：“出动”表示派出人员去执行任务，与“火灾发生后”的救火行动相符。"}, {"text": "下班", "is_correct": false, "explanation": "搭配：“下班”指结束工作，火灾发生后消防队不会马上下班。"}, {"text": "休息", "is_correct": false, "explanation": "语义：“休息”与“马上”的紧急情况不符，火灾时消防队不会马上休息。"}, {"text": "出席", "is_correct": false, "explanation": "配价：“出席”需要会议、活动等作宾语，不能单独表示消防队的行动。"}], "explanations": {"出动": "正确：“出动”表示派出人员去执行任务，与“火灾发生后”的救火行动相符。", "下班": "搭配：“下班”指结束工作，火灾发生后消防队不会马上下班。", "休息": "语义：“休息”与“马上”的紧急情况不符，火灾时消防队不会马上休息。", "出席": "配价：“出席”需要会议、活动等作宾语，不能单独表示消防队的行动。"}, "sentence_index": 0, "correct_answer": "出动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天下午出动去买菜。", "explanation": "这里应该用〈外出〉。出动指派出人员、车辆去执行任务，不用于个人的日常外出。"}, {"text": "他出动了一本书给我。", "explanation": "这里应该用〈借〉。出动的宾语是人员或车辆，不能是书这样的物品。"}, {"text": "工厂每天出动很多水果到超市。", "explanation": "这里应该用〈运送〉。出动的宾语是人员或车辆，不能是水果等货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出动", "is_correct": true, "explanation": "正确：“出动”表示警方派出很多人员去找小孩，与“为了找小孩”的目的相符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃很多人”与“为了找小孩”的目的相矛盾。"}, {"text": "下班", "is_correct": false, "explanation": "配价：“下班”不能带“很多人”作宾语。"}, {"text": "投降", "is_correct": false, "explanation": "配价：“投降”不能带宾语，也与找小孩的目的不符。"}], "explanations": {"出动": "正确：“出动”表示警方派出很多人员去找小孩，与“为了找小孩”的目的相符。", "放弃": "语义：“放弃很多人”与“为了找小孩”的目的相矛盾。", "下班": "配价：“下班”不能带“很多人”作宾语。", "投降": "配价：“投降”不能带宾语，也与找小孩的目的不符。"}, "sentence_index": 6, "correct_answer": "出动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经理出动了今天的会议。", "explanation": "这里应该用〈出席〉。出动的宾语是人员或车辆，不能是会议。"}, {"text": "我一个人出动去超市买了一瓶水。", "explanation": "这里应该用〈去〉。出动指派出人员或车辆去执行任务，一个人去超市买水不用“出动”。"}, {"text": "他每天出动上班。", "explanation": "这里应该用〈上班〉。出动指派出人员去执行任务，日常上班不用“出动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察出动了过三次，都没有抓到小偷。", "corrected_sentence": "警察出动过三次，都没有抓到小偷。", "error_description": "体标错误：“出动过”表示有过这种经历，不能再加“了”，应说“出动过”，不能说“出动了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "消防队从来不出动过这么多车。", "corrected_sentence": "消防队从来没出动过这么多车。", "error_description": "否定词错误：表示过去从未有过的经历要用“没”，不能用“不”，应说“从来没出动过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15bf9f4a-2139-4935-8242-9082b6980e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
