INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87857, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "呼吸时吸入或呼出的气息，也就是我们呼吸的空气。", "primary_collocate": null, "pronunciation": "qì", "ipa": "tɕʰi˥˩", "syllable_count": 1, "sentences": [{"text": "他深深地吸了一口气。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们呼吸的气，看不见也摸不着。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑完一千米，他累得喘不过气来。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别急，先喘口气，再慢慢说。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对着蜡烛轻轻呼了一口气。", "target_word": "气", "complexity_tier": "T3", "furigana": "tā duì zhe làzhú qīngqīng hū le yì kǒu qì.", "sentence_source": "generated"}, {"text": "游泳前，我先吸满一口气，再下水。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大口大口地喘着气。", "target_word": "气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭上眼睛，慢慢吐出一口气。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说：“先吸一口气，再开始唱。”", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他屏着气，一动也不敢动。", "target_word": "气", "complexity_tier": "T3", "furigana": "tā bǐng zhe qì, yí dòng yě bù gǎn dòng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "一口气", "label": "量词"}, {"form": "氣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "气·呼吸时吸入或呼出的气息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e807c9-c27f-4438-82f2-649eff8684c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87857, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "气", "is_correct": true, "explanation": "气（qì）指呼吸时吸进或呼出的气息，是正确答案。"}, {"text": "七", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，意思是数字七。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，意思是起来、站起。"}, {"text": "其", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是其他、他的。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 qì（第四声）韵母不同，意思是去、离开。"}, {"text": "欺", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，意思是欺负。"}], "explanations": {"气": "气（qì）指呼吸时吸进或呼出的气息，是正确答案。", "七": "qī（第一声）与 qì（第四声）声调不同，意思是数字七。", "起": "qǐ（第三声）与 qì（第四声）声调不同，意思是起来、站起。", "其": "qí（第二声）与 qì（第四声）声调不同，意思是其他、他的。", "去": "qù（第四声）与 qì（第四声）韵母不同，意思是去、离开。", "欺": "qī（第一声）与 qì（第四声）声调不同，意思是欺负。"}, "sentence_index": null, "correct_answer": "气"}, "level_3": {"options": [{"text": "气", "is_correct": true, "explanation": "正确。“一口气”是呼吸的量，“吸了一口气”指吸入一次空气。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“吸”不能跟“饭”搭配，吃饭要说“吃”或“咬”，不说“吸了一口饭”。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能被一口“吸”进肺里，闻花要说“闻”，不说“吸了一口花”。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是落下来的水，不能被一口“吸”进去，句子说的是呼吸。"}], "explanations": {"气": "正确。“一口气”是呼吸的量，“吸了一口气”指吸入一次空气。", "饭": "搭配：“吸”不能跟“饭”搭配，吃饭要说“吃”或“咬”，不说“吸了一口饭”。", "花": "语义：花不能被一口“吸”进肺里，闻花要说“闻”，不说“吸了一口花”。", "雨": "语义：雨是落下来的水，不能被一口“吸”进去，句子说的是呼吸。"}, "sentence_index": 0, "correct_answer": "气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用了很大的气才把门推开。", "explanation": "这里应该用〈力气〉。表示用力的劲儿要说“力气”，“气”不能这样单独表示力量。"}, {"text": "他的气很好，从不跟人吵架。", "explanation": "这里应该用〈脾气〉。说人的性情、脾性要说“脾气”，“气”单独不这样表示。"}, {"text": "他说话的气很温和，大家都愿意听。", "explanation": "这里应该用〈语气〉。说话的口吻要说“语气”，不能只用“气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87857, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "气", "is_correct": true, "explanation": "气（qì）指呼吸时吸进或呼出的气息，是正确答案。"}, {"text": "戏", "is_correct": false, "explanation": "xì（第四声）与 qì（第四声）声母不同，意思是戏剧。"}, {"text": "期", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，意思是时期。"}, {"text": "旗", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是旗子。"}, {"text": "趣", "is_correct": false, "explanation": "qù（第四声）与 qì（第四声）韵母不同，意思是趣味。"}], "explanations": {"气": "气（qì）指呼吸时吸进或呼出的气息，是正确答案。", "戏": "xì（第四声）与 qì（第四声）声母不同，意思是戏剧。", "期": "qī（第一声）与 qì（第四声）声调不同，意思是时期。", "旗": "qí（第二声）与 qì（第四声）声调不同，意思是旗子。", "趣": "qù（第四声）与 qì（第四声）韵母不同，意思是趣味。"}, "sentence_index": null, "correct_answer": "气"}, "level_3": {"options": [{"text": "气", "is_correct": true, "explanation": "正确。“喘着气”指大口呼吸，喘的是空气。"}, {"text": "书", "is_correct": false, "explanation": "语义：“喘”说的是呼吸，书不是可以呼吸进出的东西。"}, {"text": "汗", "is_correct": false, "explanation": "搭配：“喘”不跟“汗”搭配，出汗要说“流汗”，不说“喘汗”。"}, {"text": "歌", "is_correct": false, "explanation": "语义：“喘”的对象是空气，不能喘一首歌。"}], "explanations": {"气": "正确。“喘着气”指大口呼吸，喘的是空气。", "书": "语义：“喘”说的是呼吸，书不是可以呼吸进出的东西。", "汗": "搭配：“喘”不跟“汗”搭配，出汗要说“流汗”，不说“喘汗”。", "歌": "语义：“喘”的对象是空气，不能喘一首歌。"}, "sentence_index": 6, "correct_answer": "气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的气很鲜，大家都喝了一碗。", "explanation": "这里应该用〈味道〉。汤的滋味要说“味道”，“气”不能这样形容汤的鲜美。"}, {"text": "比赛场上的气很紧张，观众都屏住了呼吸。", "explanation": "这里应该用〈气氛〉。形容比赛现场紧张的氛围要说“气氛”，“气”单独不表示这种氛围。"}, {"text": "花园里飘来阵阵气，很好闻。", "explanation": "这里应该用〈香气〉。花的香味要说“香气”，“气”单独不表示这种香味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山顶的空气很清新，大家都想多吸几个气。", "corrected_sentence": "山顶的空气很清新，大家都想多吸几口气。", "error_description": "量词错误：“气”表示呼吸的量时要用“口”，应说“几口气”，不能说“几个气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爬完楼梯，她累得喘不过个气来。", "corrected_sentence": "爬完楼梯，她累得喘不过气来。", "error_description": "量词错误：“气”不能用“个”来数，“喘不过气来”中不需要量词，不能插入“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
