INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "没有固定形状和体积的物质；也指空气。", "primary_collocate": null, "pronunciation": "qì", "ipa": "tɕʰi˥˩", "syllable_count": 1, "sentences": [{"text": "自行车的轮胎里没有气了。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车胎漏了，里面的气慢慢跑光了。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皮球里的气太少，跳不起来。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我去加油站给轮胎打气。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个瓶子里装的是气，不是水。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气没有固定的形状，会跑满整个房间。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把游泳圈里的气放掉了。", "target_word": "气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开瓶盖，里面的气就跑出来了。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个气球里充满了气，飞得很高。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "给篮球多充点气，它才跳得高。", "target_word": "气", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "气体", "label": "复合"}, {"form": "氣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "气·没有固定形状的气体物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e807c9-c27f-4438-82f2-649eff8684c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87858, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "气", "is_correct": true, "explanation": "气（qì）指没有固定形状和体积的气体物质，是正确答案。"}, {"text": "七", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，意思是数字七。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，意思是起来、站起。"}, {"text": "其", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是其他、他的。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 qì（第四声）韵母不同，意思是去、离开。"}], "explanations": {"气": "气（qì）指没有固定形状和体积的气体物质，是正确答案。", "七": "qī（第一声）与 qì（第四声）声调不同，意思是数字七。", "起": "qǐ（第三声）与 qì（第四声）声调不同，意思是起来、站起。", "其": "qí（第二声）与 qì（第四声）声调不同，意思是其他、他的。", "去": "qù（第四声）与 qì（第四声）韵母不同，意思是去、离开。"}, "sentence_index": null, "correct_answer": "气"}, "level_3": {"options": [{"text": "气", "is_correct": true, "explanation": "正确。“没有气”指轮胎里的气体已经没有了。"}, {"text": "电", "is_correct": false, "explanation": "语义：轮胎里装的是气，不装电，句子说的是没有气。"}, {"text": "盐", "is_correct": false, "explanation": "语义：轮胎里不会装盐，句子说的是轮胎里的气体。"}, {"text": "字", "is_correct": false, "explanation": "搭配：“轮胎里没有……”后面要跟能充进轮胎的东西，“字”不能搭配。"}], "explanations": {"气": "正确。“没有气”指轮胎里的气体已经没有了。", "电": "语义：轮胎里装的是气，不装电，句子说的是没有气。", "盐": "语义：轮胎里不会装盐，句子说的是轮胎里的气体。", "字": "搭配：“轮胎里没有……”后面要跟能充进轮胎的东西，“字”不能搭配。"}, "sentence_index": 0, "correct_answer": "气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的气很大，常常跟别人吵架。", "explanation": "这里应该用〈脾气〉。说人容易发怒要说“脾气大”，“气”在这里不指气体。"}, {"text": "这场演唱会的气很热烈，观众一直在尖叫。", "explanation": "这里应该用〈气氛〉。形容现场热烈的氛围要说“气氛”，“气”在这里不指这种氛围。"}, {"text": "他用了很大的气才把箱子抬起来。", "explanation": "这里应该用〈力气〉。表示用力的劲儿要说“力气”，“气”不能这样指力量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87858, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "气", "is_correct": true, "explanation": "气（qì）指没有固定形状和体积的气体物质，是正确答案。"}, {"text": "戏", "is_correct": false, "explanation": "xì（第四声）与 qì（第四声）声母不同，意思是戏剧。"}, {"text": "期", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，意思是时期。"}, {"text": "旗", "is_correct": false, "explanation": "qí（第二声）与 qì（第四声）声调不同，意思是旗子。"}, {"text": "趣", "is_correct": false, "explanation": "qù（第四声）与 qì（第四声）韵母不同，意思是趣味。"}], "explanations": {"气": "气（qì）指没有固定形状和体积的气体物质，是正确答案。", "戏": "xì（第四声）与 qì（第四声）声母不同，意思是戏剧。", "期": "qī（第一声）与 qì（第四声）声调不同，意思是时期。", "旗": "qí（第二声）与 qì（第四声）声调不同，意思是旗子。", "趣": "qù（第四声）与 qì（第四声）韵母不同，意思是趣味。"}, "sentence_index": null, "correct_answer": "气"}, "level_3": {"options": [{"text": "气", "is_correct": true, "explanation": "正确。“放掉的气”指游泳圈里的气体。"}, {"text": "书", "is_correct": false, "explanation": "语义：游泳圈里装的是气，不装书，句子说的是放掉的气。"}, {"text": "糖", "is_correct": false, "explanation": "语义：游泳圈里不会装糖，句子说的是放掉的是气体。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“放掉”的对象是能放出的东西，“歌”不能搭配“放掉”。"}], "explanations": {"气": "正确。“放掉的气”指游泳圈里的气体。", "书": "语义：游泳圈里装的是气，不装书，句子说的是放掉的气。", "糖": "语义：游泳圈里不会装糖，句子说的是放掉的是气体。", "歌": "搭配：“放掉”的对象是能放出的东西，“歌”不能搭配“放掉”。"}, "sentence_index": 6, "correct_answer": "气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这锅汤的气很鲜，大家都喝光了。", "explanation": "这里应该用〈味道〉。汤的滋味要说“味道”，“气”不能这样形容汤的鲜美。"}, {"text": "他的气很温和，说话很慢。", "explanation": "这里应该用〈语气〉。说话的口吻要说“语气”，“气”单独不这样表示说话的温和。"}, {"text": "厨房里飘来阵阵气，很好闻。", "explanation": "这里应该用〈香气〉。食物的香味要说“香气”，“气”单独不表示这种香味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid =