INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我给轮胎打了一只气。", "corrected_sentence": "我给轮胎打了一点气。", "error_description": "量词错误：“气”不能用个体量词“只”（“只”用于动物、器官等个体），应说“打了一点气”，不能说“打了一只气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把气球里的气吃掉了。", "corrected_sentence": "她把气球里的气放掉了。", "error_description": "搭配错误：“气”要说“放掉”，不能说“吃掉”。“吃掉气”说不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699b38f6-7f64-4e1a-858e-e74385b56d51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87859, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入境", "is_correct": true, "explanation": "正确。“入境”指进入国境，与“出境”互为反义词。"}, {"text": "到达", "is_correct": false, "explanation": "无关：“到达”指抵达某地，与“出境”没有反义关系。"}, {"text": "停留", "is_correct": false, "explanation": "无关：“停留”指暂时留在某处，不是“出境”的反义词。"}, {"text": "保持", "is_correct": false, "explanation": "无关：“保持”指维持某种状态，与“出境”没有反义关系。"}], "correct_answer": "入境", "explanations": {"入境": "正确。“入境”指进入国境，与“出境”互为反义词。", "到达": "无关：“到达”指抵达某地，与“出境”没有反义关系。", "停留": "无关：“停留”指暂时留在某处，不是“出境”的反义词。", "保持": "无关：“保持”指维持某种状态，与“出境”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87859, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入境", "is_correct": true, "explanation": "正确。“入境”指进入国境，与“出境”互为反义词。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”指用脑子考虑问题，与“出境”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”指随意地步行，与“出境”没有反义关系。"}, {"text": "工作", "is_correct": false, "explanation": "无关：“工作”指从事劳动或职业活动，与“出境”没有反义关系。"}], "correct_answer": "入境", "explanations": {"入境": "正确。“入境”指进入国境，与“出境”互为反义词。", "思考": "无关：“思考”指用脑子考虑问题，与“出境”没有反义关系。", "散步": "无关：“散步”指随意地步行，与“出境”没有反义关系。", "工作": "无关：“工作”指从事劳动或职业活动，与“出境”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87859, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出境是离开一个国家，到别的国家去。", "primary_collocate": null, "pronunciation": "chū jìng", "ipa": "ʈʂʰu˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "出境前，请先检查护照。", "target_word": "出境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他明天坐飞机出境。", "target_word": "出境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出境时，工作人员看了她的签证。", "target_word": "出境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办好手续后，他就可以出境了。", "target_word": "出境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位游客昨天已经出境了。", "target_word": "出境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "带这么多钱出境，要告诉海关。", "target_word": "出境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出境的时候，别忘了带身份证。", "target_word": "出境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一家下个月要出境度假。", "target_word": "出境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有护照的人不能出境。", "target_word": "出境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟去年第一次出境，去了日本。", "target_word": "出境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出境了", "label": "体标"}, {"form": "出境游", "label": "复合"}, {"form": "出境旅游", "label": "复合"}], "register": "中性", "sense_fingerprint": "离开本国前往别国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af6f987a-8e01-425b-8e85-d1719427681f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87859, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出境", "is_correct": true, "explanation": "正确。chū jìng，指离开本国到别国去。"}, {"text": "处境", "is_correct": false, "explanation": "chǔ（第三声）与 chū（第一声）声调不同，意思是处境，指所处的状况，不是离开国境。"}, {"text": "出警", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，意思是出动警力到现场，不是出境。"}, {"text": "处警", "is_correct": false, "explanation": "chǔ（第三声）与 chū（第一声）、jǐng（第三声）与 jìng（第四声）声调都不同，意思是处理警情。"}], "explanations": {"出境": "正确。chū jìng，指离开本国到别国去。", "处境": "chǔ（第三声）与 chū（第一声）声调不同，意思是处境，指所处的状况，不是离开国境。", "出警": "jǐng（第三声）与 jìng（第四声）声调不同，意思是出动警力到现场，不是出境。", "处警": "chǔ（第三声）与 chū（第一声）、jǐng（第三声）与 jìng（第四声）声调都不同，意思是处理警情。"}, "sentence_index": null, "correct_answer": "出境"}, "level_3": {"options": [{"text": "出版", "is_correct": false, "explanation": "语义：“出版”指书籍、报刊的印行，与护照和出国无关，句子不通。"}, {"text": "出境", "is_correct": true, "explanation": "正确。“出境”指离开国境，与“出境前检查护照”的语境相符。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”指卖东西，卖东西前不需要检查护照，句意不通。"}, {"text": "出血", "is_correct": false, "explanation": "语义：“出血”指身体流出血液，与“检查护照”的语境毫无关联，句子不通。"}], "explanations": {"出版": "语义：“出版”指书籍、报刊的印行，与护照和出国无关，句子不通。", "出境": "正确。“出境”指离开国境，与“出境前检查护照”的语境相符。", "出售": "语义：“出售”指卖东西，卖东西前不需要检查护照，句意不通。", "出血": "语义：“出血”指身体流出血液，与“检查护照”的语境毫无关联，句子不通。"}, "sentence_index": 0, "correct_answer": "出境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚下飞机，就出境了。", "explanation": "这里应该用〈入境〉。他刚下飞机，是进入本国，不是离开国境。“出”和“入”方向相反，学习者容易混淆。"}, {"text": "月亮昨晚突然出境了。", "explanation": "这里应该用〈出现〉。月亮显露在天空中，与越过国境无关；“出境”只指离开本国，不能表示事物出现。"}, {"text": "他一拿到奖杯，就出境了。", "explanation": "这里应该用〈下台〉。下台指走下领奖台或舞台，与越过国境无关；“出境”只指离开本国，不能用于领奖台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人或动物降生，与“别忘了带身份证”的离境情境不合。"}, {"text": "出汗", "is_correct": false, "explanation": "语义：“出汗”指身体排出汗液，与离开国境的情境无关，句子读起来不通。"}, {"text": "出境", "is_correct": true, "explanation": "正确。“出境”指离开国境，与“别忘了带身份证”的提醒相符。"}, {"text": "出血", "is_correct": false, "explanation": "语义：“出血”指身体流出血液，与“别忘了带身份证”的提醒毫无关联，句子不通。"}], "explanations": {"出生": "语义：“出生”指人或动物降生，与“别忘了带身份证”的离境情境不合。", "出汗": "语义：“出汗”指身体排出汗液，与离开国境的情境无关，句子读起来不通。", "出境": "正确。“出境”指离开国境，与“别忘了带身份证”的提醒相符。", "出血": "语义：“出血”指身体流出血液，与“别忘了带身份证”的提醒毫无关联，句子不通。"}, "sentence_index": 6, "correct_answer": "出境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个姑娘一上花轿，就出境了。", "explanation": "这里应该用〈出嫁〉。出嫁指女子结婚到夫家，花轿在本地，与越过国境无关；“出境”只指离开本国，不能用于婚礼。"}, {"text": "他今天出境了，可以回家休息。", "explanation": "这里应该用〈出院〉。他离开的是医院，不是国境。“出境”指离开本国，用在这里不合。"}, {"text": "他十八岁就出境，去田里干活了。", "explanation": "这里应该用〈下田〉。下田指到田地里干活，与越过国境无关；“出境”不能用于下田。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅客在机场办完手续后就出境了了。", "corrected_sentence": "旅客在机场办完手续后就出境了。", "error_description": "体标错误：“出境了”后面不能再加“了”，错误形式“出境了了”多出一个“了”，应删去，正确的说法是“就出境了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她带着孩子出境着，很辛苦。", "corrected_sentence": "她带着孩子出境，很辛苦。", "error_description": "体标错误：“出境”后面不能加“着”。错误形式是“出境着”，应删去“着”，正确的说法是“她带着孩子出境，很辛苦。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9c6956b-51c6-417b-baad-332d53f3cdb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
