INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87861, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87861, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海军是在海上保护国家的军队。", "primary_collocate": null, "pronunciation": "hǎi jūn", "ipa": "xai˨˩ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "他的爸爸是海军。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军的船在海上走得很快。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想当一名海军。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军每天都在海上练习。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着海军的白衣服。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥去年参加了海军。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军保护着我们的国家。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支海军很年轻，成立才十年。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军的朋友给我寄了照片。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军和陆军一起练习。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海军基地", "label": "复合"}, {"form": "海军部队", "label": "复合"}], "register": "中性", "sense_fingerprint": "在海上保护国家的军队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9987eb-5886-4587-85c6-5e6350eb4adf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87861, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海军", "is_correct": true, "explanation": "“海军”是在海上保卫国家的军队，“他的爸爸是海军”说的是爸爸在海军服役。"}, {"text": "海鲜", "is_correct": false, "explanation": "语义：“海鲜”是食物，不是人的身份，“他的爸爸是海鲜”说不通。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”是自然地理事物，不能作人的身份，“他的爸爸是海洋”不成立。"}, {"text": "海带", "is_correct": false, "explanation": "配价：“是”后面要接表示人身份的名词，“海带”不能充当“爸爸”的身份。"}], "explanations": {"海军": "“海军”是在海上保卫国家的军队，“他的爸爸是海军”说的是爸爸在海军服役。", "海鲜": "语义：“海鲜”是食物，不是人的身份，“他的爸爸是海鲜”说不通。", "海洋": "语义：“海洋”是自然地理事物，不能作人的身份，“他的爸爸是海洋”不成立。", "海带": "配价：“是”后面要接表示人身份的名词，“海带”不能充当“爸爸”的身份。"}, "sentence_index": 0, "correct_answer": "海军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的海军是三米。", "explanation": "这里应该用〈海拔〉。“海军”指军队，不能表示高度，说城市的高度要用“海拔”。"}, {"text": "海军资源很丰富。", "explanation": "这里应该用〈海洋〉。“海军”是军队，不能说“海军资源”，指丰富的资源要用“海洋”。"}, {"text": "这些海军在草原上骑马训练。", "explanation": "这里应该用〈陆军〉。海军是在海上作战的军队，在草原上骑马训练的是陆军。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87861, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海军", "is_correct": true, "explanation": "“海军”是保卫国家的军队，“海军保护着我们的国家”说得通。"}, {"text": "海鸥", "is_correct": false, "explanation": "语义：“海鸥”是海鸟，不能保护国家，“海鸥保护着我们的国家”说不通。"}, {"text": "海豹", "is_correct": false, "explanation": "语义：“海豹”是海洋动物，不能承担保护国家的职责，句子不成立。"}, {"text": "海盗", "is_correct": false, "explanation": "语义：“海盗”会侵害国家而非保护国家，“海盗保护着我们的国家”与句意不符。"}], "explanations": {"海军": "“海军”是保卫国家的军队，“海军保护着我们的国家”说得通。", "海鸥": "语义：“海鸥”是海鸟，不能保护国家，“海鸥保护着我们的国家”说不通。", "海豹": "语义：“海豹”是海洋动物，不能承担保护国家的职责，句子不成立。", "海盗": "语义：“海盗”会侵害国家而非保护国家，“海盗保护着我们的国家”与句意不符。"}, "sentence_index": 6, "correct_answer": "海军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片海军很咸，不能直接喝。", "explanation": "这里应该用〈海水〉。“海军”指军队，不能用来形容水的咸味，这里说的是水，应该用“海水”。"}, {"text": "这家饭店的海军很新鲜。", "explanation": "这里应该用〈海鲜〉。“海军”指军队，不是食物，不能说“很新鲜”，指饭店里的海味要用“海鲜”。"}, {"text": "孩子们在海军上玩沙子。", "explanation": "这里应该用〈海滩〉。“海军”是军队，不是可以玩沙子的地方，“在海滩上”才指地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们国家有一只强大的海军。", "corrected_sentence": "我们国家有一支强大的海军。", "error_description": "错误：“一只海军”；正确：“一支海军”。作为军队的“海军”用量词“支”，“只”多用于动物，不能用于军队。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他海军服役三年。", "corrected_sentence": "他在海军服役三年。", "error_description": "错误：“海军服役”；正确：“在海军服役”。“海军”表示服役的部队，要用介词“在”引出，漏掉“在”句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
