INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87862, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87862, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在海上作战和保卫海疆的军队。", "primary_collocate": null, "pronunciation": "hǎi jūn", "ipa": "xai˨˩ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "海军在海上进行了训练。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支海军有很多大船。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军的任务是保卫海疆。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军的新船今天下水了。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海军工作了二十年。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军出海时，家人都来送行。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有一支很强的海军。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军的飞机从船上起飞。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军离开港口，向远处开去。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的海军保卫着海上的安全。", "target_word": "海军", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海军基地", "label": "复合"}, {"form": "海军部队", "label": "复合"}], "register": "中性", "sense_fingerprint": "在海上作战、保卫海疆的军队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9987eb-5886-4587-85c6-5e6350eb4adf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海军", "is_correct": true, "explanation": "“海军”是在海上作战的军队，“海军在海上进行了训练”符合句意。"}, {"text": "海鲜", "is_correct": false, "explanation": "语义：“海鲜”是食物，不能进行训练，“海鲜在海上进行了训练”说不通。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”是自然事物，不是能受训的主体，句子不成立。"}, {"text": "海滩", "is_correct": false, "explanation": "搭配：“海滩”在岸上，与“在海上”构成的地点搭配不通。"}], "explanations": {"海军": "“海军”是在海上作战的军队，“海军在海上进行了训练”符合句意。", "海鲜": "语义：“海鲜”是食物，不能进行训练，“海鲜在海上进行了训练”说不通。", "海洋": "语义：“海洋”是自然事物，不是能受训的主体，句子不成立。", "海滩": "搭配：“海滩”在岸上，与“在海上”构成的地点搭配不通。"}, "sentence_index": 0, "correct_answer": "海军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这艘货船上的海军全是大米。", "explanation": "这里应该用〈货物〉。“海军”指军队，不能指船上装的东西，“全是大米”要说货物。"}, {"text": "海军的面积很大。", "explanation": "这里应该用〈海洋〉。海军是军队，没有面积，指广阔的水域要用“海洋”。"}, {"text": "这个岛的海军很长，一直延伸到远方。", "explanation": "这里应该用〈海岸〉。“海军”指军队，不能表示延伸的长度，说海岸线延伸要用“海岸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海军", "is_correct": true, "explanation": "“海军”是军队，“这个国家有一支很强的海军”符合句意。"}, {"text": "海鸥", "is_correct": false, "explanation": "语义：“海鸥”是海鸟，不是军队，“一支很强的海鸥”说不通。"}, {"text": "海豹", "is_correct": false, "explanation": "语义：“海豹”是海洋动物，不能作为一支很强的武装力量。"}, {"text": "海带", "is_correct": false, "explanation": "搭配：“很强的”不能修饰食物“海带”，“一支很强的海带”不成词组。"}], "explanations": {"海军": "“海军”是军队，“这个国家有一支很强的海军”符合句意。", "海鸥": "语义：“海鸥”是海鸟，不是军队，“一支很强的海鸥”说不通。", "海豹": "语义：“海豹”是海洋动物，不能作为一支很强的武装力量。", "海带": "搭配：“很强的”不能修饰食物“海带”，“一支很强的海带”不成词组。"}, "sentence_index": 6, "correct_answer": "海军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这艘船停在海军里。", "explanation": "这里应该用〈海港〉。“海军”是军队，不是停船的地方，停船要说“停在海港里”。"}, {"text": "这家饭店的海军很新鲜，每天都进货。", "explanation": "这里应该用〈海鲜〉。“海军”指军队，不能形容食物新鲜，指饭店里的海味要说“海鲜”。"}, {"text": "这家店的海军汤很好喝。", "explanation": "这里应该用〈海带〉。“海军”指军队，不能用来做汤，做汤的海味食材是“海带”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那艘海军在海上训练。", "corrected_sentence": "那支海军在海上训练。", "error_description": "错误：“那艘海军”；正确：“那支海军”。作为军队的“海军”用量词“支”，“艘”只用于船只。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的哥哥海军当过指挥员。", "corrected_sentence": "她的哥哥在海军当过指挥员。", "error_description": "错误：“海军当过指挥员”；正确：“在海军当过指挥员”。“在”引出工作的单位，漏掉“在”句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '928d444e-332c-4916-9537-84ebd85376e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
