INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87864, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87864, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "亲自出来办理或交涉。", "primary_collocate": null, "pronunciation": "chū miàn", "ipa": "ʈʂʰu˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这件事太难办，请校长出面吧。", "target_word": "出面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友吵架了，你出面劝一劝。", "target_word": "出面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东不肯退钱，我们只好请律师出面。", "target_word": "出面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小事不用爸爸出面，我自己能解决。", "target_word": "出面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出面和对方谈了一个小时。", "target_word": "出面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居有矛盾，社区主任出面帮忙解决。", "target_word": "出面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房的事，让爷爷出面最合适。", "target_word": "出面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不愿出面，只让秘书去回答。", "target_word": "出面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子打架，两家大人都要出面。", "target_word": "出面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理亲自出面，客人才不生气了。", "target_word": "出面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出了面", "label": "体标"}, {"form": "出过面", "label": "体标"}], "register": "中性", "sense_fingerprint": "亲自出来办理或交涉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '167a7954-97b5-4a26-941f-142692a13d69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出面", "is_correct": true, "explanation": "正确：出面表示校长亲自站出来处理，与“事情太难办，请校长帮忙”相符。"}, {"text": "出门", "is_correct": false, "explanation": "语义：出门指外出，与“替人办难事”无关。"}, {"text": "出洋", "is_correct": false, "explanation": "语域：出洋是旧式书面说法，口语里不这样说；且指去国外，与句意不合。"}, {"text": "放假", "is_correct": false, "explanation": "语义：放假指停止工作学习休息，与“请校长处理难事”不合。"}], "explanations": {"出面": "正确：出面表示校长亲自站出来处理，与“事情太难办，请校长帮忙”相符。", "出门": "语义：出门指外出，与“替人办难事”无关。", "出洋": "语域：出洋是旧式书面说法，口语里不这样说；且指去国外，与句意不合。", "放假": "语义：放假指停止工作学习休息，与“请校长处理难事”不合。"}, "sentence_index": 0, "correct_answer": "出面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌一夜之间就出面了。", "explanation": "这里应该用〈走红〉。出面指亲自站出来办事，不指作品突然受到大众追捧。"}, {"text": "比赛开始后，他很快就出面了。", "explanation": "这里应该用〈出场〉。出面指替人办事，不指比赛中登场。"}, {"text": "工地昨天出面了，所幸没有人受伤。", "explanation": "这里应该用〈出事〉。出面指亲自出来办事，不指发生意外。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出面", "is_correct": true, "explanation": "正确：出面表示爷爷亲自出来办买房的事，与句意相符。"}, {"text": "出国", "is_correct": false, "explanation": "语义：出国指去国外，与“买房的事”无关。"}, {"text": "动工", "is_correct": false, "explanation": "搭配：动工多与工程、项目搭配，不能用于买房。"}, {"text": "出访", "is_correct": false, "explanation": "语域：出访是正式的书面用语，且指出国访问，与买房的语境不合。"}], "explanations": {"出面": "正确：出面表示爷爷亲自出来办买房的事，与句意相符。", "出国": "语义：出国指去国外，与“买房的事”无关。", "动工": "搭配：动工多与工程、项目搭配，不能用于买房。", "出访": "语域：出访是正式的书面用语，且指出国访问，与买房的语境不合。"}, "sentence_index": 6, "correct_answer": "出面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家新饭店明天就出面了。", "explanation": "这里应该用〈开业〉。出面指人亲自出来办事或交涉，不指商店开始营业。"}, {"text": "这部电影下周就出面。", "explanation": "这里应该用〈上映〉。出面指亲自站出来办事，不指影片与观众见面。"}, {"text": "这件古董他准备出面了。", "explanation": "这里应该用〈出手〉。出面指亲自出来办事，不指卖掉东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的律师很出面，问题很快就解决了。", "corrected_sentence": "我们的律师亲自出面，问题很快就解决了。", "error_description": "错误：“很出面”；正确：“亲自出面”。“很”是程度副词，不能修饰动词“出面”，应用表示本人动作的副词“亲自”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事最后还是他被出面了。", "corrected_sentence": "这件事最后还是他出面了。", "error_description": "错误：“被出面”；正确：“出面”。“出面”是不及物动词，不能用“被”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03082593-bfae-47ac-8eda-e4b23f65def1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
